const TYPE_LABELS = {
  ACCOUNT: "Account",
  TEAM: "Team",
  CLIENT: "Client",
};

const TYPE_TONES = {
  ACCOUNT: "indigo",
  TEAM: "sky",
  CLIENT: "teal",
};

export const ACCOUNT_QUALITY_FILTERS = {
  NEEDS_ATTENTION: "NEEDS_ATTENTION",
  COMPLETE: "COMPLETE",
  MISSING_TEAMS: "MISSING_TEAMS",
  MISSING_CLIENTS: "MISSING_CLIENTS",
  MISSING_EMAIL: "MISSING_EMAIL",
  MISSING_POC: "MISSING_POC",
  MISSING_DESCRIPTION: "MISSING_DESCRIPTION",
  SF_NO_ID: "SF_NO_ID",
};

function pct(count, total) {
  if (!total) return 0;
  return Math.round((count / total) * 100);
}

function isBlank(value) {
  return value == null || String(value).trim() === "";
}

function toMix(counts, total, labelMap = TYPE_LABELS, toneMap = TYPE_TONES) {
  return Object.entries(counts)
    .filter(([, count]) => count > 0)
    .map(([key, count]) => ({
      key,
      label: (labelMap && labelMap[key]) || key,
      count,
      pct: pct(count, total),
      tone: (toneMap && toneMap[key]) || "slate",
    }))
    .sort((a, b) => b.count - a.count);
}

/** Issues detected on a single directory record (for filtering & health). */
export function getAccountRecordIssues(item) {
  if (!item) return [];
  const issues = [];
  const type = item.type || "ACCOUNT";
  const teams = Number(item.noOfTeams) || 0;
  const clients = Number(item.noOfClients) || 0;

  if (type === "ACCOUNT" && teams === 0 && item.source !== "SALES_FORCE") {
    issues.push(ACCOUNT_QUALITY_FILTERS.MISSING_TEAMS);
  }
  if (type === "TEAM" && clients === 0) {
    issues.push(ACCOUNT_QUALITY_FILTERS.MISSING_CLIENTS);
  }
  if (type === "CLIENT" && !hasEmail(item)) {
    issues.push(ACCOUNT_QUALITY_FILTERS.MISSING_EMAIL);
  }
  if ((type === "ACCOUNT" || type === "TEAM" || type === "CLIENT") && isBlank(item.poc)) {
    issues.push(ACCOUNT_QUALITY_FILTERS.MISSING_POC);
  }
  if (isBlank(item.description)) {
    issues.push(ACCOUNT_QUALITY_FILTERS.MISSING_DESCRIPTION);
  }
  if (item.source === "SALES_FORCE" && isBlank(item.extAccountId)) {
    issues.push(ACCOUNT_QUALITY_FILTERS.SF_NO_ID);
  }
  return issues;
}

function hasEmail(item) {
  return !isBlank(item.email);
}

export function itemMatchesQualityFilter(item, filterKey) {
  if (!filterKey) return true;
  const issues = getAccountRecordIssues(item);
  if (filterKey === ACCOUNT_QUALITY_FILTERS.NEEDS_ATTENTION) {
    return issues.length > 0;
  }
  if (filterKey === ACCOUNT_QUALITY_FILTERS.COMPLETE) {
    return issues.length === 0;
  }
  return issues.includes(filterKey);
}

function pushSample(bucket, name, max = 4) {
  if (bucket.length < max && name) bucket.push(name);
}

function buildAttentionItems(quality, total) {
  const items = [
    {
      key: ACCOUNT_QUALITY_FILTERS.MISSING_TEAMS,
      label: "Accounts without teams",
      count: quality.accountsNoTeams,
      tone: "amber",
      icon: "fe fe-layers",
      hint: "No child teams linked — hierarchy may be incomplete",
      filterKey: ACCOUNT_QUALITY_FILTERS.MISSING_TEAMS,
      samples: quality.samples.accountsNoTeams,
    },
    {
      key: ACCOUNT_QUALITY_FILTERS.MISSING_CLIENTS,
      label: "Teams without clients",
      count: quality.teamsNoClients,
      tone: "rose",
      icon: "fe fe-users",
      hint: "Teams with zero clients — delivery mapping gap",
      filterKey: ACCOUNT_QUALITY_FILTERS.MISSING_CLIENTS,
      samples: quality.samples.teamsNoClients,
    },
    {
      key: ACCOUNT_QUALITY_FILTERS.MISSING_EMAIL,
      label: "Clients missing email",
      count: quality.clientsNoEmail,
      tone: "violet",
      icon: "fe fe-mail",
      hint: "Add contact email for invoicing & comms",
      filterKey: ACCOUNT_QUALITY_FILTERS.MISSING_EMAIL,
      samples: quality.samples.clientsNoEmail,
    },
    {
      key: ACCOUNT_QUALITY_FILTERS.MISSING_POC,
      label: "No owner assigned",
      count: quality.missingPoc,
      tone: "sky",
      icon: "fe fe-user",
      hint: "Point of contact not set on record",
      filterKey: ACCOUNT_QUALITY_FILTERS.MISSING_POC,
      samples: quality.samples.missingPoc,
    },
    {
      key: ACCOUNT_QUALITY_FILTERS.MISSING_DESCRIPTION,
      label: "Missing description",
      count: quality.missingDescription,
      tone: "slate",
      icon: "fe fe-file-text",
      hint: "Context helps onboarding and handoffs",
      filterKey: ACCOUNT_QUALITY_FILTERS.MISSING_DESCRIPTION,
      samples: quality.samples.missingDescription,
    },
    {
      key: ACCOUNT_QUALITY_FILTERS.SF_NO_ID,
      label: "Salesforce without ID",
      count: quality.sfNoExtId,
      tone: "indigo",
      icon: "fe fe-cloud-off",
      hint: "Synced source but no external account id",
      filterKey: ACCOUNT_QUALITY_FILTERS.SF_NO_ID,
      samples: quality.samples.sfNoExtId,
    },
  ];

  return items
    .filter((row) => row.count > 0)
    .sort((a, b) => b.count - a.count)
    .map((row) => ({
      ...row,
      pct: pct(row.count, total),
      severity: row.count >= 5 ? "high" : row.count >= 2 ? "medium" : "low",
    }));
}

function analyzeDataQuality(list) {
  const quality = {
    accountsNoTeams: 0,
    teamsNoClients: 0,
    clientsNoEmail: 0,
    missingPoc: 0,
    missingDescription: 0,
    sfNoExtId: 0,
    completeRecords: 0,
    recordsWithIssues: 0,
    samples: {
      accountsNoTeams: [],
      teamsNoClients: [],
      clientsNoEmail: [],
      missingPoc: [],
      missingDescription: [],
      sfNoExtId: [],
    },
  };

  const issueCounts = {
    MISSING_TEAMS: 0,
    MISSING_CLIENTS: 0,
    MISSING_EMAIL: 0,
    MISSING_POC: 0,
    MISSING_DESCRIPTION: 0,
    SF_NO_ID: 0,
  };

  list.forEach((item) => {
    const name = item.name || `#${item.id}`;
    const issues = getAccountRecordIssues(item);
    if (issues.length === 0) {
      quality.completeRecords += 1;
    } else {
      quality.recordsWithIssues += 1;
    }

    issues.forEach((key) => {
      issueCounts[key] = (issueCounts[key] || 0) + 1;
    });

    if (issues.includes(ACCOUNT_QUALITY_FILTERS.MISSING_TEAMS)) {
      quality.accountsNoTeams += 1;
      pushSample(quality.samples.accountsNoTeams, name);
    }
    if (issues.includes(ACCOUNT_QUALITY_FILTERS.MISSING_CLIENTS)) {
      quality.teamsNoClients += 1;
      pushSample(quality.samples.teamsNoClients, name);
    }
    if (issues.includes(ACCOUNT_QUALITY_FILTERS.MISSING_EMAIL)) {
      quality.clientsNoEmail += 1;
      pushSample(quality.samples.clientsNoEmail, name);
    }
    if (issues.includes(ACCOUNT_QUALITY_FILTERS.MISSING_POC)) {
      quality.missingPoc += 1;
      pushSample(quality.samples.missingPoc, name);
    }
    if (issues.includes(ACCOUNT_QUALITY_FILTERS.MISSING_DESCRIPTION)) {
      quality.missingDescription += 1;
      pushSample(quality.samples.missingDescription, name);
    }
    if (issues.includes(ACCOUNT_QUALITY_FILTERS.SF_NO_ID)) {
      quality.sfNoExtId += 1;
      pushSample(quality.samples.sfNoExtId, name);
    }
  });

  return { quality, issueCounts };
}

export function buildAccountsSummaryStats(items, options = {}) {
  const list = items || [];
  const total = list.length;
  const viewLabel = options.viewLabel || "items";
  const isUserTeamsView = options.isUserTeamsView === true;

  const typeCounts = { ACCOUNT: 0, TEAM: 0, CLIENT: 0 };
  let salesforceCount = 0;
  let totalTeams = 0;
  let totalClients = 0;
  let drillableCount = 0;
  let billableCount = 0;
  let nonBillableCount = 0;
  const sizeRows = [];

  list.forEach((item) => {
    const type = item.type || "ACCOUNT";
    if (typeCounts[type] != null) {
      typeCounts[type] += 1;
    }
    if (item.source === "SALES_FORCE") {
      salesforceCount += 1;
    }
    if (item.itemType === "BILLABLE") billableCount += 1;
    else if (item.itemType === "NON_BILLABLE") nonBillableCount += 1;

    totalTeams += Number(item.noOfTeams) || 0;
    totalClients += Number(item.noOfClients) || 0;
    if (type !== "CLIENT" && item.source !== "SALES_FORCE") {
      drillableCount += 1;
    }
    if (type === "ACCOUNT" || type === "TEAM") {
      sizeRows.push({
        name: item.name || `#${item.id}`,
        clients: Number(item.noOfClients) || 0,
        teams: Number(item.noOfTeams) || 0,
      });
    }
  });

  sizeRows.sort((a, b) => b.clients - a.clients || b.teams - a.teams);
  const topByClients = sizeRows.slice(0, 8);

  const { quality, issueCounts } = analyzeDataQuality(list);
  const healthScore = total ? Math.round((quality.completeRecords / total) * 100) : 100;
  const attentionItems = isUserTeamsView ? [] : buildAttentionItems(quality, total);
  const totalIssues = quality.recordsWithIssues;

  const typeMix = toMix(typeCounts, total);
  const sourceMix = toMix(
    { SALES_FORCE: salesforceCount, MANUAL: total - salesforceCount },
    total,
    { SALES_FORCE: "Salesforce", MANUAL: "Manual / other" },
    { SALES_FORCE: "sky", MANUAL: "indigo" }
  );

  const healthMix = toMix(
    { COMPLETE: quality.completeRecords, NEEDS_WORK: quality.recordsWithIssues },
    total,
    { COMPLETE: "Complete", NEEDS_WORK: "Needs attention" },
    { COMPLETE: "green", NEEDS_WORK: "amber" }
  );

  const billingMix =
    billableCount + nonBillableCount > 0
      ? toMix(
          { BILLABLE: billableCount, NON_BILLABLE: nonBillableCount },
          billableCount + nonBillableCount,
          { BILLABLE: "Billable", NON_BILLABLE: "Non-billable" },
          { BILLABLE: "green", NON_BILLABLE: "slate" }
        )
      : [];

  const issueMix = toMix(
    {
      MISSING_TEAMS: quality.accountsNoTeams,
      MISSING_CLIENTS: quality.teamsNoClients,
      MISSING_EMAIL: quality.clientsNoEmail,
      MISSING_POC: quality.missingPoc,
      MISSING_DESCRIPTION: quality.missingDescription,
      SF_NO_ID: quality.sfNoExtId,
    },
    Math.max(totalIssues, 1),
    {
      MISSING_TEAMS: "No teams",
      MISSING_CLIENTS: "No clients",
      MISSING_EMAIL: "No email",
      MISSING_POC: "No owner",
      MISSING_DESCRIPTION: "No description",
      SF_NO_ID: "SF no ID",
    },
    {
      MISSING_TEAMS: "amber",
      MISSING_CLIENTS: "rose",
      MISSING_EMAIL: "violet",
      MISSING_POC: "sky",
      MISSING_DESCRIPTION: "slate",
      SF_NO_ID: "indigo",
    }
  ).filter((s) => s.count > 0);

  const coverage = {
    accountsWithTeams: typeCounts.ACCOUNT
      ? typeCounts.ACCOUNT - quality.accountsNoTeams
      : 0,
    teamsWithClients: typeCounts.TEAM ? typeCounts.TEAM - quality.teamsNoClients : 0,
    clientsWithEmail: typeCounts.CLIENT ? typeCounts.CLIENT - quality.clientsNoEmail : 0,
    accountTeamRate: typeCounts.ACCOUNT
      ? pct(typeCounts.ACCOUNT - quality.accountsNoTeams, typeCounts.ACCOUNT)
      : null,
    teamClientRate: typeCounts.TEAM
      ? pct(typeCounts.TEAM - quality.teamsNoClients, typeCounts.TEAM)
      : null,
    clientEmailRate: typeCounts.CLIENT
      ? pct(typeCounts.CLIENT - quality.clientsNoEmail, typeCounts.CLIENT)
      : null,
  };

  const kpis = isUserTeamsView
    ? [
        {
          key: "teams",
          label: "User teams",
          value: total,
          hint: "Teams in directory",
          icon: "fe fe-users",
          tone: "indigo",
        },
        {
          key: "drill",
          label: "Drill-down ready",
          value: drillableCount,
          hint: "Open to manage accounts",
          icon: "fe fe-layers",
          tone: "sky",
        },
        {
          key: "sf",
          label: "Salesforce",
          value: salesforceCount,
          hint: salesforceCount ? "Synced accounts" : "No SF in this view",
          icon: "fe fe-cloud",
          tone: "teal",
        },
        {
          key: "clients",
          label: "Linked clients",
          value: totalClients,
          hint: "Across visible teams",
          icon: "fe fe-briefcase",
          tone: "green",
        },
      ]
    : [
        {
          key: "health",
          label: "Data health",
          value: healthScore,
          hint: `${quality.completeRecords} complete · ${totalIssues} need work`,
          icon: "fe fe-shield",
          tone: healthScore >= 80 ? "green" : healthScore >= 50 ? "amber" : "rose",
          suffix: "%",
        },
        {
          key: "visible",
          label: "In view",
          value: total,
          hint: viewLabel,
          icon: "fe fe-grid",
          tone: "indigo",
        },
        {
          key: "accounts",
          label: "Accounts",
          value: typeCounts.ACCOUNT,
          hint:
            coverage.accountTeamRate != null
              ? `${coverage.accountTeamRate}% have teams`
              : "In hierarchy",
          icon: "fe fe-briefcase",
          tone: "sky",
        },
        {
          key: "teams",
          label: "Teams",
          value: typeCounts.TEAM,
          hint:
            coverage.teamClientRate != null
              ? `${coverage.teamClientRate}% have clients`
              : `${totalTeams} nested`,
          icon: "fe fe-layers",
          tone: "teal",
        },
        {
          key: "clients",
          label: "Clients",
          value: typeCounts.CLIENT,
          hint:
            coverage.clientEmailRate != null
              ? `${coverage.clientEmailRate}% have email`
              : `${totalClients} linked`,
          icon: "fe fe-user",
          tone: "green",
        },
        {
          key: "sf",
          label: "Salesforce",
          value: salesforceCount,
          hint: total ? `${pct(salesforceCount, total)}% of view` : "None",
          icon: "fe fe-cloud",
          tone: "amber",
        },
      ];

  const highlights = isUserTeamsView
    ? [
        {
          key: "teams",
          label: "Teams visible",
          value: total,
          hint: "In your access scope",
          icon: "fe fe-users",
          tone: "indigo",
        },
        {
          key: "drill",
          label: "Can open",
          value: drillableCount,
          hint: "Drill into account tree",
          icon: "fe fe-chevrons-right",
          tone: "sky",
        },
      ]
    : [
        {
          key: "complete",
          label: "Complete records",
          value: quality.completeRecords,
          hint: "No data gaps detected",
          icon: "fe fe-check-circle",
          tone: "green",
        },
        {
          key: "issues",
          label: "Need attention",
          value: totalIssues,
          hint: attentionItems.length
            ? `${attentionItems.length} issue type${attentionItems.length === 1 ? "" : "s"}`
            : "All clear in this view",
          icon: "fe fe-alert-triangle",
          tone: totalIssues > 0 ? "amber" : "green",
        },
        {
          key: "hierarchy",
          label: "Browse level",
          display: options.breadcrumbDepth > 0 ? `Level ${options.breadcrumbDepth + 1}` : "Root",
          hint: options.breadcrumbLabel || "All accounts",
          icon: "fe fe-git-branch",
          tone: "indigo",
        },
        {
          key: "linked",
          label: "Child links",
          value: totalTeams + totalClients,
          hint: `${totalTeams} teams · ${totalClients} clients`,
          icon: "fe fe-link",
          tone: "teal",
        },
      ];

  const insights = [
    {
      key: "type",
      icon: "fe fe-layers",
      title: "Record types",
      subtitle: "Mix in the current view",
      mix: typeMix,
      emptyLabel: "No items in this view",
    },
    {
      key: "health",
      icon: "fe fe-activity",
      title: "Completeness",
      subtitle: "Records passing all checks",
      mix: healthMix,
      emptyLabel: "No records to assess",
    },
    {
      key: "source",
      icon: "fe fe-cloud",
      title: "Data source",
      subtitle: "Salesforce vs manually managed",
      mix: sourceMix,
      emptyLabel: "No source data",
    },
  ];

  if (billingMix.length) {
    insights.push({
      key: "billing",
      icon: "fe fe-dollar-sign",
      title: "Billing type",
      subtitle: "Billable vs non-billable accounts",
      mix: billingMix,
      emptyLabel: "No billing type set",
    });
  }

  const playbook = [
    {
      key: "hierarchy",
      step: "1",
      title: "Browse the tree",
      text: "Open accounts to reveal teams, then clients. Use breadcrumbs to jump back.",
      icon: "fe fe-git-branch",
    },
    {
      key: "fix-teams",
      step: "2",
      title: "Fill hierarchy gaps",
      text: "Accounts without teams or teams without clients block project & PO mapping.",
      icon: "fe fe-layers",
    },
    {
      key: "fix-contact",
      step: "3",
      title: "Complete client contacts",
      text: "Email and owner fields power notifications, approvals, and Salesforce sync.",
      icon: "fe fe-mail",
    },
  ];

  return {
    total,
    typeCounts,
    salesforceCount,
    totalTeams,
    totalClients,
    drillableCount,
    typeMix,
    sourceMix,
    healthMix,
    billingMix,
    issueMix,
    topByClients,
    kpis,
    highlights,
    insights,
    isUserTeamsView,
    healthScore,
    quality,
    attentionItems,
    coverage,
    issueCounts,
    playbook,
    totalIssues,
  };
}
