import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { PAYCHECK_STATUSES } from "config/payroll.config";
import {
  formatPayrollCurrency,
  formatPayrollDate,
} from "config/payroll.utils";
import {
  getPaycheckStatusTone,
  getPaycheckEmployeeInitials,
} from "config/paycheck.utils";

export default function PaycheckRegister({ paychecks, acting, onPublish, onRetract }) {
  return (
    <div className="lux-paycheck-register-wrap">
      <table className="lux-paycheck-register">
        <thead>
          <tr>
            <th>Employee</th>
            <th>Pay period</th>
            <th>Pay date</th>
            <th>Net pay</th>
            <th>Status</th>
            <th aria-label="Actions" />
          </tr>
        </thead>
        <tbody>
          {paychecks.map((row) => {
            const isDraft = row.status === PAYCHECK_STATUSES.DRAFT;
            const isPublished = row.status === PAYCHECK_STATUSES.PUBLISHED;

            return (
              <tr
                key={row.id}
                className={classNames("lux-paycheck-register__row", {
                  "is-attention": isDraft,
                })}
              >
                <td>
                  <Link to={`/payroll/paychecks/${row.id}`} className="lux-paycheck-register__primary">
                    <span className="lux-paycheck-register__avatar" aria-hidden="true">
                      {getPaycheckEmployeeInitials(row.employeeName)}
                    </span>
                    <span className="lux-paycheck-register__primary-copy">
                      <strong className="lux-paycheck-register__primary-title">{row.employeeName}</strong>
                      <span className="lux-paycheck-register__primary-meta">
                        {row.department || "—"} · {row.runName}
                      </span>
                    </span>
                  </Link>
                </td>
                <td>
                  <span className="lux-paycheck-register__period">{row.periodLabel || "—"}</span>
                </td>
                <td>
                  <span className="lux-paycheck-register__date">{formatPayrollDate(row.payDate)}</span>
                </td>
                <td>
                  <strong className="lux-paycheck-register__net">
                    {formatPayrollCurrency(row.net, row.currency)}
                  </strong>
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${getPaycheckStatusTone(row.status)}`)}>
                    {row.status}
                  </span>
                </td>
                <td>
                  <div className="lux-paycheck-register__actions">
                    {isDraft && onPublish && (
                      <button
                        type="button"
                        className="lux-paycheck-register__btn is-primary"
                        disabled={acting}
                        onClick={() => onPublish(row)}
                      >
                        <i className="fe fe-send" aria-hidden="true" />
                        Publish
                      </button>
                    )}
                    {isPublished && onRetract && (
                      <button
                        type="button"
                        className="lux-paycheck-register__btn is-ghost"
                        disabled={acting}
                        onClick={() => onRetract(row)}
                      >
                        <i className="fe fe-slash" aria-hidden="true" />
                        Retract
                      </button>
                    )}
                    <Link to={`/payroll/paychecks/${row.id}`} className="lux-paycheck-register__open" aria-label={`View paycheck for ${row.employeeName}`}>
                      <i className="fe fe-chevron-right" aria-hidden="true" />
                    </Link>
                  </div>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
