import moment from "moment";
import dateUtils from "_helpers/date.utils";

export const PROJECT_STATUS_META = {
  NEW: { label: "New", tone: "sky" },
  ASSIGNED: { label: "Assigned", tone: "indigo" },
  INPROGRESS: { label: "In progress", tone: "amber" },
  COMPLETED: { label: "Completed", tone: "green" },
  CLOSED: { label: "Closed", tone: "slate" },
};

export const PROJECT_STATUS_OPTIONS = [
  { value: "NEW", label: "New", level: 0 },
  { value: "ASSIGNED", label: "Assigned", level: 1 },
  { value: "INPROGRESS", label: "In progress", level: 2 },
  { value: "COMPLETED", label: "Completed", level: 3 },
  { value: "CLOSED", label: "Closed", level: 4 },
];

const PROJECT_TYPE_LABELS = {
  ADHOC: "Adhoc",
  FTEMS: "FTE–MS",
  FTESA: "FTE–Staff aug",
  SERVICES: "Services",
  PRODUCT: "Product",
  TRACKER: "Tracker",
  TMHB: "T&M hourly",
};

const PROJECT_TYPE_TONES = {
  ADHOC: "indigo",
  FTEMS: "violet",
  FTESA: "sky",
  SERVICES: "amber",
  PRODUCT: "teal",
  TRACKER: "green",
  TMHB: "slate",
};

export function normalizeProjectStatus(status) {
  if (status == null || status === "") return "NEW";
  const key = String(status).trim().toUpperCase().replace(/[\s_\-]+/g, "");
  if (key === "INPROGRESS" || key === "IN_PROGRESS") return "INPROGRESS";
  return key;
}

export function getProjectStatusMeta(status) {
  const key = normalizeProjectStatus(status);
  return PROJECT_STATUS_META[key] || { label: status || "—", tone: "slate" };
}

export function getProjectStatusSelectValue(status) {
  return normalizeProjectStatus(status) === "INPROGRESS" ? "INPROGRESS" : status;
}

export function getProjectTypeMeta(projectType) {
  if (!projectType) return null;
  const key = String(projectType).trim().toUpperCase();
  return {
    label: PROJECT_TYPE_LABELS[key] || projectType,
    tone: PROJECT_TYPE_TONES[key] || "slate",
  };
}

export function formatProjectClientLine(item) {
  const parts = [];
  if (item.teamName) parts.push(item.teamName);
  if (item.clientNames && item.clientNames.length) {
    parts.push(Array.isArray(item.clientNames) ? item.clientNames.join(", ") : item.clientNames);
  }
  return parts.length ? parts.join(" · ") : null;
}

export function getProjectTaskPct(item) {
  const total = Number(item.taskTotalCount) || 0;
  const done = Number(item.completedTaskCount) || 0;
  if (!total) return 0;
  return Math.round((done / total) * 100);
}

export function getProjectHoursPct(item) {
  const est = Number(item.estHours) || 0;
  const actual = Number(item.actualHours) || 0;
  if (!est) return 0;
  return Math.min(100, Math.round((actual / est) * 100));
}

const BILLING_LABELS = {
  BILLABLE: "Billable",
  BILLABLE_DA: "Billable DA",
  NON_BILLABLE_PRODUCTIVE: "NB productive",
  NON_BILLABLE: "Non-billable",
};

const PRIORITY_TONES = {
  URGENT: "rose",
  HIGH: "amber",
  MEDIUM: "indigo",
  LOW: "slate",
};

function toProjectMoment(value) {
  if (!value) return null;
  const m = dateUtils.convertDateStringToMoment(value);
  return m && m.isValid() ? m : null;
}

export function getProjectBillingLabel(type) {
  if (!type) return null;
  const key = String(type).trim();
  return BILLING_LABELS[key] || key;
}

export function getProjectPriorityTone(priority) {
  if (!priority) return "slate";
  return PRIORITY_TONES[String(priority).trim().toUpperCase()] || "slate";
}

/** Timeline health + schedule position for card visuals. */
export function getProjectTimelineMeta(item) {
  const status = normalizeProjectStatus(item.status);
  const isClosed = status === "COMPLETED" || status === "CLOSED";
  const today = moment().startOf("day");
  const start = toProjectMoment(item.estStartTime);
  const end = toProjectMoment(item.estCompletionTime);

  if (!end) {
    return {
      health: "NO_DATE",
      label: "No end date",
      tone: "slate",
      elapsedPct: 0,
      daysRemaining: null,
    };
  }

  let health = "ON_TRACK";
  let label = "On track";
  let tone = "green";

  if (!isClosed && end.isBefore(today, "day")) {
    health = "OVERDUE";
    label = "Overdue";
    tone = "rose";
  } else if (!isClosed && end.isSameOrBefore(today.clone().add(14, "days"), "day")) {
    health = "DUE_SOON";
    label = "Due soon";
    tone = "amber";
  } else if (isClosed) {
    health = "CLOSED";
    label = status === "COMPLETED" ? "Completed" : "Closed";
    tone = status === "COMPLETED" ? "green" : "slate";
  }

  let elapsedPct = 0;
  if (start && end.isAfter(start)) {
    const totalDays = Math.max(end.diff(start, "days"), 1);
    const elapsedDays = today.diff(start, "days");
    elapsedPct = Math.min(100, Math.max(0, Math.round((elapsedDays / totalDays) * 100)));
  }

  return {
    health,
    label,
    tone,
    elapsedPct,
    daysRemaining: end.diff(today, "days"),
  };
}

function csvEscape(value) {
  const text = value == null ? "" : String(value);
  if (/[",\n\r]/.test(text)) {
    return `"${text.replace(/"/g, '""')}"`;
  }
  return text;
}

/** Download a single-project summary CSV from details / register actions. */
export function downloadProjectSummaryCsv(item) {
  if (!item) return;
  const rows = [
    ["Field", "Value"],
    ["Ref", item.itemIdUserTeamPrefix || ""],
    ["Code", item.code || ""],
    ["Name", item.name || ""],
    ["Status", item.status || ""],
    ["Type", item.projectType || ""],
    ["Account", item.accountName || ""],
    ["Owner", (item.ownerDetails && item.ownerDetails.name) || ""],
    ["Team", (item.ownerUserTeamDetails && item.ownerUserTeamDetails.name) || item.teamName || ""],
    ["Category", item.category || ""],
    ["Priority", item.priority || ""],
    ["Location", item.location || ""],
    ["Start", item.estStartTime || ""],
    ["Due", item.estCompletionTime || ""],
    ["Est. hours", item.estHours || ""],
    ["Est. cost", item.estCost || ""],
    ["Proposal no.", item.proposalNumber || ""],
    ["Clients", (item.clientNames || []).join("; ")],
    ["Description", item.description || ""],
  ];
  const csv = rows.map((row) => row.map(csvEscape).join(",")).join("\n");
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  const slug = String(item.code || item.itemIdUserTeamPrefix || item.id || "project")
    .replace(/[^\w.-]+/g, "-")
    .toLowerCase();
  anchor.href = url;
  anchor.download = `project-${slug}.csv`;
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  URL.revokeObjectURL(url);
}

