import React from "react";
import classNames from "classnames/bind";
import { getApprovalAttentionMeta } from "config/approvalAttention.utils";

function UniversalApprovalAttentionBadge({ item, compact = false }) {
  const attention = getApprovalAttentionMeta(item);
  if (!attention) {
    return null;
  }

  return (
    <span
      className={classNames(
        "lux-appr-attention-badge",
        `is-${attention.tone}`,
        `is-level-${attention.level}`,
        { "is-compact": compact }
      )}
      title={attention.hint}
    >
      <i className={`fe ${attention.icon}`} aria-hidden="true" />
      <span>{compact ? attention.shortLabel : attention.label}</span>
    </span>
  );
}

export default UniversalApprovalAttentionBadge;
