import {
  AI_DRAFT_STATUSES,
  CHANGE_REQUEST_STATUSES,
  DECISION_TYPES,
  DEPENDENCY_TYPES,
  GATE_STATUSES,
  GATE_STAGES,
  ISSUE_ACTION_STATUSES,
  ISSUE_PRIORITIES,
  ISSUE_STATUSES,
  MILESTONE_STATUSES,
  RISK_SEVERITIES,
  RISK_STATUSES,
} from "config/project-governance.config";

export const MILESTONE_STATUS_FILTER_OPTIONS = [
  { id: "ALL", label: "All statuses" },
  { id: MILESTONE_STATUSES.PLANNED, label: "Planned" },
  { id: MILESTONE_STATUSES.IN_PROGRESS, label: "In progress" },
  { id: MILESTONE_STATUSES.COMPLETE, label: "Complete" },
  { id: MILESTONE_STATUSES.AT_RISK, label: "At risk" },
  { id: MILESTONE_STATUSES.BLOCKED, label: "Blocked" },
];

export function getMilestoneStatusLabel(status) {
  const match = MILESTONE_STATUS_FILTER_OPTIONS.find((row) => row.id === status);
  return (match && match.label) || status || "Unknown";
}

export function getMilestoneStatusTone(status) {
  if (status === MILESTONE_STATUSES.COMPLETE) {
    return "green";
  }
  if (status === MILESTONE_STATUSES.IN_PROGRESS) {
    return "blue";
  }
  if (status === MILESTONE_STATUSES.AT_RISK) {
    return "amber";
  }
  if (status === MILESTONE_STATUSES.BLOCKED) {
    return "rose";
  }
  return "slate";
}

export function filterMilestones(rows = [], filters = {}) {
  let list = Array.isArray(rows) ? [...rows] : [];
  if (filters.projectId) {
    list = list.filter((row) => row.projectId === filters.projectId);
  }
  if (filters.status && filters.status !== "ALL") {
    list = list.filter((row) => row.status === filters.status);
  }
  if (filters.query) {
    const q = String(filters.query).trim().toLowerCase();
    list = list.filter(
      (row) =>
        (row.name && row.name.toLowerCase().includes(q)) ||
        (row.projectName && row.projectName.toLowerCase().includes(q)) ||
        (row.ownerName && row.ownerName.toLowerCase().includes(q))
    );
  }
  return list.sort((a, b) => String(a.plannedEnd || "").localeCompare(String(b.plannedEnd || "")));
}

export function buildProjectOptions(milestones = []) {
  const map = new Map();
  milestones.forEach((row) => {
    if (!row.projectId) {
      return;
    }
    map.set(row.projectId, {
      id: row.projectId,
      label: row.projectName || row.projectCode || row.projectId,
    });
  });
  return [{ id: "ALL", label: "All projects" }, ...Array.from(map.values())];
}

function scopeMilestonesForProject(milestones = [], projectId) {
  let rows = Array.isArray(milestones) ? milestones.filter(Boolean) : [];
  if (projectId && projectId !== "ALL") {
    rows = rows.filter((row) => row.projectId === projectId);
  }
  return rows;
}

function scopeDependenciesForProject(dependencies = [], milestones = [], projectId) {
  const milestoneIds = new Set(milestones.map((row) => row.id));
  return (dependencies || []).filter((dep) => {
    if (!dep.predecessorId || !dep.successorId) {
      return false;
    }
    if (projectId && projectId !== "ALL" && dep.projectId && dep.projectId !== projectId) {
      return false;
    }
    return milestoneIds.has(dep.predecessorId) && milestoneIds.has(dep.successorId);
  });
}

function milestoneDurationDays(milestone) {
  return Math.max(1, daysBetweenDates(milestone.plannedStart, milestone.plannedEnd) + 1);
}

function addDaysToGovernanceDate(value, deltaDays) {
  const date = parseGovernanceDate(value);
  if (!date) {
    return null;
  }
  date.setDate(date.getDate() + deltaDays);
  return formatGovernanceDate(date);
}

function buildMilestoneLookup(milestones = []) {
  const map = {};
  milestones.forEach((row) => {
    if (row && row.id) {
      map[row.id] = row;
    }
  });
  return map;
}

function detectDependencyCycle(dependencies = []) {
  const graph = {};
  dependencies.forEach((row) => {
    if (!graph[row.predecessorId]) {
      graph[row.predecessorId] = [];
    }
    graph[row.predecessorId].push(row.successorId);
  });

  const visiting = new Set();
  const visited = new Set();

  function hasCycle(node) {
    if (visiting.has(node)) {
      return true;
    }
    if (visited.has(node)) {
      return false;
    }
    visiting.add(node);
    const next = graph[node] || [];
    for (let i = 0; i < next.length; i += 1) {
      if (hasCycle(next[i])) {
        return true;
      }
    }
    visiting.delete(node);
    visited.add(node);
    return false;
  }

  return Object.keys(graph).some((node) => hasCycle(node));
}

function topologicalMilestoneOrder(milestones = [], dependencies = []) {
  const ids = milestones.map((row) => row.id);
  const indegree = {};
  const adjacency = {};

  ids.forEach((id) => {
    indegree[id] = 0;
    adjacency[id] = [];
  });

  dependencies.forEach((dep) => {
    if (!adjacency[dep.predecessorId]) {
      adjacency[dep.predecessorId] = [];
    }
    if (!indegree[dep.successorId] && indegree[dep.successorId] !== 0) {
      indegree[dep.successorId] = 0;
    }
    adjacency[dep.predecessorId].push(dep.successorId);
    indegree[dep.successorId] = (indegree[dep.successorId] || 0) + 1;
  });

  const queue = ids.filter((id) => (indegree[id] || 0) === 0);
  const order = [];

  while (queue.length) {
    const node = queue.shift();
    order.push(node);
    (adjacency[node] || []).forEach((next) => {
      indegree[next] -= 1;
      if (indegree[next] === 0) {
        queue.push(next);
      }
    });
  }

  if (order.length !== ids.length) {
    return null;
  }
  return order;
}

export function computeCriticalPathAnalysis(milestones = [], dependencies = [], options = {}) {
  const scopedMilestones = scopeMilestonesForProject(milestones, options.projectId);
  const scopedDependencies = scopeDependenciesForProject(
    dependencies,
    scopedMilestones,
    options.projectId
  );

  if (!scopedMilestones.length) {
    return {
      criticalMilestoneIds: [],
      criticalDependencyIds: [],
      slackByMilestoneId: {},
      projectDurationDays: 0,
      hasCycle: false,
      orderedMilestoneIds: [],
    };
  }

  if (detectDependencyCycle(scopedDependencies)) {
    return {
      criticalMilestoneIds: [],
      criticalDependencyIds: [],
      slackByMilestoneId: {},
      projectDurationDays: 0,
      hasCycle: true,
      orderedMilestoneIds: [],
    };
  }

  const order = topologicalMilestoneOrder(scopedMilestones, scopedDependencies);
  if (!order) {
    return {
      criticalMilestoneIds: [],
      criticalDependencyIds: [],
      slackByMilestoneId: {},
      projectDurationDays: 0,
      hasCycle: true,
      orderedMilestoneIds: [],
    };
  }

  const milestoneById = buildMilestoneLookup(scopedMilestones);
  const predsBySuccessor = {};
  const succsByPredecessor = {};

  scopedDependencies.forEach((dep) => {
    if (!predsBySuccessor[dep.successorId]) {
      predsBySuccessor[dep.successorId] = [];
    }
    predsBySuccessor[dep.successorId].push(dep);
    if (!succsByPredecessor[dep.predecessorId]) {
      succsByPredecessor[dep.predecessorId] = [];
    }
    succsByPredecessor[dep.predecessorId].push(dep);
  });

  const es = {};
  const ef = {};
  const durationById = {};

  order.forEach((id) => {
    const milestone = milestoneById[id];
    const duration = milestoneDurationDays(milestone);
    durationById[id] = duration;
    const incoming = predsBySuccessor[id] || [];
    let earliestStart = 0;
    incoming.forEach((dep) => {
      const predFinish = ef[dep.predecessorId] != null ? ef[dep.predecessorId] : 0;
      const lag = dep.lagDays != null ? dep.lagDays : 0;
      earliestStart = Math.max(earliestStart, predFinish + lag + 1);
    });
    es[id] = earliestStart;
    ef[id] = earliestStart + duration - 1;
  });

  const projectFinish = Math.max(...order.map((id) => ef[id] || 0));
  const projectDurationDays = projectFinish + 1;
  const lf = {};
  const ls = {};

  order.slice().reverse().forEach((id) => {
    const duration = durationById[id];
    const outgoing = succsByPredecessor[id] || [];
    let latestFinish = projectFinish;
    if (outgoing.length) {
      latestFinish = Math.min(
        ...outgoing.map((dep) => {
          const lag = dep.lagDays != null ? dep.lagDays : 0;
          const succStart = ls[dep.successorId] != null ? ls[dep.successorId] : projectFinish;
          return succStart - lag - 1;
        })
      );
    }
    lf[id] = latestFinish;
    ls[id] = latestFinish - duration + 1;
  });

  const slackByMilestoneId = {};
  const criticalMilestoneIds = [];
  order.forEach((id) => {
    const slack = Math.max(0, (ls[id] != null ? ls[id] : 0) - (es[id] != null ? es[id] : 0));
    slackByMilestoneId[id] = slack;
    if (slack === 0) {
      criticalMilestoneIds.push(id);
    }
  });

  const criticalSet = new Set(criticalMilestoneIds);
  const criticalDependencyIds = scopedDependencies
    .filter(
      (dep) => criticalSet.has(dep.predecessorId) && criticalSet.has(dep.successorId) && slackByMilestoneId[dep.successorId] === 0
    )
    .map((dep) => dep.id);

  return {
    criticalMilestoneIds,
    criticalDependencyIds,
    slackByMilestoneId,
    projectDurationDays,
    hasCycle: false,
    orderedMilestoneIds: order,
  };
}

export function enrichMilestonesWithScheduleAnalysis(milestones = [], dependencies = [], options = {}) {
  const analysis = computeCriticalPathAnalysis(milestones, dependencies, options);
  return milestones.map((row) => ({
    ...row,
    onCriticalPath: analysis.criticalMilestoneIds.includes(row.id),
    slackDays: analysis.slackByMilestoneId[row.id] != null ? analysis.slackByMilestoneId[row.id] : null,
  }));
}

export function validateDependencySchedule(milestones = [], dependency = {}) {
  const lookup = buildMilestoneLookup(milestones);
  const predecessor = lookup[dependency.predecessorId];
  const successor = lookup[dependency.successorId];

  if (!predecessor || !successor) {
    return { valid: false, reason: "Predecessor and successor milestones must exist in this project." };
  }

  if (!predecessor.plannedEnd || !successor.plannedStart) {
    return { valid: false, reason: "Both milestones need planned dates before linking." };
  }

  const lag = dependency.lagDays != null ? dependency.lagDays : 0;
  const type = dependency.type || DEPENDENCY_TYPES.FINISH_TO_START;

  if (type !== DEPENDENCY_TYPES.FINISH_TO_START) {
    return { valid: true, reason: null, warning: "Only finish-to-start schedule checks are enforced in this release." };
  }

  const requiredSuccessorStart = addDaysToGovernanceDate(predecessor.plannedEnd, lag + 1);
  if (requiredSuccessorStart && successor.plannedStart < requiredSuccessorStart) {
    const gap = daysBetweenDates(successor.plannedStart, requiredSuccessorStart);
    return {
      valid: false,
      reason: `${successor.name} starts ${gap} day${gap === 1 ? "" : "s"} before ${predecessor.name} can finish.`,
      requiredSuccessorStart,
      actualSuccessorStart: successor.plannedStart,
    };
  }

  return { valid: true, reason: null };
}

export function buildDependencyValidationReport(milestones = [], dependencies = [], options = {}) {
  const scopedMilestones = scopeMilestonesForProject(milestones, options.projectId);
  const scopedDependencies = scopeDependenciesForProject(
    dependencies,
    scopedMilestones,
    options.projectId
  );
  const issues = [];

  if (detectDependencyCycle(scopedDependencies)) {
    issues.push({
      id: "cycle",
      severity: "error",
      title: "Circular dependency chain",
      copy: "Resolve the loop before trusting critical-path or schedule forecasts.",
    });
  }

  scopedDependencies.forEach((dep) => {
    const schedule = validateDependencySchedule(scopedMilestones, dep);
    if (!schedule.valid) {
      issues.push({
        id: `schedule-${dep.id}`,
        severity: "warning",
        title: `Schedule gap: ${dep.predecessorName || dep.predecessorId} → ${dep.successorName || dep.successorId}`,
        copy: schedule.reason,
        dependencyId: dep.id,
      });
    }
  });

  return issues;
}

export function validateMilestoneReschedule(milestones = [], dependencies = [], milestoneId, schedulePatch = {}) {
  const lookup = buildMilestoneLookup(milestones);
  const milestone = lookup[milestoneId];
  if (!milestone) {
    return { valid: false, reason: "Milestone not found." };
  }

  const preview = {
    ...milestone,
    plannedStart: schedulePatch.plannedStart || milestone.plannedStart,
    plannedEnd: schedulePatch.plannedEnd || milestone.plannedEnd,
  };

  const warnings = [];
  (dependencies || []).forEach((dep) => {
    if (dep.predecessorId === milestoneId) {
      const result = validateDependencySchedule(
        milestones.map((row) => (row.id === milestoneId ? preview : row)),
        dep
      );
      if (!result.valid) {
        warnings.push(result.reason);
      }
    }
    if (dep.successorId === milestoneId) {
      const result = validateDependencySchedule(
        milestones.map((row) => (row.id === milestoneId ? preview : row)),
        dep
      );
      if (!result.valid) {
        warnings.push(result.reason);
      }
    }
  });

  if (warnings.length) {
    return { valid: false, reason: warnings[0], warnings };
  }
  return { valid: true, reason: null, warnings: [] };
}

export function buildMilestoneMetrics(milestones = [], dependencies = [], options = {}) {
  const enriched = enrichMilestonesWithScheduleAnalysis(milestones, dependencies, options);
  const total = enriched.length;
  const complete = enriched.filter((row) => row.status === MILESTONE_STATUSES.COMPLETE).length;
  const inProgress = enriched.filter((row) => row.status === MILESTONE_STATUSES.IN_PROGRESS).length;
  const atRisk = enriched.filter((row) => row.status === MILESTONE_STATUSES.AT_RISK).length;
  const onCriticalPath = enriched.filter((row) => row.onCriticalPath).length;
  const dependencyCount = scopeDependenciesForProject(dependencies, enriched, options.projectId).length;
  const analysis = computeCriticalPathAnalysis(milestones, dependencies, options);
  const validationIssues = buildDependencyValidationReport(milestones, dependencies, options);
  const avgComplete =
    total > 0
      ? Math.round(
          milestones.reduce((sum, row) => sum + (row.percentComplete || 0), 0) / total
        )
      : 0;

  return {
    total,
    complete,
    inProgress,
    atRisk,
    onCriticalPath,
    dependencyCount,
    avgComplete,
    completionRate: total > 0 ? Math.round((complete / total) * 100) : 0,
    projectDurationDays: analysis.projectDurationDays,
    scheduleIssueCount: validationIssues.length,
    hasDependencyCycle: analysis.hasCycle,
  };
}

export function buildMilestoneInsights(metrics = {}, milestones = [], extra = {}) {
  const insights = [];
  const validationIssues = extra.validationIssues || [];

  if (metrics.hasDependencyCycle) {
    insights.push({
      id: "dependency-cycle",
      tone: "rose",
      title: "Dependency loop detected",
      copy: "Critical-path analysis is paused until circular links are removed.",
    });
  } else if (metrics.scheduleIssueCount > 0) {
    const first = validationIssues[0];
    insights.push({
      id: "schedule-validation",
      tone: "amber",
      title: `${metrics.scheduleIssueCount} schedule check${metrics.scheduleIssueCount === 1 ? "" : "s"} need review`,
      copy: first ? first.copy : "Align milestone dates with finish-to-start dependencies.",
    });
  }

  if (metrics.onCriticalPath > 0 && !metrics.hasDependencyCycle) {
    insights.push({
      id: "critical-path",
      tone: "rose",
      title: `${metrics.onCriticalPath} on critical path`,
      copy:
        metrics.projectDurationDays > 0
          ? `Longest path spans ${metrics.projectDurationDays} days — protect zero-slack milestones.`
          : "Protect critical-path milestones from scope churn and resource contention.",
    });
  }

  if (metrics.atRisk > 0) {
    insights.push({
      id: "at-risk",
      tone: "amber",
      title: `${metrics.atRisk} milestone${metrics.atRisk === 1 ? "" : "s"} at risk`,
      copy: "Review owners and dependencies before the next steering checkpoint.",
    });
  }
  const blocked = milestones.filter((row) => row.status === MILESTONE_STATUSES.BLOCKED);
  if (blocked.length > 0) {
    insights.push({
      id: "blocked",
      tone: "rose",
      title: `${blocked.length} blocked`,
      copy: blocked[0].name ? `${blocked[0].name} needs escalation.` : "Escalate blocked milestones.",
    });
  }
  if (!insights.length && metrics.total > 0) {
    insights.push({
      id: "healthy",
      tone: "green",
      title: "Delivery schedule stable",
      copy: `${metrics.completionRate}% of milestones complete with ${metrics.dependencyCount} tracked dependencies.`,
    });
  }
  return insights.slice(0, 3);
}

export function validateDependencyLink(dependencies = [], link = {}) {
  if (!link.predecessorId || !link.successorId) {
    return { valid: false, reason: "Predecessor and successor are required." };
  }
  if (link.predecessorId === link.successorId) {
    return { valid: false, reason: "A milestone cannot depend on itself." };
  }
  const duplicate = dependencies.some(
    (row) => row.predecessorId === link.predecessorId && row.successorId === link.successorId
  );
  if (duplicate) {
    return { valid: false, reason: "This dependency already exists." };
  }

  const graph = {};
  dependencies.forEach((row) => {
    if (!graph[row.predecessorId]) {
      graph[row.predecessorId] = [];
    }
    graph[row.predecessorId].push(row.successorId);
  });
  if (!graph[link.predecessorId]) {
    graph[link.predecessorId] = [];
  }
  graph[link.predecessorId].push(link.successorId);

  const visiting = new Set();
  const visited = new Set();
  function hasCycle(node) {
    if (visiting.has(node)) {
      return true;
    }
    if (visited.has(node)) {
      return false;
    }
    visiting.add(node);
    const next = graph[node] || [];
    for (let i = 0; i < next.length; i += 1) {
      if (hasCycle(next[i])) {
        return true;
      }
    }
    visiting.delete(node);
    visited.add(node);
    return false;
  }

  if (hasCycle(link.successorId)) {
    return { valid: false, reason: "Dependency would create a circular chain." };
  }

  return { valid: true, reason: null };
}

const MONTH_LABELS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

export function parseGovernanceDate(value) {
  if (!value) {
    return null;
  }
  const parts = String(value).slice(0, 10).split("-");
  if (parts.length < 3) {
    return null;
  }
  const year = Number(parts[0]);
  const month = Number(parts[1]) - 1;
  const day = Number(parts[2]);
  if (!year || month < 0 || day < 1) {
    return null;
  }
  return new Date(year, month, day);
}

export function formatGovernanceDate(date) {
  if (!date || !(date instanceof Date) || Number.isNaN(date.getTime())) {
    return null;
  }
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

export function daysBetweenDates(startDate, endDate) {
  const start = parseGovernanceDate(startDate);
  const end = parseGovernanceDate(endDate);
  if (!start || !end) {
    return 0;
  }
  return Math.round((end.getTime() - start.getTime()) / 86400000);
}

export function shiftMilestoneSchedule(milestone, deltaDays) {
  const start = parseGovernanceDate(milestone.plannedStart);
  const end = parseGovernanceDate(milestone.plannedEnd);
  if (!start || !end || !deltaDays) {
    return {
      plannedStart: milestone.plannedStart,
      plannedEnd: milestone.plannedEnd,
    };
  }
  start.setDate(start.getDate() + deltaDays);
  end.setDate(end.getDate() + deltaDays);
  return {
    plannedStart: formatGovernanceDate(start),
    plannedEnd: formatGovernanceDate(end),
  };
}

function addDays(date, count) {
  const next = new Date(date.getTime());
  next.setDate(next.getDate() + count);
  return next;
}

function buildMonthSlots(horizonStart, totalDays) {
  const slots = [];
  let cursor = new Date(horizonStart.getFullYear(), horizonStart.getMonth(), 1);
  const horizonEnd = addDays(horizonStart, totalDays);

  while (cursor < horizonEnd) {
    const monthStart = cursor < horizonStart ? horizonStart : cursor;
    const nextMonth = new Date(cursor.getFullYear(), cursor.getMonth() + 1, 1);
    const monthEnd = nextMonth < horizonEnd ? nextMonth : horizonEnd;
    const startOffset = daysBetweenDates(formatGovernanceDate(horizonStart), formatGovernanceDate(monthStart));
    const span = Math.max(1, daysBetweenDates(formatGovernanceDate(monthStart), formatGovernanceDate(monthEnd)));
    slots.push({
      id: `${cursor.getFullYear()}-${cursor.getMonth()}`,
      label: `${MONTH_LABELS[cursor.getMonth()]} ${String(cursor.getFullYear()).slice(2)}`,
      startOffset,
      span,
    });
    cursor = nextMonth;
  }

  return slots;
}

export function buildDeliveryGanttModel(milestones = [], dependencies = [], options = {}) {
  const projectId = options.projectId && options.projectId !== "ALL" ? options.projectId : null;
  const analysis = computeCriticalPathAnalysis(milestones, dependencies, { projectId: projectId || "ALL" });
  const criticalMilestoneSet = new Set(analysis.criticalMilestoneIds);
  const criticalDependencySet = new Set(analysis.criticalDependencyIds);
  let rows = enrichMilestonesWithScheduleAnalysis(milestones, dependencies, { projectId: projectId || "ALL" });
  if (projectId) {
    rows = rows.filter((row) => row.projectId === projectId);
  }
  rows = rows.sort((a, b) => String(a.plannedStart || "").localeCompare(String(b.plannedStart || "")));

  if (!rows.length) {
    return {
      rows: [],
      links: [],
      slots: [],
      totalDays: 1,
      todayOffset: null,
      horizonStart: null,
      horizonEnd: null,
    };
  }

  let minDate = null;
  let maxDate = null;
  rows.forEach((row) => {
    const start = parseGovernanceDate(row.plannedStart);
    const end = parseGovernanceDate(row.plannedEnd) || start;
    if (start && (!minDate || start < minDate)) {
      minDate = start;
    }
    if (end && (!maxDate || end > maxDate)) {
      maxDate = end;
    }
  });

  const padDays = options.padDays != null ? options.padDays : 7;
  const horizonStart = addDays(minDate, -padDays);
  const horizonEnd = addDays(maxDate, padDays);
  const totalDays = Math.max(1, daysBetweenDates(formatGovernanceDate(horizonStart), formatGovernanceDate(horizonEnd)));

  const today = new Date();
  today.setHours(0, 0, 0, 0);
  let todayOffset = null;
  if (today >= horizonStart && today <= horizonEnd) {
    todayOffset = daysBetweenDates(formatGovernanceDate(horizonStart), formatGovernanceDate(today));
  }

  const milestoneIndex = {};
  const ganttRows = rows.map((milestone, index) => {
    milestoneIndex[milestone.id] = index;
    const start = parseGovernanceDate(milestone.plannedStart);
    const end = parseGovernanceDate(milestone.plannedEnd) || start;
    const startOffset = daysBetweenDates(formatGovernanceDate(horizonStart), formatGovernanceDate(start));
    const durationDays = Math.max(1, daysBetweenDates(formatGovernanceDate(start), formatGovernanceDate(end)) + 1);
    const progressPct = Math.min(100, Math.max(0, milestone.percentComplete || 0));

    return {
      milestone: {
        ...milestone,
        onCriticalPath: criticalMilestoneSet.has(milestone.id),
      },
      rowIndex: index,
      bar: {
        left: startOffset,
        width: durationDays,
        progressWidth: Math.round((durationDays * progressPct) / 100),
      },
    };
  });

  const scopedDeps = (dependencies || []).filter((dep) => {
    if (!dep.predecessorId || !dep.successorId) {
      return false;
    }
    if (projectId && dep.projectId && dep.projectId !== projectId) {
      return false;
    }
    return milestoneIndex[dep.predecessorId] != null && milestoneIndex[dep.successorId] != null;
  });

  const links = scopedDeps.map((dep) => {
    const fromRow = ganttRows[milestoneIndex[dep.predecessorId]];
    const toRow = ganttRows[milestoneIndex[dep.successorId]];
    return {
      id: dep.id,
      predecessorId: dep.predecessorId,
      successorId: dep.successorId,
      isCritical: criticalDependencySet.has(dep.id),
      from: {
        rowIndex: fromRow.rowIndex,
        x: fromRow.bar.left + fromRow.bar.width,
      },
      to: {
        rowIndex: toRow.rowIndex,
        x: toRow.bar.left,
      },
    };
  });

  return {
    rows: ganttRows,
    links,
    slots: buildMonthSlots(horizonStart, totalDays),
    totalDays,
    todayOffset,
    horizonStart: formatGovernanceDate(horizonStart),
    horizonEnd: formatGovernanceDate(horizonEnd),
    criticalMilestoneIds: analysis.criticalMilestoneIds,
    criticalDependencyIds: analysis.criticalDependencyIds,
    hasDependencyCycle: analysis.hasCycle,
  };
}

