export function filterRisks(rows = [], filters = {}) {
  let list = Array.isArray(rows) ? [...rows] : [];
  if (filters.projectId) {
    list = list.filter((row) => row.projectId === filters.projectId);
  }
  if (filters.severity && filters.severity !== "ALL") {
    list = list.filter((row) => row.severity === filters.severity);
  }
  if (filters.status && filters.status !== "ALL") {
    list = list.filter((row) => row.status === filters.status);
  }
  if (filters.query) {
    const q = String(filters.query).trim().toLowerCase();
    list = list.filter(
      (row) =>
        (row.title && row.title.toLowerCase().includes(q)) ||
        (row.projectName && row.projectName.toLowerCase().includes(q)) ||
        (row.ownerName && row.ownerName.toLowerCase().includes(q)) ||
        (row.mitigationPlan && row.mitigationPlan.toLowerCase().includes(q))
    );
  }
  return list.sort((a, b) => {
    const weightDiff = (RISK_SEVERITY_WEIGHT[b.severity] || 0) - (RISK_SEVERITY_WEIGHT[a.severity] || 0);
    if (weightDiff !== 0) {
      return weightDiff;
    }
    return String(a.dueDate || "").localeCompare(String(b.dueDate || ""));
  });
}

