export function buildRiskMetrics(risks = []) {
  const total = risks.length;
  const open = risks.filter((row) => row.status !== RISK_STATUSES.CLOSED).length;
  const escalated = risks.filter((row) => row.status === RISK_STATUSES.ESCALATED).length;
  const highOrCritical = risks.filter(
    (row) =>
      row.status !== RISK_STATUSES.CLOSED &&
      (row.severity === RISK_SEVERITIES.HIGH || row.severity === RISK_SEVERITIES.CRITICAL)
  ).length;
  const overdue = risks.filter((row) => {
    if (row.status === RISK_STATUSES.CLOSED || !row.dueDate) {
      return false;
    }
    const due = parseGovernanceDate(row.dueDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return due && due < today;
  }).length;

  return {
    total,
    open,
    escalated,
    highOrCritical,
    overdue,
    closed: total - open,
    mitigationRate: total > 0 ? Math.round(((total - open) / total) * 100) : 0,
  };
}

