export function buildRiskHeatmap(risks = [], options = {}) {
  const scoped = options.projectId && options.projectId !== "ALL"
    ? risks.filter((row) => row.projectId === options.projectId)
    : risks;
  const openRisks = scoped.filter((row) => row.status !== RISK_STATUSES.CLOSED);
  const projects = buildProjectOptionsFromRisks(openRisks).filter((row) => row.id !== "ALL");
  const severities = [
    RISK_SEVERITIES.CRITICAL,
    RISK_SEVERITIES.HIGH,
    RISK_SEVERITIES.MEDIUM,
    RISK_SEVERITIES.LOW,
  ];

  const cells = projects.map((project) => {
    const projectRisks = openRisks.filter((row) => row.projectId === project.id);
    const counts = {};
    severities.forEach((severity) => {
      counts[severity] = projectRisks.filter((row) => row.severity === severity).length;
    });
    const exposureScore = projectRisks.reduce(
      (sum, row) => sum + (RISK_SEVERITY_WEIGHT[row.severity] || 0),
      0
    );
    return {
      projectId: project.id,
      projectLabel: project.label,
      counts,
      total: projectRisks.length,
      exposureScore,
    };
  });

  return {
    severities,
    rows: cells.sort((a, b) => b.exposureScore - a.exposureScore),
    maxExposure: Math.max(1, ...cells.map((row) => row.exposureScore)),
  };
}

