export function buildIssueMetrics(issues = [], actions = []) {
  const openIssues = issues.filter((row) => isIssueOpen(row.status));
  const p1 = openIssues.filter((row) => row.priority === ISSUE_PRIORITIES.P1).length;
  const overdueIssues = openIssues.filter((row) => {
    if (!row.dueDate) {
      return false;
    }
    const due = parseGovernanceDate(row.dueDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return due && due < today;
  }).length;

  const openActions = (actions || []).filter((row) => row.status !== ISSUE_ACTION_STATUSES.COMPLETE);
  const overdueActions = openActions.filter((row) => {
    if (!row.dueDate) {
      return false;
    }
    const due = parseGovernanceDate(row.dueDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return due && due < today;
  }).length;
  const completedActions = (actions || []).filter((row) => row.status === ISSUE_ACTION_STATUSES.COMPLETE);
  const slaMet = completedActions.filter((row) => {
    if (!row.completedAt || !row.dueDate) {
      return true;
    }
    return row.completedAt <= row.dueDate;
  }).length;
  const actionSlaRate =
    completedActions.length > 0 ? Math.round((slaMet / completedActions.length) * 100) : 100;

  return {
    total: issues.length,
    open: openIssues.length,
    p1,
    overdueIssues,
    openActions: openActions.length,
    overdueActions,
    actionSlaRate,
    avgAgeDays:
      openIssues.length > 0
        ? Math.round(openIssues.reduce((sum, row) => sum + daysOpen(row), 0) / openIssues.length)
        : 0,
  };
}

