export function buildIssueAgingModel(issues = [], options = {}) {
  const scoped =
    options.projectId && options.projectId !== "ALL"
      ? issues.filter((row) => row.projectId === options.projectId)
      : issues;
  const openIssues = scoped.filter((row) => isIssueOpen(row.status));
  const buckets = [
    { id: "0-7", label: "0–7 days", min: 0, max: 7, count: 0 },
    { id: "8-14", label: "8–14 days", min: 8, max: 14, count: 0 },
    { id: "15+", label: "15+ days", min: 15, max: 999, count: 0 },
  ];

  openIssues.forEach((issue) => {
    const age = daysOpen(issue);
    const bucket = buckets.find((row) => age >= row.min && age <= row.max) || buckets[2];
    bucket.count += 1;
  });

  const maxCount = Math.max(1, ...buckets.map((row) => row.count));
  return { buckets, maxCount, openCount: openIssues.length };
}

