export function buildGateMetrics(gates = []) {
  const total = gates.length;
  const pending = gates.filter((row) => row.status === GATE_STATUSES.PENDING).length;
  const approved = gates.filter((row) => row.status === GATE_STATUSES.APPROVED).length;
  const rejected = gates.filter((row) => row.status === GATE_STATUSES.REJECTED).length;
  const waived = gates.filter((row) => row.status === GATE_STATUSES.WAIVED).length;
  const overdue = gates.filter((row) => {
    if (row.status !== GATE_STATUSES.PENDING || !row.dueDate) {
      return false;
    }
    const due = parseGovernanceDate(row.dueDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return due && due < today;
  }).length;
  const decided = approved + rejected + waived;

  return {
    total,
    pending,
    approved,
    rejected,
    waived,
    overdue,
    complianceRate: total > 0 ? Math.round((approved / total) * 100) : 0,
    decisionRate: total > 0 ? Math.round((decided / total) * 100) : 0,
  };
}

