export function buildGateComplianceModel(gates = [], options = {}) {
  const scoped =
    options.projectId && options.projectId !== "ALL"
      ? gates.filter((row) => row.projectId === options.projectId)
      : gates;
  const stages = Object.values(GATE_STAGES);
  const statuses = [
    GATE_STATUSES.APPROVED,
    GATE_STATUSES.PENDING,
    GATE_STATUSES.REJECTED,
    GATE_STATUSES.WAIVED,
  ];

  const rows = stages
    .map((stage) => {
      const stageGates = scoped.filter((row) => row.stage === stage);
      if (!stageGates.length) {
        return null;
      }
      const counts = {};
      statuses.forEach((status) => {
        counts[status] = stageGates.filter((row) => row.status === status).length;
      });
      return {
        stage,
        total: stageGates.length,
        counts,
        approvedPct: Math.round(((counts[GATE_STATUSES.APPROVED] || 0) / stageGates.length) * 100),
      };
    })
    .filter(Boolean);

  return {
    statuses,
    rows,
    overallApprovedPct: scoped.length
      ? Math.round(
          (scoped.filter((row) => row.status === GATE_STATUSES.APPROVED).length / scoped.length) * 100
        )
      : 0,
  };
}

