/* F15-T8 — Governance analytics */

function daysVariance(plannedEnd, actualEnd) {
  if (!plannedEnd) {
    return 0;
  }
  const planned = parseGovernanceDate(plannedEnd);
  const actual = actualEnd ? parseGovernanceDate(actualEnd) : new Date();
  if (!planned || !actual) {
    return 0;
  }
  return Math.round((actual.getTime() - planned.getTime()) / (1000 * 60 * 60 * 24));
}

export function buildPlannedVsActualModel(milestones = [], options = {}) {
  const scoped = scopeMilestonesForProject(milestones, options.projectId);
  const rows = scoped
    .filter((row) => row.plannedEnd)
    .slice(0, 8)
    .map((row) => {
      const variance = daysVariance(row.plannedEnd, row.actualEnd);
      const plannedDays = milestoneDurationDays(row);
      const actualDays =
        row.actualStart && row.actualEnd
          ? Math.max(1, daysBetweenDates(row.actualStart, row.actualEnd) + 1)
          : row.status === MILESTONE_STATUSES.COMPLETE
            ? plannedDays
            : Math.round(plannedDays * ((row.percentComplete || 0) / 100));
      return {
        id: row.id,
        label: row.name,
        plannedDays,
        actualDays,
        varianceDays: variance,
        status: row.status,
      };
    });
  const maxDays = Math.max(1, ...rows.map((row) => Math.max(row.plannedDays, row.actualDays)));
  const avgVariance =
    rows.length > 0
      ? Math.round(rows.reduce((sum, row) => sum + row.varianceDays, 0) / rows.length)
      : 0;
  return { rows, maxDays, avgVarianceDays: avgVariance };
}

export function buildGovernanceAnalyticsDashboard(context = {}) {
  const {
    milestones = [],
    dependencies = [],
    risks = [],
    issues = [],
    actions = [],
    gates = [],
    decisions = [],
    changes = [],
    options = {},
  } = context;

  const milestoneMetrics = buildMilestoneMetrics(milestones, dependencies, options);
  const riskMetrics = buildRiskMetrics(risks);
  const issueMetrics = buildIssueMetrics(issues, actions);
  const gateMetrics = buildGateMetrics(gates);
  const decisionMetrics = buildDecisionMetrics(decisions);
  const changeMetrics = buildChangeMetrics(changes);
  const plannedVsActual = buildPlannedVsActualModel(milestones, options);
  const issueAging = buildIssueAgingModel(issues, options);
  const gateCompliance = buildGateComplianceModel(gates, options);
  const riskHeatmap = buildRiskHeatmap(risks);

  const healthFactors = [
    milestoneMetrics.completionRate,
    100 - Math.min(100, Math.abs(plannedVsActual.avgVarianceDays) * 3),
    riskMetrics.open > 0 ? Math.max(0, 100 - riskMetrics.open * 8) : 100,
    issueMetrics.actionSlaRate,
    gateMetrics.complianceRate,
    changeMetrics.approvalRate,
  ];
  const healthScore = Math.round(
    healthFactors.reduce((sum, value) => sum + value, 0) / healthFactors.length
  );

  return {
    healthScore,
    milestoneMetrics,
    riskMetrics,
    issueMetrics,
    gateMetrics,
    decisionMetrics,
    changeMetrics,
    plannedVsActual,
    issueAging,
    gateCompliance,
    riskHeatmap,
    criticalPathDays: milestoneMetrics.projectDurationDays,
    scheduleIssueCount: milestoneMetrics.scheduleIssueCount,
  };
}

/* F15-T9 — AI WBS/risk draft import */

export function buildGovernanceAiDraftSummary(draft) {
  if (!draft) {
    return null;
  }
  const parts = [];
  if (draft.milestones && draft.milestones.length) {
    parts.push(`${draft.milestones.length} milestone${draft.milestones.length === 1 ? "" : "s"}`);
  }
  if (draft.dependencies && draft.dependencies.length) {
    parts.push(`${draft.dependencies.length} dependenc${draft.dependencies.length === 1 ? "y" : "ies"}`);
  }
  if (draft.risks && draft.risks.length) {
    parts.push(`${draft.risks.length} risk${draft.risks.length === 1 ? "" : "s"}`);
  }
  return {
    itemCount: (draft.milestones || []).length + (draft.dependencies || []).length + (draft.risks || []).length,
    breakdown: parts.join(", ") || "No draft items",
    confidencePct: Math.round((draft.confidence || 0) * 100),
  };
}

export function validateAiDraftImport(draft) {
  if (!draft) {
    return { valid: false, reason: "Draft not found." };
  }
  if (draft.status !== AI_DRAFT_STATUSES.PENDING) {
    return { valid: false, reason: "Only pending drafts can be imported." };
  }
  if (!(draft.milestones && draft.milestones.length)) {
    return { valid: false, reason: "Draft must include at least one milestone." };
  }
  return { valid: true, reason: null };
}

export function mapAiDraftToImportPayload(draft) {
  const summary = buildGovernanceAiDraftSummary(draft);
  return {
    projectId: draft.projectId,
    projectCode: draft.projectCode,
    projectName: draft.projectName,
    milestones: draft.milestones || [],
    dependencies: draft.dependencies || [],
    risks: draft.risks || [],
    summary: summary.breakdown,
  };
}

/* F15-T10 — Performance helpers */

export function generateLargeGovernanceDataset(milestoneCount = 400, projectCount = 4) {
  const milestones = [];
  const dependencies = [];
  const projects = Array.from({ length: projectCount }, (_, index) => ({
    id: `proj-perf-${index + 1}`,
    code: `PRF-${index + 1}`,
    name: `Performance Program ${index + 1}`,
  }));

  for (let i = 0; i < milestoneCount; i += 1) {
    const project = projects[i % projectCount];
    const startOffset = i * 3;
    const endOffset = startOffset + 5;
    const start = addDaysToGovernanceDate("2026-01-01", startOffset);
    const end = addDaysToGovernanceDate("2026-01-01", endOffset);
    milestones.push({
      id: `ms-perf-${i + 1}`,
      projectId: project.id,
      projectCode: project.code,
      projectName: project.name,
      name: `Milestone ${i + 1}`,
      plannedStart: start,
      plannedEnd: end,
      status: i % 5 === 0 ? MILESTONE_STATUSES.COMPLETE : MILESTONE_STATUSES.PLANNED,
      percentComplete: i % 5 === 0 ? 100 : 0,
      ownerName: `Owner ${(i % 12) + 1}`,
    });
    if (i > 0 && i % 2 === 0 && i < milestoneCount - 1) {
      dependencies.push({
        id: `dep-perf-${i}`,
        projectId: project.id,
        predecessorId: `ms-perf-${i}`,
        successorId: `ms-perf-${i + 1}`,
        predecessorName: `Milestone ${i}`,
        successorName: `Milestone ${i + 1}`,
        type: DEPENDENCY_TYPES.FINISH_TO_START,
        lagDays: 0,
      });
    }
  }

  return { milestones, dependencies, projects };
}
