import moment from "moment";
import dateUtils from "_helpers/date.utils";

export function isFeedbackCampaignExpired(item) {
  if (!item || !item.expiryDate) return false;
  return dateUtils.compareTwoMoments(moment(item.expiryDate).endOf("day"), moment()) === 1;
}

export function countRecipientStatuses(feedbackRequestInfos) {
  const infos = feedbackRequestInfos || [];
  let received = 0;
  let requested = 0;
  let draft = 0;
  let reviewed = 0;
  let closed = 0;

  infos.forEach((info) => {
    const status = String(info.status || "").toUpperCase();
    if (status === "DRAFT") draft += 1;
    else if (status === "REQUESTED") requested += 1;
    else if (status === "RECEIVED") received += 1;
    else if (status === "REVIEWED") reviewed += 1;
    else if (status === "CLOSED") closed += 1;
  });

  const responded = received + reviewed + closed;
  return {
    total: infos.length,
    received,
    requested,
    draft,
    reviewed,
    closed,
    responded,
    awaiting: Math.max(0, infos.length - responded),
  };
}

export function buildFeedbackSummary(items) {
  const list = items || [];
  let recipients = 0;
  let responded = 0;
  let awaiting = 0;
  let expiredCampaigns = 0;
  const byType = {};

  list.forEach((item) => {
    const typeKey = item.type || "OTHER";
    byType[typeKey] = (byType[typeKey] || 0) + 1;
    if (item.recurring !== true && isFeedbackCampaignExpired(item)) {
      expiredCampaigns += 1;
    }
    const counts = countRecipientStatuses(item.feedbackRequestInfos);
    recipients += counts.total;
    responded += counts.responded;
    awaiting += counts.awaiting;
  });

  const active = list.filter((item) => item.active !== false).length;
  const recurring = list.filter((item) => item.recurring === true).length;

  return {
    total: list.length,
    active,
    inactive: list.length - active,
    recurring,
    oneOff: list.length - recurring,
    recipients,
    responded,
    awaiting,
    expiredCampaigns,
    responseRate: recipients > 0 ? Math.round((responded / recipients) * 100) : 0,
    byType,
  };
}

export function getFeedbackTypeLabel(type) {
  const labels = {
    PROJECT: "Projects",
    PURCHASE_ORDER: "Purchase orders",
    EMPLOYEE: "Employees",
    BID: "Bids",
  };
  return labels[type] || type || "Other";
}

export const FEEDBACK_STATUS_META = {
  DRAFT: { label: "Draft", tone: "draft", icon: "fe-edit-3" },
  REQUESTED: { label: "Requested", tone: "requested", icon: "fe-send" },
  RECEIVED: { label: "Received", tone: "received", icon: "fe-inbox" },
  REVIEWED: { label: "Reviewed", tone: "reviewed", icon: "fe-check-circle" },
  CLOSED: { label: "Closed", tone: "closed", icon: "fe-archive" },
};

export function getRecipientStatusMeta(status) {
  const key = String(status || "").toUpperCase();
  return FEEDBACK_STATUS_META[key] || { label: key || "—", tone: "default", icon: "fe-help-circle" };
}

/** Initials for recipient avatar chips. */
export function getRecipientInitials(name, email) {
  const source = String(name || "").trim() || String(email || "").trim();
  if (!source) return "?";
  const parts = source.split(/[\s@._-]+/).filter(Boolean);
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return `${parts[0][0] || ""}${parts[1][0] || ""}`.toUpperCase();
}

/** Human-readable campaign status for list rows and popover header. */
export function getCampaignStatusSummary(item) {
  if (!item) {
    return { label: "Unknown", tone: "default", icon: "fe-help-circle", hint: "" };
  }
  if (item.recurring === true) {
    return item.active !== false
      ? { label: "Recurring · Active", tone: "recurring", icon: "fe-repeat", hint: "Scheduled campaign" }
      : { label: "Recurring · Paused", tone: "paused", icon: "fe-pause-circle", hint: "Turn on to resume sends" };
  }
  if (item.active === false) {
    return { label: "Inactive", tone: "off", icon: "fe-pause-circle", hint: "Campaign is disabled" };
  }
  if (isFeedbackCampaignExpired(item)) {
    return { label: "Expired", tone: "expired", icon: "fe-alert-circle", hint: "Past expiry date" };
  }

  const counts = countRecipientStatuses(item.feedbackRequestInfos);
  if (counts.total === 0) {
    return { label: "No recipients", tone: "empty", icon: "fe-users", hint: "Add people to request feedback" };
  }
  if (counts.draft > 0) {
    return {
      label: "Draft",
      tone: "draft",
      icon: "fe-edit-3",
      hint: `${counts.draft} recipient${counts.draft === 1 ? "" : "s"} not sent yet`,
    };
  }
  if (counts.requested > 0) {
    return {
      label: "Awaiting response",
      tone: "requested",
      icon: "fe-send",
      hint: `${counts.requested} waiting for reply`,
    };
  }
  if (counts.closed === counts.total) {
    return { label: "Closed", tone: "closed", icon: "fe-archive", hint: "All responses closed" };
  }
  if (counts.reviewed > 0 && counts.reviewed + counts.closed === counts.total) {
    return { label: "Reviewed", tone: "reviewed", icon: "fe-check-circle", hint: "Ready to close out" };
  }
  if (counts.responded === counts.total) {
    return { label: "All received", tone: "received", icon: "fe-inbox", hint: "Every recipient responded" };
  }
  return {
    label: "In progress",
    tone: "progress",
    icon: "fe-activity",
    hint: `${counts.responded} of ${counts.total} responded`,
  };
}
