import React from "react";
import { Link, withRouter } from "react-router-dom";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { MODULE_DEFINITIONS } from "config/navigation.config";

/**
 * F01-T7: Empty / access state when a module has no visible menu items or route.
 */
function ModuleEmptyState({ moduleId, pathname, moduleName: moduleNameProp, history }) {
  const moduleDef = MODULE_DEFINITIONS.find((m) => m.id === moduleId);
  const label = moduleNameProp || (moduleDef && moduleDef.label) || "Module";

  return (
    <div className="lux-module-empty">
      <LuxRegisterEmptyState
        variant="employees"
        eyebrow="Navigation"
        title={`${label} module`}
        description={`No pages are available in ${label} for your role, persona, and organization settings yet.`}
        hints={[
          "Check that the module is enabled for your organization",
          "Your persona may hide operational modules — try switching view if allowed",
          pathname ? `Requested path: ${pathname}` : null,
        ].filter(Boolean)}
        showSecondary
        secondaryLabel="Go to workspace home"
        secondaryIcon="fe fe-home"
        onSecondary={() => history.push("/workspace/home")}
        showCreate
        createLabel="View profile settings"
        createIcon="fe fe-settings"
        onCreate={() => history.push("/people/settings")}
      />
      <p className="lux-module-empty__help">
        Need access? <Link to="/people/settings">Contact your administrator</Link>
      </p>
    </div>
  );
}

export function ModuleEmptyStateHelp({ moduleId }) {
  const moduleDef = MODULE_DEFINITIONS.find((m) => m.id === moduleId);
  if (!moduleDef) {
    return null;
  }
  return (
    <p className="lux-module-empty__help">
      Need access to {moduleDef.label}? <Link to="/people/settings">Contact your administrator</Link>
    </p>
  );
}

export default withRouter(ModuleEmptyState);
