import React from "react";
import classNames from "classnames/bind";
import PageInnerHeaderTeamsSelectionMenu from "views/common/fragments/PageInnerHeaderTeamsSelectionMenu";
import { MANAGER_SCOPE } from "./employeeDashboard.utils";

function DashboardTeamScopeBar({
  userTeams,
  teamScopeLabel,
  managerScope,
  showFilter,
  canViewAllEmployees,
  canSwitchTeams,
  loading,
  onScopeChange,
  onFilterChange,
  onUserTeamsSelection,
}) {
  return (
    <div className="lux-hrms-dash__scope-bar">
      <div className="lux-hrms-dash__scope-main">
        <span className="lux-hrms-dash__scope-eyebrow">Viewing</span>
        <strong className="lux-hrms-dash__scope-label">{teamScopeLabel}</strong>
      </div>

      <div className="lux-hrms-dash__scope-actions">
        {canViewAllEmployees && (
          <div className="lux-hrms-dash__scope-group" role="group" aria-label="Employee scope">
            <button
              type="button"
              className={classNames("lux-hrms-dash__scope-chip", {
                "is-active": managerScope === MANAGER_SCOPE.TEAMS,
              })}
              onClick={() => onScopeChange && onScopeChange(MANAGER_SCOPE.TEAMS)}
            >
              My teams
            </button>
            <button
              type="button"
              className={classNames("lux-hrms-dash__scope-chip", {
                "is-active": managerScope === MANAGER_SCOPE.ALL,
              })}
              onClick={() => onScopeChange && onScopeChange(MANAGER_SCOPE.ALL)}
            >
              All employees
            </button>
          </div>
        )}

        {managerScope === MANAGER_SCOPE.TEAMS && canSwitchTeams && userTeams && userTeams.length > 1 && (
          <PageInnerHeaderTeamsSelectionMenu
            userTeams={userTeams}
            enabled={canSwitchTeams}
            isLoading={loading}
            handleUserTeamsSelection={onUserTeamsSelection}
          />
        )}

        {managerScope === MANAGER_SCOPE.TEAMS && (!canSwitchTeams || !userTeams || userTeams.length <= 1) && (
          <span className="lux-hrms-dash__scope-team-badge">
            <i className="fe fe-briefcase" aria-hidden="true" />
            {teamScopeLabel}
          </span>
        )}

        <div className="lux-hrms-dash__filter-group" role="group" aria-label="Roster filter">
          {[
            { value: "ACTIVE", label: "Active" },
            { value: "ALL", label: "All" },
            { value: "INACTIVE", label: "Inactive" },
          ].map((opt) => (
            <button
              key={opt.value}
              type="button"
              className={classNames("lux-hrms-dash__filter-chip", {
                "is-active": showFilter === opt.value,
              })}
              onClick={() => onFilterChange && onFilterChange(opt.value)}
            >
              {opt.label}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

export default DashboardTeamScopeBar;
