import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import {
  SETUP_AUTOMATION_PLAYBOOK,
  buildSetupChecklistProgress,
  enrichSetupChecklistItems,
} from "config/customer-setup-checklist.config";
import { commonUtils } from "_helpers";
import { appConfigService } from "_services/appconfig.service";
import {
  AdminActionButton,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";
import AdminInsightsSummary from "views/admin/components/AdminInsightsSummary";
import AdminLoadAlert from "views/admin/components/AdminLoadAlert";
import SetupChecklistRegister from "views/admin/components/SetupChecklistRegister";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

const FILTERS = [
  { id: "ALL", label: "All" },
  { id: "OPEN", label: "Open" },
  { id: "DONE", label: "Done" },
  { id: "AUTOMATE", label: "Automatable" },
];

/**
 * W0A / CUST-008 / MIG-001 — luxury one-time customer implementation checklist.
 */
class CustomerSetupChecklistPage extends Component {
  state = {
    loading: true,
    saving: false,
    loadError: null,
    items: [],
    summary: {},
    dataSource: null,
    filter: "ALL",
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Setup checklist");
    }
    this.loadChecklist();
  }

  loadChecklist = async () => {
    const teamId = commonUtils.getCurrentUserTeamId();
    this.setState({ loading: true, loadError: null });
    try {
      const response = await appConfigService.getImplementationChecklist(teamId);
      const payload = (response && response.payload) || response || {};
      this.setState({
        loading: false,
        items: Array.isArray(payload.items) ? payload.items : [],
        summary: {
          total: payload.total,
          done: payload.done,
          remaining: payload.remaining,
          complete: payload.complete,
        },
        dataSource: payload.source || "application-config",
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load implementation checklist.",
        items: [],
      });
    }
  };

  toggleItem = async (itemId) => {
    const { items, saving } = this.state;
    if (saving) return;
    const nextItems = items.map((row) =>
      row.id === itemId ? { ...row, done: !row.done } : row
    );
    this.setState({ saving: true, items: nextItems, loadError: null });
    try {
      const teamId = commonUtils.getCurrentUserTeamId();
      const response = await appConfigService.updateImplementationChecklist(teamId, {
        items: nextItems,
      });
      const payload = (response && response.payload) || response || {};
      this.setState({
        saving: false,
        items: Array.isArray(payload.items) ? payload.items : nextItems,
        summary: {
          total: payload.total,
          done: payload.done,
          remaining: payload.remaining,
          complete: payload.complete,
        },
        dataSource: payload.source || "application-config",
      });
    } catch (e) {
      this.setState({ saving: false, loadError: "Unable to save checklist progress." });
      this.loadChecklist();
    }
  };

  render() {
    const { loading, saving, loadError, items, summary, dataSource, filter } = this.state;
    const progress = buildSetupChecklistProgress(items);
    const enriched = enrichSetupChecklistItems(items);
    const nextOpen = progress.nextOpen;

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.setupChecklist}
        dataSource={dataSource}
        loading={loading}
        testId="page-admin-setup-checklist"
        className="lux-admin-page lux-setup-checklist-page"
        onRefresh={this.loadChecklist}
        refreshLoading={loading}
        heroActions={<><AdminActionButton
              to="/admin/industry-templates"
              icon="fe fe-package"
              variant="secondary"
            >
              Automate with templates
            </AdminActionButton>
            <AdminActionButton to="/admin/appconfig" icon="fe fe-settings" variant="ghost">
              Application config
            </AdminActionButton>
          </>}
      >
        <AdminInsightsSummary
          storageKey="famstack-setup-checklist-summary-expanded"
          domainClass="lux-admin-summary--setup"
          loading={loading}
          eyebrow="Day-one activation"
          eyebrowIcon="fe-check-square"
          title="Setup checklist insights"
          compactTitle={`${progress.done}/${progress.total || "—"} done · ${progress.pct}% · ${
            progress.remaining
          } open`}
          collapsedLine={`${progress.automatable} automatable · ${progress.assisted} assisted · ${progress.manual} manual`}
          subtitle="One-time customer implementation checklist persisted in Application Config — not an isolated table."
          kpis={[
            {
              key: "done",
              label: "Completed",
              value: progress.done,
              hint: `of ${progress.total || 0} steps`,
              tone: progress.done ? "green" : "slate",
              icon: "fe fe-check-circle",
            },
            {
              key: "remaining",
              label: "Remaining",
              value: progress.remaining,
              hint: progress.complete ? "All closed" : "Still open",
              tone: progress.remaining ? "amber" : "green",
              icon: "fe fe-clock",
            },
            {
              key: "auto",
              label: "Automatable",
              value: progress.automatable,
              hint: "Template / import assisted",
              tone: "violet",
              icon: "fe fe-cpu",
            },
            {
              key: "status",
              label: "Status",
              value: progress.complete ? "Complete" : "In progress",
              hint: "Day-one gate",
              tone: progress.complete ? "green" : "blue",
              icon: "fe fe-flag",
            },
          ]}
          highlights={[
            {
              key: "assisted",
              label: "Assisted steps",
              value: progress.assisted,
              hint: "UI + human review",
              tone: "indigo",
              icon: "fe fe-sliders",
            },
            {
              key: "manual",
              label: "Manual gates",
              value: progress.manual,
              hint: "Security / sign-off",
              tone: "slate",
              icon: "fe fe-user-check",
            },
          ]}
          attention={
            loading
              ? []
              : progress.complete
                ? [
                    {
                      id: "complete",
                      eyebrow: "Ready",
                      stat: "100%",
                      title: "Activation checklist complete",
                      copy: "Cutover sign-off captured in Application Config. Keep reports with the go-live pack.",
                      hint: "Continue in App Config for ongoing admin.",
                      icon: "fe fe-check-circle",
                      tone: "green",
                    },
                  ]
                : nextOpen
                  ? [
                      {
                        id: "next",
                        eyebrow: "Next",
                        stat: nextOpen.id,
                        title: nextOpen.label,
                        copy: nextOpen.summary || "Open the related console and docs, then mark done.",
                        hint: nextOpen.automationHint || "Follow the How guidance on the step card.",
                        icon: "fe fe-arrow-right",
                        tone: "amber",
                      },
                    ]
                  : []
          }
          mixInsights={[
            {
              key: "automation-mix",
              icon: "fe fe-cpu",
              title: "Automation posture",
              subtitle: "How each step can be completed",
              mix: [
                {
                  key: "automate",
                  label: "Automate",
                  count: progress.automatable,
                  pct: Math.round(
                    (progress.automatable / Math.max(progress.total, 1)) * 100
                  ),
                  tone: "violet",
                },
                {
                  key: "assisted",
                  label: "Assisted",
                  count: progress.assisted,
                  pct: Math.round((progress.assisted / Math.max(progress.total, 1)) * 100),
                  tone: "indigo",
                },
                {
                  key: "manual",
                  label: "Manual",
                  count: progress.manual,
                  pct: Math.round((progress.manual / Math.max(progress.total, 1)) * 100),
                  tone: "slate",
                },
              ],
            },
          ]}
          series={[
            {
              id: "progress",
              title: "Checklist progress",
              subtitle: "Open vs done",
              rows: enriched.slice(0, 8).map((row) => ({
                key: row.id,
                label: row.id,
                icon: row.done ? "fe fe-check" : "fe fe-circle",
                tone: row.done ? "green" : "amber",
                value: row.done ? 1 : 0,
                pct: row.done ? 100 : 18,
                meta: row.done ? "Done" : "Open",
              })),
            },
          ]}
          testId="setup-checklist-insights"
        />

        <section
          className="lux-admin-atelier lux-admin-atelier--setup lux-admin-atelier--compact"
          data-testid="setup-checklist-atelier"
        >
          <header className="lux-admin-atelier__masthead">
            <div className="lux-admin-atelier__masthead-main">
              <span className="lux-admin-atelier__mark" aria-hidden="true">
                <i className="fe fe-check-square" />
              </span>
              <div className="lux-admin-atelier__masthead-copy">
                <div className="lux-admin-atelier__title-row">
                  <p className="lux-admin-atelier__eyebrow">One-time setup</p>
                  <h2 className="lux-admin-atelier__title">Implementation checklist</h2>
                </div>
                <p className="lux-admin-atelier__lede">
                  Phased day-one steps · docs · console links · automation playbook
                </p>
              </div>
            </div>
            <div className="lux-admin-atelier__masthead-aside">
              <a
                className="lux-admin-panel-link"
                href="/documentation/user-guide/admin/index.html"
                target="_blank"
                rel="noopener noreferrer"
              >
                Admin docs hub
                <i className="fe fe-external-link" aria-hidden="true" />
              </a>
              <span className="lux-admin-atelier__count">
                <strong>{progress.pct}%</strong>
                <em>ready</em>
              </span>
            </div>
          </header>

          <div className="lux-admin-atelier__body">
            <AdminLoadAlert
              error={loadError}
              fallback="Unable to load implementation checklist."
              onDismiss={() => this.setState({ loadError: null })}
              testId="setup-checklist-load-alert"
            />

            <div className="lux-setup-checklist__automation" data-testid="setup-automation-playbook">
              <header className="lux-setup-checklist__automation-head">
                <div>
                  <p className="lux-setup-checklist__eyebrow">Automation</p>
                  <h3>How setup can be automated</h3>
                  <p>
                    Prefer Industry templates and import dry-runs for repeatable work. Security proofs
                    and final sign-off stay human.
                  </p>
                </div>
              </header>
              <div className="lux-setup-checklist__automation-grid">
                {SETUP_AUTOMATION_PLAYBOOK.map((card) => (
                  <article
                    key={card.id}
                    className={classNames("lux-setup-checklist__auto-card", `is-${card.tone}`)}
                  >
                    <span className="lux-setup-checklist__auto-icon" aria-hidden="true">
                      <i className={card.icon} />
                    </span>
                    <div className="lux-setup-checklist__auto-copy">
                      <div className="lux-setup-checklist__auto-top">
                        <strong>{card.title}</strong>
                        <em>{card.status}</em>
                      </div>
                      <p>{card.copy}</p>
                      <span className="lux-setup-checklist__auto-covers">
                        Covers {card.covers.join(" · ")}
                      </span>
                      <div className="lux-setup-checklist__auto-links">
                        <Link to={card.to}>
                          Open <i className="fe fe-arrow-right" aria-hidden="true" />
                        </Link>
                        <a href={card.docHref} target="_blank" rel="noopener noreferrer">
                          Docs <i className="fe fe-external-link" aria-hidden="true" />
                        </a>
                      </div>
                    </div>
                  </article>
                ))}
              </div>
            </div>

            <div className="lux-admin-atelier__stage-card lux-setup-checklist__stage">
              <div className="lux-setup-checklist__toolbar">
                <div>
                  <p className="lux-setup-checklist__eyebrow">Checklist</p>
                  <h3>Customer implementation steps</h3>
                  <p>
                    Stored as{" "}
                    <code>HRMS.implementationChecklist</code> on Application Config — mark done as you
                    finish each gate.
                  </p>
                </div>
                <div className="lux-setup-checklist__filters" role="group" aria-label="Filter steps">
                  {FILTERS.map((item) => (
                    <button
                      key={item.id}
                      type="button"
                      className={classNames("lux-setup-checklist__filter", {
                        "is-active": filter === item.id,
                      })}
                      onClick={() => this.setState({ filter: item.id })}
                    >
                      {item.label}
                    </button>
                  ))}
                </div>
              </div>

              {loading ? (
                <LuxRegisterEmptyState
                  className="lux-register-empty--compact"
                  eyebrow="Setup"
                  title="Loading checklist"
                  description="Fetching implementation steps from Application Config."
                />
              ) : !items.length ? (
                <LuxRegisterEmptyState
                  className="lux-register-empty--compact"
                  eyebrow="Setup"
                  title="No checklist items"
                  description="No implementation steps were returned for this team."
                  hints={[
                    "Confirm Application Config is available for your team",
                    "Refresh to retry the checklist load",
                  ]}
                />
              ) : (
                <SetupChecklistRegister
                  items={items}
                  saving={saving}
                  onToggle={this.toggleItem}
                  filter={filter}
                />
              )}

              {!loading && (summary.complete || progress.complete) ? (
                <p className="lux-setup-checklist__complete-note" role="status">
                  Checklist complete — archive validation reports with the cutover pack, then continue
                  in Application Config for ongoing admin.
                </p>
              ) : null}
            </div>
          </div>
        </section>
      </AdminLuxPage>
    );
  }
}

export default CustomerSetupChecklistPage;
