import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import DashboardApexChart from "views/hrms/components/dashboard/DashboardApexChart";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import CountUp from "react-countup";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";

const SUMMARY_STORAGE_KEY = "famstack-employees-summary-expanded";

class EmployeePageSummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = {
      expanded: readSummaryExpanded(SUMMARY_STORAGE_KEY),
    };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => {
        writeSummaryExpanded(SUMMARY_STORAGE_KEY, this.state.expanded);
      }
    );
  };

  getShowFilter = () => {
    const options = this.props.filterOptions;
    return (options && options.SHOW && options.SHOW.selected) || "ACTIVE";
  };

  quickFilter = (value) => {
    if (this.props.onQuickFilter) {
      this.props.onQuickFilter(value);
    }
  };

  buildContextLine = (stat, visibleCount, filterOptions) => {
    const parts = [];
    parts.push(
      stat.selectedTeams > 0
        ? `${stat.selectedTeams} team${stat.selectedTeams === 1 ? "" : "s"} selected`
        : "All teams"
    );
    if (visibleCount !== stat.total) {
      parts.push(`${visibleCount} of ${stat.total} shown`);
    }
    if (filterOptions && filterOptions.filterText) {
      parts.push(`matching “${filterOptions.filterText}”`);
    }
    if (stat.exits30 > 0) {
      parts.push(`${stat.exits30} exit${stat.exits30 === 1 ? "" : "s"} in 30 days`);
    }
    return parts.join(" · ");
  };

  renderFilterChips = (showFilter, compact) => (
    <div
      className={classNames("lux-emp-summary__filters", {
        "lux-emp-summary__filters--compact": compact,
      })}
      role="group"
      aria-label="Filter by status"
    >
      {[
        { value: "ALL", label: "All" },
        { value: "ACTIVE", label: "Active" },
        { value: "INACTIVE", label: "Inactive" },
      ].map((option) => (
        <button
          key={option.value}
          type="button"
          className={classNames("lux-emp-summary__filter-chip", {
            "is-active": showFilter === option.value,
          })}
          onClick={() => this.quickFilter(option.value)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );

  renderKpiStrip = (stat) => (
    <div className="lux-emp-summary__grid" role="list" aria-label="Workforce key metrics">
      {stat.kpis.map((kpi) => (
        <article
          key={kpi.key}
          className={classNames("lux-emp-summary__metric", kpi.tone && `lux-emp-summary__metric--${kpi.tone}`)}
          role="listitem"
        >
          <span className="lux-emp-summary__metric-icon" aria-hidden="true">
            <i className={kpi.icon} />
          </span>
          <div className="lux-emp-summary__metric-body">
            <span className="lux-emp-summary__metric-label">{kpi.label}</span>
            <strong className="lux-emp-summary__metric-value">
              <CountUp end={kpi.value} duration={0.85} />
            </strong>
            {kpi.hint && <span className="lux-emp-summary__metric-hint">{kpi.hint}</span>}
          </div>
        </article>
      ))}
    </div>
  );

  renderHighlights = (stat) => (
    <div className="lux-emp-workforce-summary__highlights" role="list" aria-label="Workforce highlights">
      {stat.highlights.map((item) => (
        <article
          key={item.key}
          className={classNames("lux-emp-workforce-summary__highlight", item.tone && `is-${item.tone}`)}
          role="listitem"
        >
          <span className="lux-emp-workforce-summary__highlight-icon" aria-hidden="true">
            <i className={item.icon} />
          </span>
          <div className="lux-emp-workforce-summary__highlight-copy">
            <span className="lux-emp-workforce-summary__highlight-label">{item.label}</span>
            <strong>
              {item.display != null ? (
                item.display
              ) : (
                <CountUp end={item.value} duration={0.75} />
              )}
            </strong>
            <span className="lux-emp-workforce-summary__highlight-hint">{item.hint}</span>
          </div>
        </article>
      ))}
    </div>
  );

  renderInsightChart = (
    title,
    subtitle,
    chart,
    emptyMessage,
    { height = 132, chartType = "donut" } = {}
  ) => (
    <article className="lux-emp-summary__insight lux-emp-summary__insight--chart">
      <header>
        <i className="fe fe-bar-chart-2" aria-hidden="true" />
        <div>
          <strong>{title}</strong>
          <span>{subtitle}</span>
        </div>
      </header>
      <div className="lux-emp-summary__insight-chart">
        {!chart && <p className="lux-emp-summary__insight-chart-empty">{emptyMessage}</p>}
        {chart && (
          <DashboardApexChart
            type={chartType}
            series={chart.series}
            options={chart.options}
            height={height}
          />
        )}
      </div>
    </article>
  );

  renderInsightCard = (insight) => (
    <article key={insight.key} className="lux-emp-summary__insight">
      <header>
        <i className={insight.icon} aria-hidden="true" />
        <div>
          <strong>{insight.title}</strong>
          <span>{insight.subtitle}</span>
        </div>
      </header>
      {!insight.mix || !insight.mix.length ? (
        <div className="lux-emp-summary__bar lux-emp-summary__bar--empty">{insight.emptyLabel}</div>
      ) : (
        <>
          <div className="lux-emp-summary__bar" aria-hidden="true">
            {insight.mix.map((segment) => (
              <span
                key={segment.key || segment.label}
                className={classNames("lux-emp-summary__bar-segment", `is-${segment.tone}`)}
                style={{ width: `${Math.max(segment.pct, segment.count > 0 ? 4 : 0)}%` }}
                title={`${segment.label}: ${segment.count} (${segment.pct}%)`}
              />
            ))}
          </div>
          <ul className="lux-emp-summary__legend">
            {insight.mix.map((segment) => (
              <li key={segment.key || segment.label}>
                <span className={classNames("lux-emp-summary__legend-dot", `is-${segment.tone}`)} />
                <span className="lux-emp-summary__legend-label">{segment.label}</span>
                <strong>{segment.count}</strong>
                <span className="lux-emp-summary__legend-pct">{segment.pct}%</span>
              </li>
            ))}
          </ul>
        </>
      )}
    </article>
  );

  renderTenureFlow = (stat) => (
    <div className="lux-emp-workforce-summary__tenure-flow" aria-label="Tenure distribution">
      {stat.tenureBuckets.map((bucket, index, arr) => (
        <React.Fragment key={bucket.key}>
          <div className={classNames("lux-emp-workforce-summary__tenure-node", `is-${bucket.tone}`)}>
            <span className="lux-emp-workforce-summary__tenure-node-label">{bucket.label}</span>
            <strong>
              <CountUp end={bucket.count} duration={0.7} />
            </strong>
          </div>
          {index < arr.length - 1 && (
            <span className="lux-emp-workforce-summary__tenure-connector" aria-hidden="true">
              <i className="fe fe-chevron-right" />
            </span>
          )}
        </React.Fragment>
      ))}
    </div>
  );

  renderChartPanel = (
    title,
    subtitle,
    chart,
    emptyMessage,
    { height = 168, wide = false, chartType = "donut", compactHead = false } = {}
  ) => (
    <article
      className={classNames("lux-bid-summary__chart-panel", {
        "lux-bid-summary__chart-panel--wide": wide,
        "lux-bid-summary__chart-panel--compact": compactHead,
      })}
    >
      <div className="lux-bid-summary__panel-head">
        <div>
          <h3 className="lux-bid-summary__panel-title">{title}</h3>
          {!compactHead && subtitle && (
            <p className="lux-bid-summary__panel-sub">{subtitle}</p>
          )}
        </div>
      </div>
      <div className="lux-bid-summary__chart-body">
        {!chart && <p className="lux-bid-summary__chart-empty">{emptyMessage}</p>}
        {chart && (
          <DashboardApexChart
            type={chartType}
            series={chart.series}
            options={chart.options}
            height={height}
          />
        )}
      </div>
    </article>
  );

  renderSkeleton = () => (
    <SkeletonTheme baseColor="#f1f5f9" highlightColor="#e2e8f0">
      <div className="lux-emp-summary lux-emp-workforce-summary is-loading">
        <Skeleton height={72} borderRadius={16} />
        <div className="lux-emp-summary__grid lux-emp-summary__grid--skeleton">
          {[1, 2, 3, 4, 5, 6].map((key) => (
            <Skeleton key={key} height={64} borderRadius={14} />
          ))}
        </div>
        <div className="lux-emp-summary__insights lux-emp-summary__insights--skeleton">
          {[1, 2, 3].map((key) => (
            <Skeleton key={key} height={140} borderRadius={14} />
          ))}
        </div>
        <div className="lux-emp-workforce-summary__charts--skeleton">
          {[1, 2, 3].map((key) => (
            <Skeleton key={key} height={180} borderRadius={14} />
          ))}
        </div>
      </div>
    </SkeletonTheme>
  );

  renderHero = (stat, showFilter, visibleCount, filterOptions) => (
    <header className="lux-emp-summary__hero">
      <div className="lux-emp-summary__hero-main">
        <div className="lux-emp-summary__hero-copy">
          <h2 className="lux-emp-summary__title">
            <CountUp end={stat.total} duration={0.9} />{" "}
            <span>people in scope</span>
          </h2>
          <p className="lux-emp-summary__subtitle">
            {this.buildContextLine(stat, visibleCount, filterOptions)}
          </p>
        </div>

        <div className="lux-emp-summary__hero-rate" title={`${stat.active} active · ${stat.inactive} inactive`}>
          <div
            className="lux-emp-summary__rate-ring"
            style={{ "--lux-active-pct": `${stat.activeRate}%` }}
            aria-hidden="true"
          >
            <span>{stat.activeRate}%</span>
          </div>
          <div className="lux-emp-summary__rate-copy">
            <strong>Active rate</strong>
            <span>
              {stat.active} of {stat.total} people
            </span>
          </div>
        </div>

        {this.renderFilterChips(showFilter, false)}
      </div>
    </header>
  );

  render() {
    const { stat, charts, isLoading, visibleCount, filterOptions } = this.props;
    const { expanded } = this.state;
    if (isLoading && (!stat || stat.total === 0)) {
      return this.renderSkeleton();
    }

    const showFilter = this.getShowFilter();
    const chartData = charts || {};

    return (
      <section
        className={classNames("lux-emp-summary lux-emp-workforce-summary", { "is-collapsed": !expanded })}
        aria-label="Employee workforce summary"
      >
        <div className="lux-emp-summary__header-bar">
          <div className="lux-emp-summary__header-main">
            <LuxSummaryEyebrow variant="employees" className="lux-emp-summary__eyebrow">
              Workforce intelligence
            </LuxSummaryEyebrow>
            {!expanded ? (
              <h2 className="lux-emp-summary__title lux-emp-summary__title--compact">
                <CountUp end={stat.total} duration={0.9} />{" "}
                <span>people · {stat.activeRate}% active</span>
              </h2>
            ) : (
              <h2 className="lux-emp-summary__title lux-emp-summary__title--bar">Workforce overview</h2>
            )}
          </div>
          <button
            type="button"
            className="lux-emp-summary__toggle"
            onClick={this.toggleExpanded}
            aria-expanded={expanded}
            aria-controls="lux-emp-summary-body"
            title={expanded ? "Collapse summary" : "Insights"}
          >
            <span>{getSummaryToggleLabel(expanded)}</span>
            <i className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")} aria-hidden="true" />
          </button>
        </div>

        {!expanded && (
          <div className="lux-emp-summary__collapsed-strip">
            <p className="lux-emp-summary__collapsed-line">
              {this.buildContextLine(stat, visibleCount, filterOptions)}
            </p>
            {this.renderFilterChips(showFilter, true)}
          </div>
        )}

        <div
          id="lux-emp-summary-body"
          className="lux-emp-summary__body"
          aria-hidden={!expanded}
        >
          {this.renderHero(stat, showFilter, visibleCount, filterOptions)}

          {this.renderKpiStrip(stat)}

          {this.renderHighlights(stat)}

          <div className="lux-emp-summary__insights">
            {stat.insights.map(this.renderInsightCard)}
            {this.renderInsightChart(
              "Grade & band",
              "Compensation levels across active staff",
              chartData.bandTreemap,
              "No band or grade data",
              { height: 168, chartType: "treemap" }
            )}
          </div>

          {this.renderTenureFlow(stat)}

          <div className="lux-emp-workforce-summary__row lux-emp-workforce-summary__row--hero">
            {this.renderChartPanel(
              "Headcount trend",
              "Active roster over the last 6 months",
              chartData.headcountTrend,
              "No headcount history",
              { height: 176, chartType: "line", wide: true, compactHead: true }
            )}
            {this.renderChartPanel(
              "Joins & exits",
              "Monthly movement in the last 6 months",
              chartData.joinExitTrend,
              "No join or exit activity",
              { height: 176, chartType: "area", compactHead: true }
            )}
            {this.renderChartPanel(
              "Gender mix",
              "Active employees by gender",
              chartData.genderDonut,
              "No gender data",
              { height: 168, compactHead: true }
            )}
          </div>

          <div className="lux-emp-workforce-summary__row lux-emp-workforce-summary__row--structure">
            {this.renderChartPanel(
              "Employment type",
              "Permanent, contract, intern & more",
              chartData.empTypeDonut,
              "No employment type data",
              { height: 168, compactHead: true }
            )}
            {this.renderChartPanel(
              "Tenure bands",
              "How long active employees have been here",
              chartData.tenureBar,
              "No tenure data",
              { height: 168, chartType: "bar", compactHead: true }
            )}
            {this.renderChartPanel(
              "Work locations",
              "Where active employees are based",
              chartData.locationBar,
              "No location data",
              { height: 168, chartType: "bar", compactHead: true }
            )}
          </div>

          <div className="lux-emp-workforce-summary__row lux-emp-workforce-summary__row--skills">
            {this.renderChartPanel(
              "Top skills",
              "Primary skill tags across the roster",
              chartData.skillsBar,
              "No skill tags recorded",
              { height: 172, chartType: "bar", wide: true, compactHead: true }
            )}
            {this.renderChartPanel(
              "Departments & teams",
              "Largest organizational groupings",
              chartData.departmentBar,
              "No department or team data",
              { height: 172, chartType: "bar", compactHead: true }
            )}
          </div>
        </div>
      </section>
    );
  }
}

export default EmployeePageSummary;
