import React from "react";
import classNames from "classnames/bind";

function HealthRing({ score }) {
  const tone = score >= 80 ? "green" : score >= 60 ? "amber" : "rose";
  return (
    <div className={classNames("lux-portfolio-analytics__health", `is-${tone}`)}>
      <strong>{score}</strong>
      <span>Portfolio health</span>
    </div>
  );
}

function bandTone(band) {
  if (band === "HEALTHY") return "green";
  if (band === "WATCH") return "amber";
  if (band === "CRITICAL") return "rose";
  return "slate";
}

export default function PortfolioAnalyticsPanel({ analytics, loading }) {
  if (loading) {
    return <div className="lux-portfolio-analytics lux-portfolio-analytics--loading">Loading portfolio analytics…</div>;
  }

  if (!analytics) {
    return <div className="lux-portfolio-analytics lux-portfolio-analytics--empty">Analytics will populate when project health snapshots are available.</div>;
  }

  return (
    <div className="lux-portfolio-analytics">
      <div className="lux-portfolio-analytics__top">
        <HealthRing score={analytics.healthScore} />
        <div className="lux-portfolio-analytics__kpis">
          <div>
            <strong>{analytics.avgSlippage}d</strong>
            <span>Avg slippage</span>
          </div>
          <div>
            <strong>{(analytics.programHealth || []).length}</strong>
            <span>Programs tracked</span>
          </div>
          <div>
            <strong>{(analytics.healthRows || []).length}</strong>
            <span>Projects governed</span>
          </div>
        </div>
      </div>

      <section className="lux-portfolio-analytics__section">
        <header>
          <h3>Project health distribution</h3>
        </header>
        <div className="lux-portfolio-analytics__bars">
          {(analytics.healthRows || []).map((row) => (
            <div key={row.id} className="lux-portfolio-analytics__bar-row">
              <span className="lux-portfolio-analytics__label">{row.label}</span>
              <div className="lux-portfolio-analytics__track">
                <div
                  className={classNames("lux-portfolio-analytics__fill", `is-${bandTone(row.band)}`)}
                  style={{ width: `${Math.round((row.value / analytics.maxHealth) * 100)}%` }}
                />
              </div>
              <span className="lux-portfolio-analytics__value">{row.value}%</span>
            </div>
          ))}
        </div>
      </section>

      <section className="lux-portfolio-analytics__section">
        <header>
          <h3>Schedule slippage</h3>
        </header>
        <div className="lux-portfolio-analytics__bars">
          {(analytics.slippageRows || []).map((row) => (
            <div key={row.id} className="lux-portfolio-analytics__bar-row">
              <span className="lux-portfolio-analytics__label">{row.label}</span>
              <div className="lux-portfolio-analytics__track">
                <div
                  className="lux-portfolio-analytics__fill is-amber"
                  style={{ width: `${Math.round((row.days / analytics.maxSlippage) * 100)}%` }}
                />
              </div>
              <span className="lux-portfolio-analytics__value">{row.days}d</span>
            </div>
          ))}
        </div>
      </section>

      <section className="lux-portfolio-analytics__section">
        <header>
          <h3>Program health</h3>
        </header>
        <div className="lux-portfolio-analytics__program-grid">
          {(analytics.programHealth || []).map((row) => (
            <div key={row.id} className="lux-portfolio-analytics__program">
              <strong>{row.label}</strong>
              <span>{row.healthScore}%</span>
              <small>{row.status ? row.status.replace(/_/g, " ") : "—"}</small>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}
