async function testTrigger(ruleId, triggerContext) {
  if (!shouldUseWorkflowAutomationApi()) {
    return apiErrorResult(null);
  }
  const userTeamId = commonUtils.getCurrentUserTeamId();
  const actorId = commonUtils.getCurrentUserId();
  const response = await axiosUtils.post(
    `${urlConfig.WORKFLOW_AUTOMATION_API_PATH}/rules/${encodeURIComponent(ruleId)}/test-trigger?userTeamId=${userTeamId}&actorId=${actorId}&adminPersona=true`,
    triggerContext || { source: "test-trigger" }
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

