import { Component } from "react";
import { withRouter } from "react-router-dom";
import {
  captureDeliverableDetailsReturn,
  isDeliverableDetailsPath,
} from "views/project/deliverableDetailsNavigation.utils";

/**
 * Remembers the route visited immediately before opening deliverable details.
 */
class DeliverableDetailsReturnTracker extends Component {
  componentDidUpdate(prevProps) {
    const { location } = this.props;
    const prev = prevProps.location;
    if (!location || !prev) return;

    const entering =
      isDeliverableDetailsPath(location.pathname) &&
      !isDeliverableDetailsPath(prev.pathname);

    if (entering) {
      captureDeliverableDetailsReturn(prev.pathname, prev.search);
    }
  }

  render() {
    return null;
  }
}

export default withRouter(DeliverableDetailsReturnTracker);
