import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { accessUtils } from "_helpers";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import { isPayrollManagementEnabled } from "config/payroll.config";
import { resolvePayrollCheckFix } from "config/payroll-config.utils";
import { formatPayrollDate } from "config/payroll.utils";
import { payrollService } from "_services/payroll.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import {
  AdminActionButton,
  AdminPanelHead,
  AdminPanelLink,
  AdminLuxPage,
  AdminQuickNav,
  AdminInsightStrip,
} from "views/admin/components/AdminLuxShared";
import AdminLoadAlert from "views/admin/components/AdminLoadAlert";
import { PayrollHubNav } from "views/payroll/components/PayrollLuxShared";

const SETUP_LINKS = [
  {
    path: "/payroll/groups",
    label: "Payroll groups",
    desc: "Pay frequency, lock day, and pay calendar",
    icon: "fe fe-users",
    tone: "green",
  },
  {
    path: "/payroll/salary-structures",
    label: "Salary structures",
    desc: "Earning and deduction component templates",
    icon: "fe fe-sliders",
    tone: "violet",
  },
  {
    path: "/payroll/deductions",
    label: "Deduction register",
    desc: "Employee deduction schedules",
    icon: "fe fe-minus-circle",
    tone: "amber",
  },
  {
    path: "/admin/appconfig",
    label: "Application config",
    desc: "Org payroll flags and publishing modules",
    icon: "fe fe-settings",
    tone: "indigo",
  },
  {
    path: "/payroll/runs",
    label: "Payroll runs",
    desc: "Start a cycle once readiness is green",
    icon: "fe fe-layers",
    tone: "blue",
  },
  {
    path: "/workspace/approvals",
    label: "Approvals inbox",
    desc: "Clear leave, timesheet, and attendance gates",
    icon: "fe fe-check-circle",
    tone: "cyan",
  },
];

class PayrollConfigPage extends Component {
  state = { config: null, loading: true, loadError: null, dataSource: null };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Payroll readiness");
    this.loadConfig();
  }

  loadConfig = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await payrollService.getPayrollConfig();
      this.setState({
        config: result.payload || {},
        loading: false,
        dataSource: result.source,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load payroll configuration.",
        config: null,
      });
    }
  };

  renderScoreCard = (config) => {
    const score = (config && config.readinessScore) || 0;
    const passed = (config && config.checksPassed) || 0;
    const total = (config && config.checksTotal) || 0;
    const ready = config && config.readyToRun;
    const tone = ready ? "green" : score >= 70 ? "amber" : "rose";

    return (
      <section className={classNames("lux-payroll-config__score", `is-${tone}`)} aria-label="Readiness score">
        <div className="lux-payroll-config__score-main">
          <span className="lux-payroll-config__score-eyebrow">Cycle readiness</span>
          <strong className="lux-payroll-config__score-value">{score}%</strong>
          <p className="lux-payroll-config__score-copy">
            {ready
              ? "All mandatory gates passed — safe to start a payroll run."
              : `${passed} of ${total} mandatory checks passed. Resolve blockers before locking a cycle.`}
          </p>
        </div>
        <div className="lux-payroll-config__score-meter" aria-hidden="true">
          <span style={{ width: `${Math.max(score, 4)}%` }} />
        </div>
        <div className="lux-payroll-config__score-actions">
          <AdminActionButton
            to={ready ? "/payroll/runs" : "/payroll/groups"}
            icon={ready ? "fe fe-play-circle" : "fe fe-tool"}
            variant={ready ? "primary" : "ghost"}
          >
            {ready ? "Open payroll runs" : "Fix setup"}
          </AdminActionButton>
          <AdminActionButton icon="fe fe-refresh-cw" variant="ghost" onClick={this.loadConfig}>
            Recheck
          </AdminActionButton>
        </div>
      </section>
    );
  };

  renderChecks = (checks, loading) => {
    if (loading) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          title="Loading checks"
          description="Fetching payroll readiness validation."
        />
      );
    }
    if (!checks.length) {
      return (
        <LuxRegisterEmptyState
          title="No readiness checks"
          description="Refresh to reload validation from payroll config."
        />
      );
    }

    return (
      <ul className="lux-payroll-config__checks">
        {checks.map((check) => {
          const fix = resolvePayrollCheckFix(check);
          const passed = !!check.passed;
          return (
            <li
              key={check.id || check.label}
              className={classNames("lux-payroll-config__check", {
                "is-pass": passed,
                "is-fail": !passed,
              })}
            >
              <span className="lux-payroll-config__check-icon" aria-hidden="true">
                <i className={passed ? "fe fe-check-circle" : "fe fe-alert-triangle"} />
              </span>
              <div className="lux-payroll-config__check-copy">
                <strong>{check.label}</strong>
                <span>{passed ? "Ready" : "Blocker — action required"}</span>
              </div>
              {!passed ? (
                <Link to={fix.path} className="lux-payroll-config__check-fix">
                  {fix.label}
                  <i className="fe fe-arrow-right" aria-hidden="true" />
                </Link>
              ) : (
                <span className="lux-payroll-config__check-ok">Cleared</span>
              )}
            </li>
          );
        })}
      </ul>
    );
  };

  renderGroups = (groups, loading) => {
    if (loading) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          title="Loading groups"
          description="Fetching payroll group configuration."
        />
      );
    }
    if (!groups.length) {
      return (
        <div className="lux-payroll-config__empty">
          <LuxRegisterEmptyState
            title="No payroll groups yet"
            description="Create at least one group before you can run payroll."
          />
          <div className="lux-payroll-config__empty-actions">
            <AdminActionButton to="/payroll/groups" icon="fe fe-plus">
              Create group
            </AdminActionButton>
          </div>
        </div>
      );
    }

    return (
      <div className="lux-admin-register-wrap">
        <table className="lux-admin-register lux-payroll-config__groups">
          <thead>
            <tr>
              <th>Group</th>
              <th>Frequency</th>
              <th>Lock day</th>
              <th>Next pay</th>
              <th>Status</th>
              <th />
            </tr>
          </thead>
          <tbody>
            {groups.map((g) => (
              <tr key={g.id || g.code || g.name}>
                <td>
                  <div className="lux-payroll-config__group-name">
                    <strong>{g.name || "—"}</strong>
                    {g.code && <span>{g.code}</span>}
                  </div>
                </td>
                <td>{g.payFrequency || "—"}</td>
                <td>{g.lockDay != null ? g.lockDay : "—"}</td>
                <td>{formatPayrollDate(g.nextPayDate) || "—"}</td>
                <td>
                  <span
                    className={classNames(
                      "lux-doc-badge",
                      String(g.status || "Active").toLowerCase() === "active" ? "is-green" : "is-slate"
                    )}
                  >
                    {g.status || "Active"}
                  </span>
                </td>
                <td>
                  <Link to="/payroll/groups" className="lux-admin-panel-link">
                    Manage
                    <i className="fe fe-arrow-right" aria-hidden="true" />
                  </Link>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  };

  render() {
    const adminModules = accessUtils.getAccessControll("adminModules") || {};
    if (!isPayrollManagementEnabled() || adminModules.payrollConfigEnabled === false) {
      return (
        <PersonaAccessDenied
          moduleName="Payroll readiness"
          reason="Payroll readiness admin is not enabled."
        />
      );
    }

    const { config, loading, loadError, dataSource } = this.state;
    const groups = (config && config.groups) || [];
    const checks = (config && config.mandatoryChecks) || [];
    const passed = (config && config.checksPassed) || 0;
    const total = (config && config.checksTotal) || checks.length;

    const kpiCards = [
      {
        id: "score",
        label: "Readiness",
        value: loading ? "…" : `${(config && config.readinessScore) || 0}%`,
        hint: "Mandatory gates",
        tone: config && config.readyToRun ? "green" : "amber",
        icon: "fe fe-shield",
      },
      {
        id: "groups",
        label: "Payroll groups",
        value: groups.length,
        hint: "Configured cohorts",
        tone: "blue",
        icon: "fe fe-users",
      },
      {
        id: "deductions",
        label: "Deduction schedules",
        value: (config && config.deductionScheduleCount) || 0,
        hint: "Employee finance",
        tone: "violet",
        icon: "fe fe-minus-circle",
      },
      {
        id: "paychecks",
        label: "Paychecks",
        value: config && config.paychecksEnabled ? "On" : "Off",
        hint: "Publish module",
        tone: config && config.paychecksEnabled ? "green" : "slate",
        icon: "fe fe-credit-card",
      },
    ];

    const insights = [
      {
        id: "gates",
        tone: passed === total && total > 0 ? "green" : "amber",
        icon: "fe fe-check-square",
        title: `${passed}/${total || 0} gates clear`,
        copy: "Mandatory checks must pass before a run can lock safely.",
        path: null,
      },
      {
        id: "publish",
        tone: config && config.paychecksEnabled ? "green" : "indigo",
        icon: "fe fe-send",
        title: config && config.paychecksEnabled ? "Paychecks enabled" : "Enable paycheck publishing",
        copy: "Turn on paychecks in application config to publish employee slips.",
        path: "/admin/appconfig",
      },
      {
        id: "runs",
        tone: "blue",
        icon: "fe fe-play",
        title: "Ready for a cycle?",
        copy: "Open payroll runs when score is green, or fix setup first.",
        path: "/payroll/runs",
      },
    ];

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.payrollConfig}
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        testId="page-admin-payroll-config"
        className="lux-admin-page lux-payroll-config-page"
        heroNav={<PayrollHubNav />}
        onRefresh={this.loadConfig}
        refreshLoading={loading}
      >
        <AdminLoadAlert
          error={loadError}
          fallback="Unable to load payroll configuration."
          onDismiss={() => this.setState({ loadError: null })}
        />

        {!loading && config && this.renderScoreCard(config)}

        <AdminInsightStrip insights={insights} className="lux-payroll-config__insights" />

        <AdminQuickNav
          className="lux-payroll-config__setup"
          eyebrow="Configure"
          title="Where to edit payroll setup"
          ariaLabel="Payroll setup destinations"
          links={SETUP_LINKS}
        />

        <div className="lux-admin-page__grid lux-admin-page__grid--split lux-payroll-config__grid">
          <section className="lux-admin-panel lux-hrms-dash__panel">
            <AdminPanelHead
              title="Mandatory readiness checks"
              subtitle="Run cannot start safely when blockers remain"
              actions={<AdminPanelLink to="/workspace/approvals">Approvals</AdminPanelLink>}
            />
            {this.renderChecks(checks, loading)}
          </section>

          <section className="lux-admin-panel lux-hrms-dash__panel">
            <AdminPanelHead
              title="Payroll groups"
              subtitle="Pay frequency, lock day, and pay calendar"
              actions={<AdminPanelLink to="/payroll/groups">Manage groups</AdminPanelLink>}
            />
            {this.renderGroups(groups, loading)}
          </section>
        </div>
      </AdminLuxPage>
    );
  }
}

export default PayrollConfigPage;
