import React, { Component } from "react";
import { getQuestionLayoutSpan } from "../../feedbackForm.utils";
import LuxFeedbackQuestionLabel from "./LuxFeedbackQuestionLabel";
import LuxFeedbackStarRating from "./LuxFeedbackStarRating";

class MultiStarsSelectInput extends Component {
  onChange = (name, value) => {
    name = name.trim();
    var answer = this.props.questionConfig.answer || null;
    var answerList = answer ? answer.split(",") : [];
    var index = -1;
    var count = -1;
    answerList.forEach((ans) => {
      count++;
      if (ans.includes(name + "::")) {
        index = count;
      }
    });

    if (index > -1) {
      answerList[index] = (name + "::" + value).trim();
    } else {
      answerList.push((name + "::" + value).trim());
    }

    this.props.onChange({
      ...this.props.questionConfig,
      answer: answerList.join(","),
    });
  };

  getAnswerNameValue = (optionNameValue) => {
    var answer = this.props.questionConfig.answer || null;
    var answerList = answer ? answer.split(",") : [];
    answerList.forEach((ans) => {
      if (ans.includes(optionNameValue + "::")) {
        optionNameValue = ans;
      }
    });
    return optionNameValue;
  };

  getDimensionOptions = (questionConfig) => {
    if (!questionConfig || !questionConfig.questionOptions) return [];
    return questionConfig.questionOptions
      .split(",")
      .map((part) => part.trim())
      .filter(Boolean);
  };

  render() {
    const { questionConfig, readonly } = this.props;
    if (!questionConfig) return null;
    const span = getQuestionLayoutSpan(questionConfig.type);
    const dimensions = this.getDimensionOptions(questionConfig);

    return (
      <div className={`lux-fb-q lux-fb-q--${span} lux-fb-q--multi-rating`}>
        <div className="lux-fb-q__card lux-fb-q__card--multi-rating">
          <div className="lux-fb-multi-rating">
            <LuxFeedbackQuestionLabel questionConfig={questionConfig} />
            <div className="lux-fb-multi-rating__table" role="group" aria-label="Rate each area">
              <div className="lux-fb-multi-rating__head" aria-hidden="true">
                <span className="lux-fb-multi-rating__col lux-fb-multi-rating__col--label">
                  Rating area
                </span>
                <span className="lux-fb-multi-rating__col lux-fb-multi-rating__col--stars">
                  Your score (tap 1–5 stars)
                </span>
                <span className="lux-fb-multi-rating__col lux-fb-multi-rating__col--score">
                  Score
                </span>
              </div>
              <div className="lux-fb-multi-rating__body">
                {dimensions.map((dimension) => (
                  <SingleRating
                    key={dimension}
                    dimension={dimension}
                    nameValue={this.getAnswerNameValue(dimension)}
                    onChange={this.onChange}
                    readonly={readonly}
                  />
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }
}

class SingleRating extends Component {
  getSelectedStars = () => {
    const parts = (this.props.nameValue || "").split("::");
    return Number(parts[1]) || 0;
  };

  onChange = (stars) => {
    const dimension = (this.props.nameValue || "").split("::")[0];
    this.props.onChange(dimension, stars);
  };

  render() {
    const dimension =
      this.props.dimension || (this.props.nameValue || "").split("::")[0];
    const selected = this.getSelectedStars();

    return (
      <div className="lux-fb-dimension-rating">
        <div className="lux-fb-dimension-rating__title" title={dimension}>
          {dimension}
        </div>
        <div className="lux-fb-dimension-rating__stars-cell">
          <LuxFeedbackStarRating
            variant="matrix"
            value={selected}
            readonly={this.props.readonly}
            onChange={this.onChange}
            showHint={false}
            ariaLabel={`Rate ${dimension}`}
          />
        </div>
        <span className="lux-fb-dimension-rating__score">{selected || "—"}/5</span>
      </div>
    );
  }
}
export default MultiStarsSelectInput;
