import React, { Component } from "react";
import LuxRegisterListSkeletonRows from "views/common/fragments/LuxRegisterListSkeletonRows";
import classNames from "classnames/bind";
import EmployeeInfoLine from "./EmployeeInfoLine";

const LIST_COLUMNS = [
  { key: "employee", label: "Employee", icon: "fe-user" },
  { key: "skill", label: "Primary skill", icon: "fe-award" },
  { key: "type", label: "Type", icon: "fe-briefcase", center: true },
  { key: "email", label: "Email", icon: "fe-mail" },
  { key: "joined", label: "Joined", icon: "fe-calendar" },
  { key: "contact", label: "Contact", icon: "fe-phone" },
  { key: "actions", label: "Actions", icon: null, center: true },
];

class EmployeeListTable extends Component {

  render() {
    return (
      <div className="lux-emp-list" aria-label="Employee list">
        <div className="lux-emp-list__head" role="row">
          {LIST_COLUMNS.map((col) => (
            <div
              key={col.key}
              className={classNamesCol(col)}
              role="columnheader"
            >
              {col.icon ? (
                <span className="lux-emp-list__head-label">
                  <i className={`fe ${col.icon}`} aria-hidden="true" />
                  {col.label}
                </span>
              ) : (
                <span className="lux-emp-list__head-label">{col.label}</span>
              )}
            </div>
          ))}
        </div>

        <div
          className={classNames("lux-emp-list__body", { "is-loading": this.props.isLoading })}
          role="list"
        >
          {this.props.isLoading && <LuxRegisterListSkeletonRows variant="emp" />}
          {!this.props.isLoading &&
            this.props.employees &&
            this.props.employees.map((employee) => (
              <EmployeeInfoLine
                key={employee.id}
                employee={employee}
                handleDeleteEmployee={this.props.handleDeleteEmployee}
                handleEditEmployee={this.props.handleEditEmployee}
                handleActivateEmployee={this.props.handleActivateEmployee}
                handleRemoveEmployee={this.props.handleRemoveEmployee}
                permission={this.props.permission}
              />
            ))}
        </div>
      </div>
    );
  }
}

function classNamesCol(col) {
  const classes = [`lux-emp-list__head-cell`, `lux-emp-list__head-cell--${col.key}`];
  if (col.center) classes.push("is-center");
  return classes.join(" ");
}

export default EmployeeListTable;
