import React from "react";
import classNames from "classnames/bind";
import { getEmployeeInitials } from "config/resource-planning.utils";

export default function ResourceAllocationHeatmap({ rows }) {
  const list = rows || [];
  if (list.length === 0) {
    return <p className="lux-resource-analytics__empty">No allocation data for heatmap.</p>;
  }

  return (
    <div className="lux-resource-analytics__heatmap">
      {list.map((row) => (
        <div key={row.employeeId} className="lux-resource-analytics__heatmap-row">
          <div className="lux-resource-analytics__heatmap-person">
            <span className="lux-resource-analytics__heatmap-avatar" aria-hidden="true">
              {getEmployeeInitials(row.employeeName)}
            </span>
            <span className="lux-resource-analytics__heatmap-name">
              <strong>{row.employeeName}</strong>
              <small>{row.totalPct}% total</small>
            </span>
          </div>
          <div className="lux-resource-analytics__heatmap-cells" role="list">
            {row.cells.map((cell) => (
              <span
                key={cell.id}
                className={classNames("lux-resource-analytics__heatmap-cell", `is-${cell.tone}`)}
                role="listitem"
                title={`${cell.projectName}: ${cell.allocationPct}%`}
              >
                <span className="lux-resource-analytics__heatmap-cell-pct">{cell.allocationPct}%</span>
                <span className="lux-resource-analytics__heatmap-cell-project">{cell.projectName}</span>
              </span>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}
