const STORAGE_KEY = "famstack-return-url";

const ALLOWED_PREFIXES = ["/project", "/people", "/hrms", "/sales", "/report", "/workspace", "/admin", "/finance"];

function isValidReturnPath(pathname) {
  if (!pathname || pathname === "/") return false;
  if (pathname.startsWith("/user")) return false;
  if (pathname.startsWith("/error")) return false;
  return ALLOWED_PREFIXES.some((prefix) => pathname.startsWith(prefix));
}

function toReturnUrl(location) {
  if (!location) return null;

  const pathname = location.pathname || "";
  const search = location.search || "";
  const hash = location.hash || "";

  if (!isValidReturnPath(pathname)) return null;
  return `${pathname}${search}${hash}`;
}

export function saveReturnUrl(location) {
  const url = toReturnUrl(location);
  if (url) {
    sessionStorage.setItem(STORAGE_KEY, url);
  }
}

export function saveReturnUrlFromWindow() {
  if (typeof window === "undefined") return;
  saveReturnUrl({
    pathname: window.location.pathname,
    search: window.location.search,
    hash: window.location.hash,
  });
}

export function peekReturnUrl() {
  if (typeof window === "undefined") return null;
  const url = sessionStorage.getItem(STORAGE_KEY);
  if (!url) return null;

  const pathname = url.split("?")[0].split("#")[0];
  return isValidReturnPath(pathname) ? url : null;
}

export function consumeReturnUrl() {
  const url = peekReturnUrl();
  if (url) {
    sessionStorage.removeItem(STORAGE_KEY);
  }
  return url;
}

export const returnUrlUtils = {
  saveReturnUrl,
  saveReturnUrlFromWindow,
  peekReturnUrl,
  consumeReturnUrl,
};
