import { AI_WORK_INTELLIGENCE_PERSONAS } from "config/ai-work-intelligence.config";

const EXECUTIVE_DOMAINS = new Set(["executive", "governance"]);
const PMO_PERSONAS = new Set(["PMO", "MANAGER", "PROJECT_MANAGER", "RESOURCE_MANAGER", "ADMIN"]);
const FINANCE_PERSONAS = new Set(["FINANCE_MANAGER", "FINANCE"]);
const HR_PERSONAS = new Set(["HR_ADMIN", "PAYROLL_MANAGER", "HR"]);

export function normalizeAiPersona(persona) {
  const key = String(persona || "").toUpperCase();
  if (key === "EXECUTIVE") {
    return AI_WORK_INTELLIGENCE_PERSONAS.EXECUTIVE;
  }
  if (PMO_PERSONAS.has(key)) {
    return AI_WORK_INTELLIGENCE_PERSONAS.PMO;
  }
  if (FINANCE_PERSONAS.has(key)) {
    return AI_WORK_INTELLIGENCE_PERSONAS.FINANCE;
  }
  if (HR_PERSONAS.has(key)) {
    return AI_WORK_INTELLIGENCE_PERSONAS.HR;
  }
  return AI_WORK_INTELLIGENCE_PERSONAS.EMPLOYEE;
}
const FINANCE_DOMAINS = new Set(["payroll", "expense", "executive"]);
const HR_DOMAINS = new Set(["staffing", "payroll"]);

export function canViewAiWorkIntelligence(activePersona) {
  return Boolean(activePersona);
}

export function canRunAgent(activePersona, agent) {
  if (!activePersona || !agent) {
    return false;
  }
  activePersona = normalizeAiPersona(activePersona);
  if (activePersona === AI_WORK_INTELLIGENCE_PERSONAS.EXECUTIVE) {
    return true;
  }
  if (activePersona === AI_WORK_INTELLIGENCE_PERSONAS.PMO) {
    return !EXECUTIVE_DOMAINS.has(agent.domain);
  }
  if (activePersona === AI_WORK_INTELLIGENCE_PERSONAS.FINANCE) {
    return FINANCE_DOMAINS.has(agent.domain);
  }
  if (activePersona === AI_WORK_INTELLIGENCE_PERSONAS.HR) {
    return HR_DOMAINS.has(agent.domain);
  }
  return agent.domain === "wbs";
}

export function canDecideRecommendation(activePersona) {
  activePersona = normalizeAiPersona(activePersona);
  return [
    AI_WORK_INTELLIGENCE_PERSONAS.EXECUTIVE,
    AI_WORK_INTELLIGENCE_PERSONAS.PMO,
    AI_WORK_INTELLIGENCE_PERSONAS.FINANCE,
    AI_WORK_INTELLIGENCE_PERSONAS.HR,
  ].includes(activePersona);
}

export function maskAgentEvidence(evidence, activePersona) {
  if (!Array.isArray(evidence)) {
    return [];
  }
  activePersona = normalizeAiPersona(activePersona);
  if (activePersona === AI_WORK_INTELLIGENCE_PERSONAS.EXECUTIVE) {
    return evidence;
  }
  return evidence.map((item) => ({
    ...item,
    detail: item.sensitive && activePersona !== AI_WORK_INTELLIGENCE_PERSONAS.FINANCE
      ? "Restricted detail — finance or executive persona required"
      : item.detail,
  }));
}
