import React, { Component } from "react";
import { dossierService } from "_services/dossier/dossier.service";
import DossierLuxPage, {
  DossierActionButton,
  DossierLuxPanel,
} from "views/dossiers/components/DossierLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class DossierDetailPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dossier: null,
    completeness: null,
    requiredDocs: [],
    vaultDocumentRef: "",
    requiredDocRef: "",
    reqForm: { docTypeCode: "", title: "" },
    busy: false,
  };

  get dossierRef() {
    const match = this.props.match;
    return match && match.params ? match.params.id : undefined;
  }

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Dossier detail");
    }
    this.load();
  }

  load = async () => {
    const ref = this.dossierRef;
    this.setState({ loading: true, loadError: null });
    const [dossierRes, completenessRes, requiredRes] = await Promise.all([
      dossierService.getDossier(ref),
      dossierService.getCompleteness(ref),
      dossierService.listRequiredDocs(ref),
    ]);
    if (dossierRes.source !== "api") {
      this.setState({
        loading: false,
        loadError: dossierRes.error || new Error("Unable to load dossier"),
      });
      return;
    }
    this.setState({
      loading: false,
      dossier: dossierRes.payload,
      completeness: completenessRes.source === "api" ? completenessRes.payload : null,
      requiredDocs: requiredRes.source === "api" ? requiredRes.payload : [],
    });
  };

  runWorkflow = async (action) => {
    const ref = this.dossierRef;
    this.setState({ busy: true, loadError: null });
    let result;
    if (action === "submit") result = await dossierService.submitReview(ref);
    else if (action === "approve") result = await dossierService.approve(ref);
    else if (action === "reject") result = await dossierService.reject(ref);
    else if (action === "baseline") {
      result = await dossierService.createBaseline(ref, { versionLabel: "v1" });
    }
    this.setState({ busy: false });
    if (result && result.source === "api") this.load();
    else this.setState({ loadError: (result && result.error) || new Error("Action failed") });
  };

  handleAddRequired = async (e) => {
    e.preventDefault();
    const { reqForm } = this.state;
    if (!reqForm.docTypeCode || !reqForm.title) return;
    this.setState({ busy: true });
    const result = await dossierService.createRequiredDoc(this.dossierRef, reqForm);
    this.setState({ busy: false });
    if (result.source === "api") {
      this.setState({ reqForm: { docTypeCode: "", title: "" } });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Required doc failed") });
    }
  };

  handleAttach = async (e) => {
    e.preventDefault();
    const { vaultDocumentRef, requiredDocRef } = this.state;
    if (!vaultDocumentRef) return;
    this.setState({ busy: true });
    const result = await dossierService.attachDocument(this.dossierRef, {
      vaultDocumentRef,
      requiredDocRef: requiredDocRef || undefined,
    });
    this.setState({ busy: false });
    if (result.source === "api") {
      this.setState({ vaultDocumentRef: "", requiredDocRef: "" });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Attach failed") });
    }
  };

  render() {
    const {
      loading,
      loadError,
      dossier,
      completeness,
      requiredDocs,
      vaultDocumentRef,
      requiredDocRef,
      reqForm,
      busy,
    } = this.state;
    const ref = this.dossierRef;
    return (
      <DossierLuxPage
        testId="dossier-detail-page"
        dataSource={dossier ? "api" : loadError ? "api-error" : null}
        loading={loading}
        pageMeta={{
          tone: "slate",
          icon: "fe fe-folder",
          eyebrow: "Projects · Dossier",
          titleLead: dossier ? dossier.title : "Dossier",
          titleAccent: dossier ? dossier.status : "detail",
          lede: dossier
            ? `${dossier.dossierRef}${dossier.description ? ` — ${dossier.description}` : ""}`
            : "Review workflow, required documents, and vault attachments.",
        }}
        heroActions={
          <>
            <DossierActionButton to="/dossiers" icon="fe fe-arrow-left" variant="ghost">
              Dossiers
            </DossierActionButton>
            <DossierActionButton
              to={`/dossiers/${encodeURIComponent(ref)}/sections`}
              icon="fe fe-layers"
              variant="secondary"
            >
              Sections
            </DossierActionButton>
            <DossierActionButton
              to={`/dossiers/${encodeURIComponent(ref)}/export`}
              icon="fe fe-download"
              variant="secondary"
            >
              Export
            </DossierActionButton>
          </>
        }
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load dossier">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
        {!loading && !dossier && !loadError ? (
          <LuxRegisterEmptyState title="Dossier not found" description="No dossier loaded for this reference." showCreate={false} />
        ) : null}
        {dossier ? (
          <>
            {completeness ? (
              <DossierLuxPanel title="Completeness" icon="fe fe-pie-chart">
                <p className="mb-0">
                  <strong>{String(completeness.completenessPct)}%</strong> (
                  {String(completeness.requiredSatisfied)} / {String(completeness.requiredTotal)}{" "}
                  required)
                </p>
              </DossierLuxPanel>
            ) : null}
            <DossierLuxPanel title="Workflow" icon="fe fe-git-branch">
              <div className="d-flex flex-wrap" style={{ gap: 8 }}>
                <DossierActionButton
                  type="button"
                  variant="secondary"
                  className="lux-onb-action--compact"
                  disabled={busy || dossier.status !== "DRAFT"}
                  onClick={() => this.runWorkflow("submit")}
                >
                  Submit review
                </DossierActionButton>
                <DossierActionButton
                  type="button"
                  variant="secondary"
                  className="lux-onb-action--compact"
                  disabled={busy || dossier.status !== "IN_REVIEW"}
                  onClick={() => this.runWorkflow("approve")}
                >
                  Approve
                </DossierActionButton>
                <DossierActionButton
                  type="button"
                  variant="ghost"
                  className="lux-onb-action--compact"
                  disabled={busy || dossier.status !== "IN_REVIEW"}
                  onClick={() => this.runWorkflow("reject")}
                >
                  Reject
                </DossierActionButton>
                <DossierActionButton
                  type="button"
                  variant="ghost"
                  className="lux-onb-action--compact"
                  disabled={busy || (dossier.status !== "APPROVED" && dossier.status !== "BASELINED")}
                  onClick={() => this.runWorkflow("baseline")}
                >
                  Baseline
                </DossierActionButton>
              </div>
            </DossierLuxPanel>
            <DossierLuxPanel title="Required documents" meta={`${requiredDocs.length} item${requiredDocs.length === 1 ? "" : "s"}`} icon="fe fe-file-text">
              <form className="lux-module-inline-form mb-3" onSubmit={this.handleAddRequired}>
                <div className="form-row">
                  <div className="col-md-3">
                    <input
                      className="form-control"
                      placeholder="Doc type"
                      value={reqForm.docTypeCode}
                      onChange={(e) =>
                        this.setState({ reqForm: { ...reqForm, docTypeCode: e.target.value } })
                      }
                    />
                  </div>
                  <div className="col-md-3">
                    <input
                      className="form-control"
                      placeholder="Title"
                      value={reqForm.title}
                      onChange={(e) => this.setState({ reqForm: { ...reqForm, title: e.target.value } })}
                    />
                  </div>
                  <div className="col-md-2">
                    <DossierActionButton type="submit" disabled={busy}>
                      Add required
                    </DossierActionButton>
                  </div>
                </div>
              </form>
              {requiredDocs.length === 0 ? (
                <p className="text-muted small mb-0">No required documents yet.</p>
              ) : (
                <ul className="mb-0">
                  {requiredDocs.map((r) => (
                    <li key={r.requiredRef}>
                      {r.requiredRef}: {r.docTypeCode} — {r.title}
                    </li>
                  ))}
                </ul>
              )}
            </DossierLuxPanel>
            <DossierLuxPanel title="Attach from Document Vault" icon="fe fe-paperclip">
              <form className="lux-module-inline-form" onSubmit={this.handleAttach}>
                <div className="form-row">
                  <div className="col-md-4">
                    <input
                      className="form-control"
                      placeholder="vault_document_ref"
                      value={vaultDocumentRef}
                      onChange={(e) => this.setState({ vaultDocumentRef: e.target.value })}
                    />
                  </div>
                  <div className="col-md-4">
                    <input
                      className="form-control"
                      placeholder="required_doc_ref (optional)"
                      value={requiredDocRef}
                      onChange={(e) => this.setState({ requiredDocRef: e.target.value })}
                    />
                  </div>
                  <div className="col-md-2">
                    <DossierActionButton type="submit" disabled={busy}>
                      Attach
                    </DossierActionButton>
                  </div>
                </div>
              </form>
            </DossierLuxPanel>
          </>
        ) : null}
      </DossierLuxPage>
    );
  }
}

export default DossierDetailPage;
