import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import ProjectDetailsTabShell from "views/project/components/ProjectDetailsTabShell";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import {
  buildProjectAllocations,
  buildProjectsTabStats,
} from "config/employee360Tab.utils";
import { getEmployeeDisplayName } from "config/employee360.utils";

function healthTone(health) {
  const value = String(health || "").toLowerCase();
  if (value.includes("risk")) {
    return "warning";
  }
  if (value.includes("track") || value.includes("plan")) {
    return "success";
  }
  if (value.includes("watch")) {
    return "info";
  }
  return undefined;
}

export default function Employee360ProjectsTab({ employee, summary }) {
  if (!employee) {
    return null;
  }

  const allocations = buildProjectAllocations(summary, employee);
  const stats = buildProjectsTabStats(allocations);
  const displayName = getEmployeeDisplayName(employee);

  return (
    <ProjectDetailsTabShell
      icon="fe fe-layers"
      eyebrow="Delivery"
      title="Project allocations"
      subtitle={`Active project assignments and utilization for ${displayName}.`}
      stats={stats}
      className="lux-employee-360__embed lux-employee-360__embed--projects"
    >
      <div className="lux-employee-360__embed-toolbar">
        <strong className="lux-employee-360__embed-period">
          {allocations.length} active allocation{allocations.length === 1 ? "" : "s"}
        </strong>
        <Link to="/project/capacity" className="lux-employee-360__embed-link">
          Resource capacity
          <i className="fe fe-external-link" aria-hidden="true" />
        </Link>
        <Link to="/project/dashboard" className="lux-employee-360__embed-link">
          Project dashboard
          <i className="fe fe-external-link" aria-hidden="true" />
        </Link>
      </div>

      {allocations.length === 0 ? (
        <>
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-employee-360__embed-empty"
            icon="fe fe-layers"
            title="No project allocations"
            description="This employee is not currently assigned to any active projects. Assign capacity from resource planning when staffing is confirmed."
          />
          <div className="lux-employee-360__embed-toolbar">
            <Link to="/project/capacity" className="lux-employee-360__embed-link">
              View resource allocations
              <i className="fe fe-external-link" aria-hidden="true" />
            </Link>
          </div>
        </>
      ) : (
        <div className="lux-employee-360__register-wrap">
          <table className="lux-employee-360__register">
            <thead>
              <tr>
                <th>Project</th>
                <th>Code</th>
                <th>Role</th>
                <th>Allocation</th>
                <th>Health</th>
                <th>Schedule</th>
              </tr>
            </thead>
            <tbody>
              {allocations.map((row) => (
                <tr key={row.id || row.name}>
                  <td>
                    <strong>{row.name || "—"}</strong>
                    {row.billable === false && (
                      <span className="lux-employee-360__inline-badge">Non-billable</span>
                    )}
                  </td>
                  <td>{row.code || "—"}</td>
                  <td>{row.role || "—"}</td>
                  <td>{row.allocationPct != null ? `${row.allocationPct}%` : "—"}</td>
                  <td>
                    {row.health && row.health !== "—" ? (
                      <span
                        className={classNames(
                          "lux-employee-360__badge",
                          healthTone(row.health) && `is-${healthTone(row.health)}`
                        )}
                      >
                        {row.health}
                      </span>
                    ) : (
                      "—"
                    )}
                  </td>
                  <td>{row.schedule || "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </ProjectDetailsTabShell>
  );
}
