import React, { Component } from "react";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import ClientLuxPage, {
  ClientActionButton,
  ClientLuxPanel,
} from "views/client/components/ClientLuxShared";
import { isClientPortalEnabled } from "config/client-portal.config";
import { clientPortalService } from "_services/clientPortal.service";
import ClientPortalNav from "./ClientPortalNav";

class ClientProjectDetailPage extends Component {
  state = {
    loading: false,
    error: null,
    project: null,
    documents: [],
    signing: false,
    message: null,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Client project");
    }
    this.load();
  }

  getProjectId = () => {
    const { match } = this.props;
    return match && match.params ? Number(match.params.id) : null;
  };

  load = async () => {
    const projectId = this.getProjectId();
    this.setState({ loading: true, error: null });
    try {
      const [projectResult, docsResult] = await Promise.all([
        clientPortalService.getProject({ projectId }),
        clientPortalService.listDocuments({ projectId }),
      ]);
      if (!projectResult || projectResult.source === "api-error") {
        this.setState({
          loading: false,
          error: "Unable to load project (access denied or not signed in).",
          project: null,
        });
        return;
      }
      this.setState({
        loading: false,
        project: projectResult.payload,
        documents: (docsResult && docsResult.payload && docsResult.payload.documents) || [],
      });
    } catch (e) {
      this.setState({ loading: false, error: (e && e.message) || "Unable to load project." });
    }
  };

  handleSignOff = async () => {
    const projectId = this.getProjectId();
    this.setState({ signing: true, message: null });
    try {
      const result = await clientPortalService.signOffProjectForClientUser({ projectId });
      if (!result || result.source === "api-error") {
        this.setState({ signing: false, message: "Sign-off failed (SIGN_OFF access required)." });
        return;
      }
      this.setState({ signing: false, message: `Signed off (gate ${result.payload && result.payload.gateId}).` });
    } catch (e) {
      this.setState({ signing: false, message: (e && e.message) || "Sign-off failed." });
    }
  };

  handleDownload = async (documentRef) => {
    const projectId = this.getProjectId();
    try {
      const result = await clientPortalService.getDocumentDownloadUrl({ projectId, documentRef });
      if (result && result.payload && result.payload.downloadUrl) {
        window.open(result.payload.downloadUrl, "_blank", "noopener,noreferrer");
      } else {
        this.setState({ message: "Download URL unavailable." });
      }
    } catch (e) {
      this.setState({ message: (e && e.message) || "Download failed." });
    }
  };

  render() {
    if (!isClientPortalEnabled()) {
      return (
        <ClientLuxPage>
          <LuxRegisterEmptyState title="Client portal unavailable" description="Enable REACT_APP_USE_CLIENT_PORTAL_API." />
        </ClientLuxPage>
      );
    }
    const { loading, error, project, documents, signing, message } = this.state;
    return (
      <ClientLuxPage
        testId="client-project-detail-page"
        className="lux-client-portal-page"
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-briefcase",
          eyebrow: "Client portal",
          titleLead: (project && project.name) || "Project",
          titleAccent: "detail",
          lede: "Deliverables/gates + Document Vault downloads for permitted projects.",
        }}
        heroActions={
          <>
            <ClientActionButton variant="secondary" onClick={this.load} disabled={loading}>
              Refresh
            </ClientActionButton>
            <ClientActionButton variant="primary" onClick={this.handleSignOff} disabled={signing}>
              {signing ? "Signing…" : "Sign off"}
            </ClientActionButton>
          </>
        }
      >
        <ClientPortalNav />
        {error ? (
          <LuxInlineAlert tone="warning" title="Unable to load project">
            {error}
          </LuxInlineAlert>
        ) : null}
        {message ? (
          <LuxInlineAlert tone="info" title="Project update">
            {message}
          </LuxInlineAlert>
        ) : null}
        {project ? (
          <ClientLuxPanel title="Project" icon="fe fe-info">
            <p className="mb-1">Status: {project.status || "—"}</p>
            <p className="mb-1">Access: {project.accessLevel || "—"}</p>
            <p className="small text-muted mb-0">{project.deliverablesNote}</p>
          </ClientLuxPanel>
        ) : null}
        <ClientLuxPanel title="Documents" icon="fe fe-folder">
          {documents.length === 0 ? (
            <LuxRegisterEmptyState title="No documents" description="No vault documents for this project." showCreate={false} />
          ) : (
            <ul className="lux-client-portal-list">
              {documents.map((doc) => (
                <li key={doc.documentRef}>
                  <span>{doc.name || doc.documentRef}</span>
                  <ClientActionButton
                    variant="secondary"
                    className="lux-onb-action--compact"
                    onClick={() => this.handleDownload(doc.documentRef)}
                  >
                    Download
                  </ClientActionButton>
                </li>
              ))}
            </ul>
          )}
        </ClientLuxPanel>
      </ClientLuxPage>
    );
  }
}

export default ClientProjectDetailPage;
