import moment from "moment";
import dateUtils from "_helpers/date.utils";
import { normalizeBidRequestStatus } from "../bidRequestList.utils";

const STATUS_TONES = {
  NEW: "sky",
  ASSIGNED: "indigo",
  INPROGRESS: "amber",
  WON: "green",
  LOST: "slate",
  CANCELLED: "rose",
  REJECTED: "slate",
  CLOSED: "slate",
};

const STATUS_LABELS = {
  NEW: "New",
  ASSIGNED: "Assigned",
  INPROGRESS: "In progress",
  WON: "Won",
  LOST: "Lost",
  CANCELLED: "Cancelled",
  REJECTED: "Rejected",
  CLOSED: "Closed",
};

const STUDY_TYPE_LABELS = {
  ADHOC: "Adhoc",
  FTEMS: "FTE–MS",
  FTESA: "FTE–Staff aug",
  SERVICES: "Services",
  PRODUCT: "Product",
  TRACKER: "Tracker",
  TMHB: "T&M hourly",
};

const AGE_LABELS = {
  FRESH: "Under 14 days",
  ACTIVE: "14–60 days",
  STALE: "Over 60 days",
};
const AGE_TONES = {
  FRESH: "green",
  ACTIVE: "amber",
  STALE: "rose",
};

const PIPELINE_STATUSES = ["NEW", "ASSIGNED", "INPROGRESS"];
const FUNNEL_STAGES = ["NEW", "ASSIGNED", "INPROGRESS", "WON"];
const TREND_MONTHS = 6;

function pct(count, total) {
  if (!total) return 0;
  return Math.round((count / total) * 100);
}

function itemStatus(item) {
  return normalizeBidRequestStatus(item && item.status);
}

function toMoment(value) {
  if (!value) return null;
  const m = dateUtils.convertDateStringToMoment(value);
  return m && m.isValid() ? m : null;
}

function buildMixSegments(counts, total, labelMap = STATUS_LABELS, toneMap = STATUS_TONES) {
  return Object.entries(counts)
    .filter(([, count]) => count > 0)
    .map(([key, count]) => ({
      key,
      label: (labelMap && labelMap[key]) || key,
      count,
      pct: pct(count, total),
      tone: (toneMap && toneMap[key]) || "slate",
    }))
    .sort((a, b) => b.count - a.count);
}

function tallyListValues(items, getValues, limit = 6) {
  const counts = {};
  items.forEach((item) => {
    const raw = getValues(item);
    if (!raw) return;
    const values = Array.isArray(raw) ? raw : [raw];
    values.forEach((value) => {
      const key = String(value || "").trim();
      if (!key) return;
      counts[key] = (counts[key] || 0) + 1;
    });
  });
  return Object.entries(counts)
    .map(([key, count]) => ({
      key,
      label: key,
      count,
      pct: pct(count, Math.max(items.length, 1)),
      tone: "indigo",
    }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

function getOwnerName(item) {
  return (
    (item.ownerDetails && item.ownerDetails.name) ||
    (item.ownerUserTeamDetails && item.ownerUserTeamDetails.name) ||
    null
  );
}

function buildCreatedTrend(allItems) {
  const today = moment().startOf("month");
  const buckets = [];
  for (let i = TREND_MONTHS - 1; i >= 0; i -= 1) {
    const month = today.clone().subtract(i, "months");
    buckets.push({
      key: month.format("YYYY-MM"),
      label: month.format("MMM YY"),
      count: 0,
    });
  }
  const bucketMap = buckets.reduce((acc, b) => {
    acc[b.key] = b;
    return acc;
  }, {});

  allItems.forEach((item) => {
    const created = toMoment(item.createdDate);
    if (!created) return;
    const key = created.startOf("month").format("YYYY-MM");
    if (bucketMap[key]) bucketMap[key].count += 1;
  });

  return buckets;
}

function buildPipelineAgeMix(openPipeline) {
  const today = moment().startOf("day");
  const counts = { FRESH: 0, ACTIVE: 0, STALE: 0 };
  openPipeline.forEach((item) => {
    const created = toMoment(item.createdDate);
    if (!created) return;
    const days = today.diff(created, "days");
    if (days < 14) counts.FRESH += 1;
    else if (days <= 60) counts.ACTIVE += 1;
    else counts.STALE += 1;
  });
  return counts;
}

function buildEmptyStats(userTeams) {
  const empty = {
    total: 0,
    active: 0,
    listVisibleCount: 0,
    archived: 0,
    deleted: 0,
    pipeline: 0,
    won: 0,
    lost: 0,
    winRate: 0,
    pipelineRate: 0,
    salesforceCount: 0,
    salesforceRate: 0,
    assignedCount: 0,
    unassignedNewCount: 0,
    multiMarketCount: 0,
    ownedPipelineCount: 0,
    selectedTeams: 0,
    statusMix: [],
    studyTypeMix: [],
    studyDisciplineMix: [],
    kindMix: [],
    countryMix: [],
    ownerMix: [],
    pipelineAgeMix: [],
    createdTrend: buildCreatedTrend([]),
    funnel: [],
    outcomes: { open: 0, won: 0, lost: 0, otherClosed: 0 },
    kpis: [],
    highlights: [],
    insights: [],
    stageCounts: { newCount: 0, assignedCount: 0, inProgressCount: 0 },
    inProgressRate: 0,
  };
  if (userTeams && userTeams.length) {
    empty.selectedTeams = userTeams.filter((team) => team.isChecked).length;
  }
  return empty;
}

export function buildBidRequestSummaryStats(items, userTeams) {
  if (!items || !items.length) {
    return buildEmptyStats(userTeams);
  }

  const all = items;
  const activeList = all.filter((item) => !item.archived);
  const workingList = activeList.filter((item) => !item.deleted);
  const archived = all.filter((item) => item.archived).length;
  const deleted = all.filter((item) => item.deleted).length;
  const pipeline = workingList.filter((item) =>
    PIPELINE_STATUSES.includes(itemStatus(item))
  ).length;
  const won = workingList.filter((item) => itemStatus(item) === "WON").length;
  const lost = workingList.filter((item) => itemStatus(item) === "LOST").length;
  const otherClosed = workingList.filter((item) =>
    ["CANCELLED", "REJECTED", "CLOSED"].includes(itemStatus(item))
  ).length;
  const closedWonLost = won + lost;
  const winRate = closedWonLost ? pct(won, closedWonLost) : 0;
  const pipelineRate = workingList.length ? pct(pipeline, workingList.length) : 0;
  const salesforceCount = workingList.filter((item) => item.salesForceId).length;
  const salesforceRate = workingList.length ? pct(salesforceCount, workingList.length) : 0;
  const assignedCount = workingList.filter((item) => itemStatus(item) === "ASSIGNED").length;
  const unassignedNewCount = workingList.filter(
    (item) => itemStatus(item) === "NEW" && !getOwnerName(item)
  ).length;
  const multiMarketCount = workingList.filter(
    (item) => item.countries && item.countries.length > 1
  ).length;

  const openPipeline = workingList.filter((item) =>
    PIPELINE_STATUSES.includes(itemStatus(item))
  );
  const ownedPipelineCount = openPipeline.filter((item) => getOwnerName(item)).length;

  const statusCounts = {};
  const studyTypeCounts = {};
  const ownerCounts = {};

  workingList.forEach((item) => {
    const statusKey = itemStatus(item);
    statusCounts[statusKey] = (statusCounts[statusKey] || 0) + 1;
    const typeKey = item.type || "OTHER";
    studyTypeCounts[typeKey] = (studyTypeCounts[typeKey] || 0) + 1;
    const owner = getOwnerName(item);
    if (owner) {
      ownerCounts[owner] = (ownerCounts[owner] || 0) + 1;
    }
  });

  const funnelMax = Math.max(
    ...FUNNEL_STAGES.map(
      (stage) => workingList.filter((item) => itemStatus(item) === stage).length
    ),
    1
  );

  const funnel = FUNNEL_STAGES.map((stage) => {
    const count = workingList.filter((item) => itemStatus(item) === stage).length;
    return {
      key: stage,
      label: STATUS_LABELS[stage] || stage,
      count,
      tone: STATUS_TONES[stage] || "slate",
      widthPct: Math.max(18, Math.round((count / funnelMax) * 100)),
    };
  });

  const newCount = workingList.filter((item) => itemStatus(item) === "NEW").length;
  const assignedStageCount = assignedCount;
  const inProgressCount = workingList.filter((item) => itemStatus(item) === "INPROGRESS").length;
  const inProgressRate = workingList.length ? pct(inProgressCount, workingList.length) : 0;

  const activeTotal = Math.max(workingList.length, 1);
  const listVisibleCount = activeList.length;
  const openTotal = Math.max(openPipeline.length, 1);

  const statusMix = buildMixSegments(statusCounts, activeTotal);
  const pipelineAgeMix = buildMixSegments(
    buildPipelineAgeMix(openPipeline),
    openTotal,
    AGE_LABELS,
    AGE_TONES
  );

  const studyDisciplineMix = tallyListValues(workingList, (item) => item.studyTypes);
  const kindMix = tallyListValues(workingList, (item) => item.kindOfStudies);
  const countryMix = tallyListValues(workingList, (item) => item.countries);
  const ownerMix = Object.entries(ownerCounts)
    .map(([key, count]) => ({
      key,
      label: key,
      count,
      pct: pct(count, workingList.length),
      tone: "violet",
    }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 6);

  const winLossInsightMix = buildMixSegments(
    { WON: won, LOST: lost, OPEN: pipeline },
    Math.max(won + lost + pipeline, 1),
    { WON: "Won", LOST: "Lost", OPEN: "Open pipeline" },
    { WON: "green", LOST: "slate", OPEN: "indigo" }
  );

  const insights = [
    {
      key: "status",
      title: "Pipeline by status",
      subtitle: `${pipeline} bids in working pipeline`,
      icon: "fe-activity",
      mix: statusMix,
      emptyLabel: "No active bids",
    },
    {
      key: "winloss",
      title: "Win / loss balance",
      subtitle: closedWonLost ? `${winRate}% win rate on decided bids` : "No decided outcomes yet",
      icon: "fe-target",
      mix: winLossInsightMix,
      emptyLabel: "No outcome data",
    },
    {
      key: "disciplines",
      title: "Study disciplines",
      subtitle: studyDisciplineMix.length
        ? `${studyDisciplineMix.length} disciplines in play`
        : "Tag study types on bids",
      icon: "fe-book-open",
      mix: studyDisciplineMix,
      emptyLabel: "No study type tags",
    },
  ];

  const highlights = [
    {
      key: "unassigned",
      label: "New & unassigned",
      value: unassignedNewCount,
      tone: "sky",
      icon: "fe-user-plus",
      hint: "Awaiting owner assignment",
    },
    {
      key: "assigned",
      label: "Assigned queue",
      value: assignedCount,
      tone: "indigo",
      icon: "fe-briefcase",
      hint: "Ready to progress",
    },
    {
      key: "salesforce",
      label: "Salesforce",
      value: salesforceCount,
      tone: "teal",
      icon: "fe-cloud",
      hint: `${salesforceRate}% with SF opportunity`,
    },
    {
      key: "multimarket",
      label: "Multi-market",
      value: multiMarketCount,
      tone: "amber",
      icon: "fe-globe",
      hint: "Bids spanning 2+ countries",
    },
  ];

  const summary = {
    total: all.length,
    active: workingList.length,
    listVisibleCount,
    archived,
    deleted,
    pipeline,
    won,
    lost,
    winRate,
    pipelineRate,
    salesforceCount,
    salesforceRate,
    assignedCount,
    unassignedNewCount,
    multiMarketCount,
    ownedPipelineCount,
    selectedTeams: 0,
    statusMix,
    studyTypeMix: buildMixSegments(
      studyTypeCounts,
      activeTotal,
      STUDY_TYPE_LABELS,
      {
        ADHOC: "indigo",
        FTEMS: "violet",
        FTESA: "sky",
        SERVICES: "amber",
        PRODUCT: "teal",
        TRACKER: "green",
        TMHB: "slate",
        OTHER: "slate",
      }
    ),
    studyDisciplineMix,
    kindMix,
    countryMix,
    ownerMix,
    pipelineAgeMix,
    createdTrend: buildCreatedTrend(all),
    funnel,
    outcomes: {
      open: pipeline,
      won,
      lost,
      otherClosed,
    },
    kpis: [
      {
        key: "active",
        label: "Active bids",
        value: workingList.length,
        hint:
          deleted > 0
            ? `${listVisibleCount} in register · ${deleted} soft-deleted`
            : "Not archived or deleted",
        icon: "fe-layers",
        tone: "indigo",
      },
      {
        key: "inProgress",
        label: "In progress",
        value: inProgressCount,
        hint:
          pipeline > 0
            ? `${inProgressRate}% of active · ${pipeline} in pipeline`
            : `${inProgressRate}% of active`,
        icon: "fe-loader",
        tone: "amber",
      },
      {
        key: "won",
        label: "Won",
        value: won,
        hint: `${winRate}% win rate`,
        icon: "fe-award",
        tone: "green",
      },
      {
        key: "archived",
        label: "Archived",
        value: archived,
        hint: deleted ? `${deleted} deleted` : "Stored bids",
        icon: "fe-archive",
        tone: "slate",
      },
    ],
    highlights,
    insights,
    stageCounts: { newCount, assignedCount: assignedStageCount, inProgressCount },
    inProgressRate,
  };

  if (userTeams && userTeams.length) {
    summary.selectedTeams = userTeams.filter((team) => team.isChecked).length;
  }

  return summary;
}
