import React, { Component } from "react";
import classNames from "classnames/bind";
import { MILESTONE_STATUSES } from "config/project-governance.config";
import { getMilestoneStatusLabel, getMilestoneStatusTone } from "config/project-governance.utils";
import GovernanceLuxDrawerShell from "views/project/components/GovernanceLuxDrawerShell";
import {
  GovernanceDrawerBanner,
  GovernanceDrawerCard,
  GovernanceDrawerField,
  GovernanceDrawerMeta,
  GovernanceDrawerModuleLink,
  GovernanceDrawerStatStrip,
} from "views/project/components/GovernanceLuxDrawerShared";

export default class MilestoneDrawer extends Component {
  state = {
    percentComplete: 0,
    status: MILESTONE_STATUSES.PLANNED,
    saving: false,
    error: null,
  };

  componentDidUpdate(prevProps) {
    const { milestone, open } = this.props;
    if (open && milestone && milestone !== prevProps.milestone) {
      this.setState({
        percentComplete: milestone.percentComplete || 0,
        status: milestone.status || MILESTONE_STATUSES.PLANNED,
        saving: false,
        error: null,
      });
    }
  }

  handleSave = async () => {
    const { milestone, onSave, onClose } = this.props;
    const { percentComplete, status } = this.state;
    if (!milestone || !onSave) {
      return;
    }
    this.setState({ saving: true, error: null });
    try {
      await onSave(milestone.id, { percentComplete: Number(percentComplete), status });
      onClose();
    } catch (e) {
      this.setState({
        saving: false,
        error: (e && e.message) || "Unable to update milestone.",
      });
    }
  };

  render() {
    const { open, milestone, onClose } = this.props;
    const { percentComplete, status, saving, error } = this.state;
    if (!open || !milestone) {
      return null;
    }

    const tone = getMilestoneStatusTone(milestone.status);
    const progressTone = Number(percentComplete) >= 100 ? "success" : Number(percentComplete) >= 50 ? "warning" : undefined;

    return (
      <GovernanceLuxDrawerShell
        open={open}
        onClose={onClose}
        accent="primary"
        icon="fe-flag"
        eyebrow="Delivery milestone"
        title={milestone.name}
        subtitle={milestone.projectName}
        quickLinks={[
          { to: "/project/timeline", label: "Delivery timeline", hint: "Gantt", icon: "fe fe-bar-chart-2" },
          { to: "/project/milestones", label: "Milestone register", hint: "All milestones", icon: "fe fe-flag" },
        ]}
        ariaLabel={`Milestone ${milestone.name}`}
        footer={
          <div className="lux-gov-drawer__foot-bar">
            <GovernanceDrawerModuleLink
              to="/project/milestones"
              label="Open milestone register"
              onNavigate={onClose}
            />
            <div className="lux-onb-drawer__foot-actions">
              <button type="button" className="lux-onb-action lux-onb-action--ghost" onClick={onClose}>
                Cancel
              </button>
              <button
                type="button"
                className="lux-onb-action lux-onb-action--primary"
                onClick={this.handleSave}
                disabled={saving}
              >
                {saving ? "Saving…" : "Save milestone"}
              </button>
            </div>
          </div>
        }
      >
        <GovernanceDrawerStatStrip
          stats={[
            { label: "Complete", value: `${percentComplete || 0}%`, tone: progressTone },
            { label: "Status", value: getMilestoneStatusLabel(status), tone: getMilestoneStatusTone(status) },
            { label: "Owner", value: milestone.ownerName || "Unassigned" },
          ]}
        />

        <GovernanceDrawerCard title="Update progress" subtitle="Adjust lifecycle status and completion">
          <div className="lux-gov-drawer__progress-panel">
            <div className="lux-gov-drawer__progress-summary">
              <span className="lux-gov-drawer__progress-value">{percentComplete || 0}% complete</span>
              <span className={classNames("lux-doc-badge", `is-${getMilestoneStatusTone(status)}`)}>
                {getMilestoneStatusLabel(status)}
              </span>
            </div>
            <div className="lux-gov-drawer__progress-track" aria-hidden="true">
              <span className="lux-gov-drawer__progress-fill" style={{ width: `${Math.min(100, Math.max(0, Number(percentComplete) || 0))}%` }} />
            </div>
            <GovernanceDrawerField label="Percent complete">
              <input
                className="lux-gov-drawer__progress-range"
                type="range"
                min="0"
                max="100"
                step="1"
                value={percentComplete}
                onChange={(e) => this.setState({ percentComplete: e.target.value })}
                aria-valuemin={0}
                aria-valuemax={100}
                aria-valuenow={Number(percentComplete) || 0}
              />
            </GovernanceDrawerField>
            <div className="lux-gov-drawer__field-grid">
              <GovernanceDrawerField label="Status">
                <select value={status} onChange={(e) => this.setState({ status: e.target.value })}>
                  {Object.values(MILESTONE_STATUSES).map((value) => (
                    <option key={value} value={value}>
                      {getMilestoneStatusLabel(value)}
                    </option>
                  ))}
                </select>
              </GovernanceDrawerField>
              <GovernanceDrawerField label="Exact percent">
                <input
                  type="number"
                  min="0"
                  max="100"
                  value={percentComplete}
                  onChange={(e) => this.setState({ percentComplete: e.target.value })}
                />
              </GovernanceDrawerField>
            </div>
          </div>
          {error ? <p className="lux-gov-drawer__error">{error}</p> : null}
        </GovernanceDrawerCard>

        <GovernanceDrawerCard title="Schedule snapshot" subtitle="Planned window and delivery signals">
          <GovernanceDrawerMeta
            items={[
              {
                label: "Planned start",
                value: milestone.plannedStart || "—",
              },
              {
                label: "Planned end",
                value: milestone.plannedEnd || "—",
              },
              {
                label: "Project",
                value: milestone.projectName,
              },
              {
                label: "Saved status",
                value: (
                  <span className={classNames("lux-doc-badge", `is-${tone}`)}>
                    {getMilestoneStatusLabel(milestone.status)}
                  </span>
                ),
              },
            ]}
          />
        </GovernanceDrawerCard>

        {milestone.isCritical ? (
          <GovernanceDrawerBanner icon="fe-zap" tone="warning">
            Critical path milestone — changes may affect gate readiness and downstream dependencies.
          </GovernanceDrawerBanner>
        ) : null}
      </GovernanceLuxDrawerShell>
    );
  }
}
