import dateUtils from "_helpers/date.utils";
import { getItemStartDate, getWorkItemEmployeeId } from "./planner.utils";
import { getLeaveHolidayKind } from "views/hrms/components/timesheet/timesheetBoard.utils";

/** employeeId -> Map(dayKey -> { type: 'leave'|'holiday'|'pto', label }) */
export function buildEmployeeLeaveMap({ workItems, holidayItems, timesheetByEmployee, employees }) {
  const map = new Map();

  const ensure = (employeeId) => {
    const key = String(employeeId);
    if (!map.has(key)) map.set(key, new Map());
    return map.get(key);
  };

  (employees || []).forEach((emp) => {
    if (emp && emp.id != null) ensure(emp.id);
  });

  (workItems || []).forEach((item) => {
    const eid = getWorkItemEmployeeId(item);
    if (eid == null) return;
    const type = String(item.taskType || "").toUpperCase();
    const cat = String(item.taskActCategory || "").toLowerCase();
    if (type !== "LEAVE" && type !== "HOLIDAY" && cat !== "leave" && cat !== "holiday") {
      return;
    }
    const start = getItemStartDate(item);
    if (!start) return;
    const dayKey = dateUtils.convertDateToMoment(start).format("YYYY-MM-DD");
    const days = ensure(eid);
    days.set(dayKey, {
      type: type === "HOLIDAY" || cat === "holiday" ? "holiday" : "leave",
      label: item.name || item.taskActCategory || "Leave",
    });
  });

  (holidayItems || []).forEach((h) => {
    if (!h || !h.holidayDate) return;
    const m = dateUtils.convertDateStringToMoment(h.holidayDate);
    if (!m || !m.isValid()) return;
    const dayKey = m.format("YYYY-MM-DD");
    const targets =
      h.employeeId != null
        ? [String(h.employeeId)]
        : (employees || []).map((e) => String(e.id));
    targets.forEach((eid) => {
      const days = ensure(eid);
      if (!days.has(dayKey)) {
        days.set(dayKey, { type: "holiday", label: h.name || h.description || "Holiday" });
      }
    });
  });

  if (timesheetByEmployee) {
    Object.keys(timesheetByEmployee).forEach((employeeId) => {
      const sheet = timesheetByEmployee[employeeId];
      if (!sheet) return;
      const weekDates = extractTimesheetDateKeys(sheet);
      weekDates.forEach((dateString) => {
        const leaveMins = sumLeaveMinutesOnDate(sheet, dateString);
        if (leaveMins >= 240) {
          const days = ensure(employeeId);
          days.set(dateString, { type: "leave", label: "Leave (timesheet)" });
        }
      });
    });
  }

  return map;
}

function extractTimesheetDateKeys(sheet) {
  const keys = new Set();
  ["project", "nonProject"].forEach((type) => {
    const groups = sheet[type];
    if (!groups) return;
    Object.keys(groups).forEach((gid) => {
      const tasks = groups[gid] && groups[gid].tasks;
      if (!tasks) return;
      tasks.forEach((task) => {
        const te = task.timeEntry || {};
        Object.keys(te).forEach((d) => keys.add(d));
      });
    });
  });
  return [...keys];
}

function sumLeaveMinutesOnDate(sheet, dateString) {
  let mins = 0;
  const nonProject = sheet.nonProject;
  if (!nonProject) return 0;
  Object.keys(nonProject).forEach((groupId) => {
    const kind = getLeaveHolidayKind(groupId, null);
    if (!kind) return;
    const tasks = nonProject[groupId] && nonProject[groupId].tasks;
    if (!tasks) return;
    tasks.forEach((task) => {
      const cell = task.timeEntry && task.timeEntry[dateString];
      if (cell) mins += parseInt(cell.timesheetTimeMins || 0, 10);
    });
  });
  return mins;
}

export function getEmployeeLeaveOnDay(leaveMap, employeeId, dayKey) {
  if (!leaveMap || employeeId == null) return null;
  const days = leaveMap.get(String(employeeId));
  return days ? days.get(dayKey) : null;
}

export function isEmployeeOnLeave(leaveMap, employeeId, dayKey) {
  return !!getEmployeeLeaveOnDay(leaveMap, employeeId, dayKey);
}

export function isPlannerLeaveOrHolidayItem(item) {
  if (!item) return false;
  const type = String(item.taskType || "").toUpperCase();
  const cat = String(item.taskActCategory || "").toLowerCase();
  return type === "LEAVE" || type === "HOLIDAY" || cat === "leave" || cat === "holiday";
}
