function packKey(row) {
  const raw = String(
    (row && (row.industryPack || row.code || row.templateRef)) || ""
  )
    .trim()
    .toUpperCase()
    .replace(/[\s-]+/g, "_");
  if (ITPL_PACK_ENRICHMENT[raw]) return raw;
  const alias = {
    ITPL_IT_SERVICES: "IT_SERVICES",
    "ITPL-IT-SERVICES": "IT_SERVICES",
    ITPL_CONSULTING: "CONSULTING",
    "ITPL-CONSULTING": "CONSULTING",
    ITPL_MANAGED_SERVICES: "MANAGED_SERVICES",
    "ITPL-MANAGED-SERVICES": "MANAGED_SERVICES",
    ITPL_NPD: "NPD",
    "ITPL-NPD": "NPD",
    ITPL_DOSSIER_HEAVY: "DOSSIER_HEAVY",
    "ITPL-DOSSIER-HEAVY": "DOSSIER_HEAVY",
  };
  return alias[raw] || raw.split(/_/).slice(0, 3).join("_");
}

export function getIndustryPackEnrichment(row) {
  const key = packKey(row);
  return ITPL_PACK_ENRICHMENT[key] || DEFAULT_ENRICHMENT;
}

export function normalizeIndustryTemplateStatus(status) {
  return String(status || "UNKNOWN").toUpperCase();
}

export function industryTemplateStatusTone(status) {
  const s = normalizeIndustryTemplateStatus(status);
  if (s === "PUBLISHED" || s === "ACTIVE") return "green";
  if (s === "DRAFT") return "amber";
  if (s === "ARCHIVED" || s === "RETIRED") return "slate";
  return "indigo";
}

export function buildIndustryTemplateMetrics(rows) {
  const list = Array.isArray(rows) ? rows : [];
  const published = list.filter(
    (r) => normalizeIndustryTemplateStatus(r.status) === "PUBLISHED"
  ).length;
  const draft = list.filter((r) => normalizeIndustryTemplateStatus(r.status) === "DRAFT").length;
  const packs = new Set(list.map((r) => r.industryPack || r.code).filter(Boolean)).size;
  return {
    total: list.length,
    published,
    draft,
    packs,
    applyReady: published,
  };
}

export function enrichIndustryTemplateRows(rows) {
  return (Array.isArray(rows) ? rows : []).map((row) => {
    const enrichment = getIndustryPackEnrichment(row);
    return {
      ...row,
      enrichment,
      statusTone: industryTemplateStatusTone(row.status),
      statusLabel: normalizeIndustryTemplateStatus(row.status),
    };
  });
}
