import { appConfigService } from '../_services';
import { commonUtils } from './common.utils';
import envconfig from '../env.config';
import { isDevEnvPilotEnabled, resolveDevEnvOrOrg } from './featurePilot.utils';

export const TIMESHEET_ADDITIONAL_CONFIG_KEY = 'timesheetAdditional';
export const TIMESHEET_APPROVAL_ENABLED_KEY = 'timesheetApprovalEnabled';
export const TIMESHEET_REOPEN_ENABLED_KEY = 'timesheetReopenEnabled';
export const PARTIAL_WEEK_SUBMISSION_ENABLED_KEY = 'partialWeekSubmissionEnabled';
export const TIMESHEET_HOURS_CONSISTENCY_AUDIT_ENABLED_KEY = 'timesheetHoursConsistencyAuditEnabled';
export const TIMESHEET_DATA_QUALITY_SCHEDULER_ENABLED_KEY = 'timesheetDataQualitySchedulerEnabled';
export const TIMESHEET_DATA_QUALITY_ADMIN_EMAILS_KEY = 'timesheetDataQualityAdminEmails';
export const TIMESHEET_DATA_QUALITY_LOOKBACK_WEEKS_KEY = 'timesheetDataQualityLookbackWeeks';
export const TIMESHEET_APPROVAL_CONFIG_CHANGED = 'famstack-timesheet-approval-config-changed';
export const DEFAULT_TIMESHEET_DATA_QUALITY_LOOKBACK_WEEKS = 8;

const HRMS_MODULE = 'HRMS';

let orgTimesheetApprovalEnabled = false;
let orgTimesheetReopenEnabled = true;
let orgPartialWeekSubmissionEnabled = false;
let configLoaded = false;
let loadPromise = null;

export function readTimesheetAdditionalFlag(configList, flagKey) {
  const group = commonUtils.getAppConfigValue(configList, TIMESHEET_ADDITIONAL_CONFIG_KEY);
  if (!group || typeof group !== 'object') {
    return false;
  }
  return group[flagKey] === true;
}

export function isTimesheetApprovalEnabledFromConfig(configList) {
  return readTimesheetAdditionalFlag(configList, TIMESHEET_APPROVAL_ENABLED_KEY);
}

export function isTimesheetReopenEnabledFromConfig(configList) {
  const group = commonUtils.getAppConfigValue(configList, TIMESHEET_ADDITIONAL_CONFIG_KEY);
  if (!group || typeof group !== 'object') {
    // Default on when approval is on and reopen key is unset.
    return isTimesheetApprovalEnabledFromConfig(configList);
  }
  if (Object.prototype.hasOwnProperty.call(group, TIMESHEET_REOPEN_ENABLED_KEY)) {
    return group[TIMESHEET_REOPEN_ENABLED_KEY] === true;
  }
  return isTimesheetApprovalEnabledFromConfig(configList);
}

/** Requires approval workflow; defaults off when unset. */
export function isPartialWeekSubmissionEnabledFromConfig(configList) {
  if (!isTimesheetApprovalEnabledFromConfig(configList)) {
    return false;
  }
  return readTimesheetAdditionalFlag(configList, PARTIAL_WEEK_SUBMISSION_ENABLED_KEY);
}

/** Requires approval workflow; defaults off when unset. */
export function isTimesheetHoursConsistencyAuditEnabledFromConfig(configList) {
  if (!isTimesheetApprovalEnabledFromConfig(configList)) {
    return false;
  }
  return readTimesheetAdditionalFlag(configList, TIMESHEET_HOURS_CONSISTENCY_AUDIT_ENABLED_KEY);
}

/** Org master switch for scheduled timesheet DQ scan; defaults off. */
export function isTimesheetDataQualitySchedulerEnabledFromConfig(configList) {
  return readTimesheetAdditionalFlag(configList, TIMESHEET_DATA_QUALITY_SCHEDULER_ENABLED_KEY);
}

export function getTimesheetDataQualityLookbackWeeksFromConfig(configList) {
  const group = commonUtils.getAppConfigValue(configList, TIMESHEET_ADDITIONAL_CONFIG_KEY);
  if (!group || typeof group !== 'object') {
    return DEFAULT_TIMESHEET_DATA_QUALITY_LOOKBACK_WEEKS;
  }
  const raw = group[TIMESHEET_DATA_QUALITY_LOOKBACK_WEEKS_KEY];
  const n = typeof raw === 'number' ? raw : parseInt(raw, 10);
  if (!Number.isFinite(n) || n < 1) {
    return DEFAULT_TIMESHEET_DATA_QUALITY_LOOKBACK_WEEKS;
  }
  return n;
}

export function getTimesheetDataQualityAdminEmailsFromConfig(configList) {
  const group = commonUtils.getAppConfigValue(configList, TIMESHEET_ADDITIONAL_CONFIG_KEY);
  if (!group || typeof group !== 'object') {
    return [];
  }
  const raw = group[TIMESHEET_DATA_QUALITY_ADMIN_EMAILS_KEY];
  if (Array.isArray(raw)) {
    return raw.map((e) => String(e || '').trim()).filter(Boolean);
  }
  if (typeof raw === 'string' && raw.trim()) {
    return raw.split(/\s*,\s*/).map((e) => e.trim()).filter(Boolean);
  }
  return [];
}

export function applyTimesheetApprovalConfig(configList) {
  orgTimesheetApprovalEnabled = isTimesheetApprovalEnabledFromConfig(configList);
  orgTimesheetReopenEnabled = isTimesheetReopenEnabledFromConfig(configList);
  orgPartialWeekSubmissionEnabled = isPartialWeekSubmissionEnabledFromConfig(configList);
  configLoaded = true;
  return orgTimesheetApprovalEnabled;
}

export function isTimesheetApprovalOrgEnabled() {
  return orgTimesheetApprovalEnabled;
}

export function isTimesheetReopenOrgEnabled() {
  return orgTimesheetReopenEnabled;
}

export function isPartialWeekSubmissionOrgEnabled() {
  return orgPartialWeekSubmissionEnabled;
}

/** Dev-only env pilot. Production ignores REACT_APP_TIMESHEET_APPROVAL_ENABLED. */
export function isTimesheetApprovalEnvEnabled() {
  return isDevEnvPilotEnabled(envconfig.TIMESHEET_APPROVAL_ENABLED);
}

export function isTimesheetApprovalConfigLoaded() {
  return configLoaded;
}

export function notifyTimesheetApprovalConfigChanged() {
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent(TIMESHEET_APPROVAL_CONFIG_CHANGED));
  }
}

export function loadTimesheetApprovalConfig(force, teamIdOverride) {
  if (!force && configLoaded) {
    return Promise.resolve(orgTimesheetApprovalEnabled);
  }
  if (!force && loadPromise) {
    return loadPromise;
  }

  const teamId = teamIdOverride || commonUtils.getCurrentUserTeamId();
  if (!teamId) {
    orgTimesheetApprovalEnabled = false;
    orgTimesheetReopenEnabled = false;
    orgPartialWeekSubmissionEnabled = false;
    configLoaded = true;
    return Promise.resolve(false);
  }

  loadPromise = appConfigService
    .getModuleConfig(teamId, HRMS_MODULE)
    .then((response) => {
      const list = response && response.payload;
      applyTimesheetApprovalConfig(list);
      notifyTimesheetApprovalConfigChanged();
      return orgTimesheetApprovalEnabled;
    })
    .catch(() => {
      orgTimesheetApprovalEnabled = false;
      orgTimesheetReopenEnabled = false;
      orgPartialWeekSubmissionEnabled = false;
      configLoaded = true;
      return false;
    })
    .finally(() => {
      loadPromise = null;
    });

  return loadPromise;
}

export function refreshTimesheetApprovalConfig(teamIdOverride) {
  configLoaded = false;
  return loadTimesheetApprovalConfig(true, teamIdOverride);
}

/**
 * Org `timesheetAdditional.timesheetApprovalEnabled` from Application Config.
 * Manager approve actions still require role.json `timeSheet.enableTimeSheetApproval`.
 */
export function shouldUseTimesheetApprovalWorkflow() {
  return resolveDevEnvOrOrg(envconfig.TIMESHEET_APPROVAL_ENABLED, isTimesheetApprovalOrgEnabled());
}

/** Org `timesheetAdditional.timesheetReopenEnabled` (defaults on when approval is on). */
export function shouldAllowTimesheetReopen() {
  return isTimesheetReopenOrgEnabled();
}

/**
 * Org `timesheetAdditional.partialWeekSubmissionEnabled`.
 * Requires approval workflow; defaults off.
 */
export function shouldAllowPartialWeekTimesheetSubmission() {
  return shouldUseTimesheetApprovalWorkflow() && isPartialWeekSubmissionOrgEnabled();
}

export function isEffectiveAutoApproveOwn(roleAutoApproveOwnEnabled) {
  return shouldUseTimesheetApprovalWorkflow() && roleAutoApproveOwnEnabled === true;
}

export function isEffectiveAutoApproveOthers(roleAutoApproveOthersEnabled) {
  return shouldUseTimesheetApprovalWorkflow() && roleAutoApproveOthersEnabled === true;
}
