import html2canvas from "html2canvas";
import jsPDF from "jspdf";

const PDF_MARGIN_MM = 8;

function waitForImages(root) {
  const images = Array.from(root.querySelectorAll("img"));
  return Promise.all(
    images.map(
      (img) =>
        new Promise((resolve) => {
          if (img.complete) {
            resolve();
            return;
          }
          img.onload = () => resolve();
          img.onerror = () => resolve();
        })
    )
  );
}

export async function downloadInvoicePdf(element, filename = "invoice.pdf") {
  if (!element) {
    throw new Error("Invoice document is not available.");
  }

  element.classList.add("lux-inv-detail__sheet--pdf-capture");

  try {
    await waitForImages(element);

    const canvas = await html2canvas(element, {
      scale: 2,
      useCORS: true,
      allowTaint: false,
      logging: false,
      backgroundColor: "#ffffff",
      scrollX: 0,
      scrollY: -window.scrollY,
      windowWidth: element.scrollWidth,
      windowHeight: element.scrollHeight,
    });

    const pdf = new jsPDF("p", "mm", "a4");
    const pageWidth = pdf.internal.pageSize.getWidth();
    const pageHeight = pdf.internal.pageSize.getHeight();
    const contentWidth = pageWidth - PDF_MARGIN_MM * 2;
    const contentHeight = pageHeight - PDF_MARGIN_MM * 2;
    const imgHeight = (canvas.height * contentWidth) / canvas.width;
    const imgData = canvas.toDataURL("image/jpeg", 0.92);

    let heightLeft = imgHeight;
    let position = PDF_MARGIN_MM;

    pdf.addImage(imgData, "JPEG", PDF_MARGIN_MM, position, contentWidth, imgHeight);
    heightLeft -= contentHeight;

    while (heightLeft > 0) {
      pdf.addPage();
      position = PDF_MARGIN_MM - (imgHeight - heightLeft);
      pdf.addImage(imgData, "JPEG", PDF_MARGIN_MM, position, contentWidth, imgHeight);
      heightLeft -= contentHeight;
    }

    pdf.save(filename);
  } finally {
    element.classList.remove("lux-inv-detail__sheet--pdf-capture");
  }
}
