import React from "react";
import classNames from "classnames/bind";

export default function OneOnOneRegister({ notes, loading }) {
  if (loading) {
    return <div className="lux-perf-skeleton lux-perf-skeleton--panel" />;
  }
  if (!notes || !notes.length) {
    return (
      <div className="lux-perf-empty">
        <i className="fe fe-users" aria-hidden="true" />
        <p>No 1:1 notes recorded.</p>
      </div>
    );
  }
  return (
    <div className="lux-perf-register">
      {notes.map((row, index) => (
        <article key={row.id} className="lux-perf-register__row">
          <span className="lux-perf-register__index">{index + 1}</span>
          <span className={classNames("lux-perf-register__rail", row.tone && `is-${row.tone}`)}>
            <i className="fe fe-users" aria-hidden="true" />
          </span>
          <div className="lux-perf-register__main">
            <span className="lux-perf-register__eyebrow">{row.managerName} · {row.meetingDate}</span>
            <h3>{row.employeeName}</h3>
            <p>{row.summary}</p>
            {row.actionItems && row.actionItems.length ? (
              <ul className="lux-perf-action-list">
                {row.actionItems.map((item) => (
                  <li key={item}>{item}</li>
                ))}
              </ul>
            ) : null}
          </div>
        </article>
      ))}
    </div>
  );
}
