import React, { Component } from "react";
import { connect } from "react-redux";
import classNames from "classnames/bind";
import { store } from "_helpers";
import { auditActions } from "_actions";
import {
  AUDIT_DEFAULT_PAGE_SIZE,
  AUDIT_EMBEDDED_PAGE_SIZE,
  AUDIT_ENTITY_FILTER_OPTIONS,
  AUDIT_SCOPES,
} from "_constants/audit.constants";
import {
  buildAuditScopeKey,
  enrichAuditEventsWithEmployees,
  filterEventsByActionType,
  filterEventsByEntityType,
  filterEventsByViewMode,
} from "_helpers/audit.utils";
import {
  readAuditPanelActionFilter,
  readAuditPanelEntityFilter,
  writeAuditPanelPrefs,
} from "_helpers/audit.panel.utils";
import { isAuditUiEnabled, isAuditOrgEnabled, isAuditConfigLoaded } from "_helpers/audit.config";
import {
  getApiErrorMessage,
  isApiForbiddenError,
  isApiNotFoundError,
} from "_helpers/apiError.utils";
import { commonUtils } from "_helpers";
import AuditTimeline from "./AuditTimeline";

class AuditTrailSection extends Component {
  componentDidMount() {
    this.applyInitialFilter();
    if (!this.props.disabled) {
      this.loadIfNeeded();
    }
  }

  componentDidUpdate(prevProps) {
    if (this.props.disabled) {
      return;
    }
    const scopeChanged =
      prevProps.disabled !== this.props.disabled ||
      prevProps.scope !== this.props.scope ||
      prevProps.actorUserId !== this.props.actorUserId ||
      prevProps.entityType !== this.props.entityType ||
      prevProps.entityId !== this.props.entityId;
    const refreshChanged =
      prevProps.refreshKey !== this.props.refreshKey && this.props.refreshKey != null;

    if (scopeChanged) {
      this.applyInitialFilter();
      this.loadIfNeeded();
    } else if (refreshChanged) {
      this.loadTimeline(1);
    }
  }

  resolveInitialEntityFilter = () => {
    const { initialEntityFilter, persistKey, lockedEntityFilter } = this.props;
    if (lockedEntityFilter) {
      return lockedEntityFilter;
    }
    if (persistKey) {
      const saved = readAuditPanelEntityFilter(persistKey, initialEntityFilter || "ALL");
      if (saved) return saved;
    }
    return initialEntityFilter;
  };

  applyInitialFilter = () => {
    const entityFilter = this.resolveInitialEntityFilter();
    const actionFilter = this.resolveInitialActionFilter();
    const scopeKey = this.getScopeKey();
    const filters = {};
    if (entityFilter && entityFilter !== "ALL") {
      filters.entityType = entityFilter;
    }
    if (actionFilter && actionFilter !== "ALL") {
      filters.actionType = actionFilter;
    }
    if (Object.keys(filters).length) {
      store.dispatch(auditActions.setTimelineFilters(scopeKey, filters));
    }
  };

  resolveInitialActionFilter = () => {
    const { initialActionFilter, persistKey, actionFilterOptions } = this.props;
    if (!actionFilterOptions || !actionFilterOptions.length) {
      return initialActionFilter || "ALL";
    }
    if (persistKey) {
      return readAuditPanelActionFilter(persistKey, initialActionFilter || "ALL");
    }
    return initialActionFilter || "ALL";
  };

  getScopeKey = () => {
    const { scope, actorUserId, entityType, entityId } = this.props;
    if (scope === AUDIT_SCOPES.ACTOR) {
      return buildAuditScopeKey("actor", { actorUserId });
    }
    return buildAuditScopeKey("entity", { entityType, entityId });
  };

  loadTimeline = (page = 1) => {
    const { scope, actorUserId, entityType, entityId, disabled, lockedEntityFilter, pageSize } =
      this.props;
    if (disabled || !isAuditUiEnabled()) return;
    if (!commonUtils.getCurrentUserId()) return;

    const resolvedPageSize = pageSize || AUDIT_DEFAULT_PAGE_SIZE;
    const params = { page, pageSize: resolvedPageSize };
    if (lockedEntityFilter) {
      params.entityType = lockedEntityFilter;
    }

    if (scope === AUDIT_SCOPES.ACTOR && actorUserId) {
      store.dispatch(auditActions.loadActorTimeline(actorUserId, params));
      return;
    }

    if (scope === AUDIT_SCOPES.ENTITY && entityType && entityId) {
      const loaders = {
        PROJECT: auditActions.loadProjectAudit,
        PURCHASE_ORDER: auditActions.loadPurchaseOrderAudit,
        EMPLOYEE: auditActions.loadEmployeeAudit,
        DELIVERABLE: auditActions.loadDeliverableAudit,
        LEAVE: auditActions.loadLeaveAudit,
        ATTENDANCE: auditActions.loadAttendanceAudit,
        TIMESHEET_WEEK: auditActions.loadTimesheetWeekAudit,
      };
      const loader = loaders[entityType] || auditActions.loadEntityTimeline;
      if (loader === auditActions.loadEntityTimeline) {
        store.dispatch(loader(entityType, entityId, params));
      } else {
        store.dispatch(loader(entityId, params));
      }
    }
  };

  loadIfNeeded = () => {
    const { timeline } = this.props;
    const page = (timeline && timeline.page) || 1;
    this.loadTimeline(page);
  };

  handlePageChange = (page) => {
    if (!page || page < 1) return;
    this.loadTimeline(page);
  };

  handleEntityFilter = (entityType) => {
    const { persistKey, lockedEntityFilter } = this.props;
    const nextFilter = lockedEntityFilter || entityType;
    const scopeKey = this.getScopeKey();
    store.dispatch(auditActions.setTimelineFilters(scopeKey, { entityType: nextFilter }));
    if (persistKey && !lockedEntityFilter) {
      writeAuditPanelPrefs(persistKey, { entityFilter: nextFilter });
    }
  };

  getFilterOptions = () => {
    const { entityFilterOptions } = this.props;
    if (entityFilterOptions && entityFilterOptions.length) {
      return entityFilterOptions;
    }
    return AUDIT_ENTITY_FILTER_OPTIONS;
  };

  handleActionFilter = (actionType) => {
    const { persistKey } = this.props;
    const scopeKey = this.getScopeKey();
    store.dispatch(auditActions.setTimelineFilters(scopeKey, { actionType }));
    if (persistKey) {
      writeAuditPanelPrefs(persistKey, { actionFilter: actionType });
    }
  };

  getActionFilterOptions = () => {
    const { actionFilterOptions } = this.props;
    return actionFilterOptions && actionFilterOptions.length ? actionFilterOptions : null;
  };

  renderActionFilterChips = () => {
    const { timeline, compact } = this.props;
    const options = this.getActionFilterOptions();
    if (!options) return null;

    const selected = (timeline && timeline.filters && timeline.filters.actionType) || "ALL";

    return (
      <div
        className={classNames("lux-audit-panel__filters lux-audit-panel__filters--action", {
          "lux-audit-panel__filters--compact": compact,
        })}
        role="group"
        aria-label="Filter audit by action"
      >
        {options.map((option) => (
          <button
            key={option.value}
            type="button"
            className={classNames("lux-audit-panel__filter-chip", {
              "lux-audit-panel__filter-chip--compact": compact,
              "is-active": selected === option.value,
              [`is-tone-${option.tone || "slate"}`]: selected === option.value && option.tone,
            })}
            onClick={() => this.handleActionFilter(option.value)}
          >
            {option.label}
          </button>
        ))}
      </div>
    );
  };

  renderFilterChips = () => {
    const { showEntityFilters, timeline, compact } = this.props;
    const options = this.getFilterOptions();
    if (!showEntityFilters || options.length <= 1) return null;

    const selected = (timeline && timeline.filters && timeline.filters.entityType) || "ALL";

    return (
      <div
        className={classNames("lux-audit-panel__filters", {
          "lux-audit-panel__filters--compact": compact,
        })}
        role="group"
        aria-label="Filter audit by area"
      >
        {options.map((option) => (
          <button
            key={option.value}
            type="button"
            className={classNames("lux-audit-panel__filter-chip", {
              "lux-audit-panel__filter-chip--compact": compact,
              "is-active": selected === option.value,
            })}
            onClick={() => this.handleEntityFilter(option.value)}
          >
            {option.label}
          </button>
        ))}
      </div>
    );
  };

  render() {
    const {
      className,
      eyebrow,
      title,
      subtitle,
      timeline,
      emptyState,
      showToolbar,
      onEventDeepLink,
      children,
      hideHeader,
      viewMode,
      compact,
      softEmptyOnError,
      scrollable,
      pageSize,
      refreshKey,
    } = this.props;

    if (!isAuditUiEnabled()) {
      return children || null;
    }

    const { lockedEntityFilter, employees } = this.props;
    const entityFilter =
      lockedEntityFilter || (timeline && timeline.filters && timeline.filters.entityType);
    const actionFilter =
      (timeline && timeline.filters && timeline.filters.actionType) || "ALL";
    const rawItems = (timeline && timeline.items) || [];
    let items = filterEventsByEntityType(rawItems, entityFilter);
    items = filterEventsByViewMode(items, viewMode);
    items = filterEventsByActionType(items, actionFilter);
    items = enrichAuditEventsWithEmployees(items, employees);

    const resolvedPageSize = pageSize || AUDIT_DEFAULT_PAGE_SIZE;
    const useScroll =
      scrollable === true ||
      items.length > AUDIT_EMBEDDED_PAGE_SIZE ||
      (timeline && timeline.pageInfo && timeline.pageInfo.hasMore);

    const rawError = timeline && timeline.error;
    const errorMessage = rawError ? getApiErrorMessage(rawError, "") : "";
    const treatErrorAsEmpty =
      softEmptyOnError &&
      rawError &&
      (isApiNotFoundError(rawError) ||
        isApiForbiddenError(rawError) ||
        /audit.*disabled|not available|not enabled/i.test(errorMessage));
    const resolvedError = treatErrorAsEmpty ? null : rawError;

    let resolvedEmptyState = emptyState;
    if (treatErrorAsEmpty && emptyState) {
      resolvedEmptyState = {
        ...emptyState,
        description: isApiForbiddenError(rawError)
          ? "Audit viewing is disabled for your team or you do not have permission for these events."
          : emptyState.description,
      };
    } else if (!items.length && rawItems.length) {
      resolvedEmptyState = {
        eyebrow: "Filtered out",
        title: "No events match this filter",
        description: "Select All or pick a different action filter to see your timesheet audit events.",
        hints: ["Submitted events appear under Submitted or All"],
      };
    } else if (
      !items.length &&
      !rawItems.length &&
      isAuditConfigLoaded() &&
      !isAuditOrgEnabled()
    ) {
      resolvedEmptyState = {
        eyebrow: "Audit logging off",
        title: "No audit events recorded",
        description:
          "Organization audit logging (auditEnabled) is disabled, so submit and approval actions are not being stored.",
        hints: [
          "Ask your admin to enable auditEnabled under Application Config → Audit",
          "After enabling, new actions will appear here — older actions are not backfilled",
        ],
      };
    }

    return (
      <section className={classNames("lux-audit-panel", className)} aria-label={title || "Audit trail"}>
        {!hideHeader && (eyebrow || title) && (
          <header className="lux-audit-panel__head">
            <div>
              {eyebrow && <span className="lux-audit-panel__eyebrow">{eyebrow}</span>}
              {title && <h2 className="lux-audit-panel__title">{title}</h2>}
              {subtitle && <p className="lux-audit-panel__subtitle">{subtitle}</p>}
            </div>
            {timeline && !timeline.isLoading && (
              <span className="lux-audit-panel__count">
                {items.length} event{items.length === 1 ? "" : "s"}
              </span>
            )}
          </header>
        )}

        {(this.getActionFilterOptions() || (showToolbar !== false && this.getFilterOptions().length > 1)) && (
          <div className="lux-audit-panel__toolbar">
            {this.renderActionFilterChips()}
            {showToolbar !== false && this.renderFilterChips()}
          </div>
        )}

        {children}

        <AuditTimeline
          events={items}
          isLoading={timeline && timeline.isLoading}
          error={resolvedError}
          compact={compact === true}
          scrollable={useScroll}
          emptyState={resolvedEmptyState}
          pagination={
            timeline && (timeline.pageInfo || (timeline.page && timeline.page > 1))
              ? {
                  page: (timeline.pageInfo && timeline.pageInfo.page) || timeline.page || 1,
                  pageSize:
                    (timeline.pageInfo && timeline.pageInfo.pageSize) ||
                    timeline.pageSize ||
                    resolvedPageSize,
                  hasMore: timeline.pageInfo ? timeline.pageInfo.hasMore === true : false,
                }
              : null
          }
          onPageChange={this.handlePageChange}
          onEventDeepLink={onEventDeepLink}
        />
      </section>
    );
  }
}

const mapStateToProps = (state, ownProps) => {
  const scopeKey =
    ownProps.scope === AUDIT_SCOPES.ACTOR
      ? buildAuditScopeKey("actor", { actorUserId: ownProps.actorUserId })
      : buildAuditScopeKey("entity", {
          entityType: ownProps.entityType,
          entityId: ownProps.entityId,
        });

  return {
    timeline: state.audit && state.audit.timelines && state.audit.timelines[scopeKey],
  };
};

export default connect(mapStateToProps)(AuditTrailSection);
