import React, { Component } from "react";
import { summarizePendingTimesheetWeeks } from "./timesheetApproval.utils";
import TimesheetApprovalTable from "./TimesheetApprovalTable";
import { getPendingInboxEyebrow } from "_helpers/approvalAuthority.utils";

class TimesheetPendingApprovals extends Component {
  constructor(props) {
    super(props);
    this.state = { comments: {}, rejectErrors: {}, collapsed: false };
  }

  getComment = (weekId) => this.state.comments[weekId] || "";

  setComment = (weekId, value) => {
    this.setState((prevState) => ({
      comments: { ...prevState.comments, [weekId]: value },
      rejectErrors:
        prevState.rejectErrors[weekId] && value.trim()
          ? { ...prevState.rejectErrors, [weekId]: null }
          : prevState.rejectErrors,
    }));
  };

  handleReject = (week, comment) => {
    const { onReject, isLoading } = this.props;
    if (isLoading || !onReject || !week) return;
    const trimmed = (comment || "").trim();
    const commentKey = week.submissionId || week.id;
    if (!trimmed) {
      this.setState((prevState) => ({
        rejectErrors: {
          ...prevState.rejectErrors,
          [commentKey]: "Add a rejection comment before rejecting.",
        },
      }));
      return;
    }
    this.setState((prevState) => ({
      rejectErrors: { ...prevState.rejectErrors, [commentKey]: null },
    }));
    onReject(week, trimmed);
  };

  handleApprove = (week, comment) => {
    const { onApprove, isLoading } = this.props;
    if (isLoading || !onApprove || !week) return;
    onApprove(week, (comment || "").trim() || null);
  };

  toggleCollapsed = () => {
    this.setState((prevState) => ({ collapsed: !prevState.collapsed }));
  };

  renderCollapsedSummary = (summary) => (
    <button
      type="button"
      className="lux-ts-pending__collapsed-bar"
      onClick={this.toggleCollapsed}
      aria-expanded="false"
      aria-label={`${summary.total} pending timesheets. Click to expand.`}
    >
      <span className="lux-ts-pending__collapsed-icon" aria-hidden="true">
        <i className="fe fe-clock" />
      </span>
      <span className="lux-ts-pending__collapsed-copy">
        <strong>
          {summary.total} pending timesheet{summary.total === 1 ? "" : "s"} need your review
        </strong>
        <em>
          {summary.employeeCount} team member{summary.employeeCount === 1 ? "" : "s"}
        </em>
      </span>
      <span className="lux-ts-pending__count">{summary.total}</span>
      <span className="lux-ts-pending__collapsed-expand">
        Expand
        <i className="fe fe-chevron-down" aria-hidden="true" />
      </span>
    </button>
  );

  render() {
    const { weeks, isLoading, onOpenConflicts, onViewWeek, actingDelegations, employees } =
      this.props;
    const { collapsed } = this.state;

    if (!weeks || !weeks.length) return null;

    const summary = summarizePendingTimesheetWeeks(weeks);
    const inboxEyebrow = getPendingInboxEyebrow(weeks);

    if (collapsed) {
      return (
        <section
          className="lux-ts-pending lux-ts-pending--collapsed"
          aria-label="Pending timesheet approvals"
        >
          {this.renderCollapsedSummary(summary)}
        </section>
      );
    }

    return (
      <section className="lux-ts-pending" aria-label="Pending timesheet approvals">
        <header className="lux-ts-pending__head">
          <div>
            {inboxEyebrow && <span className="lux-ts-pending__eyebrow">{inboxEyebrow}</span>}
            <h3>Pending approvals</h3>
            <p>
              {summary.total} week{summary.total === 1 ? "" : "s"} across{" "}
              {summary.employeeCount} team member{summary.employeeCount === 1 ? "" : "s"}
            </p>
          </div>
          <div className="lux-ts-pending__head-actions">
            <span className="lux-ts-pending__count">{summary.total}</span>
            <button
              type="button"
              className="lux-ts-pending__toggle"
              onClick={this.toggleCollapsed}
              aria-expanded="true"
              aria-label="Collapse pending approvals"
            >
              Collapse
            </button>
          </div>
        </header>

        <TimesheetApprovalTable
          weeks={weeks}
          comments={this.state.comments}
          rejectErrors={this.state.rejectErrors}
          conflictCounts={this.props.conflictCounts}
          isLoading={isLoading}
          actingDelegations={actingDelegations}
          employees={employees}
          onCommentChange={this.setComment}
          onApprove={this.handleApprove}
          onReject={this.handleReject}
          onOpenConflicts={onOpenConflicts}
          onViewWeek={onViewWeek}
        />
      </section>
    );
  }
}

export default TimesheetPendingApprovals;
