import {
  toAreaChart,
  toDonutChart,
  toGroupedBarChart,
} from "views/hrms/components/dashboard/employeeDashboard.utils";

const STATUS_COLORS = {
  NEW: "#0ea5e9",
  ASSIGNED: "#6366f1",
  INPROGRESS: "#f59e0b",
  COMPLETED: "#10b981",
  CLOSED: "#475569",
};

const TIMELINE_COLORS = {
  OVERDUE: "#f43f5e",
  DUE_SOON: "#f59e0b",
  ON_TRACK: "#10b981",
  NO_DATE: "#94a3b8",
};

const TYPE_COLORS = ["#5b5ff4", "#8b5cf6", "#0ea5e9", "#f59e0b", "#14b8a6", "#10b981", "#64748b"];

const LUX_CHART_FONT = {
  fontFamily: "Inter, system-ui, sans-serif",
  fontSize: "11px",
  fontWeight: 600,
};

function applyLuxChartBase(options) {
  return {
    ...options,
    chart: { ...(options.chart || {}), fontFamily: LUX_CHART_FONT.fontFamily, toolbar: { show: false } },
    grid: { borderColor: "rgba(226,232,240,0.85)", strokeDashArray: 4, ...(options.grid || {}) },
  };
}

function withDonutCenter(chart, centerLabel, centerValue) {
  chart.options.plotOptions = {
    pie: {
      donut: {
        size: "76%",
        labels: {
          show: true,
          name: { show: true, fontSize: "11px", fontWeight: 600, color: "#64748b" },
          value: { show: true, fontSize: "15px", fontWeight: 800, color: "#0f172a" },
          total: {
            show: true,
            label: centerLabel,
            fontSize: "11px",
            fontWeight: 700,
            color: "#64748b",
            formatter: () => String(centerValue),
          },
        },
      },
    },
  };
  chart.options.legend = {
    position: "bottom",
    fontSize: "10px",
    fontWeight: 600,
    labels: { colors: "#475569" },
  };
  chart.options.stroke = { width: 2, colors: ["#fff"] };
  return chart;
}

function mixToDonut(mix, colorMap, centerLabel) {
  if (!mix || !mix.length) return null;
  const labels = mix.map((s) => s.label);
  const series = mix.map((s) => s.count);
  const colors = mix.map((s) => colorMap[s.key] || TYPE_COLORS[labels.indexOf(s.label) % TYPE_COLORS.length]);
  const total = series.reduce((a, b) => a + b, 0);
  return withDonutCenter(toDonutChart(labels, series, colors), centerLabel, total);
}

export function buildProjectStatusDonutChart(stat) {
  return mixToDonut(stat.statusMix, STATUS_COLORS, "Active");
}

export function buildProjectTimelineDonutChart(stat) {
  return mixToDonut(stat.timelineMix, TIMELINE_COLORS, "Open");
}

export function buildProjectOutcomeDonutChart(stat) {
  const { outcomes } = stat;
  if (!outcomes) return null;
  const labels = ["Open pipeline", "Completed", "Closed"];
  const series = [outcomes.open, outcomes.completed, outcomes.closed];
  if (!series.some((v) => v > 0)) return null;
  return withDonutCenter(
    toDonutChart(labels, series, ["#6366f1", "#10b981", "#64748b"]),
    "Portfolio",
    stat.active
  );
}

export function buildProjectTypeBarChart(stat) {
  const mix = stat.projectTypeMix;
  if (!mix || !mix.length) return null;
  return {
    series: [{ name: "Projects", data: mix.map((s) => s.count) }],
    options: applyLuxChartBase({
      chart: { type: "bar" },
      plotOptions: { bar: { horizontal: true, borderRadius: 4, barHeight: "68%" } },
      dataLabels: { enabled: false },
      xaxis: { categories: mix.map((s) => s.label) },
      colors: [TYPE_COLORS[0]],
    }),
  };
}

