export function buildProjectCreatedTrendAreaChart(stat) {
  const trend = stat.createdTrend;
  if (!trend || !trend.some((b) => b.count > 0)) return null;
  const chart = toAreaChart(
    trend.map((b) => b.label),
    [{ name: "New projects", data: trend.map((b) => b.count) }],
    ["#5b5ff4"]
  );
  return { series: chart.series, options: applyLuxChartBase(chart.options) };
}

export function buildProjectPoLinkDonutChart(stat) {
  const linked = stat.poLinked || 0;
  const unlinked = Math.max((stat.active || 0) - linked, 0);
  if (!linked && !unlinked) return null;
  return withDonutCenter(
    toDonutChart(["PO linked", "Standalone"], [linked, unlinked], ["#0ea5e9", "#94a3b8"]),
    "Active",
    stat.active
  );
}

