import React from "react";
import classNames from "classnames/bind";

/**
 * Shared rich KPI strip (governance luxury treatment).
 * Used by Admin, Payroll, Finance, and Governance module shells.
 */
export default function LuxKpiStrip({ cards, loading, className }) {
  const rows = cards || [];
  if (!rows.length) {
    return null;
  }

  return (
    <div
      className={classNames("lux-hrms-dash__kpi-strip", "lux-gov-kpi-strip", "lux-gov-lux__kpi-strip", className)}
      role="list"
      aria-busy={loading}
    >
      {rows.map((card, index) => (
        <article
          key={card.id || card.label || index}
          className={classNames("lux-hrms-dash__kpi", "lux-gov-kpi", card.tone && `is-${card.tone}`)}
          role="listitem"
        >
          <span className="lux-gov-kpi__accent" aria-hidden="true" />
          <span className="lux-gov-kpi__glow" aria-hidden="true" />
          <div className="lux-gov-kpi__inner">
            <div className="lux-gov-kpi__head">
              {card.icon ? (
                <span className={classNames("lux-gov-kpi__icon", card.tone && `is-${card.tone}`)} aria-hidden="true">
                  <i className={card.icon} />
                </span>
              ) : null}
              <span className="lux-hrms-dash__kpi-label">{card.label}</span>
            </div>
            <strong className="lux-hrms-dash__kpi-value">{loading ? "—" : card.value}</strong>
            {card.hint ? <span className="lux-hrms-dash__kpi-hint">{card.hint}</span> : null}
          </div>
        </article>
      ))}
    </div>
  );
}
