import React, { Component } from "react";
import { connect } from "react-redux";
import { appConfigActions } from "_actions";
import { store } from "_helpers";
import ApplicationConfigSection from "./components/ApplicationConfigSection";
import ApplicationConfigLeftMenu from "./components/ApplicationConfigLeftMenu";
import ApplicationConfigHero from "./components/ApplicationConfigHero";
import { commonUtils } from "_helpers";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

class ApplicationConfigPage extends Component {
    constructor() {
        super();
        this.state = {
            appConfigRequest: null,
            showConfigProperty: {
                name: { enabled: false },
                parent: { enabled: false },
                category: { enabled: false },
            },
        };
    }

    componentDidMount() {
        this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
        store.dispatch(this.props.initializeConfig(commonUtils.getCurrentUserTeamId()));
        this.syncConfigPropertyValues(this.props.selectedConfigData);
    }

    componentDidUpdate(previousProps) {
        const selectionChanged =
            this.props.appConfigMenuSelection &&
            previousProps.appConfigMenuSelection &&
            (previousProps.appConfigMenuSelection.id !== this.props.appConfigMenuSelection.id ||
                previousProps.appConfigMenuSelection.type !== this.props.appConfigMenuSelection.type);

        if (selectionChanged) {
            this.setState({
                showConfigProperty: {
                    name: { enabled: false },
                    parent: { enabled: false },
                    category: { enabled: false },
                },
            });
        }

        if (
            this.props.selectedConfigData &&
            previousProps.selectedConfigData !== this.props.selectedConfigData
        ) {
            this.syncConfigPropertyValues(this.props.selectedConfigData);
        }
    }

    syncConfigPropertyValues = (data) => {
        if (!data) return;

        this.setState((prevState) => ({
            showConfigProperty: {
                name: {
                    ...prevState.showConfigProperty.name,
                    enabled: prevState.showConfigProperty.name.enabled,
                    value: prevState.showConfigProperty.name.enabled
                        ? prevState.showConfigProperty.name.value
                        : data.name,
                },
                parent: {
                    ...prevState.showConfigProperty.parent,
                    enabled: prevState.showConfigProperty.parent.enabled,
                    value: prevState.showConfigProperty.parent.enabled
                        ? prevState.showConfigProperty.parent.value
                        : data.parent,
                },
                category: {
                    ...prevState.showConfigProperty.category,
                    enabled: prevState.showConfigProperty.category.enabled,
                    value: prevState.showConfigProperty.category.enabled
                        ? prevState.showConfigProperty.category.value
                        : data.category,
                },
            },
        }));
    };

    onChangeShowAddtionalOption = (propertyName, type, value) => {
        this.setState((prevState) => ({
            showConfigProperty: {
                ...prevState.showConfigProperty,
                [propertyName]: {
                    ...prevState.showConfigProperty[propertyName],
                    [type]: value,
                },
            },
        }));
    };

    handleSaveConfigPropertyFromHero = (propertyName) => {
        const propertyValue = this.state.showConfigProperty[propertyName].value;
        this.onChangeShowAddtionalOption(propertyName, "enabled", false);
        this.handleSaveConfigProperty(propertyName, propertyValue);
    };

    onAppConfigItemChange = (value) => {
        this.setState({
            appConfigRequest: {
                ...value,
            },
        });
    };

    handleAppConfigMenuSelect = (id, type) => {
        store.dispatch(this.props.configMenuChange(id, type));
        store.dispatch(this.props.getAppConfig(id, type));
    };

    handleCreateAppConfigItem = (value, parentId) => {
        store.dispatch(
            this.props.createNewConfig(this.props.appConfigMenuSelection.type, value, parentId)
        );
    };

    handleUpdateAppConfigItem = (configRequest) => {
        store.dispatch(this.props.updateConfig(configRequest, this.props.appConfigMenuSelection.id));
    };

    handleSaveConfigProperty = (propertyName, propertyValue) => {
        store.dispatch(
            this.props.updateConfigProperty(this.props.appConfigMenuSelection.id, propertyName, propertyValue)
        );
    };

    renderEmptyState = () => (
        <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-appconfig-empty"
            variant="config"
            eyebrow="Organization settings"
            title="Select a configuration item"
            description="Choose an organization unit or role from the tree on the left to view and edit settings, permissions, and module configuration."
            hints={[
                "Org units inherit defaults from parent nodes",
                "Role templates control module access per team",
                "Save changes to apply permissions across the workspace",
            ]}
        />
    );

    render() {
        return (
            <div className="applicationconfig lux-appconfig" data-testid="page-admin-appconfig">
                <ApplicationConfigHero
                    configMenuData={this.props.configMenuData}
                    appConfigMenuSelection={this.props.appConfigMenuSelection}
                    selectedConfigData={this.props.selectedConfigData}
                    parentMenuOptions={this.props.parentMenuOptions}
                    showConfigProperty={this.state.showConfigProperty}
                    onChangeShowAddtionalOption={this.onChangeShowAddtionalOption}
                    handleSaveConfigProperty={this.handleSaveConfigPropertyFromHero}
                />

                <div className="lux-appconfig__layout">
                    <aside className="lux-appconfig__sidebar">
                        <ApplicationConfigLeftMenu
                            handleAppConfigMenuSelect={this.handleAppConfigMenuSelect}
                            orgMenuData={this.props.configMenuData && this.props.configMenuData.org}
                            roleMenuData={this.props.configMenuData && this.props.configMenuData.role}
                            appConfigMenuSelection={this.props.appConfigMenuSelection}
                            handleCreateAppConfigItem={this.handleCreateAppConfigItem}
                        />
                    </aside>

                    <main className="lux-appconfig__main">
                        {this.props.selectedConfigData ? (
                            <ApplicationConfigSection
                                roles={this.props.configMenuData && this.props.configMenuData.role}
                                data={this.props.selectedConfigData}
                                onChange={() => {}}
                                menuSelection={this.props.appConfigMenuSelection}
                                handleUpdateAppConfigItem={this.handleUpdateAppConfigItem}
                                parentMenuOptions={this.props.parentMenuOptions}
                                handleSaveConfigProperty={this.handleSaveConfigProperty}
                            />
                        ) : (
                            this.renderEmptyState()
                        )}
                    </main>
                </div>
            </div>
        );
    }
}

const mapStateToProps = state => ({
    configMenuData: state.appconfig.configMenuData,
    configData: state.appconfig.configData,
    selectedConfigData: state.appconfig.selectedConfigData,
    appConfigMenuSelection : state.appconfig.appConfigMenuSelection,
    parentMenuOptions : state.appconfig.parentMenuOptions
});

const mapDispatchToProps = dispatch => ({
    initializeConfig: appConfigActions.initializeConfig,
    createNewConfig: appConfigActions.createNewConfig,
    updateConfig: appConfigActions.updateConfig,
    getAppConfig: appConfigActions.getAppConfig,
    configMenuChange: appConfigActions.configMenuChange,
    updateConfigProperty: appConfigActions.updateConfigProperty
});

export default connect(
    mapStateToProps,
    mapDispatchToProps
)(ApplicationConfigPage);
