import React, { useEffect, useMemo, useState } from "react";
import moment from "moment";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import {
  LEAVE_CALENDAR_WEEKDAYS,
  buildLeaveCalendarWeeks,
  groupLeavesForCalendar,
} from "./leave.utils";

function initials(name) {
  return String(name || "?")
    .split(" ")
    .filter(Boolean)
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

/**
 * Luxury team leave calendar — rich month atelier for /people/leaves Team view.
 */
function LeaveTeamCalendar({ leaves, employees, loading, monthDate, onMonthChange, workdays }) {
  const [selectedDayKey, setSelectedDayKey] = useState(null);

  const employeesById = useMemo(() => {
    const map = {};
    (employees || []).forEach((emp) => {
      map[emp.id] = emp;
    });
    return map;
  }, [employees]);

  const calendar = useMemo(
    () =>
      buildLeaveCalendarWeeks({
        monthDate,
        leaves,
        employeesById,
        workdays,
      }),
    [monthDate, leaves, employeesById, workdays]
  );

  const rows = useMemo(
    () => groupLeavesForCalendar(leaves, employeesById),
    [leaves, employeesById]
  );

  const uniqueEmployees = useMemo(() => new Set(rows.map((row) => row.employeeId)).size, [rows]);
  const totalDays = useMemo(
    () => rows.reduce((sum, row) => sum + (Number(row.days) || 0), 0),
    [rows]
  );
  const coveragePct = useMemo(() => {
    const teamSize = Math.max((employees || []).length, 1);
    return Math.round((uniqueEmployees / teamSize) * 100);
  }, [employees, uniqueEmployees]);

  useEffect(() => {
    setSelectedDayKey(null);
  }, [monthDate]);

  const selectedCell =
    calendar.weeks.flat().find((cell) => cell.key === selectedDayKey) ||
    calendar.weeks.flat().find((cell) => cell.inMonth && cell.isToday) ||
    calendar.peakDay ||
    null;

  const handlePrev = () => {
    if (onMonthChange) onMonthChange(calendar.month.clone().subtract(1, "month").toDate());
  };

  const handleNext = () => {
    if (onMonthChange) onMonthChange(calendar.month.clone().add(1, "month").toDate());
  };

  const handleToday = () => {
    if (onMonthChange) onMonthChange(moment().startOf("month").toDate());
  };

  const pulseCards = [
    {
      key: "people",
      label: "People away",
      value: uniqueEmployees,
      hint: "Unique employees",
      tone: "violet",
      icon: "fe fe-users",
    },
    {
      key: "blocks",
      label: "Leave blocks",
      value: rows.length,
      hint: "Approved / synced",
      tone: "indigo",
      icon: "fe fe-layers",
    },
    {
      key: "days",
      label: "Total days",
      value: totalDays,
      hint: "Across the month",
      tone: "amber",
      icon: "fe fe-sun",
      decimals: totalDays % 1 ? 1 : 0,
    },
    {
      key: "busy",
      label: "Busy days",
      value: calendar.busyDays,
      hint: coveragePct ? `${coveragePct}% of roster touched` : "Days with leave",
      tone: "rose",
      icon: "fe fe-activity",
    },
  ];

  return (
    <section
      className="lux-leave-cal lux-admin-atelier lux-admin-atelier--leave"
      data-testid="leave-team-calendar"
      aria-label="Team leave calendar"
    >
      <div className="lux-leave-cal__glow" aria-hidden="true" />

      <header className="lux-leave-cal__masthead">
        <div className="lux-leave-cal__masthead-main">
          <span className="lux-leave-cal__mark" aria-hidden="true">
            <i className="fe fe-calendar" />
          </span>
          <div>
            <p className="lux-leave-cal__eyebrow">Team view</p>
            <h3 className="lux-leave-cal__title">Leave calendar</h3>
            <p className="lux-leave-cal__lede">
              Rich month atelier for{" "}
              <strong>{calendar.monthLabel}</strong> — density, coverage, and who is away at a
              glance
            </p>
          </div>
        </div>
        {calendar.peakDay ? (
          <div className="lux-leave-cal__peak">
            <em>Peak day</em>
            <strong>{calendar.peakDay.day.format("MMM D")}</strong>
            <span>
              {calendar.peakDay.count} leave block{calendar.peakDay.count === 1 ? "" : "s"}
            </span>
          </div>
        ) : (
          <div className="lux-leave-cal__peak is-quiet">
            <em>Peak day</em>
            <strong>—</strong>
            <span>No leave density yet</span>
          </div>
        )}
      </header>

      <div className="lux-leave-cal__command">
        <div className="lux-leave-cal__month-band" aria-label="Change month">
          <div className="lux-leave-cal__month-band-line" aria-hidden="true" />
          <div className="lux-leave-cal__nav" role="group">
            <button
              type="button"
              onClick={handlePrev}
              disabled={loading}
              aria-label="Previous month"
            >
              <i className="fe fe-chevron-left" aria-hidden="true" />
            </button>
            <button type="button" className="is-today-btn" onClick={handleToday} disabled={loading}>
              Today
            </button>
            <strong className="lux-leave-cal__nav-month">{calendar.monthLabel}</strong>
            <button type="button" onClick={handleNext} disabled={loading} aria-label="Next month">
              <i className="fe fe-chevron-right" aria-hidden="true" />
            </button>
          </div>
          <div className="lux-leave-cal__month-band-line" aria-hidden="true" />
        </div>

        <div className="lux-leave-cal__pulse" aria-label="Month pulse">
          {pulseCards.map((card) => (
            <article
              key={card.key}
              className={classNames("lux-leave-cal__pulse-card", `is-${card.tone}`)}
            >
              <span className="lux-leave-cal__pulse-accent" aria-hidden="true" />
              <div className="lux-leave-cal__pulse-top">
                <span className="lux-leave-cal__pulse-icon" aria-hidden="true">
                  <i className={card.icon} />
                </span>
                <em>{card.label}</em>
              </div>
              <strong className="lux-leave-cal__pulse-value">
                {loading ? (
                  "—"
                ) : (
                  <CountUp
                    end={card.value || 0}
                    duration={0.7}
                    decimals={card.decimals || 0}
                  />
                )}
              </strong>
              <span className="lux-leave-cal__pulse-hint">{card.hint}</span>
            </article>
          ))}
        </div>
      </div>

      <div className="lux-leave-cal__body">
        <div className="lux-leave-cal__stage">
          <ul className="lux-leave-cal__legend" aria-label="Leave density legend">
            <li className="is-none">
              <i /> Clear
            </li>
            <li className="is-low">
              <i /> 1 away
            </li>
            <li className="is-medium">
              <i /> 2–3
            </li>
            <li className="is-high">
              <i /> 4+
            </li>
            <li className="is-weekend">
              <i /> Off day
            </li>
          </ul>

          {loading ? (
            <div className="lux-leave-cal__grid is-skeleton" aria-busy="true" />
          ) : (
            <div
              className="lux-leave-cal__grid"
              role="grid"
              aria-label={`${calendar.monthLabel} leave density`}
            >
              <div className="lux-leave-cal__weekdays" role="row">
                {LEAVE_CALENDAR_WEEKDAYS.map((label) => (
                  <span key={label} role="columnheader">
                    {label}
                  </span>
                ))}
              </div>
              {calendar.weeks.map((week, wi) => (
                <div key={`week-${wi}`} className="lux-leave-cal__week" role="row">
                  {week.map((cell) => {
                    const isSelected = selectedCell && selectedCell.key === cell.key;
                    return (
                      <button
                        key={cell.key}
                        type="button"
                        role="gridcell"
                        className={classNames("lux-leave-cal__cell", `is-${cell.heat}`, {
                          "is-out": !cell.inMonth,
                          "is-today": cell.isToday,
                          "is-weekend": cell.isWeekend,
                          "is-selected": isSelected,
                          "is-clickable": cell.inMonth,
                        })}
                        disabled={!cell.inMonth}
                        onClick={() => cell.inMonth && setSelectedDayKey(cell.key)}
                        aria-label={`${cell.day.format("MMM D")}: ${cell.count} leave block${
                          cell.count === 1 ? "" : "s"
                        }`}
                        data-testid={`leave-cal-day-${cell.key}`}
                      >
                        <span className="lux-leave-cal__cell-top">
                          <span className="lux-leave-cal__day-num">{cell.day.format("D")}</span>
                          {cell.isToday ? (
                            <span className="lux-leave-cal__cell-today">Now</span>
                          ) : null}
                        </span>
                        {cell.inMonth ? (
                          <>
                            <span className="lux-leave-cal__day-chip">
                              {cell.count > 0 ? (
                                <>
                                  <i className="fe fe-sun" aria-hidden="true" />
                                  <em>
                                    {cell.count} away
                                  </em>
                                </>
                              ) : cell.isWeekend ? (
                                <em className="is-muted">Off</em>
                              ) : (
                                <em className="is-muted">Clear</em>
                              )}
                            </span>
                            {cell.people.length > 0 ? (
                              <span className="lux-leave-cal__avatars" aria-hidden="true">
                                {cell.people.slice(0, 3).map((person) => (
                                  <span key={`${cell.key}-${person.employeeId}`}>
                                    {initials(person.name)}
                                  </span>
                                ))}
                                {cell.people.length > 3 ? (
                                  <span className="is-more">+{cell.people.length - 3}</span>
                                ) : null}
                              </span>
                            ) : (
                              <span className="lux-leave-cal__day-bar" aria-hidden="true">
                                <i style={{ width: cell.count ? "100%" : "8%" }} />
                              </span>
                            )}
                          </>
                        ) : null}
                      </button>
                    );
                  })}
                </div>
              ))}
            </div>
          )}
        </div>

        <aside className="lux-leave-cal__rail" aria-label="Day details">
          {!selectedCell || !selectedCell.inMonth ? (
            <div className="lux-leave-cal__rail-stack">
              <div className="lux-leave-cal__rail-hero is-idle">
                <span className="lux-leave-cal__rail-orb" aria-hidden="true">
                  <i className="fe fe-calendar" />
                </span>
                <p className="lux-leave-cal__eyebrow">Day atelier</p>
                <strong>Select a day</strong>
                <p>See who is away, leave types, and month coverage for that date.</p>
              </div>
            </div>
          ) : (
            <div className="lux-leave-cal__rail-stack">
              <div
                className={classNames(
                  "lux-leave-cal__rail-hero",
                  `is-${selectedCell.heat === "none" ? "idle" : selectedCell.heat}`
                )}
              >
                <div className="lux-leave-cal__rail-hero-top">
                  <p className="lux-leave-cal__eyebrow">Selected day</p>
                  {selectedCell.isToday ? (
                    <span className="lux-leave-cal__today-chip">Today</span>
                  ) : null}
                </div>
                <h4>{selectedCell.day.format("D")}</h4>
                <p className="lux-leave-cal__rail-date">
                  {selectedCell.day.format("dddd · MMMM D, YYYY")}
                </p>
                <span className={classNames("lux-leave-cal__status-pill", `is-${selectedCell.heat}`)}>
                  <i className="fe fe-users" aria-hidden="true" />
                  {selectedCell.count} leave block{selectedCell.count === 1 ? "" : "s"}
                </span>
              </div>

              {selectedCell.people.length === 0 ? (
                <div className="lux-leave-cal__insight-card">
                  <i className="fe fe-check-circle" aria-hidden="true" />
                  <div>
                    <strong>Full coverage</strong>
                    <em>No approved leave overlaps this day for the team roster.</em>
                  </div>
                </div>
              ) : (
                <ul className="lux-leave-cal__people" aria-label="People on leave">
                  {selectedCell.people.map((person) => (
                    <li key={`${selectedCell.key}-${person.employeeId}-${person.leaveType}`}>
                      <span className="lux-leave-cal__avatar" aria-hidden="true">
                        {initials(person.name)}
                      </span>
                      <div>
                        <strong>{person.name}</strong>
                        <em>
                          {person.leaveType}
                          {person.halfDay ? " · Half day" : ""}
                        </em>
                      </div>
                    </li>
                  ))}
                </ul>
              )}

              <div className="lux-leave-cal__insight-card is-amber">
                <i className="fe fe-info" aria-hidden="true" />
                <div>
                  <strong>Month pulse</strong>
                  <em>
                    {uniqueEmployees} people · {rows.length} blocks · {calendar.busyDays} busy days
                  </em>
                </div>
              </div>
            </div>
          )}
        </aside>
      </div>

      {loading ? (
        <div className="lux-leave-cal__register-skeleton" aria-busy="true" />
      ) : rows.length === 0 ? (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact lux-leave-empty"
          icon="fe fe-calendar"
          title="No approved leave this month"
          description={`No approved or synced leave between ${calendar.month
            .clone()
            .startOf("month")
            .format("MMM D")} and ${calendar.month.clone().endOf("month").format("MMM D")}.`}
        />
      ) : (
        <div className="lux-leave-cal__register-wrap">
          <div className="lux-leave-cal__register-head">
            <p className="lux-leave-cal__eyebrow">Leave register</p>
            <strong>Approved blocks in {calendar.monthLabel}</strong>
          </div>
          <div className="lux-leave-register-wrap lux-leave-cal__register">
            <table className="lux-leave-register">
              <thead>
                <tr>
                  <th>Employee</th>
                  <th>Dates</th>
                  <th>Type</th>
                  <th>Days</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {rows.map((row) => (
                  <tr key={row.id} className="lux-leave-register__row">
                    <td>
                      <span className="lux-leave-cal__employee">
                        <span className="lux-leave-cal__avatar" aria-hidden="true">
                          {initials(row.employeeName)}
                        </span>
                        <strong>{row.employeeName}</strong>
                      </span>
                    </td>
                    <td>
                      <span className="lux-leave-register__dates">{row.dateLabel}</span>
                    </td>
                    <td>
                      <span className="lux-leave-register__type">
                        <strong>{row.leaveTypeDescription || row.leaveTypeCode || "—"}</strong>
                        {row.halfDay && <em>Half day</em>}
                      </span>
                    </td>
                    <td>
                      <span className="lux-leave-register__duration">
                        {row.days != null ? row.days : "—"}
                      </span>
                    </td>
                    <td>
                      <span className={classNames("lux-leave-status-badge", `is-${row.statusMeta.tone}`)}>
                        {row.statusMeta.label}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </section>
  );
}

export default LeaveTeamCalendar;
