import React from "react";
import classNames from "classnames/bind";
import { ResourcesRegisterAtelier } from "views/resources/components/ResourcesLuxShared";

export default function SkillsProficiencyPanel({ distribution, loading }) {
  if (loading || !distribution || distribution.length === 0) {
    return null;
  }

  const total = distribution.reduce((sum, entry) => sum + (entry.count || 0), 0);
  const expertEntry = distribution.find((entry) => String(entry.id || "").toLowerCase() === "expert");
  const expertCount = expertEntry ? expertEntry.count : 0;

  return (
    <ResourcesRegisterAtelier
      tone="sky"
      className="lux-res-atelier--compact lux-skills-panel lux-skills-panel--mix"
      kickerIcon="fe fe-bar-chart-2"
      kicker="Depth mix"
      title="Proficiency mix"
      subtitle="How ratings spread across the roster"
      pulseCards={[
        { id: "ratings", label: "Ratings", value: total, tone: "sky" },
        { id: "expert", label: "Expert", value: expertCount, tone: "green" },
      ]}
    >
      <div className="lux-skills-distribution" role="list">
        {distribution.map((entry) => (
          <article
            key={entry.id}
            className={classNames("lux-skills-distribution__row", entry.tone && `is-${entry.tone}`)}
            role="listitem"
          >
            <div className="lux-skills-distribution__label">
              <span
                className={classNames(
                  "lux-skills-distribution__dot",
                  entry.tone && `is-${entry.tone}`
                )}
                aria-hidden="true"
              />
              <div className="lux-skills-distribution__copy">
                <strong>{entry.label}</strong>
                <span>{entry.pct}% of ratings</span>
              </div>
            </div>
            <div className="lux-skills-distribution__bar" aria-hidden="true">
              <span
                className={classNames(
                  "lux-skills-distribution__fill",
                  entry.tone && `is-${entry.tone}`
                )}
                style={{ width: `${entry.pct}%` }}
              />
            </div>
            <span className="lux-skills-distribution__count">
              <strong>{entry.count}</strong>
              <small>people</small>
            </span>
          </article>
        ))}
      </div>
    </ResourcesRegisterAtelier>
  );
}
