import { PLANNER_DAY_CAPACITY_MINUTES } from "./planner.utils";

const CAPACITY_STORAGE_KEY = "famstack-planner-capacity-overrides-v1";

export function readCapacityOverrides() {
  try {
    const raw = localStorage.getItem(CAPACITY_STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}

export function writeCapacityOverride(employeeId, dailyMinutes) {
  try {
    const all = readCapacityOverrides();
    if (dailyMinutes == null || dailyMinutes === "") {
      delete all[String(employeeId)];
    } else {
      all[String(employeeId)] = Number(dailyMinutes);
    }
    localStorage.setItem(CAPACITY_STORAGE_KEY, JSON.stringify(all));
    return all;
  } catch (e) {
    return readCapacityOverrides();
  }
}

/** Resolve billable capacity minutes per calendar day for one employee. */
export function getEmployeeDailyCapacityMinutes(employee, capacityOverrides) {
  const id = employee && employee.id != null ? String(employee.id) : null;
  if (capacityOverrides && id && capacityOverrides[id] != null) {
    const v = Number(capacityOverrides[id]);
    if (!Number.isNaN(v) && v >= 0) return v;
  }

  if (!employee) return PLANNER_DAY_CAPACITY_MINUTES;

  if (employee.plannerDayCapacityMins != null && employee.plannerDayCapacityMins !== "") {
    const v = Number(employee.plannerDayCapacityMins);
    if (!Number.isNaN(v) && v > 0) return v;
  }

  if (employee.dailyWorkMinutes != null) {
    const v = Number(employee.dailyWorkMinutes);
    if (!Number.isNaN(v) && v > 0) return v;
  }

  if (employee.workingHoursPerDay != null) {
    const v = Number(employee.workingHoursPerDay);
    if (!Number.isNaN(v) && v > 0) return Math.round(v * 60);
  }

  if (employee.fte != null && employee.fte !== "") {
    const fte = Number(employee.fte);
    if (!Number.isNaN(fte) && fte > 0 && fte <= 2) {
      return Math.round(PLANNER_DAY_CAPACITY_MINUTES * fte);
    }
  }

  if (employee.workWeekHours != null) {
    const w = Number(employee.workWeekHours);
    if (!Number.isNaN(w) && w > 0) return Math.round((w / 5) * 60);
  }

  return PLANNER_DAY_CAPACITY_MINUTES;
}

export function getDayCapacityMinutesForEmployee(
  employee,
  dayMoment,
  { holidayKeys, reduceForHolidays, leaveKeys, capacityOverrides }
) {
  const dayKey = dayMoment.format("YYYY-MM-DD");
  if (leaveKeys && leaveKeys.has(dayKey)) {
    return 0;
  }
  if (reduceForHolidays && holidayKeys && holidayKeys.has(dayKey)) {
    return 0;
  }
  return getEmployeeDailyCapacityMinutes(employee, capacityOverrides);
}
