/**
 * Strip internal feature / epic identifiers from user-visible copy.
 * Examples: F15, F17-T7, EA12, RDB-42
 */
export function polishUiCopy(text) {
  if (text == null || typeof text !== "string") {
    return text;
  }

  return text
    .replace(/^\s*\/\s*/g, "")
    .replace(/\bships in\s*\./gi, "is coming in a future release.")
    .replace(/\bships with\s*\.?\s*$/gi, "is coming in a future release.")
    .replace(/^gateway stub$/i, "Unavailable")
    .replace(/\bgateway stub\b/gi, "unavailable")
    .replace(/\s{2,}/g, " ")
    .trim();
}

export function sanitizeUiCopy(text) {
  if (text == null || typeof text !== "string") {
    return text;
  }

  if (!/\b(?:F\d{2}(?:-T\d+)?|EA\d+|RDB-\d+)\b/i.test(text)) {
    return polishUiCopy(text);
  }

  const stripped = text
    .replace(/\bF\d{2}(?:-T\d+)?\b/g, "")
    .replace(/\bRDB-\d+\b/gi, "")
    .replace(/\bEA\d+\b/gi, "")
    .replace(/(?:\s*·\s*)+/g, " · ")
    .replace(/(?:\s*—\s*)+/g, " — ")
    .replace(/^\s*[·—]\s*/, "")
    .replace(/\s*[·—]\s*$/, "")
    .replace(/\s{2,}/g, " ")
    .trim();

  return polishUiCopy(stripped);
}
