import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isFinanceIntelligenceEnabled } from "config/finance-intelligence.config";
import { REVENUE_FORECAST_PAGE_META } from "config/finance-intelligence-nav.config";
import { financeIntelligenceService } from "_services/financeIntelligence.service";
import FinanceLuxPage, {
  FinanceActionButton,
  FinanceInsightPanel,
  FinanceLuxPanel,
} from "views/finance/components/FinanceLuxShared";
import FinanceLoadAlert from "views/finance/components/FinanceLoadAlert";
import RevenueForecastPanel from "views/finance/components/RevenueForecastPanel";
import { shouldHideRegisterOnLoadError } from "_helpers/registerListError.utils";

class RevenueForecastPage extends Component {
  state = {
    loading: true,
    loadError: null,
    saving: false,
    dataSource: null,
    forecasts: [],
    activeForecast: null,
    chartSeries: [],
    kpiCards: [],
    insights: [],
    activeForecastId: null,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Revenue forecast");
    }
    this.loadData();
  }

  loadData = async (activeForecastId = this.state.activeForecastId) => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await financeIntelligenceService.listRevenueForecasts({ activeForecastId });
      const overview = result.overview || {};
      this.setState({
        loading: false,
        forecasts: result.payload || [],
        activeForecast: overview.activeForecast || null,
        chartSeries: overview.chartSeries || [],
        kpiCards: overview.kpiCards || [],
        insights: overview.insights || [],
        activeForecastId: overview.activeForecast ? overview.activeForecast.id : activeForecastId,
        dataSource: result.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: error,
      });
    }
  };

  handleSelectForecast = (forecastId) => {
    this.setState({ activeForecastId: forecastId }, () => this.loadData(forecastId));
  };

  handleSaveForecast = async () => {
    const { activeForecast } = this.state;
    if (!activeForecast) {
      return;
    }
    this.setState({ saving: true });
    try {
      await financeIntelligenceService.saveRevenueForecast({
        ...activeForecast,
        variancePct: Number(activeForecast.variancePct || 0) + 0.5,
      });
      await this.loadData(activeForecast.id);
    } catch (error) {
      this.setState({ loadError: error });
    } finally {
      this.setState({ saving: false });
    }
  };

  render() {
    if (!isFinanceIntelligenceEnabled()) {
      return <PersonaAccessDenied featureLabel="Revenue forecast" />;
    }

    const {
      loading,
      loadError,
      saving,
      dataSource,
      forecasts,
      activeForecast,
      chartSeries,
      kpiCards,
      insights,
      activeForecastId,
    } = this.state;
    const meta = REVENUE_FORECAST_PAGE_META;
    const hideRegister = shouldHideRegisterOnLoadError(loadError, forecasts);

    return (
      <FinanceLuxPage
        testId="page-finance-revenue-forecast"
        pageMeta={meta}
        dataSource={dataSource}
        demoLabel="Demo revenue forecast"
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <FinanceActionButton to="/finance/dashboard" icon="fe fe-grid" variant="ghost">
              Finance hub
            </FinanceActionButton>
            <FinanceActionButton to="/finance/project-financials" icon="fe fe-pie-chart" variant="primary">
              Project financials
            </FinanceActionButton>
          </>
        }
      >
        <FinanceInsightPanel insights={insights} />
        <FinanceLoadAlert
          error={loadError}
          fallback="Unable to load revenue forecasts."
          onDismiss={() => this.setState({ loadError: null })}
        />
        {hideRegister ? null : (
        <FinanceLuxPanel title={meta.panelTitle} meta={meta.panelMeta} icon="fe fe-trending-up" accent="green">
          <RevenueForecastPanel
            forecasts={forecasts}
            activeForecast={activeForecast}
            chartSeries={chartSeries}
            loading={loading}
            activeForecastId={activeForecastId}
            onSelectForecast={this.handleSelectForecast}
            onSaveForecast={this.handleSaveForecast}
            saving={saving}
          />
        </FinanceLuxPanel>
        )}
      </FinanceLuxPage>
    );
  }
}

export default RevenueForecastPage;
