import React, { Component } from "react";
import classNames from "classnames/bind";
import { validationUtils } from "_helpers";
import {
  resolveServiceLineLabel,
  formatEstimateHoursDisplay,
  formatEstimateRateDisplay,
  formatEstimateCostDisplay,
  getServiceLineEstimatePermissionNotes,
} from "./projectServiceLine.utils";

/**
 * In-panel service line multi-select (checkbox chips) — avoids react-select clipping in modals.
 */
class ProjectServiceLinePicker extends Component {
  state = { query: "" };

  getOptions = () => this.props.options || [];

  getSelected = () => {
    const raw = this.props.value;
    if (!raw) return [];
    return Array.isArray(raw) ? raw : [raw];
  };

  toggle = (value) => {
    const selected = this.getSelected();
    const next = selected.includes(value)
      ? selected.filter((v) => v !== value)
      : [...selected, value];
    this.props.onChange(next.length ? next : null);
  };

  render() {
    const { readOnly, emptyMessage, sectionTitle, sectionHint } = this.props;
    const options = this.getOptions();
    const selected = this.getSelected();
    const q = this.state.query.trim().toLowerCase();
    const filtered = q
      ? options.filter((o) => (o.label || o.value || "").toLowerCase().includes(q))
      : options;

    if (!options.length) {
      return (
        <div className="lux-project-svc-picker lux-project-svc-picker--empty">
          <i className="fe fe-alert-circle" aria-hidden="true" />
          <p>{emptyMessage || "No service lines are configured. Link a purchase contract or check application settings."}</p>
        </div>
      );
    }

    return (
      <section className="lux-project-svc-picker">
        {(sectionTitle || sectionHint) && (
          <header className="lux-project-svc-picker__head">
            {sectionTitle && <strong>{sectionTitle}</strong>}
            {sectionHint && <span>{sectionHint}</span>}
          </header>
        )}
        {options.length > 6 && (
          <div className="lux-project-svc-picker__search">
            <i className="fe fe-search" aria-hidden="true" />
            <input
              type="search"
              value={this.state.query}
              onChange={(e) => this.setState({ query: e.target.value })}
              placeholder="Search service types…"
              aria-label="Search service types"
            />
          </div>
        )}
        <div className="lux-project-svc-picker__grid" role="group" aria-label="Service types">
          {filtered.map((opt) => {
            const value = opt.value;
            const label = opt.label || value;
            const isOn = selected.includes(value);
            return (
              <button
                key={value}
                type="button"
                disabled={readOnly}
                className={classNames("lux-project-svc-picker__chip", { "is-selected": isOn })}
                onClick={() => this.toggle(value)}
                aria-pressed={isOn}
                title={label}
              >
                <span className="lux-project-svc-picker__check" aria-hidden="true">
                  <i className={isOn ? "fe fe-check" : "fe fe-plus"} />
                </span>
                <span className="lux-project-svc-picker__label">{label}</span>
              </button>
            );
          })}
        </div>
        {!filtered.length && (
          <p className="lux-project-svc-picker__no-match">No service types match your search.</p>
        )}
      </section>
    );
  }
}

function EstimateField({ label, value, readOnly, placeholder, onChange, validate }) {
  const handleChange = (event) => {
    const next = event.target.value;
    if (validate && !validate(next)) return;
    onChange(next);
  };

  return (
    <label className="lux-project-svc-estimate__field">
      <span className="lux-project-svc-estimate__field-label">{label}</span>
      <input
        type="text"
        className="lux-project-svc-estimate__field-input"
        value={value || ""}
        readOnly={readOnly}
        placeholder={placeholder}
        onChange={handleChange}
        inputMode="decimal"
      />
    </label>
  );
}

function EstimateStaticValue({ label, text, isPlaceholder, hint, isTotal }) {
  return (
    <div
      className={classNames("lux-project-svc-estimate__field", {
        "lux-project-svc-estimate__field--total": isTotal,
      })}
    >
      <span className="lux-project-svc-estimate__field-label">{label}</span>
      <span
        className={classNames("lux-project-svc-estimate__field-static", {
          "is-placeholder": isPlaceholder,
        })}
      >
        {text}
      </span>
      {hint && <span className="lux-project-svc-estimate__field-hint">{hint}</span>}
    </div>
  );
}

export function ProjectServiceLineEstimateTable({
  readOnly,
  permissionFlags,
  selectedLines,
  serviceLineEstimate,
  parentServiceLineEstimate,
  onLineEstimateChange,
  options,
}) {
  if (!selectedLines || !selectedLines.length) {
    return (
      <p className="lux-project-svc-estimate__empty">
        Select service types above to enter estimated hours and rates.
      </p>
    );
  }

  const flags = permissionFlags || {};
  const permNotes = getServiceLineEstimatePermissionNotes(flags);

  return (
    <section className="lux-project-svc-estimate">
      <header className="lux-project-svc-estimate__head">
        <div>
          <strong>2 · Effort by service type</strong>
          <span>Enter hours and hourly rate for each selected line.</span>
        </div>
      </header>
      {permNotes.length > 0 && (
        <div className="lux-project-svc-field__perm-notes" role="status">
          {permNotes.map((note) => (
            <span key={note} className="lux-project-svc-field__perm-note">
              <i className="fe fe-lock" aria-hidden="true" />
              {note}
            </span>
          ))}
        </div>
      )}
      <div className="lux-project-svc-estimate__cards">
        {selectedLines.map((line) => {
          const row =
            (serviceLineEstimate && serviceLineEstimate[line]) ||
            (parentServiceLineEstimate && parentServiceLineEstimate[line]) ||
            {};
          const hoursDisplay = formatEstimateHoursDisplay(row.estHours);
          const rateDisplay = formatEstimateRateDisplay(row.estHourlyRate);
          const costDisplay = formatEstimateCostDisplay(row.estHours, row.estHourlyRate);
          const label = resolveServiceLineLabel(line, options);

          const patchRow = (field, val) => {
            onLineEstimateChange(line, { ...row, [field]: val });
          };

          const hoursEditable = !readOnly && flags.hoursView && flags.hoursEdit;
          const rateEditable = !readOnly && flags.costView && flags.costEdit;

          return (
            <article key={line} className="lux-project-svc-estimate__card">
              <h5 className="lux-project-svc-estimate__card-title">{label}</h5>
              <div className="lux-project-svc-estimate__card-fields">
                {!flags.hoursView ? (
                  <EstimateStaticValue
                    label="Est. hours"
                    text="--"
                    isPlaceholder={true}
                    hint="View disabled"
                  />
                ) : hoursEditable ? (
                  <EstimateField
                    label="Est. hours"
                    value={row.estHours}
                    readOnly={false}
                    placeholder="--"
                    validate={(val) => !val || validationUtils.validateHourDecimal(val)}
                    onChange={(val) => patchRow("estHours", val)}
                  />
                ) : (
                  <EstimateStaticValue
                    label="Est. hours"
                    text={hoursDisplay.text}
                    isPlaceholder={hoursDisplay.isPlaceholder}
                    hint={!flags.hoursEdit ? "Edit disabled" : undefined}
                  />
                )}
                {!flags.costView ? (
                  <EstimateStaticValue
                    label="Hourly rate ($)"
                    text="$--"
                    isPlaceholder={true}
                    hint="View disabled"
                  />
                ) : rateEditable ? (
                  <EstimateField
                    label="Hourly rate ($)"
                    value={row.estHourlyRate}
                    readOnly={false}
                    placeholder="$--"
                    validate={(val) => !val || validationUtils.validateDecimalNumberic(val)}
                    onChange={(val) => patchRow("estHourlyRate", val)}
                  />
                ) : (
                  <EstimateStaticValue
                    label="Hourly rate ($)"
                    text={rateDisplay.text}
                    isPlaceholder={rateDisplay.isPlaceholder}
                    hint={!flags.costEdit ? "Edit disabled" : undefined}
                  />
                )}
                <EstimateStaticValue
                  label="Est. cost"
                  text={flags.costView ? costDisplay.text : "$--"}
                  isPlaceholder={!flags.costView || costDisplay.isPlaceholder}
                  hint={!flags.costView ? "View disabled" : undefined}
                  isTotal={true}
                />
              </div>
            </article>
          );
        })}
      </div>
    </section>
  );
}

export default ProjectServiceLinePicker;
