export const GOVERNANCE_KPI_ICONS = {
  blue: "fe fe-layers",
  green: "fe fe-check-circle",
  rose: "fe fe-alert-triangle",
  amber: "fe fe-clock",
  violet: "fe fe-shield",
  slate: "fe fe-git-branch",
  indigo: "fe fe-flag",
};

export function enrichGovernanceInsights(insights = []) {
  return (insights || []).map((row) => ({
    ...row,
    icon: row.icon || GOVERNANCE_INSIGHT_ICONS[row.tone] || GOVERNANCE_INSIGHT_ICONS.slate,
  }));
}

export function enrichGovernanceKpiCards(cards = []) {
  return (cards || []).map((row) => ({
    ...row,
    icon: row.icon || GOVERNANCE_KPI_ICONS[row.tone] || GOVERNANCE_KPI_ICONS.slate,
  }));
}

const QUICK_LINK_TONES = {
  blue: "blue",
  indigo: "primary",
  amber: "amber",
  rose: "rose",
  violet: "violet",
};

export function getGovernanceQuickLinks(activeId) {
  return GOVERNANCE_MODULE_NAV.filter((item) => item.id !== activeId)
    .slice(0, 3)
    .map((item) => {
      const meta = GOVERNANCE_PAGE_META[item.id] || {};
      return {
        path: item.path,
        label: item.label,
        icon: item.icon,
        desc: meta.lede || "",
        tone: QUICK_LINK_TONES[meta.tone] || "primary",
      };
    });
}
