import React from "react";
import classNames from "classnames/bind";

export default function TimesheetRecommendationPanel({ recommendation, loading, compact }) {
  // Keep showing the last suggestion while a background refresh runs so the
  // board does not flicker between content and skeleton on every reload.
  if (loading && !recommendation) {
    return (
      <section
        className={classNames("lux-ts-intel__rec", { "is-compact": compact, "is-loading": true })}
        aria-busy="true"
      >
        <div className="lux-ts-intel__rec-skeleton" />
      </section>
    );
  }
  if (!recommendation) {
    return null;
  }

  const confidence = Math.round((recommendation.confidence || 0) * 100);

  return (
    <section
      className={classNames("lux-ts-intel__rec", {
        "is-compact": compact,
        "is-refreshing": loading,
      })}
      aria-busy={loading ? "true" : undefined}
      aria-label="Timesheet recommendation"
    >
      <div className="lux-ts-intel__rec-glow" aria-hidden="true" />

      <header className="lux-ts-intel__rec-head">
        <div>
          <span className="lux-ts-intel__rec-kicker">
            <i className="fe fe-zap" aria-hidden="true" />
            Weekly insight
          </span>
          <h4 className="lux-ts-intel__rec-title">Recommended action</h4>
        </div>
        <span className="lux-ts-intel__rec-badge">AI suggestion</span>
      </header>

      <p className="lux-ts-intel__rec-summary">{recommendation.summary}</p>
      <p className="lux-ts-intel__rec-action">{recommendation.recommendation}</p>

      <footer className="lux-ts-intel__rec-meta">
        <span
          className={classNames("lux-ts-intel__rec-confidence", {
            "is-high": confidence >= 75,
            "is-medium": confidence >= 50 && confidence < 75,
          })}
        >
          Confidence {confidence}%
        </span>
        {recommendation.disclaimer && (
          <span className="lux-ts-intel__rec-disclaimer">{recommendation.disclaimer}</span>
        )}
      </footer>
    </section>
  );
}
