import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPayrollManagementEnabled } from "config/payroll.config";
import { buildSalaryStructureMetrics, formatPayrollDate } from "config/payroll.utils";
import { payrollService } from "_services/payroll.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { PayrollStructuresRegister } from "views/payroll/components/PayrollRegister";
import {
  PayrollActionButton,
  PayrollLuxPage,
  PayrollPanelHead,
} from "views/payroll/components/PayrollLuxShared";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

class SalaryStructuresPage extends Component {
  state = { structures: [], loading: true, loadError: null, dataSource: null };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Salary structures");
    this.loadStructures();
  }

  loadStructures = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await payrollService.listSalaryStructures();
      this.setState({ structures: result.payload || [], loading: false, dataSource: result.source || null });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load salary structures.", structures: [] });
    }
  };

  render() {
    if (!isPayrollManagementEnabled()) {
      return <PersonaAccessDenied moduleName="Salary structures" reason="Payroll management is not enabled." />;
    }

    const { structures, loading, loadError, dataSource } = this.state;
    const metrics = buildSalaryStructureMetrics(structures);
    const kpiCards = [
      { id: "total", label: "Structures", value: metrics.total, hint: "Component templates", tone: "primary", icon: "fe fe-sliders" },
      { id: "active", label: "Active", value: metrics.active, hint: "In production use", tone: "green", icon: "fe fe-check-circle" },
      { id: "employees", label: "Employees mapped", value: metrics.employees, hint: "Across all structures", tone: "blue", icon: "fe fe-users" },
      { id: "components", label: "Avg components", value: metrics.avgComponents, hint: `${metrics.draft} draft structure(s)`, tone: "violet", icon: "fe fe-grid" },
    ];

    return (
      <PayrollLuxPage
        dataSource={dataSource}
        pageMeta={DENSE_PAGE_META.salaryStructures}
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <PayrollActionButton to="/payroll/dashboard" icon="fe fe-pie-chart" variant="ghost">
              Dashboard
            </PayrollActionButton>
            <PayrollActionButton to="/payroll/groups" icon="fe fe-users" variant="primary">
              Payroll groups
            </PayrollActionButton>
          </>
        }
      >
        {loadError && <div className="lux-employee-360__error" role="alert">{loadError}</div>}

        {!loading && structures.length > 0 && (
          <div className="lux-payroll-summary-grid">
            {structures.map((row) => (
              <article key={row.id} className="lux-payroll-summary-card">
                <div className="lux-payroll-summary-card__head">
                  <span className={classNames("lux-doc-badge", row.status === "Active" ? "is-success" : "is-warning")}>{row.status}</span>
                  <span className="lux-payroll-summary-card__code">{row.code}</span>
                </div>
                <h3 className="lux-payroll-summary-card__title">{row.name}</h3>
                <p className="lux-payroll-summary-card__meta">{row.payFrequency} · {row.currency}</p>
                <dl className="lux-payroll-summary-card__stats">
                  <div><dt>Components</dt><dd>{row.componentCount}</dd></div>
                  <div><dt>Employees</dt><dd>{row.employeeCount}</dd></div>
                  <div><dt>Updated</dt><dd>{formatPayrollDate(row.updatedAt)}</dd></div>
                </dl>
              </article>
            ))}
          </div>
        )}

        <section className="lux-hrms-dash__panel lux-payroll-panel">
          <PayrollPanelHead title="Structure register" subtitle="Base component, pay frequency, and employee mapping per template" />
          <div className="lux-hrms-dash__panel-body">
            {loading ? (
              <LuxRegisterEmptyState className="lux-register-empty--compact" title="Loading structures" description="Fetching salary structure catalog." />
            ) : structures.length === 0 ? (
              <LuxRegisterEmptyState className="lux-register-empty--compact" icon="fe fe-sliders" title="No salary structures" description="Configure earnings and deduction components." />
            ) : (
              <PayrollStructuresRegister structures={structures} />
            )}
          </div>
        </section>
      </PayrollLuxPage>
    );
  }
}

export default SalaryStructuresPage;
