import React, { Component } from "react";
import { Link } from "react-router-dom";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPayrollManagementEnabled } from "config/payroll.config";
import { buildPayrollDashboardMetrics, formatPayrollDate } from "config/payroll.utils";
import { payrollService } from "_services/payroll.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import PayrollReadinessPanel from "views/payroll/components/PayrollReadinessPanel";
import PayrollExceptionQueue from "views/payroll/components/PayrollExceptionQueue";
import { PayrollRecentRunsRegister } from "views/payroll/components/PayrollRegister";
import {
  PayrollActionButton,
  PayrollLuxPage,
  PayrollPanelHead,
  PayrollPanelLink,
} from "views/payroll/components/PayrollLuxShared";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

class PayrollDashboardPage extends Component {
  state = {
    runs: [],
    groups: [],
    exceptions: [],
    loading: true,
    loadError: null,
    dataSource: null,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Payroll dashboard");
    this.loadDashboard();
  }

  loadDashboard = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await payrollService.getDashboard();
      this.setState({
        runs: result.runs || [],
        groups: result.groups || [],
        exceptions: result.exceptions || [],
        loading: false,
        dataSource: result.source || null,
      });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load payroll dashboard.", runs: [], groups: [], exceptions: [] });
    }
  };

  renderInsightAlerts = () => {
    const { runs, exceptions, groups, loading } = this.state;
    if (loading) {
      return null;
    }
    const metrics = buildPayrollDashboardMetrics(runs, exceptions, groups);
    const alerts = [];
    if (metrics.blockers > 0) {
      alerts.push({
        id: "blockers",
        tone: "amber",
        icon: "fe fe-alert-triangle",
        title: `${metrics.blockers} payroll blocker(s)`,
        copy: "Resolve exceptions before finalizing open runs.",
        to: "/payroll/runs",
      });
    }
    if (metrics.pendingApproval > 0) {
      alerts.push({
        id: "approval",
        tone: "green",
        icon: "fe fe-check-circle",
        title: `${metrics.pendingApproval} run(s) awaiting approval`,
        copy: "Review calculated totals and submit sign-off.",
        to: "/workspace/approvals",
      });
    }
    if (metrics.nextPayDate) {
      alerts.push({
        id: "paydate",
        tone: "green",
        icon: "fe fe-calendar",
        title: `Next pay date · ${formatPayrollDate(metrics.nextPayDate)}`,
        copy: `${metrics.groups} active payroll group(s) on schedule.`,
        to: "/payroll/groups",
      });
    }
    if (alerts.length === 0) {
      return null;
    }
    return (
      <div className="lux-payroll-insights" role="list">
        {alerts.map((alert) => (
          <Link key={alert.id} to={alert.to} className={`lux-hrms-dash__alert lux-payroll-insight is-${alert.tone}`} role="listitem">
            <span className="lux-hrms-dash__alert-icon" aria-hidden="true"><i className={alert.icon} /></span>
            <span className="lux-payroll-insight__copy">
              <strong>{alert.title}</strong>
              <small>{alert.copy}</small>
            </span>
            <i className="fe fe-chevron-right lux-payroll-insight__chevron" aria-hidden="true" />
          </Link>
        ))}
      </div>
    );
  };

  render() {
    if (!isPayrollManagementEnabled()) {
      return <PersonaAccessDenied moduleName="Payroll" reason="Payroll management is not enabled for your organization." />;
    }

    const { runs, groups, exceptions, loading, loadError, dataSource } = this.state;
    const metrics = buildPayrollDashboardMetrics(runs, exceptions, groups);
    const recentRuns = [...runs].slice(0, 5);
    const kpiCards = [
      { id: "readiness", label: "Avg readiness", value: `${metrics.avgReadiness}%`, hint: "Across open runs", tone: metrics.avgReadiness >= 90 ? "green" : "amber", icon: "fe fe-activity" },
      { id: "open", label: "Open runs", value: metrics.openRuns, hint: `${metrics.totalRuns} total cycles`, tone: "primary", icon: "fe fe-layers" },
      { id: "approval", label: "Pending approval", value: metrics.pendingApproval, hint: "Needs sign-off", tone: "amber", icon: "fe fe-clock" },
      { id: "blockers", label: "Blockers", value: metrics.blockers, hint: "Must resolve", tone: metrics.blockers > 0 ? "rose" : "green", icon: "fe fe-alert-triangle" },
    ];

    return (
      <PayrollLuxPage
        testId="page-payroll-dashboard"
        dataSource={dataSource}
        pageMeta={DENSE_PAGE_META.payrollDashboard}
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <PayrollActionButton to="/payroll/runs" icon="fe fe-plus" variant="primary">
              New payroll run
            </PayrollActionButton>
            <PayrollActionButton to="/payroll/groups" icon="fe fe-users" variant="ghost">
              Groups
            </PayrollActionButton>
          </>
        }
      >
        {loadError && <div className="lux-employee-360__error" role="alert">{loadError}</div>}
        {this.renderInsightAlerts()}

        <div className="lux-payroll-dashboard__grid">
          <section className="lux-hrms-dash__panel lux-payroll-panel lux-payroll-panel--accent">
            <PayrollPanelHead title="Readiness by run" subtitle="Lowest scores need attention before approval" />
            <div className="lux-hrms-dash__panel-body">
              {loading ? (
                <LuxRegisterEmptyState className="lux-register-empty--compact" title="Loading readiness" description="Calculating payroll readiness scores." />
              ) : (
                <PayrollReadinessPanel runs={runs} />
              )}
            </div>
          </section>

          <section className="lux-hrms-dash__panel lux-payroll-panel">
            <PayrollPanelHead title="Exception queue" subtitle="Open blockers and warnings across runs" />
            <div className="lux-hrms-dash__panel-body">
              <PayrollExceptionQueue exceptions={exceptions} loading={loading} compact />
            </div>
          </section>
        </div>

        <section className="lux-hrms-dash__panel lux-payroll-panel">
          <PayrollPanelHead
            title="Recent runs"
            subtitle="Latest payroll cycles with gross totals and readiness"
            actions={<PayrollPanelLink to="/payroll/runs">View all runs</PayrollPanelLink>}
          />
          <div className="lux-hrms-dash__panel-body">
            {loading ? (
              <LuxRegisterEmptyState className="lux-register-empty--compact" title="Loading runs" description="Fetching payroll runs." />
            ) : recentRuns.length === 0 ? (
              <LuxRegisterEmptyState className="lux-register-empty--compact" icon="fe fe-layers" title="No payroll runs" description="Create a run to start the payroll cycle." />
            ) : (
              <PayrollRecentRunsRegister rows={recentRuns} />
            )}
          </div>
        </section>
      </PayrollLuxPage>
    );
  }
}

export default PayrollDashboardPage;
