import React from "react";
import classNames from "classnames/bind";
import {
  formatLeaveDateRange,
  formatLeaveDays,
  getWorkflowStatusMeta,
  getLeaveTypeLabel,
  isPendingLeave,
  isDraftLeave,
  isApprovedLeave,
} from "./leave.utils";
import LeaveSyncStatusBadge from "./LeaveSyncStatusBadge";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import ApprovalRemindApproverButton from "../delegation/ApprovalRemindApproverButton";

function isProofReadyStatus(status) {
  const s = String(status || "").toUpperCase();
  return ["LINKED", "UPLOADED", "SUBMITTED", "APPROVED", "VERIFIED", "COMPLETE", "COMPLETED"].includes(s);
}

function openDocRequestsForLeave(documentRequests, leave) {
  if (!leave || !leave.id || !Array.isArray(documentRequests)) return [];
  return documentRequests.filter((req) => {
    if (!req) return false;
    if (String(req.sourceId) !== String(leave.id) && req.sourceId != null) return false;
    return !isProofReadyStatus(req.status);
  });
}

function LeaveHistoryTable({
  leaves,
  documentRequests,
  loading,
  onViewAudit,
  onRetryPromote,
  retryLeaveId,
  onWithdraw,
  onCancel,
  onSubmitDraft,
  onLinkProof,
  currentUserId,
  permission,
}) {
  if (loading) {
    return <div className="lux-leave-register__skeleton" aria-busy="true" role="status" />;
  }

  const list = (leaves || []).slice().sort((a, b) => {
    const da = a.submittedAt || a.createdDate || a.applicationFromDate;
    const db = b.submittedAt || b.createdDate || b.applicationFromDate;
    return String(db).localeCompare(String(da));
  });

  if (!list.length) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact lux-leave-empty"
        icon="fe fe-calendar"
        title="No leave requests yet"
        description="Apply for leave or sync from HR to see your history here."
      />
    );
  }

  return (
    <div className="lux-leave-register-wrap">
      <table className="lux-leave-register">
        <thead>
          <tr>
            <th>Type</th>
            <th>Dates</th>
            <th>Duration</th>
            <th>Status</th>
            <th>Source</th>
            <th>Reason</th>
            <th aria-hidden="true" />
          </tr>
        </thead>
        <tbody>
          {list.map((leave) => {
            const status = getWorkflowStatusMeta(leave);
            const isOwner =
              currentUserId &&
              String(leave.employeeId || leave.employee_id) === String(currentUserId);
            const canWithdraw = (isPendingLeave(leave) || isDraftLeave(leave)) && isOwner && onWithdraw;
            const canCancel = isApprovedLeave(leave) && isOwner && onCancel;
            const canSubmitDraft = isDraftLeave(leave) && isOwner && onSubmitDraft;
            const openDocs = openDocRequestsForLeave(documentRequests, leave);

            return (
              <tr key={leave.id} className="lux-leave-register__row">
                <td>
                  <span className="lux-leave-register__type">
                    <strong>{getLeaveTypeLabel(leave.leaveTypeCode, leave.leaveTypeDescription)}</strong>
                    {leave.halfDay && <em>Half day</em>}
                  </span>
                </td>
                <td>
                  <span className="lux-leave-register__dates">{formatLeaveDateRange(leave)}</span>
                </td>
                <td>
                  <span className="lux-leave-register__duration">{formatLeaveDays(leave)}</span>
                </td>
                <td>
                  <span className={classNames("lux-leave-status-badge", `is-${status.tone}`)}>
                    {status.label}
                  </span>
                  {openDocs.length > 0 && (
                    <p className="lux-leave-register__comment" title="Proof required before submit">
                      Docs needed ({openDocs.map((d) => d.documentType || "proof").join(", ")})
                    </p>
                  )}
                  {leave.approvalComment && (
                    <p className="lux-leave-register__comment" title={leave.approvalComment}>
                      {leave.approvalComment}
                    </p>
                  )}
                </td>
                <td>
                  <LeaveSyncStatusBadge
                    leave={leave}
                    onRetry={onRetryPromote}
                    retryInProgress={retryLeaveId === leave.id}
                  />
                </td>
                <td>
                  <span className="lux-leave-register__reason">{leave.reason || "—"}</span>
                </td>
                <td>
                  <div className="lux-leave-register__actions">
                    {onViewAudit && (
                      <button
                        type="button"
                        className="lux-leave-register__action"
                        onClick={() => onViewAudit(leave)}
                      >
                        Audit
                      </button>
                    )}
                    {openDocs.length > 0 && onLinkProof && isOwner && (
                      <button
                        type="button"
                        className="lux-leave-register__action"
                        data-testid={`leave-link-proof-${leave.id}`}
                        onClick={() => onLinkProof(leave, openDocs[0])}
                      >
                        Link proof
                      </button>
                    )}
                    {canSubmitDraft && (
                      <button
                        type="button"
                        className="lux-leave-register__action"
                        data-testid={`leave-submit-draft-${leave.id}`}
                        onClick={() => onSubmitDraft(leave)}
                      >
                        Submit
                      </button>
                    )}
                    {canWithdraw && onWithdraw && (
                      <button
                        type="button"
                        className="lux-leave-register__action is-muted"
                        onClick={() => onWithdraw(leave)}
                      >
                        Withdraw
                      </button>
                    )}
                    {canCancel && (
                      <button
                        type="button"
                        className="lux-leave-register__action is-muted"
                        data-testid={`leave-cancel-${leave.id}`}
                        onClick={() => onCancel(leave)}
                      >
                        Cancel
                      </button>
                    )}
                    {canWithdraw && leave.id && (leave.employeeId || leave.employee_id) && (
                      <ApprovalRemindApproverButton
                        visible={true}
                        requestType="LEAVE"
                        referenceId={leave.id}
                        employeeId={leave.employeeId || leave.employee_id}
                        permission={permission}
                        compact={true}
                      />
                    )}
                  </div>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export default LeaveHistoryTable;
