import React, { Component } from "react";
import LuxListCountSkeleton from "views/common/fragments/LuxListCountSkeleton";
import LuxRegisterListSkeletonRows from "views/common/fragments/LuxRegisterListSkeletonRows";
import classNames from "classnames/bind";
import WorkItemListRow from "./WorkItemListRow";
import WorkItemActivityDetailPopover from "./WorkItemActivityDetailPopover";
import LuxRegisterPagination from "views/common/fragments/LuxRegisterPagination";
import { REGISTER_PAGE_SIZE_OPTIONS } from "_helpers/registerPagination.utils";

const LIST_COLUMNS = [
  { key: "index", label: "#", icon: "fe-hash" },
  { key: "id", label: "Ref", icon: "fe-hash" },
  { key: "name", label: "Work item", icon: "fe-check-square" },
  { key: "category", label: "Category", icon: "fe-tag" },
  { key: "owner", label: "Owner", icon: "fe-user" },
  { key: "dates", label: "Schedule", icon: "fe-clock" },
  { key: "hours", label: "Hours", icon: "fe-watch" },
  { key: "status", label: "Status", icon: "fe-flag", center: true },
  { key: "actions", label: "", center: true },
];

class WorkItemListTable extends Component {
  constructor(props) {
    super(props);
    this.state = {
      detailOpen: false,
      detailItem: null,
    };
  }

  handleOpenDetail = (item) => {
    this.setState({ detailOpen: true, detailItem: item });
  };

  handleCloseDetail = () => {
    this.setState({ detailOpen: false, detailItem: null });
  };

  render() {
    const count =
      this.props.totalCount != null
        ? this.props.totalCount
        : this.props.items
        ? this.props.items.length
        : 0;
    const rangeStart = this.props.pagination ? this.props.pagination.rangeStart : 1;

    return (
      <>
        <div className="lux-bid-list-shell lux-workitem-register">
          <div className="lux-workitem-register__toolbar">
            <span className="lux-workitem-register__count">
              {this.props.isLoading ? (
                <LuxListCountSkeleton />
              ) : (
                <>
                  <strong>{count}</strong>
                  <em>{count === 1 ? "record" : "records"}</em>
                </>
              )}
            </span>
            <button
              type="button"
              className={classNames(
                "lux-bid-list-shell__refresh lux-workitem-register__refresh",
                { "is-loading": this.props.isLoading }
              )}
              title="Refresh list"
              aria-label="Refresh work items"
              onClick={() => this.props.onRefresh && this.props.onRefresh()}
            >
              <i className="fe fe-refresh-cw" aria-hidden="true" />
            </button>
          </div>

          <div className="lux-bid-list lux-workitem-register__list" aria-label="Work items">
            <div className="lux-bid-list__head" role="row">
              {LIST_COLUMNS.map((col) => (
                <div
                  key={col.key}
                  className={[
                    "lux-bid-list__head-cell",
                    `lux-bid-list__head-cell--${col.key}`,
                    col.center ? "is-center" : "",
                  ]
                    .filter(Boolean)
                    .join(" ")}
                  role="columnheader"
                >
                  {col.icon && col.label ? (
                    <span className="lux-bid-list__head-label">
                      <i className={`fe ${col.icon}`} aria-hidden="true" />
                      {col.label}
                    </span>
                  ) : (
                    <span className="lux-bid-list__head-label lux-bid-list__head-label--sr">
                      Actions
                    </span>
                  )}
                </div>
              ))}
            </div>

            <div
              className={classNames("lux-bid-list__body", {
                "is-loading": this.props.isLoading,
              })}
              role="list"
            >
              {this.props.isLoading && (
                <LuxRegisterListSkeletonRows
                  variant="bid"
                  pageSize={this.props.pagination && this.props.pagination.pageSize}
                />
              )}
              {!this.props.isLoading &&
                this.props.items &&
                this.props.items.map((item, index) => (
                  <WorkItemListRow
                    key={item.id}
                    item={item}
                    rowIndex={rangeStart + index}
                    permission={this.props.permission}
                    handleEditWorkItem={this.props.handleEditWorkItem}
                    handleDeleteWorkItem={this.props.handleDeleteWorkItem}
                    handleRemoveWorkItem={this.props.handleRemoveWorkItem}
                    onOpenDetail={this.handleOpenDetail}
                    onCheklistItemClick={this.props.onCheklistItemClick}
                  />
                ))}
            </div>
          </div>

          {this.props.pagination &&
            !this.props.isLoading &&
            this.props.pagination.total > 0 && (
              <LuxRegisterPagination
                pagination={this.props.pagination}
                onPageChange={this.props.onPageChange}
                onPageSizeChange={this.props.onPageSizeChange}
                pageSizeOptions={REGISTER_PAGE_SIZE_OPTIONS}
                summaryLabel="work items"
                className="lux-register-list__pagination"
              />
            )}
        </div>

        <WorkItemActivityDetailPopover
          show={this.state.detailOpen}
          item={this.state.detailItem}
          permission={this.props.permission}
          onClose={this.handleCloseDetail}
        />
      </>
    );
  }
}

export default WorkItemListTable;
