import React from "react";
import classNames from "classnames/bind";
import { RETENTION_STATUS_LABELS } from "config/data-retention.config";
import { formatRetentionPeriod, getRetentionDomainMeta } from "config/data-retention.utils";

function formatUpdatedAt(value) {
  if (!value) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

function formatRecords(value) {
  if (value == null) return "—";
  return value.toLocaleString();
}

export default function DataRetentionRegister({ policies, selectedId, onSelect }) {
  return (
    <div className="lux-retention-register-wrap">
      <table className="lux-retention-register">
        <thead>
          <tr>
            <th>Entity</th>
            <th>Domain</th>
            <th>Retention</th>
            <th>Records</th>
            <th>Status</th>
            <th>Updated</th>
          </tr>
        </thead>
        <tbody>
          {policies.map((policy) => {
            const meta = getRetentionDomainMeta(policy.domain);
            return (
              <tr
                key={policy.id}
                className={classNames("lux-retention-register__row", {
                  "is-selected": selectedId === policy.id,
                  "is-attention": policy.legalHold,
                })}
                onClick={() => onSelect && onSelect(policy)}
              >
                <td>
                  <div className="lux-retention-register__primary">
                    <span className={classNames("lux-retention-register__avatar", meta.tone && `is-${meta.tone}`)} aria-hidden="true">
                      <i className={meta.icon} />
                    </span>
                    <span className="lux-retention-register__primary-copy">
                      <strong className="lux-retention-register__primary-title">{policy.name}</strong>
                      <span className="lux-retention-register__primary-meta">{policy.entityType}</span>
                      {policy.description && <span className="lux-retention-register__primary-meta">{policy.description}</span>}
                    </span>
                  </div>
                </td>
                <td>
                  <span className="lux-retention-register__chip">{policy.domain}</span>
                </td>
                <td>
                  <span className="lux-retention-register__period">{formatRetentionPeriod(policy.retentionDays)}</span>
                </td>
                <td>
                  <span className="lux-retention-register__count">{formatRecords(policy.recordsHeld)}</span>
                </td>
                <td>
                  <span
                    className={classNames("lux-retention-register__status", {
                      "is-hold": policy.legalHold,
                      "is-archived": policy.status === "ARCHIVED",
                    })}
                  >
                    {policy.legalHold ? RETENTION_STATUS_LABELS.LEGAL_HOLD : RETENTION_STATUS_LABELS[policy.status] || policy.status}
                  </span>
                </td>
                <td>
                  <span className="lux-retention-register__date">{formatUpdatedAt(policy.updatedAt)}</span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
