import React, { useEffect } from "react";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { AdminInsightStrip } from "views/admin/components/AdminLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxKpiStrip from "views/common/fragments/LuxKpiStrip";

export default function IntegrationsLuxPage({
  pageMeta,
  dataSource,
  demoLabel = "Demo integration center data",
  heroActions,
  kpiCards,
  loading,
  onRefresh,
  refreshLoading,
  pageHeaderNameChangeHandler,
  shellTitle,
  testId,
  pageId,
  children,
}) {
  useReportPageDataSource(dataSource);
  const meta = pageMeta || {
    tone: "blue",
    icon: "fe fe-link",
    eyebrow: "Integrations",
    titleLead: "Connector",
    titleAccent: "hub",
    lede: "Enterprise adapter registry and sync observability.",
  };

  useEffect(() => {
    if (pageHeaderNameChangeHandler && shellTitle) {
      pageHeaderNameChangeHandler(shellTitle);
    }
  }, [pageHeaderNameChangeHandler, shellTitle]);

  return (
    <div
      className={classNames("lux-register-page", "lux-integrations-module", "lux-integ-lux", meta.tone && `is-${meta.tone}`)}
      data-testid={testId || (pageId ? `page-integrations-${pageId}` : undefined)}
    >
      <div className="lux-integ-lux__ambient" aria-hidden="true">
        <span className="lux-integ-lux__orb lux-integ-lux__orb--a" />
        <span className="lux-integ-lux__orb lux-integ-lux__orb--b" />
        <span className="lux-integ-lux__orb lux-integ-lux__orb--c" />
      </div>
      <LuxModuleIntro
        meta={meta}
        actions={heroActions || undefined}
        onRefresh={onRefresh}
        refreshLoading={refreshLoading != null ? refreshLoading : loading}
      />
      <div className="lux-register-page__body">
        {kpiCards && kpiCards.length ? (
          <LuxKpiStrip cards={kpiCards} loading={loading} className="lux-integ-lux__kpi-strip" />
        ) : null}

        <div className="lux-integ-lux__content">{children}</div>
      </div>
    </div>
  );
}

export function IntegrationActionButton({ to, onClick, icon, variant = "ghost", children, disabled, className }) {
  const classes = classNames("lux-onb-action", "lux-integ-action", `lux-onb-action--${variant}`, className);
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{children}</span>
    </>
  ) : (
    children
  );
  if (to && !onClick) {
    return (
      <Link to={to} className={classes}>
        {content}
      </Link>
    );
  }
  return (
    <button type="button" className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  );
}

export function IntegrationLuxPanel({ title, meta, icon, accent, actions, children, featured }) {
  return (
    <section
      className={classNames(
        "lux-hrms-dash__panel",
        "lux-integ-lux__panel",
        accent && `is-${accent}`,
        featured && "lux-integ-lux__panel--featured"
      )}
    >
      <header className="lux-hrms-dash__panel-head lux-integ-lux__panel-head">
        <div className="lux-integ-lux__panel-head-main">
          {icon ? <i className={icon} aria-hidden="true" /> : null}
          <div>
            <h2 className="lux-hrms-dash__panel-title">{title}</h2>
            {meta ? <p className="lux-hrms-dash__panel-sub">{meta}</p> : null}
          </div>
        </div>
        {actions ? <div className="lux-hrms-dash__panel-actions lux-integ-lux__panel-actions">{actions}</div> : null}
      </header>
      <div className="lux-hrms-dash__panel-body lux-integ-lux__panel-body">{children}</div>
    </section>
  );
}

export function IntegrationInsightPanel({ insights }) {
  if (!insights || !insights.length) {
    return null;
  }
  return <AdminInsightStrip insights={insights} className="lux-integ-lux__insights" />;
}

export function IntegrationTrustBadge({ score }) {
  const value = Number(score) || 0;
  const tone = value >= 90 ? "success" : value >= 80 ? "warning" : "danger";
  return (
    <span className={classNames("lux-integ-trust", `is-${tone}`)} style={{ "--integ-trust": value }}>
      <span className="lux-integ-trust__ring" aria-hidden="true" />
      <span className="lux-integ-trust__label">Trust {value}%</span>
    </span>
  );
}

export function IntegrationStatusBadge({ status }) {
  return <span className={classNames("lux-integ-status", `is-${status}`)}>{status}</span>;
}
