import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import LuxActionButton from "views/common/lux/LuxActionButton";
import { createModuleLuxPage, LuxModulePanel } from "views/common/lux/createModuleLuxPage";
import { AdminInsightStrip, AdminQuickNav } from "views/admin/components/AdminLuxShared";
import { isDeliverySprintsEnabled } from "config/delivery-sprints.config";
import { deliverySprintsService } from "_services/deliverySprints.service";
import { commonUtils } from "_helpers";
import {
  ASSIGNABLE_BUCKETS,
  DELIVERY_STATUS_SCOPES,
  DELIVERY_VIEW_MODES,
  buildBucketOptions,
  buildDeliveryInsights,
  buildDeliveryKpiCards,
  buildDeliveryMetrics,
  buildDeliveryPulseRows,
  buildDeliveryQuickLinks,
  buildProjectOptions,
  downloadDeliveryCsv,
  filterDeliveryTasks,
  flattenDeliveryTasks,
  formatDeliveryDateLabel,
  groupTasksBySprint,
  isDeliveryTaskOverdue,
  priorityTone,
  sprintProgressPct,
  statusTone,
} from "./components/deliverySprints.utils";

const DeliverySprintsLuxPage = createModuleLuxPage({
  rootClass: "lux-project-lux",
  defaultMeta: {
    tone: "blue",
    icon: "fe fe-zap",
    eyebrow: "Projects · Delivery",
    titleLead: "Delivery",
    titleAccent: "sprints",
    lede: "Orchestrate backlog, active, and week buckets derived from deliverables — assign focus without a separate sprint table.",
  },
});

const TASKS_PREVIEW = 8;

function DeliveryProgressRing({ pct }) {
  const value = Math.max(0, Math.min(100, pct || 0));
  return (
    <div
      className="lux-delivery-sprint__ring"
      style={{ "--delivery-pct": `${value}%` }}
      title={`${value}% done`}
      aria-label={`${value} percent complete`}
    >
      <strong>{value}%</strong>
    </div>
  );
}

function DeliveryTaskMeta({ task }) {
  const overdue = isDeliveryTaskOverdue(task);
  return (
    <div className="lux-delivery-sprint__task-meta">
      <span className={classNames("lux-delivery-sprint__pill", `is-${statusTone(task.status)}`)}>
        {task.status || "NEW"}
      </span>
      {task.priority ? (
        <span className={classNames("lux-delivery-sprint__pill is-priority", `is-${priorityTone(task.priority)}`)}>
          {task.priority}
        </span>
      ) : null}
      {overdue ? <span className="lux-delivery-sprint__pill is-rose">Overdue</span> : null}
      <span className="lux-delivery-sprint__muted">
        Due {formatDeliveryDateLabel(task.estCompletionTime)}
      </span>
    </div>
  );
}

/**
 * EH16 — Derived delivery sprints from TaskModel (no sprint truth table).
 * Canonical route: /project/delivery
 */
class DeliverySprintsPage extends Component {
  state = {
    loading: false,
    loadError: null,
    dataSource: null,
    overview: null,
    selectedSprintId: "",
    statusScope: "ALL",
    projectFilter: "",
    query: "",
    viewMode: "board",
    assigningTaskId: null,
    bulkAssigning: false,
    assignError: null,
    assignSuccess: null,
    expandedSprintIds: {},
    selectedTaskIds: {},
    bulkBucket: "active",
    userTeamId: commonUtils.getCurrentUserTeamId(),
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Delivery sprints");
    }
    this.loadSprints();
  }

  componentDidUpdate() {
    const currentTeamId = commonUtils.getCurrentUserTeamId();
    if (currentTeamId !== this.state.userTeamId) {
      this.setState(
        {
          userTeamId: currentTeamId,
          selectedSprintId: "",
          selectedTaskIds: {},
          projectFilter: "",
        },
        this.loadSprints
      );
    }
  }

  loadSprints = async () => {
    this.setState({ loading: true, loadError: null, assignError: null, assignSuccess: null });
    try {
      const result = await deliverySprintsService.listSprints();
      if (!result || result.source === "api-error") {
        this.setState({
          loading: false,
          dataSource: result && result.reason === "flag-off" ? "flag-off" : "api-error",
          overview: null,
          loadError:
            result && result.reason === "flag-off"
              ? "Delivery sprints API is turned off for this build."
              : "Unable to load derived delivery sprints from API.",
        });
        return;
      }
      this.setState({
        loading: false,
        dataSource: result.source,
        overview: result.payload,
        loadError: null,
        userTeamId: commonUtils.getCurrentUserTeamId(),
      });
    } catch (error) {
      this.setState({
        loading: false,
        dataSource: "api-error",
        overview: null,
        loadError: (error && error.message) || "Unable to load delivery sprints.",
      });
    }
  };

  filteredTasks = () => {
    const all = flattenDeliveryTasks(this.state.overview);
    return filterDeliveryTasks(all, {
      query: this.state.query,
      statusScope: this.state.statusScope,
      projectId: this.state.projectFilter,
      sprintId: this.state.selectedSprintId,
    });
  };

  handleAssignTask = async (taskId, sprintBucket) => {
    if (!taskId || !sprintBucket) return;
    this.setState({ assigningTaskId: taskId, assignError: null, assignSuccess: null });
    try {
      const result = await deliverySprintsService.assignSprint(taskId, sprintBucket);
      if (!result || result.source === "api-error") {
        this.setState({
          assigningTaskId: null,
          assignError: "Unable to assign deliverable sprint bucket.",
        });
        return;
      }
      this.setState({
        assigningTaskId: null,
        assignSuccess: `Deliverable ${taskId} moved to ${sprintBucket}.`,
        selectedTaskIds: {
          ...this.state.selectedTaskIds,
          [taskId]: false,
        },
      });
      await this.loadSprints();
    } catch (error) {
      this.setState({
        assigningTaskId: null,
        assignError: (error && error.message) || "Unable to assign deliverable sprint bucket.",
      });
    }
  };

  handleBulkAssign = async () => {
    const ids = Object.keys(this.state.selectedTaskIds).filter((id) => this.state.selectedTaskIds[id]);
    const bucket = this.state.bulkBucket;
    if (!ids.length || !bucket) return;
    this.setState({ bulkAssigning: true, assignError: null, assignSuccess: null });
    try {
      const results = await Promise.all(ids.map((id) => deliverySprintsService.assignSprint(id, bucket)));
      const failed = results.filter((result) => !result || result.source === "api-error").length;
      if (failed === ids.length) {
        this.setState({
          bulkAssigning: false,
          assignError: "Unable to assign selected deliverables.",
        });
        return;
      }
      this.setState({
        bulkAssigning: false,
        assignSuccess:
          failed > 0
            ? `Moved ${ids.length - failed} of ${ids.length} deliverables to ${bucket}.`
            : `Moved ${ids.length} deliverable${ids.length === 1 ? "" : "s"} to ${bucket}.`,
        selectedTaskIds: {},
      });
      await this.loadSprints();
    } catch (error) {
      this.setState({
        bulkAssigning: false,
        assignError: (error && error.message) || "Unable to assign selected deliverables.",
      });
    }
  };

  toggleTaskSelected = (taskId) => {
    this.setState((prev) => ({
      selectedTaskIds: {
        ...prev.selectedTaskIds,
        [taskId]: !prev.selectedTaskIds[taskId],
      },
    }));
  };

  toggleExpand = (sprintId) => {
    this.setState((prev) => ({
      expandedSprintIds: {
        ...prev.expandedSprintIds,
        [sprintId]: !prev.expandedSprintIds[sprintId],
      },
    }));
  };

  clearFilters = () => {
    this.setState({
      query: "",
      statusScope: "ALL",
      projectFilter: "",
      selectedSprintId: "",
    });
  };

  renderTaskRow = (task, buckets, { compact } = {}) => {
    const { assigningTaskId, selectedTaskIds, loading } = this.state;
    const selected = !!selectedTaskIds[task.id];
    return (
      <li
        key={task.id}
        className={classNames("lux-delivery-sprint__task", {
          "is-selected": selected,
          "is-compact": compact,
        })}
        data-testid={`eh16-delivery-task-${task.id}`}
      >
        <label className="lux-delivery-sprint__check">
          <input
            type="checkbox"
            checked={selected}
            onChange={() => this.toggleTaskSelected(task.id)}
            aria-label={`Select deliverable ${task.name || task.id}`}
          />
        </label>
        <div className="lux-delivery-sprint__task-main">
          <div className="lux-delivery-sprint__task-title-row">
            <Link className="lux-delivery-sprint__task-name" to={`/project/deliverable/${task.id}`}>
              {task.name || `Deliverable ${task.id}`}
            </Link>
            {task.projectId ? (
              <Link className="lux-delivery-sprint__project-link" to={`/project/details/${task.projectId}`}>
                {task.projectName || `Project ${task.projectId}`}
              </Link>
            ) : null}
          </div>
          <DeliveryTaskMeta task={task} />
        </div>
        <div className="lux-delivery-sprint__task-actions">
          <select
            className="lux-delivery-sprint__select"
            value={task.sprintId || ""}
            disabled={assigningTaskId === task.id || loading}
            aria-label={`Assign sprint for deliverable ${task.id}`}
            data-testid={`eh16-assign-sprint-${task.id}`}
            onChange={(event) => this.handleAssignTask(task.id, event.target.value)}
          >
            {buckets.map((bucket) => (
              <option key={bucket.id} value={bucket.id}>
                {bucket.label}
              </option>
            ))}
          </select>
        </div>
      </li>
    );
  };

  renderBoard = (grouped, buckets) => {
    const { expandedSprintIds, loading } = this.state;
    if (!grouped.length && !loading) {
      return (
        <LuxRegisterEmptyState
          variant="employees"
          title="No deliverables match filters"
          description="Clear filters or create dated tasks on projects in this team to derive sprint buckets."
        />
      );
    }

    return (
      <div className="lux-delivery-sprint__board" data-testid="eh16-delivery-board">
        {grouped.map((sprint) => {
          const expanded = !!expandedSprintIds[sprint.sprintId];
          const visible = expanded ? sprint.tasks : sprint.tasks.slice(0, TASKS_PREVIEW);
          const hiddenCount = Math.max(0, sprint.tasks.length - visible.length);
          const pct = sprintProgressPct(sprint);
          return (
            <section
              className="lux-delivery-sprint__card"
              key={sprint.sprintId}
              data-testid={`eh16-sprint-card-${sprint.sprintId}`}
            >
              <header className="lux-delivery-sprint__card-head">
                <div>
                  <button
                    type="button"
                    className="lux-delivery-sprint__card-title-btn"
                    onClick={() => this.setState({ selectedSprintId: sprint.sprintId })}
                  >
                    <h3>{sprint.sprintLabel}</h3>
                  </button>
                  <p className="lux-delivery-sprint__card-sub">
                    <code>{sprint.sprintId}</code>
                    <span>
                      {sprint.openCount} open · {sprint.doneCount} done
                    </span>
                  </p>
                </div>
                <DeliveryProgressRing pct={pct} />
              </header>
              <div className="lux-delivery-sprint__bar" aria-hidden="true">
                <span style={{ width: `${pct}%` }} />
              </div>
              <ul className="lux-delivery-sprint__task-list">
                {visible.map((task) => this.renderTaskRow(task, buckets))}
              </ul>
              {hiddenCount > 0 ? (
                <button
                  type="button"
                  className="lux-delivery-sprint__more"
                  onClick={() => this.toggleExpand(sprint.sprintId)}
                >
                  {expanded ? "Show fewer" : `Show ${hiddenCount} more`}
                </button>
              ) : null}
            </section>
          );
        })}
      </div>
    );
  };

  renderList = (tasks, buckets) => {
    if (!tasks.length) {
      return (
        <LuxRegisterEmptyState
          variant="employees"
          title="No deliverables in register"
          description="Adjust search or status chips to see TaskModel-derived delivery items."
        />
      );
    }
    return (
      <div className="lux-delivery-sprint__register" data-testid="eh16-delivery-register">
        <ul className="lux-delivery-sprint__task-list is-register">
          {tasks.map((task) => this.renderTaskRow(task, buckets, { compact: true }))}
        </ul>
      </div>
    );
  };

  renderPulse = (grouped) => {
    const rows = buildDeliveryPulseRows(grouped);
    if (!rows.length) {
      return (
        <LuxRegisterEmptyState
          variant="employees"
          title="No pulse data"
          description="Load or create deliverables to visualize open vs done mix by bucket."
        />
      );
    }
    return (
      <div className="lux-delivery-sprint__pulse" data-testid="eh16-delivery-pulse">
        {rows.map((row) => (
          <article key={row.sprintId} className="lux-delivery-sprint__pulse-row">
            <div className="lux-delivery-sprint__pulse-copy">
              <strong>{row.sprintLabel}</strong>
              <span>
                {row.done} done · {row.open} open · {row.total} total
              </span>
            </div>
            <div className="lux-delivery-sprint__pulse-track" role="img" aria-label={`${row.donePct}% done`}>
              <span className="is-done" style={{ width: `${row.donePct}%` }} />
              <span className="is-open" style={{ width: `${row.openPct}%` }} />
            </div>
            <strong className="lux-delivery-sprint__pulse-pct">{row.donePct}%</strong>
          </article>
        ))}
      </div>
    );
  };

  render() {
    if (!isDeliverySprintsEnabled()) {
      return (
        <DeliverySprintsLuxPage testId="eh16-delivery-flag-off">
          <LuxRegisterEmptyState
            variant="employees"
            title="Delivery sprints unavailable"
            description="Enable REACT_APP_USE_DELIVERY_SPRINTS_API to load TaskModel-derived sprint buckets."
          />
          <AdminQuickNav
            eyebrow="Continue in delivery"
            title="Related workspaces"
            links={buildDeliveryQuickLinks()}
          />
        </DeliverySprintsLuxPage>
      );
    }

    const {
      loading,
      loadError,
      overview,
      dataSource,
      selectedSprintId,
      statusScope,
      projectFilter,
      query,
      viewMode,
      assigningTaskId,
      bulkAssigning,
      assignError,
      assignSuccess,
      selectedTaskIds,
      bulkBucket,
      userTeamId,
    } = this.state;

    const metrics = buildDeliveryMetrics(overview);
    const insights = buildDeliveryInsights(metrics, overview);
    const kpiCards = buildDeliveryKpiCards(metrics);
    const filteredTasks = this.filteredTasks();
    const grouped = groupTasksBySprint(filteredTasks, (overview && overview.sprints) || []);
    const buckets = buildBucketOptions((overview && overview.sprints) || []);
    const projectOptions = buildProjectOptions(flattenDeliveryTasks(overview));
    const selectedCount = Object.keys(selectedTaskIds).filter((id) => selectedTaskIds[id]).length;
    const busy = loading || !!assigningTaskId || bulkAssigning;

    return (
      <DeliverySprintsLuxPage
        testId="eh16-delivery-page"
        dataSource={dataSource}
        loading={loading}
        kpiCards={kpiCards}
        onRefresh={this.loadSprints}
        refreshLoading={loading}
        heroActions={
          <>
            <LuxActionButton
              type="button"
              variant="secondary"
              icon="fe fe-download"
              onClick={() =>
                downloadDeliveryCsv(
                  filteredTasks,
                  `delivery-sprints-team-${userTeamId || "all"}.csv`
                )
              }
              disabled={!filteredTasks.length}
              data-testid="eh16-delivery-export"
            >
              Export CSV
            </LuxActionButton>
          </>
        }
      >
        <AdminInsightStrip insights={insights} className="lux-delivery-sprint__insights" />

        <LuxModulePanel
          title="Sprint command center"
          meta={
            userTeamId
              ? `Team ${userTeamId} · ${metrics.taskCount} deliverable${metrics.taskCount === 1 ? "" : "s"} · TaskModel buckets (no sprint table)`
              : "Assign below or use the task board for day-to-day moves"
          }
          icon="fe fe-layers"
          className="lux-delivery-sprint__panel"
          actions={
            <div className="lux-delivery-sprint__view-toggle" role="tablist" aria-label="Delivery views">
              {DELIVERY_VIEW_MODES.map((mode) => (
                <button
                  key={mode.id}
                  type="button"
                  role="tab"
                  aria-selected={viewMode === mode.id}
                  className={classNames("lux-delivery-sprint__view-btn", {
                    "is-active": viewMode === mode.id,
                  })}
                  onClick={() => this.setState({ viewMode: mode.id })}
                  data-testid={`eh16-view-${mode.id}`}
                >
                  <i className={`fe ${mode.icon}`} aria-hidden="true" />
                  {mode.label}
                </button>
              ))}
            </div>
          }
        >
          <div className="lux-delivery-sprint__toolbar">
            <label className="lux-delivery-sprint__search">
              <i className="fe fe-search" aria-hidden="true" />
              <input
                type="search"
                value={query}
                onChange={(event) => this.setState({ query: event.target.value })}
                placeholder="Search deliverables, projects, buckets…"
                data-testid="eh16-delivery-search"
              />
            </label>

            <div className="lux-delivery-sprint__chips" role="group" aria-label="Status scope">
              {DELIVERY_STATUS_SCOPES.map((scope) => (
                <button
                  key={scope.id}
                  type="button"
                  className={classNames("lux-delivery-sprint__chip", {
                    "is-active": statusScope === scope.id,
                  })}
                  onClick={() => this.setState({ statusScope: scope.id })}
                  data-testid={`eh16-scope-${scope.id}`}
                >
                  {scope.label}
                  {scope.id === "OVERDUE" && metrics.overdueCount ? (
                    <em>{metrics.overdueCount}</em>
                  ) : null}
                </button>
              ))}
            </div>

            <select
              className="lux-delivery-sprint__select"
              value={selectedSprintId}
              onChange={(event) => this.setState({ selectedSprintId: event.target.value })}
              data-testid="eh16-sprint-filter"
              aria-label="Filter by sprint bucket"
            >
              <option value="">All buckets</option>
              {((overview && overview.sprints) || []).map((sprint) => (
                <option key={sprint.sprintId} value={sprint.sprintId}>
                  {sprint.sprintLabel} ({sprint.taskCount})
                </option>
              ))}
            </select>

            <select
              className="lux-delivery-sprint__select"
              value={projectFilter}
              onChange={(event) => this.setState({ projectFilter: event.target.value })}
              data-testid="eh16-project-filter"
              aria-label="Filter by project"
            >
              <option value="">All projects</option>
              {projectOptions.map((project) => (
                <option key={project.id} value={project.id}>
                  {project.label}
                </option>
              ))}
            </select>

            <button
              type="button"
              className="lux-delivery-sprint__clear"
              onClick={this.clearFilters}
              data-testid="eh16-clear-filters"
            >
              Clear
            </button>
          </div>

          {selectedCount > 0 ? (
            <div className="lux-delivery-sprint__bulk" data-testid="eh16-bulk-bar">
              <span>
                <strong>{selectedCount}</strong> selected
              </span>
              <select
                className="lux-delivery-sprint__select"
                value={bulkBucket}
                onChange={(event) => this.setState({ bulkBucket: event.target.value })}
                aria-label="Bulk assign bucket"
              >
                {(buckets.length ? buckets : ASSIGNABLE_BUCKETS).map((bucket) => (
                  <option key={bucket.id} value={bucket.id}>
                    {bucket.label}
                  </option>
                ))}
              </select>
              <LuxActionButton
                type="button"
                variant="primary"
                icon="fe fe-move"
                onClick={this.handleBulkAssign}
                disabled={busy}
                data-testid="eh16-bulk-assign"
              >
                {bulkAssigning ? "Assigning…" : "Move selected"}
              </LuxActionButton>
              <button
                type="button"
                className="lux-delivery-sprint__clear"
                onClick={() => this.setState({ selectedTaskIds: {} })}
              >
                Clear selection
              </button>
            </div>
          ) : null}

          <LuxInlineAlert
            message={loadError}
            tone="warning"
            onDismiss={() => this.setState({ loadError: null })}
          />
          <LuxInlineAlert
            message={assignError}
            tone="warning"
            onDismiss={() => this.setState({ assignError: null })}
          />
          <LuxInlineAlert
            message={assignSuccess}
            tone="success"
            onDismiss={() => this.setState({ assignSuccess: null })}
          />

          {loading && !overview ? (
            <div className="lux-delivery-sprint__skeleton" aria-busy="true">
              <div className="lux-delivery-sprint__skeleton-card" />
              <div className="lux-delivery-sprint__skeleton-card" />
              <div className="lux-delivery-sprint__skeleton-card" />
            </div>
          ) : viewMode === "list" ? (
            this.renderList(filteredTasks, buckets)
          ) : viewMode === "pulse" ? (
            this.renderPulse(grouped)
          ) : (
            this.renderBoard(grouped, buckets)
          )}
        </LuxModulePanel>
      </DeliverySprintsLuxPage>
    );
  }
}

export default DeliverySprintsPage;
