import React, { useEffect, useState } from "react";
import BrandNameLogo from "views/common/fragments/BrandNameLogo";

const CHECKLIST = [
  {
    icon: "fe fe-server",
    title: "Application server",
    hint: "The API may be restarting or temporarily offline.",
  },
  {
    icon: "fe fe-wifi",
    title: "Your network",
    hint: "Check VPN, Wi‑Fi, or corporate proxy settings.",
  },
  {
    icon: "fe fe-shield",
    title: "Session preserved",
    hint: "Your sign-in is still active — nothing was lost locally.",
  },
];

function readLuxShellDark() {
  if (typeof document === "undefined") {
    return false;
  }
  return document.body.classList.contains("lux-shell-dark");
}

function useLuxShellDark() {
  const [isDark, setIsDark] = useState(readLuxShellDark);

  useEffect(() => {
    const sync = () => setIsDark(readLuxShellDark());
    sync();

    const observer = new MutationObserver(sync);
    observer.observe(document.body, { attributes: true, attributeFilter: ["class"] });

    return () => observer.disconnect();
  }, []);

  return isDark;
}

function ConnectionErrorPage({ onRetry }) {
  const isDarkShell = useLuxShellDark();

  return (
    <div className="lux-connection-error-screen">
      <div className="lux-connection-error__backdrop" aria-hidden="true">
        <span className="lux-connection-error__scrim" />
        <span className="lux-connection-error__grid" />
        <span className="lux-connection-error__orb lux-connection-error__orb--1" />
        <span className="lux-connection-error__orb lux-connection-error__orb--2" />
        <span className="lux-connection-error__orb lux-connection-error__orb--3" />
      </div>

      <section className="lux-connection-error" aria-labelledby="lux-connection-error-title">
        <div className="lux-connection-error__card">
          <div className="lux-connection-error__card-brand">
            <BrandNameLogo
              variant="card"
              wrapperClassName="auth-login__brand"
              logoSurface={isDarkShell ? "dark" : "light"}
            />
          </div>

          <div className="lux-connection-error__icon-wrap" aria-hidden="true">
            <span className="lux-connection-error__pulse lux-connection-error__pulse--outer" />
            <span className="lux-connection-error__pulse lux-connection-error__pulse--inner" />
            <span className="lux-connection-error__icon">
              <i className="fe fe-wifi-off" />
            </span>
          </div>

          <p className="lux-connection-error__eyebrow">Connection interrupted</p>
          <h1 id="lux-connection-error-title" className="lux-connection-error__title">
            We can&apos;t reach the server right now
          </h1>
          <p className="lux-connection-error__lead">
            Tracopus couldn&apos;t connect to the backend. This is usually brief — a restart,
            deployment, or network blip — and your work on this device is safe.
          </p>

          <ul className="lux-connection-error__checks">
            {CHECKLIST.map((item) => (
              <li key={item.title} className="lux-connection-error__check">
                <span className="lux-connection-error__check-icon" aria-hidden="true">
                  <i className={item.icon} />
                </span>
                <span className="lux-connection-error__check-copy">
                  <strong>{item.title}</strong>
                  <span>{item.hint}</span>
                </span>
              </li>
            ))}
          </ul>

          <div className="lux-connection-error__actions">
            <button
              type="button"
              className="lux-connection-error__btn lux-connection-error__btn--primary"
              onClick={onRetry}
            >
              <i className="fe fe-refresh-cw" aria-hidden="true" />
              Try again
            </button>
          </div>

          <p className="lux-connection-error__footnote">
            If the problem continues for more than a few minutes, contact your IT support team.
          </p>
        </div>
      </section>
    </div>
  );
}

export default ConnectionErrorPage;
