import React, { Component } from "react";
import classNames from "classnames/bind";
import { ISSUE_PRIORITIES, ISSUE_STATUSES } from "config/project-governance.config";
import { GOVERNANCE_PAGE_IDS } from "config/project-governance-nav.config";
import { getIssuePriorityTone, getIssueStatusTone } from "config/project-governance.utils";
import GovernanceLuxDrawerShell from "views/project/components/GovernanceLuxDrawerShell";
import {
  GovernanceDrawerCard,
  GovernanceDrawerField,
  GovernanceDrawerMeta,
  GovernanceDrawerModuleLink,
  GovernanceDrawerStatStrip,
  buildGovernanceQuickLinks,
} from "views/project/components/GovernanceLuxDrawerShared";

export default class IssueDrawer extends Component {
  state = {
    priority: ISSUE_PRIORITIES.P2,
    status: ISSUE_STATUSES.OPEN,
    ownerName: "",
    dueDate: "",
    description: "",
    actions: [],
    newActionTitle: "",
    newActionOwner: "",
    newActionDue: "",
    saving: false,
    closing: false,
    addingAction: false,
    error: null,
  };

  componentDidUpdate(prevProps) {
    const { issue, open } = this.props;
    if (open && issue && issue !== prevProps.issue) {
      this.setState({
        priority: issue.priority || ISSUE_PRIORITIES.P2,
        status: issue.status || ISSUE_STATUSES.OPEN,
        ownerName: issue.ownerName || "",
        dueDate: issue.dueDate || "",
        description: issue.description || "",
        actions: issue.actions || [],
        newActionTitle: "",
        newActionOwner: issue.ownerName || "",
        newActionDue: "",
        saving: false,
        closing: false,
        addingAction: false,
        error: null,
      });
    }
  }

  refreshActions = async () => {
    const { issue, onLoadActions } = this.props;
    if (!issue || !onLoadActions) {
      return;
    }
    const actions = await onLoadActions(issue.id);
    this.setState({ actions });
  };

  handleSave = async () => {
    const { issue, onSave, onClose } = this.props;
    const { priority, status, ownerName, dueDate, description } = this.state;
    if (!issue || !onSave) {
      return;
    }
    this.setState({ saving: true, error: null });
    try {
      await onSave(issue.id, {
        priority,
        status,
        ownerName,
        dueDate: dueDate || null,
        description,
      });
      onClose();
    } catch (e) {
      this.setState({
        saving: false,
        error: (e && e.message) || "Unable to update issue.",
      });
    }
  };

  handleCloseIssue = async () => {
    const { issue, onCloseIssue, onClose } = this.props;
    if (!issue || !onCloseIssue) {
      return;
    }
    this.setState({ closing: true, error: null });
    try {
      await onCloseIssue(issue.id);
      onClose();
    } catch (e) {
      this.setState({
        closing: false,
        error: (e && e.message) || "Unable to close issue.",
      });
    }
  };

  handleAddAction = async () => {
    const { issue, onCreateAction } = this.props;
    const { newActionTitle, newActionOwner, newActionDue } = this.state;
    if (!issue || !onCreateAction || !newActionTitle.trim()) {
      return;
    }
    this.setState({ addingAction: true, error: null });
    try {
      await onCreateAction({
        issueId: issue.id,
        title: newActionTitle.trim(),
        ownerName: newActionOwner,
        dueDate: newActionDue || null,
        slaDays: 5,
      });
      await this.refreshActions();
      this.setState({
        addingAction: false,
        newActionTitle: "",
        newActionDue: "",
      });
    } catch (e) {
      this.setState({
        addingAction: false,
        error: (e && e.message) || "Unable to add action.",
      });
    }
  };

  handleCompleteAction = async (actionId) => {
    const { onCompleteAction } = this.props;
    if (!onCompleteAction) {
      return;
    }
    await onCompleteAction(actionId);
    await this.refreshActions();
  };

  render() {
    const { open, issue, onClose } = this.props;
    const {
      priority,
      status,
      ownerName,
      dueDate,
      description,
      actions,
      newActionTitle,
      newActionOwner,
      newActionDue,
      saving,
      closing,
      addingAction,
      error,
    } = this.state;

    if (!open || !issue) {
      return null;
    }

    const priorityTone = getIssuePriorityTone(issue.priority);
    const statusTone = getIssueStatusTone(issue.status);
    const canClose = issue.status !== ISSUE_STATUSES.CLOSED && issue.status !== ISSUE_STATUSES.RESOLVED;
    const openActionCount = actions.filter((action) => action.status !== "Complete").length;

    return (
      <GovernanceLuxDrawerShell
        open={open}
        onClose={onClose}
        wide
        accent="danger"
        icon="fe-alert-circle"
        eyebrow="Delivery issue"
        title={issue.title}
        subtitle={issue.projectName}
        quickLinks={buildGovernanceQuickLinks(GOVERNANCE_PAGE_IDS.ISSUES, [
          { to: "/project/risks", label: "Risk register", hint: "Exposure", icon: "fe fe-alert-triangle" },
        ])}
        ariaLabel={`Issue ${issue.title}`}
        footer={
          <div className="lux-gov-drawer__foot-bar">
            <GovernanceDrawerModuleLink to="/project/issues" label="Open issue register" onNavigate={onClose} />
            {canClose ? (
              <button
                type="button"
                className="lux-onb-action lux-onb-action--ghost is-danger"
                onClick={this.handleCloseIssue}
                disabled={closing || saving}
              >
                {closing ? "Closing…" : "Close issue"}
              </button>
            ) : null}
            <div className="lux-onb-drawer__foot-actions">
              <button type="button" className="lux-onb-action lux-onb-action--ghost" onClick={onClose}>
                Cancel
              </button>
              <button
                type="button"
                className="lux-onb-action lux-onb-action--primary"
                onClick={this.handleSave}
                disabled={saving || closing}
              >
                {saving ? "Saving…" : "Save issue"}
              </button>
            </div>
          </div>
        }
      >
        <GovernanceDrawerStatStrip
          stats={[
            { label: "Priority", value: issue.priority, tone: priorityTone },
            { label: "Status", value: issue.status, tone: statusTone },
            { label: "Open actions", value: openActionCount, tone: openActionCount > 0 ? "warning" : "success" },
          ]}
        />

        <GovernanceDrawerCard title="Issue snapshot" subtitle="Priority, lifecycle, and ownership">
          <GovernanceDrawerMeta
            items={[
              {
                label: "Priority",
                value: <span className={classNames("lux-doc-badge", `is-${priorityTone}`)}>{issue.priority}</span>,
              },
              {
                label: "Status",
                value: <span className={classNames("lux-doc-badge", `is-${statusTone}`)}>{issue.status}</span>,
              },
              { label: "Owner", value: issue.ownerName || "Unassigned" },
              { label: "Opened", value: issue.openedAt || "—" },
            ]}
          />
        </GovernanceDrawerCard>

        <GovernanceDrawerCard title="Update issue" subtitle="Description, owner, and target dates">
          <GovernanceDrawerField label="Description">
            <textarea rows={2} value={description} onChange={(e) => this.setState({ description: e.target.value })} />
          </GovernanceDrawerField>
          <GovernanceDrawerField label="Owner">
            <input value={ownerName} onChange={(e) => this.setState({ ownerName: e.target.value })} />
          </GovernanceDrawerField>
          <GovernanceDrawerField label="Priority">
            <select value={priority} onChange={(e) => this.setState({ priority: e.target.value })}>
              {Object.values(ISSUE_PRIORITIES).map((value) => (
                <option key={value} value={value}>
                  {value}
                </option>
              ))}
            </select>
          </GovernanceDrawerField>
          <GovernanceDrawerField label="Status">
            <select value={status} onChange={(e) => this.setState({ status: e.target.value })}>
              {Object.values(ISSUE_STATUSES).map((value) => (
                <option key={value} value={value}>
                  {value}
                </option>
              ))}
            </select>
          </GovernanceDrawerField>
          <GovernanceDrawerField label="Due date">
            <input type="date" value={dueDate || ""} onChange={(e) => this.setState({ dueDate: e.target.value })} />
          </GovernanceDrawerField>
        </GovernanceDrawerCard>

        <GovernanceDrawerCard
          title={`Corrective actions (${actions.length})`}
          subtitle="Track owners, due dates, and completion"
        >
          <ul className="lux-gov-issue-actions">
            {actions.length ? (
              actions.map((action) => (
                <li
                  key={action.id}
                  className={classNames("lux-gov-issue-actions__item", {
                    "is-complete": action.status === "Complete",
                  })}
                >
                  <div>
                    <strong>{action.title}</strong>
                    <span>
                      {action.ownerName || "Unassigned"} · due {action.dueDate || "—"}
                    </span>
                  </div>
                  {action.status !== "Complete" ? (
                    <button
                      type="button"
                      className="lux-onb-action lux-onb-action--ghost"
                      onClick={() => this.handleCompleteAction(action.id)}
                    >
                      Complete
                    </button>
                  ) : (
                    <span className="lux-gov-register__chip is-complete">Done</span>
                  )}
                </li>
              ))
            ) : (
              <li className="lux-gov-issue-actions__empty">No corrective actions yet — add one below.</li>
            )}
          </ul>
          <div className="lux-gov-issue-actions__form">
            <input
              placeholder="New action"
              value={newActionTitle}
              onChange={(e) => this.setState({ newActionTitle: e.target.value })}
            />
            <input
              placeholder="Owner"
              value={newActionOwner}
              onChange={(e) => this.setState({ newActionOwner: e.target.value })}
            />
            <input
              type="date"
              value={newActionDue}
              onChange={(e) => this.setState({ newActionDue: e.target.value })}
            />
            <button
              type="button"
              className="lux-onb-action lux-onb-action--primary"
              onClick={this.handleAddAction}
              disabled={addingAction}
            >
              {addingAction ? "Adding…" : "Add action"}
            </button>
          </div>
        </GovernanceDrawerCard>

        {error ? <p className="lux-gov-drawer__error">{error}</p> : null}
      </GovernanceLuxDrawerShell>
    );
  }
}
