import { shouldUsePortfolioControlTower } from "config/tracopus-pilot.config";
import envconfig from "env.config";

export const PORTFOLIO_STATUSES = {
  ACTIVE: "ACTIVE",
  PLANNING: "PLANNING",
  ON_HOLD: "ON_HOLD",
  CLOSED: "CLOSED",
};

export const PROGRAM_STATUSES = {
  ON_TRACK: "ON_TRACK",
  AT_RISK: "AT_RISK",
  OFF_TRACK: "OFF_TRACK",
  COMPLETE: "COMPLETE",
};

export const INITIATIVE_STATUSES = {
  PLANNED: "PLANNED",
  IN_FLIGHT: "IN_FLIGHT",
  BLOCKED: "BLOCKED",
  DONE: "DONE",
};

export const PROJECT_HEALTH_BANDS = {
  HEALTHY: "HEALTHY",
  WATCH: "WATCH",
  CRITICAL: "CRITICAL",
};

export const SCENARIO_STATUSES = {
  DRAFT: "DRAFT",
  SAVED: "SAVED",
  ARCHIVED: "ARCHIVED",
};

export const ROADMAP_PHASES = ["Initiate", "Plan", "Deliver", "Close", "Scale"];

export function isPortfolioControlTowerEnabled() {
  return shouldUsePortfolioControlTower();
}

export function shouldUsePortfolioControlTowerApi() {
  return envconfig.USE_PORTFOLIO_CONTROL_TOWER_API === true;
}

export function normalizePortfolio(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    code: row.code || "",
    name: row.name || "Portfolio",
    description: row.description || "",
    ownerId: row.ownerId || null,
    ownerName: row.ownerName || row.owner || "",
    status: row.status || PORTFOLIO_STATUSES.ACTIVE,
    programIds: Array.isArray(row.programIds) ? row.programIds : [],
    healthScore: row.healthScore != null ? row.healthScore : null,
    updatedAt: row.updatedAt || null,
  };
}

export function normalizeProgram(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    portfolioId: row.portfolioId || null,
    code: row.code || "",
    name: row.name || "Program",
    description: row.description || "",
    sponsorName: row.sponsorName || row.sponsor || "",
    status: row.status || PROGRAM_STATUSES.ON_TRACK,
    roadmapPhase: row.roadmapPhase || "Deliver",
    projectIds: Array.isArray(row.projectIds) ? row.projectIds : [],
    healthScore: row.healthScore != null ? row.healthScore : null,
    updatedAt: row.updatedAt || null,
  };
}

export function normalizeInitiative(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    programId: row.programId || null,
    projectId: row.projectId || null,
    name: row.name || "Initiative",
    description: row.description || "",
    ownerName: row.ownerName || "",
    status: row.status || INITIATIVE_STATUSES.PLANNED,
    targetDate: row.targetDate || null,
    updatedAt: row.updatedAt || null,
  };
}

export function normalizeProjectHealthSnapshot(row) {
  if (!row) {
    return null;
  }
  return {
    projectId: row.projectId,
    projectCode: row.projectCode || "",
    projectName: row.projectName || "Project",
    programId: row.programId || null,
    programName: row.programName || "",
    portfolioId: row.portfolioId || null,
    healthScore: row.healthScore != null ? row.healthScore : 0,
    healthBand: row.healthBand || PROJECT_HEALTH_BANDS.WATCH,
    milestoneSlippageDays: row.milestoneSlippageDays != null ? row.milestoneSlippageDays : 0,
    openRisks: row.openRisks != null ? row.openRisks : 0,
    criticalRisks: row.criticalRisks != null ? row.criticalRisks : 0,
    openIssues: row.openIssues != null ? row.openIssues : 0,
    gateComplianceRate: row.gateComplianceRate != null ? row.gateComplianceRate : 100,
    resourceUtilization: row.resourceUtilization != null ? row.resourceUtilization : null,
    marginPct: row.marginPct != null ? row.marginPct : null,
    forecastVariancePct: row.forecastVariancePct != null ? row.forecastVariancePct : null,
    updatedAt: row.updatedAt || null,
  };
}

export function normalizePortfolioScenario(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    portfolioId: row.portfolioId || null,
    name: row.name || "Scenario",
    description: row.description || "",
    status: row.status || SCENARIO_STATUSES.DRAFT,
    baselineHealth: row.baselineHealth != null ? row.baselineHealth : null,
    scenarioHealth: row.scenarioHealth != null ? row.scenarioHealth : null,
    slippageDeltaDays: row.slippageDeltaDays != null ? row.slippageDeltaDays : 0,
    riskDelta: row.riskDelta != null ? row.riskDelta : 0,
    marginDeltaPct: row.marginDeltaPct != null ? row.marginDeltaPct : 0,
    assumptions: Array.isArray(row.assumptions) ? row.assumptions : [],
    updatedAt: row.updatedAt || null,
  };
}

export function normalizeExecutiveMetric(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    label: row.label || "",
    value: row.value != null ? row.value : "—",
    unit: row.unit || "",
    tone: row.tone || "slate",
    hint: row.hint || "",
    trend: row.trend || null,
  };
}
