import React from "react";
import classNames from "classnames/bind";
import { PerformanceActionButton, PerformanceStatusBadge } from "views/performance/components/PerformanceLuxShared";

export default function ReviewRegister({ reviews, loading, onOpenSelfReview, onOpenManagerReview, onViewReview }) {
  if (loading) {
    return <div className="lux-perf-skeleton lux-perf-skeleton--panel" />;
  }
  if (!reviews || !reviews.length) {
    return (
      <div className="lux-perf-empty">
        <i className="fe fe-clipboard" aria-hidden="true" />
        <p>No reviews in this cycle.</p>
      </div>
    );
  }
  return (
    <div className="lux-perf-register">
      {reviews.map((review, index) => (
        <article key={review.id} className="lux-perf-register__row">
          <span className="lux-perf-register__index">{index + 1}</span>
          <span className={classNames("lux-perf-register__rail", review.tone && `is-${review.tone}`)}>
            <i className="fe fe-clipboard" aria-hidden="true" />
          </span>
          <div className="lux-perf-register__main">
            <span className="lux-perf-register__eyebrow">{review.cycleName}</span>
            <h3>{review.employeeName}</h3>
            <p>Manager: {review.managerName}</p>
            <div className="lux-perf-register__meta">
              <PerformanceStatusBadge status={review.status} />
              {review.selfRating != null ? <span>Self: {review.selfRating}</span> : null}
              {review.managerRating != null ? <span>Manager: {review.managerRating}</span> : null}
              {review.dueDate ? <span>Due {review.dueDate}</span> : null}
            </div>
          </div>
          <div className="lux-perf-register__actions">
            {(review.status === "self_review" || review.status === "not_started") && onOpenSelfReview ? (
              <PerformanceActionButton icon="fe fe-edit-3" variant="primary" onClick={() => onOpenSelfReview(review)}>
                {review.status === "not_started" ? "Start self review" : "Continue self review"}
              </PerformanceActionButton>
            ) : null}
            {review.status === "manager_review" && onOpenManagerReview ? (
              <PerformanceActionButton icon="fe fe-star" variant="primary" onClick={() => onOpenManagerReview(review)}>
                Rate as manager
              </PerformanceActionButton>
            ) : null}
            {review.status === "completed" && onViewReview ? (
              <PerformanceActionButton icon="fe fe-eye" onClick={() => onViewReview(review)}>
                View record
              </PerformanceActionButton>
            ) : null}
          </div>
        </article>
      ))}
    </div>
  );
}
