import React, { Component } from "react";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import ClientLuxPage, {
  ClientActionButton,
  ClientLuxPanel,
} from "views/client/components/ClientLuxShared";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import { isClientPortalEnabled } from "config/client-portal.config";
import { clientPortalService } from "_services/clientPortal.service";
import { commonUtils } from "_helpers";

/**
 * EH15 — Client portal page gated by REACT_APP_USE_CLIENT_PORTAL_API.
 * Overview aggregate + project client sign-off (governance gate).
 */
class ClientPortalPage extends Component {
  state = {
    loading: false,
    loadError: null,
    dataSource: null,
    clientId: "",
    overview: null,
    signingProjectId: null,
    signOffMessage: null,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Client portal");
    }
  }

  handleClientIdChange = (event) => {
    this.setState({ clientId: event.target.value });
  };

  loadOverview = async () => {
    const { clientId } = this.state;
    if (!clientId || !String(clientId).trim()) {
      this.setState({ loadError: "Enter a client id to load the portal overview.", overview: null });
      return;
    }
    this.setState({ loading: true, loadError: null, signOffMessage: null });
    try {
      const result = await clientPortalService.getOverview({ clientId: String(clientId).trim() });
      if (!result || result.source === "api-error") {
        this.setState({
          loading: false,
          dataSource: "api-error",
          overview: null,
          loadError: "Unable to load client portal overview from API.",
        });
        return;
      }
      this.setState({
        loading: false,
        dataSource: result.source,
        overview: result.payload,
        loadError: null,
      });
    } catch (error) {
      this.setState({
        loading: false,
        dataSource: "api-error",
        overview: null,
        loadError: (error && error.message) || "Unable to load client portal overview.",
      });
    }
  };

  handleSignOff = async (projectId) => {
    const { clientId } = this.state;
    if (!clientId || !String(clientId).trim()) {
      this.setState({ signOffMessage: "Enter a client id before signing off." });
      return;
    }
    this.setState({ signingProjectId: projectId, signOffMessage: null });
    try {
      const result = await clientPortalService.signOffProject({
        projectId,
        clientId: String(clientId).trim(),
        actorId: commonUtils.getCurrentUserId(),
      });
      if (!result || result.source === "api-error") {
        this.setState({
          signingProjectId: null,
          signOffMessage: "Sign-off failed. Try again or check API availability.",
        });
        return;
      }
      this.setState({
        signingProjectId: null,
        signOffMessage: `Signed off project ${projectId} (gate ${result.payload && result.payload.gateId}).`,
      });
    } catch (error) {
      this.setState({
        signingProjectId: null,
        signOffMessage: (error && error.message) || "Sign-off failed.",
      });
    }
  };

  render() {
    if (!isClientPortalEnabled()) {
      return (
        <ClientLuxPage
          testId="client-portal-flag-off"
          className="lux-client-portal-page"
          pageMeta={ADMIN_PAGE_META.clientPortal}
        >
          <LuxRegisterEmptyState
            variant="employees"
            title="Client portal unavailable"
            description="Enable REACT_APP_USE_CLIENT_PORTAL_API to use the client portal aggregate and sign-off."
          />
        </ClientLuxPage>
      );
    }

    const { loading, loadError, overview, clientId, dataSource, signingProjectId, signOffMessage } = this.state;
    const projects = (overview && overview.projects) || [];
    const tickets = (overview && overview.tickets) || [];
    const invoices = (overview && overview.invoices) || [];

    return (
      <ClientLuxPage
        testId="client-portal-page"
        className="lux-client-portal-page"
        dataSource={dataSource}
        pageMeta={ADMIN_PAGE_META.clientPortal}
        heroActions={
          <ClientActionButton variant="primary" icon="fe fe-search" onClick={this.loadOverview} disabled={loading}>
            {loading ? "Loading…" : "Load overview"}
          </ClientActionButton>
        }
      >
        <LuxInlineAlert
          tone="info"
          title="Legacy preview"
          testId="client-portal-legacy-preview"
        >
          Legacy clientId preview. Production client flow uses /client/login (IdP session) and
          bridge-scoped routes under /client/projects.
        </LuxInlineAlert>

        <ClientLuxPanel title="Client id" icon="fe fe-user">
          <div className="lux-client-portal-toolbar__row">
            <label className="form-label mb-0" htmlFor="client-portal-client-id">
              Client id
            </label>
            <input
              id="client-portal-client-id"
              className="form-control"
              style={{ maxWidth: 280 }}
              value={clientId}
              onChange={this.handleClientIdChange}
              placeholder="e.g. Acme"
            />
            {dataSource ? (
              <span className="small text-muted" data-testid="client-portal-source">
                Source: {dataSource}
              </span>
            ) : null}
          </div>
        </ClientLuxPanel>

        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load overview">
            {loadError}
          </LuxInlineAlert>
        ) : null}
        {signOffMessage ? (
          <LuxInlineAlert tone="info" title="Sign-off" testId="client-portal-signoff-message">
            {signOffMessage}
          </LuxInlineAlert>
        ) : null}

        {overview ? (
          <div className="lux-client-portal-grid">
            <ClientLuxPanel title={`Projects (${overview.projectCount || 0})`} icon="fe fe-briefcase">
              {projects.length === 0 ? (
                <LuxRegisterEmptyState title="No matching projects" description="No projects for this client id." showCreate={false} />
              ) : (
                <ul className="lux-client-portal-list">
                  {projects.map((row) => (
                    <li key={row.id}>
                      <span>{row.name || row.id}</span>
                      <ClientActionButton
                        variant="primary"
                        className="lux-onb-action--compact"
                        testId={`client-portal-signoff-${row.id}`}
                        disabled={signingProjectId === row.id}
                        onClick={() => this.handleSignOff(row.id)}
                      >
                        {signingProjectId === row.id ? "Signing…" : "Sign off"}
                      </ClientActionButton>
                    </li>
                  ))}
                </ul>
              )}
            </ClientLuxPanel>
            <ClientLuxPanel title={`Tickets (${overview.ticketCount || 0})`} icon="fe fe-message-square">
              {tickets.length === 0 ? (
                <LuxRegisterEmptyState title="No matching tickets" description="No tickets for this client id." showCreate={false} />
              ) : (
                <ul className="lux-client-portal-list lux-client-portal-list--plain">
                  {tickets.map((row) => (
                    <li key={row.id}>{row.title || row.id}</li>
                  ))}
                </ul>
              )}
            </ClientLuxPanel>
            <ClientLuxPanel title={`Invoices (${overview.invoiceCount || 0})`} icon="fe fe-file-text">
              {invoices.length === 0 ? (
                <LuxRegisterEmptyState title="No invoices" description="No invoices in lookback." showCreate={false} />
              ) : (
                <ul className="lux-client-portal-list lux-client-portal-list--plain">
                  {invoices.map((row) => (
                    <li key={row.id}>
                      {row.id ? (
                        <a href={`/finance/invoice/details/${row.id}`}>
                          {row.invoiceNumber || row.name || row.id}
                        </a>
                      ) : (
                        row.invoiceNumber || row.name || "Invoice"
                      )}
                    </li>
                  ))}
                </ul>
              )}
            </ClientLuxPanel>
          </div>
        ) : null}
      </ClientLuxPage>
    );
  }
}

export default ClientPortalPage;
