import React from "react";
import { Redirect } from "react-router-dom";
import { resolveModuleRootRedirect } from "config/navigation.config";

/**
 * F01-T4: Module root redirects (/people → /people/dashboard, etc.)
 * Returns flat Switch children — must NOT wrap in Fragment (breaks Switch matching).
 */
export function buildNavigationModuleRedirects(menuAccessControl) {
  const peopleTarget = resolveModuleRootRedirect("/people", menuAccessControl);
  const financeTarget = resolveModuleRootRedirect("/finance", menuAccessControl);
  const resourcesTarget = resolveModuleRootRedirect("/resources", menuAccessControl);
  const adminTarget = resolveModuleRootRedirect("/admin", menuAccessControl);
  const recruitingTarget = resolveModuleRootRedirect("/recruiting", menuAccessControl);
  const learningTarget = resolveModuleRootRedirect("/learning", menuAccessControl);
  const benefitsTarget = resolveModuleRootRedirect("/benefits", menuAccessControl);
  const npdTarget = resolveModuleRootRedirect("/npd", menuAccessControl);
  const vendorsTarget = resolveModuleRootRedirect("/vendors", menuAccessControl);

  const routes = [];

  if (peopleTarget) {
    routes.push(<Redirect key="/people" exact from="/people" to={peopleTarget} />);
  }
  if (financeTarget) {
    routes.push(<Redirect key="/finance" exact from="/finance" to={financeTarget} />);
  }
  if (resourcesTarget) {
    routes.push(<Redirect key="/resources" exact from="/resources" to={resourcesTarget} />);
  }
  if (adminTarget) {
    routes.push(<Redirect key="/admin" exact from="/admin" to={adminTarget} />);
  }
  if (recruitingTarget) {
    routes.push(<Redirect key="/recruiting" exact from="/recruiting" to={recruitingTarget} />);
  }
  if (learningTarget) {
    routes.push(<Redirect key="/learning" exact from="/learning" to={learningTarget} />);
  }
  if (benefitsTarget) {
    routes.push(<Redirect key="/benefits" exact from="/benefits" to={benefitsTarget} />);
  }
  if (npdTarget) {
    routes.push(<Redirect key="/npd" exact from="/npd" to={npdTarget} />);
  }
  if (vendorsTarget) {
    routes.push(<Redirect key="/vendors" exact from="/vendors" to={vendorsTarget} />);
  }

  routes.push(
    <Redirect key="/payroll" exact from="/payroll" to="/payroll/dashboard" />,
    <Redirect key="/performance" exact from="/performance" to="/performance/dashboard" />,
    <Redirect key="/analytics" exact from="/analytics" to="/analytics/executive-control-tower" />,
    <Redirect key="/integrations" exact from="/integrations" to="/integrations/hub" />,
    <Redirect key="/ai" exact from="/ai" to="/ai/agents" />
  );

  return routes;
}

export default buildNavigationModuleRedirects;
