import {
  WORK_GRAPH_EDGE_TYPES,
  WORK_GRAPH_NODE_TYPES,
} from "config/work-graph.config";

const SENSITIVE_NODE_FIELDS = ["ssn", "salary", "bankAccount"];

export function normalizeNode(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id || "",
    type: row.type || WORK_GRAPH_NODE_TYPES.TASK,
    label: row.label || row.title || "Untitled",
    module: row.module || "workspace",
    route: row.route || "",
    status: row.status || "active",
    teamId: row.teamId || null,
    layoutX: typeof row.layoutX === "number" ? row.layoutX : 50,
    layoutY: typeof row.layoutY === "number" ? row.layoutY : 50,
    tone: row.tone || "slate",
    meta: row.meta || {},
    updatedAt: row.updatedAt || null,
  };
}

export function normalizeEdge(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id || "",
    sourceId: row.sourceId || "",
    targetId: row.targetId || "",
    type: row.type || WORK_GRAPH_EDGE_TYPES.LINKED_TO,
    label: row.label || "",
    weight: typeof row.weight === "number" ? row.weight : 1,
  };
}

export function normalizeSearchHit(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id || "",
    nodeId: row.nodeId || "",
    title: row.title || "",
    snippet: row.snippet || "",
    module: row.module || "",
    type: row.type || "",
    route: row.route || "",
    score: typeof row.score === "number" ? row.score : 0,
    tone: row.tone || "slate",
  };
}

export function maskSensitiveGraphNode(node) {
  const normalized = normalizeNode(node);
  if (!normalized) {
    return null;
  }
  const meta = { ...(normalized.meta || {}) };
  SENSITIVE_NODE_FIELDS.forEach((field) => {
    if (meta[field]) {
      meta[field] = "***";
    }
  });
  return { ...normalized, meta };
}

export function filterNodes(nodes, filters) {
  const list = (nodes || []).map(normalizeNode).filter(Boolean);
  const f = filters || {};
  return list.filter((row) => {
    if (f.type && f.type !== "ALL" && row.type !== f.type) {
      return false;
    }
    if (f.module && f.module !== "ALL" && row.module !== f.module) {
      return false;
    }
    if (f.query) {
      const q = String(f.query).toLowerCase();
      const hay = `${row.label} ${row.module} ${row.type}`.toLowerCase();
      if (hay.indexOf(q) === -1) {
        return false;
      }
    }
    return true;
  });
}

export function getEdgesForNode(edges, nodeId) {
  return (edges || [])
    .map(normalizeEdge)
    .filter((edge) => edge && (edge.sourceId === nodeId || edge.targetId === nodeId));
}

export function getRelatedNodes(nodes, edges, nodeId) {
  const nodeMap = {};
  (nodes || []).forEach((row) => {
    const normalized = normalizeNode(row);
    if (normalized) {
      nodeMap[normalized.id] = normalized;
    }
  });
  const relatedEdges = getEdgesForNode(edges, nodeId);
  const relatedIds = {};
  relatedEdges.forEach((edge) => {
    if (edge.sourceId !== nodeId) {
      relatedIds[edge.sourceId] = true;
    }
    if (edge.targetId !== nodeId) {
      relatedIds[edge.targetId] = true;
    }
  });
  return Object.keys(relatedIds).map((id) => nodeMap[id]).filter(Boolean);
}

export function buildGraphKpis(nodes, edges) {
  const nodeList = (nodes || []).map(normalizeNode).filter(Boolean);
  const edgeList = (edges || []).map(normalizeEdge).filter(Boolean);
  const modules = {};
  const types = {};
  nodeList.forEach((row) => {
    modules[row.module] = (modules[row.module] || 0) + 1;
    types[row.type] = (types[row.type] || 0) + 1;
  });
  const moduleCount = Object.keys(modules).length;
  const density = nodeList.length ? (edgeList.length / nodeList.length).toFixed(1) : "0";
  return [
    { id: "nodes", label: "Graph nodes", value: String(nodeList.length), tone: "violet" },
    { id: "edges", label: "Relationships", value: String(edgeList.length), tone: "blue" },
    { id: "modules", label: "Modules linked", value: String(moduleCount), tone: "emerald" },
    { id: "density", label: "Edge density", value: density, tone: "amber" },
  ];
}

export function buildGraphInsights(nodes, edges) {
  const nodeList = (nodes || []).map(normalizeNode).filter(Boolean);
  const edgeList = (edges || []).map(normalizeEdge).filter(Boolean);
  const insights = [];
  const blocked = edgeList.filter((edge) => edge.type === WORK_GRAPH_EDGE_TYPES.BLOCKED_BY);
  if (blocked.length) {
    insights.push({
      id: "blocked",
      tone: "rose",
      title: `${blocked.length} blocked relationships`,
      body: "Delivery items have upstream blockers — review dependency register and integration sync health.",
    });
  }
  const riskNodes = nodeList.filter((row) => row.type === WORK_GRAPH_NODE_TYPES.RISK);
  if (riskNodes.length) {
    insights.push({
      id: "risks",
      tone: "amber",
      title: `${riskNodes.length} risks in graph cluster`,
      body: "Cross-module risk nodes tie delivery, finance, and service tickets — open portfolio control tower for rollups.",
    });
  }
  const ticketNodes = nodeList.filter((row) => row.type === WORK_GRAPH_NODE_TYPES.TICKET);
  if (ticketNodes.length) {
    insights.push({
      id: "tickets",
      tone: "indigo",
      title: `${ticketNodes.length} service tickets linked`,
      body: "Tickets bridge infra, billing, and project work items — check SLA posture on project tickets page.",
    });
  }
  if (!insights.length) {
    insights.push({
      id: "healthy",
      tone: "emerald",
      title: "Graph index healthy",
      body: "No critical bottleneck clusters detected in the mock work graph snapshot.",
    });
  }
  return insights;
}

export function buildGraphAnalytics(nodes, edges) {
  const nodeList = (nodes || []).map(normalizeNode).filter(Boolean);
  const edgeList = (edges || []).map(normalizeEdge).filter(Boolean);
  const moduleDensity = {};
  const edgeTypeCounts = {};
  nodeList.forEach((row) => {
    moduleDensity[row.module] = moduleDensity[row.module] || { nodes: 0, edges: 0 };
    moduleDensity[row.module].nodes += 1;
  });
  edgeList.forEach((edge) => {
    edgeTypeCounts[edge.type] = (edgeTypeCounts[edge.type] || 0) + 1;
    const source = nodeList.find((row) => row.id === edge.sourceId);
    if (source && moduleDensity[source.module]) {
      moduleDensity[source.module].edges += 1;
    }
  });
  const densityBars = Object.keys(moduleDensity).map((key) => ({
    label: key,
    nodes: moduleDensity[key].nodes,
    edges: moduleDensity[key].edges,
    score: moduleDensity[key].nodes + moduleDensity[key].edges * 2,
  }));
  densityBars.sort((a, b) => b.score - a.score);
  const bottleneckNodes = nodeList
    .map((row) => ({
      id: row.id,
      label: row.label,
      degree: getEdgesForNode(edgeList, row.id).length,
      type: row.type,
      tone: row.tone,
    }))
    .sort((a, b) => b.degree - a.degree)
    .slice(0, 5);
  return {
    densityBars,
    edgeTypeCounts,
    bottleneckNodes,
    riskClusters: nodeList.filter((row) => row.type === WORK_GRAPH_NODE_TYPES.RISK).length,
  };
}

export function searchGraphIndex(index, query, filters) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) {
    return [];
  }
  const f = filters || {};
  return (index || [])
    .map(normalizeSearchHit)
    .filter(Boolean)
    .filter((hit) => {
      if (f.module && f.module !== "ALL" && hit.module !== f.module) {
        return false;
      }
      if (f.type && f.type !== "ALL" && hit.type !== f.type) {
        return false;
      }
      const hay = `${hit.title} ${hit.snippet} ${hit.module}`.toLowerCase();
      return hay.indexOf(q) !== -1;
    })
    .sort((a, b) => b.score - a.score);
}

export function buildGraphAiContext(node, relatedNodes, edges) {
  const normalized = normalizeNode(node);
  if (!normalized) {
    return null;
  }
  const related = (relatedNodes || []).map(normalizeNode).filter(Boolean);
  const nodeEdges = getEdgesForNode(edges, normalized.id);
  return {
    focusNode: normalized.label,
    focusType: normalized.type,
    relatedCount: related.length,
    edgeCount: nodeEdges.length,
    summary: `Graph context for ${normalized.label}: ${related.length} related entities across ${nodeEdges.length} relationships.`,
    suggestions: [
      related.length > 3 ? "High fan-out node — consider delegating or splitting work items." : "Relationship fan-out is within normal range.",
      normalized.type === WORK_GRAPH_NODE_TYPES.RISK ? "Open risk register for mitigation owners and heatmap." : "Trace upstream approvals before changing delivery dates.",
      nodeEdges.some((edge) => edge.type === WORK_GRAPH_EDGE_TYPES.BLOCKED_BY)
        ? "Blocked dependency detected — review integration sync and milestone gates."
        : "No hard blockers on this entity in the graph snapshot.",
    ],
  };
}

export function exportGraphCsv(nodes, edges) {
  const header = "id,type,label,module,status,updatedAt";
  const nodeRows = (nodes || []).map((row) => {
    const n = normalizeNode(row);
    if (!n) {
      return "";
    }
    return [n.id, n.type, `"${n.label.replace(/"/g, '""')}"`, n.module, n.status, n.updatedAt || ""].join(",");
  });
  const edgeHeader = "\n\nedge_id,source_id,target_id,type,weight";
  const edgeRows = (edges || []).map((row) => {
    const e = normalizeEdge(row);
    if (!e) {
      return "";
    }
    return [e.id, e.sourceId, e.targetId, e.type, e.weight].join(",");
  });
  return [header].concat(nodeRows.filter(Boolean)).concat(edgeHeader).concat(edgeRows.filter(Boolean)).join("\n");
}
