/**
 * F05 — Attendance regularization APIs (fail-closed; no client invent).
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import envconfig from "env.config";
import { shouldUseAttendanceRegularizationApi } from "config/attendance-enhancement.config";
import {
  normalizeRegularizationPayload,
  summarizeRegularizationPending,
} from "config/attendance-regularization.utils";
import { apiErrorResult } from "config/mock-fallback.utils";
import { buildAnomalyRecommendationDraft } from "config/attendance-intelligence.utils";
import {
  AnalyticsEvents,
  trackAttendanceAction,
} from "config/analytics-events.config";

export const attendanceRegularizationService = {
  listByEmployee,
  listPending,
  submitRegularization,
  approveRegularization,
  rejectRegularization,
  getPolicy,
  savePolicy,
  getIntelligence,
  getAnomalyRecommendation,
};

function unavailable(emptyPayload = null, reason = "Attendance regularization API unavailable") {
  return { payload: emptyPayload, source: "api-error", error: reason, unavailable: true };
}

async function listByEmployeeFromApi(employeeId) {
  const userTeamId = commonUtils.getCurrentUserTeamId();
  const response = await axiosUtils.getWithParam(urlConfig.ATTENDANCE_REGULARIZATIONS, {
    employeeId,
    userTeamId,
  });
  const payload = response && response.payload ? response.payload : response;
  return Array.isArray(payload) ? payload.map(normalizeRegularizationPayload) : [];
}

async function listByEmployee(employeeId) {
  if (envconfig.USE_ATTENDANCE_REGULARIZATION_API !== true) {
    return unavailable([], "Attendance regularization API flag is off");
  }
  try {
    const rows = await listByEmployeeFromApi(employeeId);
    return { payload: rows, source: "api" };
  } catch (e) {
    return unavailable([], e && e.message ? e.message : "listByEmployee failed");
  }
}

async function listPendingFromApi(userTeamIds, managerId) {
  const params = { managerId: managerId };
  if (Array.isArray(userTeamIds) && userTeamIds.length) {
    params.userTeamId = userTeamIds[0];
    params.userTeamIds = userTeamIds;
  } else if (userTeamIds != null && userTeamIds !== "") {
    params.userTeamId = userTeamIds;
  }
  const response = await axiosUtils.getWithParam(
    `${urlConfig.ATTENDANCE_REGULARIZATIONS}/pending`,
    params
  );
  const payload = response && response.payload ? response.payload : response;
  return Array.isArray(payload) ? payload.map(normalizeRegularizationPayload) : [];
}

async function listPending(userTeamIds, managerId) {
  if (!shouldUseAttendanceRegularizationApi()) {
    return unavailable([], "Attendance regularization API flag is off");
  }
  const hasTeams =
    (Array.isArray(userTeamIds) && userTeamIds.length > 0) ||
    (userTeamIds != null && userTeamIds !== "");
  if (!hasTeams || !managerId) {
    return unavailable([], "userTeamId and managerId are required");
  }
  try {
    const rows = await listPendingFromApi(userTeamIds, managerId);
    return { payload: rows, source: "api" };
  } catch (e) {
    return unavailable([], e && e.message ? e.message : "listPending failed");
  }
}

function regularizationTeamQuery(extra) {
  const query = {
    userTeamId: (extra && extra.userTeamId) || commonUtils.getCurrentUserTeamId(),
  };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (key === "userTeamId") return;
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

function regularizationTeamQueryString(extra) {
  const query = regularizationTeamQuery(extra);
  return Object.keys(query)
    .map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(query[key])}`)
    .join("&");
}

function toSubmitBody(payload = {}) {
  return {
    employeeId: payload.employeeId,
    markDate: payload.markDate,
    exceptionType: payload.exceptionType,
    requestedInTime: payload.requestedInTime || null,
    requestedOutTime: payload.requestedOutTime || null,
    reason: payload.reason || "",
    remarks: payload.remarks || null,
  };
}

async function submitRegularization(payload = {}) {
  if (envconfig.USE_ATTENDANCE_REGULARIZATION_API !== true) {
    const err = new Error("Attendance regularization API is disabled");
    err.unavailable = true;
    throw err;
  }
  const userTeamId = payload.userTeamId || commonUtils.getCurrentUserTeamId();
  const actorId = payload.actorId || commonUtils.getCurrentUserId();
  const response = await axiosUtils.post(
    `${urlConfig.ATTENDANCE_REGULARIZATIONS}?${regularizationTeamQueryString({
      userTeamId,
      actorId,
    })}`,
    toSubmitBody(payload)
  );
  const normalized = normalizeRegularizationPayload(response && response.payload ? response.payload : response);
  trackAttendanceAction(AnalyticsEvents.ATTENDANCE_REG_SUBMIT, normalized && normalized.id);
  return normalized;
}

async function approveRegularization(id, approverId, comment, userTeamId) {
  if (envconfig.USE_ATTENDANCE_REGULARIZATION_API !== true) {
    const err = new Error("Attendance regularization API is disabled");
    err.unavailable = true;
    throw err;
  }
  const response = await axiosUtils.patch(
    `${urlConfig.ATTENDANCE_REGULARIZATIONS}/${id}/approve?${regularizationTeamQueryString({
      userTeamId: userTeamId || commonUtils.getCurrentUserTeamId(),
      approverId,
      approvalComment: comment || undefined,
    })}`,
    {}
  );
  const normalized = normalizeRegularizationPayload(response && response.payload ? response.payload : response);
  trackAttendanceAction(AnalyticsEvents.ATTENDANCE_REG_APPROVE, id);
  return normalized;
}

async function rejectRegularization(id, approverId, comment, userTeamId) {
  if (envconfig.USE_ATTENDANCE_REGULARIZATION_API !== true) {
    const err = new Error("Attendance regularization API is disabled");
    err.unavailable = true;
    throw err;
  }
  const response = await axiosUtils.patch(
    `${urlConfig.ATTENDANCE_REGULARIZATIONS}/${id}/reject?${regularizationTeamQueryString({
      userTeamId: userTeamId || commonUtils.getCurrentUserTeamId(),
      approverId,
      rejectionComment: comment || undefined,
    })}`,
    {}
  );
  const normalized = normalizeRegularizationPayload(response && response.payload ? response.payload : response);
  trackAttendanceAction(AnalyticsEvents.ATTENDANCE_REG_REJECT, id);
  return normalized;
}

async function getPolicyFromApi(userTeamId) {
  const response = await axiosUtils.get(
    `${urlConfig.ATTENDANCE_REGULARIZATION_POLICY}?userTeamId=${userTeamId}`
  );
  return response && response.payload ? response.payload : response;
}

async function getPolicy(userTeamId) {
  if (!shouldUseAttendanceRegularizationApi() || !userTeamId) {
    return unavailable(null, "Attendance regularization policy API unavailable");
  }
  try {
    const policy = await getPolicyFromApi(userTeamId);
    if (policy) return { payload: policy, source: "api" };
    return unavailable(null, "Policy not returned by API");
  } catch (e) {
    return unavailable(null, e && e.message ? e.message : "getPolicy failed");
  }
}

async function savePolicy(userTeamId, payload) {
  if (!shouldUseAttendanceRegularizationApi() || !userTeamId) {
    return unavailable(null, "Attendance regularization policy API unavailable");
  }
  if (!payload || typeof payload !== "object") {
    return unavailable(null, "Policy payload is required");
  }
  try {
    const actorId = commonUtils.getCurrentUserId();
    const response = await axiosUtils.put(
      `${urlConfig.ATTENDANCE_REGULARIZATION_POLICY}?userTeamId=${userTeamId}&actorId=${actorId}`,
      payload
    );
    const policy = response && response.payload ? response.payload : response;
    if (policy) return { payload: policy, source: "api" };
    return unavailable(null, "Policy not returned by save API");
  } catch (e) {
    return unavailable(null, e && e.message ? e.message : "savePolicy failed");
  }
}

async function getIntelligence(context) {
  const { userTeamId } = context || {};
  const teamId = userTeamId || commonUtils.getCurrentUserTeamId();
  if (!shouldUseAttendanceRegularizationApi() || !teamId) {
    return apiErrorResult(null);
  }
  try {
    const response = await axiosUtils.getWithParam(urlConfig.ATTENDANCE_INTELLIGENCE, { userTeamId: teamId });
    const payload = response && response.payload ? response.payload : response;
    if (payload) return { ...payload, source: "api" };
    return apiErrorResult(null);
  } catch (e) {
    return { payload: null, source: "api-error", error: e };
  }
}

async function getAnomalyRecommendation(intelligence) {
  if (!intelligence || intelligence.source === "api-error") {
    return { payload: null, source: "api-error" };
  }
  return buildAnomalyRecommendationDraft(intelligence);
}

export { summarizeRegularizationPending };
