import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { POLICY_ACK_STATUSES } from "config/document-vault.config";
import { isPolicyHubEnabled, shouldUsePolicyCampaigns, shouldUsePolicyVersioning } from "config/policy-hub.config";
import { buildPolicyHubInsights, buildPolicyHubMetrics } from "config/policy-hub.utils";
import { documentVaultService } from "_services/documentVault.service";
import { policyHubService } from "_services/policyHub.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import OrgPolicyAnalyticsPanel from "views/people/components/policy/OrgPolicyAnalyticsPanel";
import {
  PeopleActionButton,
  PeopleRowAction,
  PeopleSegmentNav,
} from "views/people/components/PeopleLuxShared";
import { POLICY_HUB_PAGE_META, POLICY_HUB_VIEW_NAV } from "config/people-module-nav.config";

class PolicyHubPage extends Component {
  state = {
    acknowledgments: [],
    registry: [],
    campaigns: [],
    analytics: null,
    loading: true,
    loadError: null,
    dataSource: null,
    statusFilter: "ALL",
    viewMode: "acknowledgments",
    launching: false,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Policies");
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const [ackResult, registryResult, campaignsResult, analyticsResult] = await Promise.all([
        documentVaultService.listPolicies(),
        policyHubService.listPolicies(),
        policyHubService.listCampaigns(),
        policyHubService.getAnalytics(),
      ]);
      this.setState({
        acknowledgments: ackResult.payload || [],
        registry: registryResult.payload || [],
        campaigns: campaignsResult.payload || [],
        analytics: analyticsResult.payload || null,
        loading: false,
        dataSource: ackResult.source || registryResult.source || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load policy hub data.",
        acknowledgments: [],
        registry: [],
        campaigns: [],
      });
    }
  };

  handleAcknowledge = async (policy) => {
    await documentVaultService.acknowledgePolicy(policy.id, policy.employeeName || "Current user");
    const campaign = this.state.campaigns.find((row) => row.policyId === policy.policyId);
    if (campaign) {
      await policyHubService.acknowledgeCampaign(campaign.id, policy.employeeName || "Current user");
    }
    await this.loadData();
  };

  handleLaunchCampaign = async (policy) => {
    if (!shouldUsePolicyCampaigns() || !policy) {
      return;
    }
    this.setState({ launching: true });
    try {
      await policyHubService.launchCampaign({
        policyId: policy.id,
        policyTitle: policy.title,
        version: policy.currentVersion,
        dueDate: "2026-07-15",
        audience: "All employees",
        description: `Acknowledgment campaign for ${policy.title} v${policy.currentVersion}`,
      });
      await this.loadData();
    } finally {
      this.setState({ launching: false });
    }
  };

  getFilteredAcknowledgments = () => {
    const { acknowledgments, statusFilter } = this.state;
    if (statusFilter === "ALL") {
      return acknowledgments;
    }
    return acknowledgments.filter((row) => row.status === statusFilter);
  };

  renderKpiStrip = () => {
    const { acknowledgments, registry, campaigns, loading } = this.state;
    const metrics = buildPolicyHubMetrics(registry, campaigns, acknowledgments);
    const cards = [
      { id: "registry", label: "Published", value: metrics.policies, hint: `${metrics.publishedVersions} versions`, tone: "primary" },
      { id: "campaigns", label: "Campaigns", value: metrics.activeCampaigns, hint: "Active rollouts", tone: "blue" },
      { id: "compliance", label: "Compliance", value: `${metrics.complianceRate}%`, hint: `${metrics.missingAcks} outstanding`, tone: "amber" },
      { id: "overdue", label: "Overdue", value: metrics.overdue, hint: `${metrics.acknowledged} complete`, tone: "rose" },
    ];

    return (
      <div className="lux-hrms-dash__kpi-strip lux-doc-kpi-strip" role="list" aria-busy={loading}>
        {cards.map((card) => (
          <article
            key={card.id}
            className={classNames("lux-hrms-dash__kpi lux-doc-kpi", card.tone && `is-${card.tone}`)}
            role="listitem"
          >
            <span className="lux-hrms-dash__kpi-label">{card.label}</span>
            <strong className="lux-hrms-dash__kpi-value">{loading ? "—" : card.value}</strong>
            <span className="lux-hrms-dash__kpi-hint">{card.hint}</span>
          </article>
        ))}
      </div>
    );
  };

  renderInsights = () => {
    const { acknowledgments, registry, campaigns, loading } = this.state;
    if (loading) return null;
    const insights = buildPolicyHubInsights(buildPolicyHubMetrics(registry, campaigns, acknowledgments));
    return (
      <div className="lux-policy-hub-insights" role="list">
        {insights.map((insight) => (
          <article
            key={insight.id}
            className={classNames("lux-hrms-dash__alert lux-policy-hub-insight", `is-${insight.tone}`)}
            role="listitem"
          >
            <span className="lux-hrms-dash__alert-icon" aria-hidden="true">
              <i className={insight.icon} />
            </span>
            <span className="lux-policy-hub-insight__copy">
              <strong>{insight.title}</strong>
              <small>{insight.copy}</small>
            </span>
          </article>
        ))}
      </div>
    );
  };

  renderAcknowledgments = () => {
    const { loading } = this.state;
    const rows = this.getFilteredAcknowledgments();
    if (loading) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          title="Loading policies"
          description="Fetching acknowledgment campaigns."
        />
      );
    }
    if (rows.length === 0) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          icon="fe fe-book"
          title="No policies"
          description="Policy acknowledgment campaigns will appear here."
        />
      );
    }
    return (
      <div className="lux-doc-register-wrap">
        <table className="lux-doc-register">
          <thead>
            <tr>
              <th>Policy</th>
              <th>Version</th>
              <th>Due</th>
              <th>Progress</th>
              <th>Status</th>
              <th aria-label="Actions" />
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => {
              const progress =
                row.assignedCount != null && row.acknowledgedCount != null
                  ? `${row.acknowledgedCount}/${row.assignedCount}`
                  : row.employeeName || "Org-wide";
              return (
                <tr key={row.id}>
                  <td>
                    <strong>
                      {row.policyId ? (
                        <Link to={`/people/policies/${row.policyId}`} className="lux-doc-register__link">
                          {row.title}
                        </Link>
                      ) : (
                        row.title
                      )}
                    </strong>
                    {row.description && <span className="lux-doc-register__meta">{row.description}</span>}
                  </td>
                  <td>{row.version}</td>
                  <td>{row.dueDate || "—"}</td>
                  <td>{progress}</td>
                  <td>
                    <span
                      className={classNames("lux-doc-badge", {
                        "is-success": row.status === POLICY_ACK_STATUSES.ACKNOWLEDGED,
                        "is-warning": row.status === POLICY_ACK_STATUSES.PENDING,
                        "is-danger": row.status === POLICY_ACK_STATUSES.OVERDUE,
                      })}
                    >
                      {row.status}
                    </span>
                  </td>
                  <td>
                    {row.status !== POLICY_ACK_STATUSES.ACKNOWLEDGED && (
                      <PeopleRowAction
                        icon="fe fe-check"
                        onClick={() => this.handleAcknowledge(row)}
                      >
                        Acknowledge
                      </PeopleRowAction>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    );
  };

  renderRegistry = () => {
    const { registry, loading, launching } = this.state;
    if (loading) {
      return <LuxRegisterEmptyState className="lux-register-empty--compact" title="Loading registry" />;
    }
    if (!registry.length) {
      return <LuxRegisterEmptyState className="lux-register-empty--compact" title="No published policies" />;
    }
    return (
      <div className="lux-doc-register-wrap">
        <table className="lux-doc-register">
          <thead>
            <tr>
              <th>Policy</th>
              <th>Category</th>
              <th>Version</th>
              <th>Compliance</th>
              <th aria-label="Actions" />
            </tr>
          </thead>
          <tbody>
            {registry.map((row) => {
              const assigned = row.assignedCount || 0;
              const acknowledged = row.acknowledgedCount || 0;
              const rate = assigned > 0 ? Math.round((acknowledged / assigned) * 100) : 0;
              return (
                <tr key={row.id}>
                  <td>
                    <Link to={`/people/policies/${row.id}`} className="lux-doc-register__link">
                      <strong>{row.title}</strong>
                    </Link>
                    <span className="lux-doc-register__meta">{row.summary}</span>
                  </td>
                  <td>{row.category}</td>
                  <td>v{row.currentVersion}</td>
                  <td>{assigned ? `${rate}% (${acknowledged}/${assigned})` : "—"}</td>
                  <td>
                    <div className="lux-policy-hub__actions">
                      <PeopleRowAction to={`/people/policies/${row.id}`} variant="secondary" icon="fe fe-layers">
                        Versions
                      </PeopleRowAction>
                      {shouldUsePolicyCampaigns() && (
                        <PeopleRowAction
                          icon="fe fe-send"
                          disabled={launching}
                          onClick={() => this.handleLaunchCampaign(row)}
                        >
                          Launch campaign
                        </PeopleRowAction>
                      )}
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    );
  };

  render() {
    if (!isPolicyHubEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Policies"
          reason="Policy hub is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, dataSource, statusFilter, viewMode, analytics } = this.state;
    const viewModes = POLICY_HUB_VIEW_NAV.filter(
      (item) => item.id !== "registry" || shouldUsePolicyVersioning()
    );

    return (
      <div className="lux-doc-page lux-policy-hub-page lux-people-page lux-register-page" data-testid="page-policies">
        <PageDataSourceReporter dataSource={dataSource} />
        <LuxModuleIntro
                  meta={POLICY_HUB_PAGE_META}
                  nav={
                    <PeopleSegmentNav
                      items={viewModes}
                      activeId={viewMode}
                      onChange={(next) => this.setState({ viewMode: next })}
                      ariaLabel="Policy hub views"
                    />
                  }
                  actions={
                    <>
                      <PeopleActionButton to="/people/org-chart" variant="ghost" icon="fe fe-git-branch">
                        Org chart
                      </PeopleActionButton>
                      <PeopleActionButton to="/people/documents" variant="ghost" icon="fe fe-folder">
                        Document vault
                      </PeopleActionButton>
                    </>
                  }
                />

        <div className="lux-register-page__body">
        {this.renderKpiStrip()}
        {this.renderInsights()}

        {loadError ? <LuxInlineAlert message={loadError} tone="danger" /> : null}

        <section className="lux-hrms-dash__panel lux-doc-panel">
          <header className="lux-hrms-dash__panel-head lux-appr-toolbar">
            {viewMode === "acknowledgments" ? (
              <div className="lux-hrms-dash__filter-group">
                {["ALL", POLICY_ACK_STATUSES.PENDING, POLICY_ACK_STATUSES.OVERDUE, POLICY_ACK_STATUSES.ACKNOWLEDGED].map(
                  (value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", {
                        "is-active": statusFilter === value,
                      })}
                      onClick={() => this.setState({ statusFilter: value })}
                    >
                      {value === "ALL" ? "All" : value}
                    </button>
                  )
                )}
              </div>
            ) : (
              <h2 className="lux-hrms-dash__panel-title">
                {viewMode === "registry" ? "Policy registry" : "Policy analytics"}
              </h2>
            )}
          </header>

          <div className="lux-hrms-dash__panel-body">
            {viewMode === "acknowledgments" && this.renderAcknowledgments()}
            {viewMode === "registry" && this.renderRegistry()}
            {viewMode === "analytics" && (
              <OrgPolicyAnalyticsPanel analytics={analytics} loading={loading} showOrg showPolicy />
            )}
          </div>
        </section>
        </div>
      </div>
    );
  }
}

export default PolicyHubPage;
