import React from "react";
import classNames from "classnames/bind";
import { getDecisionTypeTone } from "config/project-governance.utils";

export default function DecisionRegister({ rows, loading, onSelect }) {
  if (loading) {
    return null;
  }

  return (
    <div className="lux-gov-register-wrap">
      <table className="lux-gov-register lux-gov-register--decisions">
        <thead>
          <tr>
            <th>Decision</th>
            <th>Project</th>
            <th>Type</th>
            <th>Decided by</th>
            <th>Date</th>
            <th>Impact</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const tone = getDecisionTypeTone(row.type);
            return (
              <tr key={row.id} className="lux-gov-register__row">
                <td>
                  <button type="button" className="lux-gov-register__link" onClick={() => onSelect && onSelect(row)}>
                    <strong>{row.title}</strong>
                    {row.rationale ? <span>{row.rationale}</span> : null}
                  </button>
                </td>
                <td>
                  <span className="lux-gov-register__project">{row.projectName}</span>
                  {row.projectCode ? <span className="lux-gov-register__meta">{row.projectCode}</span> : null}
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${tone}`)}>{row.type}</span>
                </td>
                <td>{row.decidedBy || "—"}</td>
                <td>{row.decidedAt || "—"}</td>
                <td>{row.impact || "—"}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
