import React, { Component } from "react";
import { connect } from "react-redux";
import { Link } from "react-router-dom";
import Skeleton from "react-loading-skeleton";
import { workItemConstants } from "_constants";
import { workItemActions } from "_actions";
import { commonUtils } from "_helpers";
import { dashbaordService } from "_services";
import { leaveService } from "_services/leave.service";
import dateUtils from "_helpers/date.utils";
import { store, accessUtils } from "_helpers";
import { shouldUseLeaveManagement } from "_helpers/leave.config";
import { isPendingLeave } from "views/hrms/components/leave/leave.utils";
import {
  buildActivityFeed,
  formatTodayDate,
  getItemTimeRangeLabel,
  getTaskStatusMeta,
  minsToHoursLabel,
  summarizeTodayItems,
} from "./todayActivity.utils";

class TodayActivitySidebar extends Component {
  closeTodayActivitySidebar = () => {
    store.dispatch({ type: workItemConstants.CLOSE_TODAYS_ACTIVITY_WINDOW });
  };

  render() {
    const { show } = this.props;

    return (
      <>
        {show && (
          <button
            type="button"
            className="lux-today-panel__backdrop"
            aria-label="Close today's activity"
            onClick={this.closeTodayActivitySidebar}
          />
        )}
        <aside
          id="todayactivity_right_sidebar"
          className={`right_sidebar todayactivity_right_sidebar lux-today-panel${show ? " open" : ""}`}
          aria-hidden={!show}
          aria-label="Today's activity"
        >
          <header className="lux-today-panel__header">
            <div className="lux-today-panel__header-copy">
              <p className="lux-today-panel__kicker">Daily workspace</p>
              <h2 className="lux-today-panel__title">Today&apos;s activity</h2>
              <p className="lux-today-panel__date">{formatTodayDate()}</p>
            </div>
            <button
              type="button"
              className="lux-today-panel__close"
              onClick={this.closeTodayActivitySidebar}
              aria-label="Close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          {show && (
            <TodayActivityContent
              items={this.props.items}
              isLoading={this.props.isLoading}
              onRefresh={this.props.getTodaysWorkItemActivities}
              onClose={this.closeTodayActivitySidebar}
            />
          )}
        </aside>
      </>
    );
  }
}

class TodayActivityContent extends Component {
  state = {
    todayUtilization: null,
    utilLoading: false,
    pendingLeaveCount: 0,
    leaveLoading: false,
  };

  componentDidMount() {
    this.loadAll();
  }

  loadAll = () => {
    this.loadTodayTasks();
    this.loadTodayUtilization();
    this.loadPendingLeaveCount();
  };

  loadPendingLeaveCount = () => {
    const employeeId = commonUtils.getCurrentUserId();
    const permission = accessUtils.getLeaveAccessControl();
    if (!employeeId || !shouldUseLeaveManagement() || !permission.viewEnabled) {
      this.setState({ pendingLeaveCount: 0 });
      return;
    }
    this.setState({ leaveLoading: true });
    leaveService
      .listByEmployee(employeeId)
      .then((res) => {
        const list = (res && res.payload) || [];
        const pendingLeaveCount = list.filter((leave) => isPendingLeave(leave)).length;
        this.setState({ pendingLeaveCount, leaveLoading: false });
      })
      .catch(() => this.setState({ pendingLeaveCount: 0, leaveLoading: false }));
  };

  loadTodayTasks = () => {
    const employeeIds = [commonUtils.getCurrentUserId()];
    const teamIds = commonUtils.getCurrentUserTeamIds();
    const userTeamIds =
      teamIds && teamIds.length > 0 ? teamIds : [commonUtils.getCurrentUserTeamId()];
    const startDate = dateUtils.getCurrentDayStart().clone().format(dateUtils.SERVER_DATE_FORMAT);
    const endDate = dateUtils.getCurrentDayEnd().clone().format(dateUtils.SERVER_DATE_FORMAT);

    this.props.onRefresh({
      employeeIds,
      userTeamIds,
      startDate,
      endDate,
    });
  };

  loadTodayUtilization = () => {
    const employeeId = commonUtils.getCurrentUserId();
    const startDate = dateUtils.getCurrentDayStart().clone().format(dateUtils.SERVER_DATE_FORMAT);
    const endDate = dateUtils.getCurrentDayEnd().clone().format(dateUtils.SERVER_DATE_FORMAT);

    this.setState({ utilLoading: true });
    dashbaordService
      .employeeWeeklyUtilization({ employeeId, startDate, endDate })
      .then((res) => {
        this.setState({
          todayUtilization: (res && res.payload) || null,
          utilLoading: false,
        });
      })
      .catch(() => {
        this.setState({ utilLoading: false });
      });
  };

  renderProgress = () => {
    const { items, isLoading } = this.props;
    const summary = summarizeTodayItems(items);

    if (isLoading && (!items || items.length === 0)) {
      return <Skeleton height={120} borderRadius={16} />;
    }

    return (
      <section className="lux-today-panel__section">
        <div className="lux-today-panel__section-head">
          <h3 className="lux-today-panel__section-title">Day progress</h3>
          <button
            type="button"
            className="lux-today-panel__refresh"
            onClick={this.loadAll}
            title="Refresh"
          >
            <i className="fe fe-refresh-cw" aria-hidden="true" />
          </button>
        </div>

        <div className="lux-today-panel__progress-hero">
          <div
            className="lux-today-panel__ring"
            style={{ "--lux-progress": `${summary.progressPct}%` }}
            aria-hidden="true"
          >
            <div className="lux-today-panel__ring-inner">
              <strong>{summary.progressPct}%</strong>
              <span>done</span>
            </div>
          </div>
          <div className="lux-today-panel__progress-copy">
            <p>
              <strong>{summary.completed}</strong> of <strong>{summary.total}</strong> tasks
              completed today
            </p>
            <div className="lux-today-panel__progress-bar">
              <div
                className="lux-today-panel__progress-fill"
                style={{ width: `${summary.timeProgressPct}%` }}
              />
            </div>
            <span className="lux-today-panel__progress-meta">
              {minsToHoursLabel(summary.loggedMins)} logged ·{" "}
              {minsToHoursLabel(summary.estMins)} planned
            </span>
          </div>
        </div>

        <div className="lux-today-panel__stat-row">
          <article className="lux-today-panel__stat">
            <strong>{summary.inProgress}</strong>
            <span>Active</span>
          </article>
          <article className="lux-today-panel__stat">
            <strong>{summary.scheduled}</strong>
            <span>Scheduled</span>
          </article>
          <article className="lux-today-panel__stat">
            <strong>{summary.paused}</strong>
            <span>Paused</span>
          </article>
        </div>
      </section>
    );
  };

  renderLeavePending = () => {
    const { pendingLeaveCount, leaveLoading } = this.state;
    const permission = accessUtils.getLeaveAccessControl();
    if (!shouldUseLeaveManagement() || !permission.viewEnabled) {
      return null;
    }
    if (leaveLoading && pendingLeaveCount === 0) {
      return <Skeleton height={56} borderRadius={14} />;
    }
    if (pendingLeaveCount === 0) {
      return null;
    }

    return (
      <section className="lux-today-panel__section lux-today-panel__section--compact">
        <h3 className="lux-today-panel__section-title">Leave awaiting approval</h3>
        <Link to="/people/leaves" className="lux-today-panel__leave-pending" onClick={this.props.onClose}>
          <span>
            <strong>{pendingLeaveCount}</strong> request{pendingLeaveCount === 1 ? "" : "s"} pending
          </span>
          <i className="fe fe-arrow-right" aria-hidden="true" />
        </Link>
      </section>
    );
  };

  renderUtilization = () => {
    const { todayUtilization, utilLoading } = this.state;

    if (utilLoading && !todayUtilization) {
      return <Skeleton height={72} borderRadius={14} />;
    }

    if (!todayUtilization) return null;

    const total =
      (todayUtilization.billableMins || 0) +
      (todayUtilization.nonBillableMins || 0) +
      (todayUtilization.leaveMins || 0) +
      (todayUtilization.holidayMins || 0);

    return (
      <section className="lux-today-panel__section lux-today-panel__section--compact">
        <h3 className="lux-today-panel__section-title">Today&apos;s hours</h3>
        <div className="lux-today-panel__hours-row">
          <span className="lux-today-panel__hour-chip lux-today-panel__hour-chip--billable">
            Billable {minsToHoursLabel(todayUtilization.billableMins)}
          </span>
          <span className="lux-today-panel__hour-chip">
            Non-billable {minsToHoursLabel(todayUtilization.nonBillableMins)}
          </span>
          {(todayUtilization.leaveMins > 0 || todayUtilization.holidayMins > 0) && (
            <span className="lux-today-panel__hour-chip lux-today-panel__hour-chip--leave">
              Leave {minsToHoursLabel(
                (todayUtilization.leaveMins || 0) + (todayUtilization.holidayMins || 0)
              )}
            </span>
          )}
          <span className="lux-today-panel__hour-total">Total {minsToHoursLabel(total)}</span>
        </div>
      </section>
    );
  };

  renderTimeline = () => {
    const { items, isLoading } = this.props;
    const list = items || [];

    if (isLoading && list.length === 0) {
      return <Skeleton height={180} borderRadius={16} />;
    }

    return (
      <section className="lux-today-panel__section">
        <h3 className="lux-today-panel__section-title">Today&apos;s schedule</h3>
        {list.length === 0 ? (
          <p className="lux-today-panel__empty">No tasks scheduled for today yet.</p>
        ) : (
          <ol className="lux-today-panel__timeline">
            <li className="lux-today-panel__timeline-marker lux-today-panel__timeline-marker--start">
              <span className="lux-today-panel__timeline-dot" />
              <div>
                <strong>Day start</strong>
                <p>Good morning — let&apos;s get started</p>
              </div>
            </li>
            {list.map((item) => {
              const meta = getTaskStatusMeta(item.status);
              return (
                <li key={item.id} className="lux-today-panel__timeline-item">
                  <span className={`lux-today-panel__timeline-dot ${meta.className}`} />
                  <div className="lux-today-panel__timeline-body">
                    <div className="lux-today-panel__timeline-head">
                      <time>{getItemTimeRangeLabel(item)}</time>
                      <span className={`lux-today-panel__status ${meta.className}`}>
                        {meta.label}
                      </span>
                    </div>
                    <strong>{item.name}</strong>
                    <p>{item.taskActCategory || item.taskName}</p>
                  </div>
                </li>
              );
            })}
            <li className="lux-today-panel__timeline-marker lux-today-panel__timeline-marker--end">
              <span className="lux-today-panel__timeline-dot" />
              <div>
                <strong>Wrap up</strong>
                <p>Review progress and close the day</p>
              </div>
            </li>
          </ol>
        )}
      </section>
    );
  };

  renderActivityFeed = () => {
    const { items } = this.props;
    const feed = buildActivityFeed(items);

    if (feed.length === 0) return null;

    return (
      <section className="lux-today-panel__section">
        <h3 className="lux-today-panel__section-title">User activity</h3>
        <ul className="lux-today-panel__feed">
          {feed.map((entry) => (
            <li key={entry.id} className="lux-today-panel__feed-item">
              <span className={`lux-today-panel__feed-icon ${entry.statusClass}`}>
                <i className={`fe ${entry.icon}`} aria-hidden="true" />
              </span>
              <div className="lux-today-panel__feed-copy">
                <div className="lux-today-panel__feed-head">
                  <strong>{entry.action}</strong>
                  {entry.time && <time>{entry.time}</time>}
                </div>
                <p>{entry.title}</p>
                <span>{entry.subtitle}</span>
              </div>
            </li>
          ))}
        </ul>
      </section>
    );
  };

  render() {
    return (
      <div className="lux-today-panel__body">
        {this.renderProgress()}
        {this.renderLeavePending()}
        {this.renderUtilization()}
        {this.renderTimeline()}
        {this.renderActivityFeed()}
        <div className="lux-today-panel__links">
          <Link
            to="/project/taskboard"
            className="lux-today-panel__link-btn"
            onClick={this.props.onClose}
          >
            Open taskboard
          </Link>
          <Link
            to="/project/activites"
            className="lux-today-panel__link-btn lux-today-panel__link-btn--ghost"
            onClick={this.props.onClose}
          >
            Task activity
          </Link>
        </div>
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  show: state.workItem.showTodaysActivityModel,
  items:
    state.workItem.todaysWorkItems &&
    commonUtils.sortArrayOfObjectsByDateField(state.workItem.todaysWorkItems, "estStartTime", true),
  isLoading: state.workItem.isTodaysWorkItemsLoading,
});

const mapDispatchToProps = {
  getTodaysWorkItemActivities: workItemActions.getTodaysWorkItemActivities,
};

export default connect(mapStateToProps, mapDispatchToProps)(TodayActivitySidebar);
