import moment from "moment";
import dateUtils from "_helpers/date.utils";
import { commonUtils } from "_helpers";
import { normalizeProjectStatus } from "../projectList.utils";

const STATUS_TONES = {
  NEW: "sky",
  ASSIGNED: "indigo",
  INPROGRESS: "amber",
  COMPLETED: "green",
  CLOSED: "slate",
};

const STATUS_LABELS = {
  NEW: "New",
  ASSIGNED: "Assigned",
  INPROGRESS: "In progress",
  COMPLETED: "Completed",
  CLOSED: "Closed",
};

const PROJECT_TYPE_LABELS = {
  ADHOC: "Adhoc",
  FTEMS: "FTE–MS",
  FTESA: "FTE–Staff aug",
  SERVICES: "Services",
  PRODUCT: "Product",
  TRACKER: "Tracker",
  TMHB: "T&M hourly",
};

const BILLING_TYPE_LABELS = {
  BILLABLE: "Billable",
  BILLABLE_DA: "Billable DA",
  NON_BILLABLE_PRODUCTIVE: "NB productive",
  NON_BILLABLE: "Non-billable",
};

const PRIORITY_LABELS = {
  URGENT: "Urgent",
  HIGH: "High",
  MEDIUM: "Medium",
  LOW: "Low",
};

const COMPLEXITY_LABELS = {
  BASIC: "Basic",
  MEDIUM: "Medium",
  COMPLEX: "Complex",
  UNSPECIFIED: "Not set",
};

const CAPEX_LABELS = {
  Capex: "Capex",
  Opex: "Opex",
  UNSPECIFIED: "Not set",
};

const SHARED_LABELS = {
  SHARED: "Shared",
  PRIVATE: "Private",
};

const HOURS_ESTIMATE_LABELS = {
  WITH_HOURS: "Hours estimated",
  MISSING: "No hours estimate",
};

function hasNumericEstimate(value) {
  if (value === null || value === undefined || value === "") return false;
  const num = parseFloat(value);
  return !Number.isNaN(num) && num > 0;
}

export function resolveServiceLineEstimateEnabled(createConfig, activeList) {
  if (createConfig && createConfig.length) {
    return !!commonUtils.getAppConfigValue(createConfig, "enableServiceLineEstimate");
  }
  const withLineEstimates = activeList.filter(
    (item) => item.serviceLineEstimate && Object.keys(item.serviceLineEstimate).length > 0
  ).length;
  return withLineEstimates > Math.max(0, Math.floor(activeList.length * 0.2));
}

function getServiceLinesForItem(item) {
  if (item.serviceLines && item.serviceLines.length) {
    return Array.isArray(item.serviceLines) ? item.serviceLines : [item.serviceLines];
  }
  if (item.category) return [item.category];
  return [];
}

export function isMissingServiceLineEstimate(item) {
  const lines = getServiceLinesForItem(item);
  const estimate = item.serviceLineEstimate;
  if (!lines.length) {
    return !estimate || !Object.keys(estimate).length;
  }
  if (!estimate || typeof estimate !== "object") return true;
  return lines.some((line) => {
    const row = estimate[line];
    if (!row) return true;
    return !hasNumericEstimate(row.estHours) && !hasNumericEstimate(row.estHourlyRate);
  });
}

export function isMissingProjectLevelEstimate(item) {
  return (
    !hasNumericEstimate(item.estHours) &&
    !hasNumericEstimate(item.estCost) &&
    !hasNumericEstimate(item.estHourlyRate)
  );
}

function buildEstimateGapEntry(item) {
  return {
    id: item.id,
    name: item.name || item.code || "Untitled project",
    code: item.code,
    accountName: item.accountName,
    teamName: item.teamName,
    status: itemStatus(item),
  };
}

const TIMELINE_LABELS = {
  OVERDUE: "Overdue",
  DUE_SOON: "Due in 14 days",
  ON_TRACK: "On track",
  NO_DATE: "No end date",
};

const TIMELINE_TONES = {
  OVERDUE: "rose",
  DUE_SOON: "amber",
  ON_TRACK: "green",
  NO_DATE: "slate",
};

const PIPELINE_STATUSES = ["NEW", "ASSIGNED", "INPROGRESS"];
const FUNNEL_STAGES = ["NEW", "ASSIGNED", "INPROGRESS", "COMPLETED"];
const TREND_MONTHS = 6;
const DUE_SOON_DAYS = 14;

function pct(count, total) {
  if (!total) return 0;
  return Math.round((count / total) * 100);
}

function itemStatus(item) {
  return normalizeProjectStatus(item && item.status);
}

function toMoment(value) {
  if (!value) return null;
  const m = dateUtils.convertDateStringToMoment(value);
  return m && m.isValid() ? m : null;
}

function buildMixSegments(counts, total, labelMap = STATUS_LABELS, toneMap = STATUS_TONES) {
  return Object.entries(counts)
    .filter(([, count]) => count > 0)
    .map(([key, count]) => ({
      key,
      label: (labelMap && labelMap[key]) || key,
      count,
      pct: pct(count, total),
      tone: (toneMap && toneMap[key]) || "slate",
    }))
    .sort((a, b) => b.count - a.count);
}

function classifyTimelineHealth(item, today, dueSoonEnd) {
  const end = toMoment(item.estCompletionTime);
  if (!end) return "NO_DATE";
  if (end.isBefore(today, "day")) return "OVERDUE";
  if (end.isSameOrBefore(dueSoonEnd, "day")) return "DUE_SOON";
  return "ON_TRACK";
}

function buildCreatedTrend(activeList) {
  const today = moment().startOf("month");
  const buckets = [];
  for (let i = TREND_MONTHS - 1; i >= 0; i -= 1) {
    const month = today.clone().subtract(i, "months");
    buckets.push({ key: month.format("YYYY-MM"), label: month.format("MMM YY"), count: 0 });
  }
  const bucketMap = buckets.reduce((acc, b) => {
    acc[b.key] = b;
    return acc;
  }, {});

  activeList.forEach((item) => {
    const created = toMoment(item.createdDate);
    if (!created) return;
    const key = created.startOf("month").format("YYYY-MM");
    if (bucketMap[key]) bucketMap[key].count += 1;
  });
  return buckets;
}

function buildEmptyStats(userTeams) {
  const empty = {
    total: 0,
    active: 0,
    archived: 0,
    deleted: 0,
    pipeline: 0,
    completed: 0,
    closed: 0,
    favorites: 0,
    shared: 0,
    poLinked: 0,
    completionRate: 0,
    pipelineRate: 0,
    avgTaskPct: 0,
    avgHoursPct: 0,
    overdueCount: 0,
    dueSoonCount: 0,
    selectedTeams: 0,
    statusMix: [],
    projectTypeMix: [],
    accountMix: [],
    teamMix: [],
    timelineMix: [],
    createdTrend: buildCreatedTrend([]),
    funnel: [],
    outcomes: { open: 0, completed: 0, closed: 0, other: 0 },
    kpis: [],
    highlights: [],
    insights: [],
    stageCounts: { newCount: 0, assignedCount: 0, inProgressCount: 0, completedCount: 0 },
    billingTypeMix: [],
    priorityMix: [],
    automationMix: [],
    sharedMix: [],
    complexityMix: [],
    capexMix: [],
    hoursEstimateMix: [],
    estimateGaps: null,
  };
  if (userTeams && userTeams.length) {
    empty.selectedTeams = userTeams.filter((t) => t.isChecked).length;
  }
  return empty;
}

function buildKpis(stat) {
  return [
    { key: "active", label: "Active", value: stat.active, hint: "In portfolio", icon: "fe fe-layers", tone: "green" },
    { key: "pipeline", label: "In pipeline", value: stat.pipeline, hint: `${stat.pipelineRate}% of active`, icon: "fe fe-git-branch", tone: "indigo" },
    { key: "completed", label: "Completed", value: stat.completed, hint: `${stat.completionRate}% done`, icon: "fe fe-check-circle", tone: "teal" },
    { key: "overdue", label: "Overdue", value: stat.overdueCount, hint: "Needs attention", icon: "fe fe-alert-circle", tone: "rose" },
    { key: "favorites", label: "Favorites", value: stat.favorites, hint: "Starred projects", icon: "fe fe-star", tone: "amber" },
    { key: "poLinked", label: "PO linked", value: stat.poLinked, hint: "Under contract", icon: "fe fe-link", tone: "sky" },
  ];
}

function buildHighlights(stat) {
  return [
    { key: "tasks", label: "Avg task progress", value: stat.avgTaskPct, hint: "Completed vs total tasks", icon: "fe fe-check-square", tone: "teal", suffix: "%" },
    { key: "hours", label: "Hours utilization", value: stat.avgHoursPct, hint: "Actual vs estimated", icon: "fe fe-clock", tone: "indigo", suffix: "%" },
    { key: "shared", label: "Shared", value: stat.shared, hint: "Cross-team visibility", icon: "fe fe-share-2", tone: "sky" },
    { key: "dueSoon", label: "Due soon", value: stat.dueSoonCount, hint: "Next 14 days", icon: "fe fe-calendar", tone: "amber" },
  ];
}

function buildInsights(statusMix, timelineMix) {
  return [
    {
      key: "status",
      icon: "fe fe-activity",
      title: "Status mix",
      subtitle: "Where active projects sit in delivery",
      mix: statusMix,
      emptyLabel: "No status data",
    },
    {
      key: "timeline",
      icon: "fe fe-clock",
      title: "Timeline health",
      subtitle: "Open projects by due-date risk",
      mix: timelineMix,
      emptyLabel: "No open projects to assess",
    },
  ];
}

export function buildProjectSummaryStats(items, userTeams, options = {}) {
  const { createConfig } = options;

  if (!items || !items.length) {
    const empty = buildEmptyStats(userTeams);
    empty.kpis = buildKpis(empty);
    empty.highlights = buildHighlights(empty);
    empty.insights = buildInsights([], []);
    empty.estimateGaps = {
      serviceLineMode: resolveServiceLineEstimateEnabled(createConfig, []),
      items: [],
      total: 0,
    };
    return empty;
  }

  const all = items;
  const activeList = all.filter((item) => !item.archived && !item.deleted);
  const serviceLineEstimateMode = resolveServiceLineEstimateEnabled(createConfig, activeList);
  const archived = all.filter((item) => item.archived).length;
  const deleted = all.filter((item) => item.deleted).length;
  const pipeline = activeList.filter((item) => PIPELINE_STATUSES.includes(itemStatus(item))).length;
  const completed = activeList.filter((item) => itemStatus(item) === "COMPLETED").length;
  const closed = activeList.filter((item) => itemStatus(item) === "CLOSED").length;
  const favorites = activeList.filter((item) => item.favorite).length;
  const shared = activeList.filter((item) => item.shared).length;
  const poLinked = activeList.filter((item) => item.purchaseOrderId).length;
  const completionRate = activeList.length ? pct(completed, activeList.length) : 0;
  const pipelineRate = activeList.length ? pct(pipeline, activeList.length) : 0;

  const today = moment().startOf("day");
  const dueSoonEnd = today.clone().add(DUE_SOON_DAYS, "days");
  const trackable = activeList.filter((item) => !["COMPLETED", "CLOSED"].includes(itemStatus(item)));

  const timelineCounts = { OVERDUE: 0, DUE_SOON: 0, ON_TRACK: 0, NO_DATE: 0 };
  trackable.forEach((item) => {
    const bucket = classifyTimelineHealth(item, today, dueSoonEnd);
    timelineCounts[bucket] = (timelineCounts[bucket] || 0) + 1;
  });

  const statusCounts = {};
  const projectTypeCounts = {};
  const accountCounts = {};
  const teamCounts = {};
  const billingTypeCounts = {};
  const priorityCounts = {};
  const automationCounts = { ENABLED: 0, DISABLED: 0 };
  const complexityCounts = {};
  const capexCounts = {};
  const sharedCounts = { SHARED: 0, PRIVATE: 0 };
  const hoursEstimateCounts = { WITH_HOURS: 0, MISSING: 0 };

  activeList.forEach((item) => {
    const statusKey = itemStatus(item);
    statusCounts[statusKey] = (statusCounts[statusKey] || 0) + 1;
    const typeKey = item.projectType || "OTHER";
    projectTypeCounts[typeKey] = (projectTypeCounts[typeKey] || 0) + 1;
    const account = item.accountName || "Unassigned";
    accountCounts[account] = (accountCounts[account] || 0) + 1;
    const team = item.teamName || "No team";
    teamCounts[team] = (teamCounts[team] || 0) + 1;
    const billingKey = item.type || "UNSPECIFIED";
    billingTypeCounts[billingKey] = (billingTypeCounts[billingKey] || 0) + 1;
    const priorityKey = item.priority || "UNSPECIFIED";
    priorityCounts[priorityKey] = (priorityCounts[priorityKey] || 0) + 1;
    if (item.automationEnabled) automationCounts.ENABLED += 1;
    else automationCounts.DISABLED += 1;
    const complexityKey = item.complexity || "UNSPECIFIED";
    complexityCounts[complexityKey] = (complexityCounts[complexityKey] || 0) + 1;
    const capexKey = item.capexOpex || "UNSPECIFIED";
    capexCounts[capexKey] = (capexCounts[capexKey] || 0) + 1;
    if (item.shared) sharedCounts.SHARED += 1;
    else sharedCounts.PRIVATE += 1;
    if (hasNumericEstimate(item.estHours)) hoursEstimateCounts.WITH_HOURS += 1;
    else hoursEstimateCounts.MISSING += 1;
  });

  let taskPctSum = 0;
  let taskPctCount = 0;
  let hoursPctSum = 0;
  let hoursPctCount = 0;
  activeList.forEach((item) => {
    const total = Number(item.taskTotalCount) || 0;
    if (total > 0) {
      taskPctSum += Math.round(((Number(item.completedTaskCount) || 0) / total) * 100);
      taskPctCount += 1;
    }
    const est = Number(item.estHours) || 0;
    if (est > 0) {
      hoursPctSum += Math.min(100, Math.round(((Number(item.actualHours) || 0) / est) * 100));
      hoursPctCount += 1;
    }
  });

  const stageCounts = {
    newCount: statusCounts.NEW || 0,
    assignedCount: statusCounts.ASSIGNED || 0,
    inProgressCount: statusCounts.INPROGRESS || 0,
    completedCount: statusCounts.COMPLETED || 0,
  };

  const funnel = FUNNEL_STAGES.map((stage) => ({
    key: stage.toLowerCase(),
    label: STATUS_LABELS[stage],
    count: statusCounts[stage] || 0,
    tone: STATUS_TONES[stage],
  }));

  const stat = {
    total: all.length,
    active: activeList.length,
    archived,
    deleted,
    pipeline,
    completed,
    closed,
    favorites,
    shared,
    poLinked,
    completionRate,
    pipelineRate,
    avgTaskPct: taskPctCount ? Math.round(taskPctSum / taskPctCount) : 0,
    avgHoursPct: hoursPctCount ? Math.round(hoursPctSum / hoursPctCount) : 0,
    overdueCount: timelineCounts.OVERDUE,
    dueSoonCount: timelineCounts.DUE_SOON,
    selectedTeams: userTeams ? userTeams.filter((t) => t.isChecked).length : 0,
    statusMix: buildMixSegments(statusCounts, activeList.length),
    projectTypeMix: buildMixSegments(projectTypeCounts, activeList.length, PROJECT_TYPE_LABELS),
    accountMix: buildMixSegments(accountCounts, activeList.length, null),
    teamMix: buildMixSegments(teamCounts, activeList.length, null),
    timelineMix: buildMixSegments(timelineCounts, trackable.length || activeList.length, TIMELINE_LABELS, TIMELINE_TONES),
    createdTrend: buildCreatedTrend(activeList),
    funnel,
    outcomes: {
      open: pipeline,
      completed,
      closed,
      other: Math.max(activeList.length - pipeline - completed - closed, 0),
    },
    stageCounts,
    inProgressRate: activeList.length ? pct(stageCounts.inProgressCount, activeList.length) : 0,
    billingTypeMix: buildMixSegments(billingTypeCounts, activeList.length, BILLING_TYPE_LABELS),
    priorityMix: buildMixSegments(priorityCounts, activeList.length, PRIORITY_LABELS, {
      URGENT: "rose",
      HIGH: "amber",
      MEDIUM: "indigo",
      LOW: "slate",
      UNSPECIFIED: "slate",
    }),
    automationMix: buildMixSegments(automationCounts, activeList.length, {
      ENABLED: "Automation on",
      DISABLED: "Manual",
    }),
    sharedMix: buildMixSegments(sharedCounts, activeList.length, SHARED_LABELS, {
      SHARED: "sky",
      PRIVATE: "slate",
    }),
    complexityMix: buildMixSegments(complexityCounts, activeList.length, COMPLEXITY_LABELS, {
      BASIC: "green",
      MEDIUM: "amber",
      COMPLEX: "rose",
      UNSPECIFIED: "slate",
    }),
    capexMix: buildMixSegments(capexCounts, activeList.length, CAPEX_LABELS, {
      Capex: "indigo",
      Opex: "teal",
      UNSPECIFIED: "slate",
    }),
    hoursEstimateMix: buildMixSegments(hoursEstimateCounts, activeList.length, HOURS_ESTIMATE_LABELS, {
      WITH_HOURS: "green",
      MISSING: "amber",
    }),
  };

  const gapCandidates = activeList.filter((item) =>
    PIPELINE_STATUSES.includes(itemStatus(item))
  );
  const missingEstimateItems = gapCandidates
    .filter((item) =>
      serviceLineEstimateMode
        ? isMissingServiceLineEstimate(item)
        : isMissingProjectLevelEstimate(item)
    )
    .map(buildEstimateGapEntry)
    .sort((a, b) => a.name.localeCompare(b.name));

  stat.estimateGaps = {
    serviceLineMode: serviceLineEstimateMode,
    items: missingEstimateItems,
    total: missingEstimateItems.length,
    pipelineTotal: gapCandidates.length,
  };

  stat.kpis = buildKpis(stat);
  stat.highlights = buildHighlights(stat);
  stat.insights = buildInsights(stat.statusMix, stat.timelineMix);

  return stat;
}
