import React, { Component } from "react";
import { learningService } from "_services/learning/learning.service";
import LearningLuxPage, { LearningLuxPanel } from "views/learning/components/LearningLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class CompliancePage extends Component {
  state = { loading: true, loadError: null, rows: [] };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Learning compliance");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await learningService.complianceDue();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load compliance due"),
      });
    }
  };

  render() {
    const { loading, loadError, rows } = this.state;
    return (
      <LearningLuxPage
        testId="learning-compliance-page"
        dataSource={rows.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        pageMeta={{
          tone: "teal",
          icon: "fe fe-shield",
          eyebrow: "People · Learning",
          titleLead: "Compliance",
          titleAccent: "due",
          lede: "Assignments that are due or overdue for compliance tracking.",
        }}
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load compliance due">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        <LearningLuxPanel title="Compliance due / overdue" meta={`${rows.length} record${rows.length === 1 ? "" : "s"}`} icon="fe fe-alert-circle">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
          {!loading && rows.length === 0 ? (
            <LuxRegisterEmptyState
              title="Nothing due"
              description="No compliance assignments are currently due or overdue."
              showCreate={false}
            />
          ) : !loading ? (
            <div className="lux-module-table-wrap">
              <table className="table table-sm mb-0">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Course</th>
                    <th>Assignee</th>
                    <th>Due</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r) => (
                    <tr key={r.assignmentRef || r.id}>
                      <td>{r.assignmentRef}</td>
                      <td>{r.courseId}</td>
                      <td>
                        {r.assigneeType}:{r.assigneeId}
                      </td>
                      <td>{r.dueDate || "—"}</td>
                      <td>
                        <span className={`lux-learning-status is-${String(r.status || "due").toLowerCase()}`}>
                          {r.status || "Due"}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : null}
        </LearningLuxPanel>
      </LearningLuxPage>
    );
  }
}

export default CompliancePage;
