import { store } from '_helpers';
import { auditActions } from '_actions';
import { AUDIT_EMBEDDED_PAGE_SIZE, AUDIT_ENTITY_TYPES } from '_constants/audit.constants';
import { buildAuditScopeKey } from '_helpers/audit.utils';

/**
 * Reload timesheet audit panels after save/submit/approve so timelines are not stuck on the initial empty fetch.
 */
export function refreshTimesheetAuditPanels({
  weekId,
  actorUserId,
  pageSize = AUDIT_EMBEDDED_PAGE_SIZE,
} = {}) {
  const params = {
    page: 1,
    pageSize,
    entityType: AUDIT_ENTITY_TYPES.TIMESHEET_WEEK,
  };

  if (weekId != null && weekId !== '') {
    const weekScope = buildAuditScopeKey('entity', {
      entityType: AUDIT_ENTITY_TYPES.TIMESHEET_WEEK,
      entityId: weekId,
    });
    store.dispatch(auditActions.clearTimeline(weekScope));
    store.dispatch(auditActions.loadTimesheetWeekAudit(weekId, params));
  }

  if (actorUserId != null && actorUserId !== '') {
    const actorScope = buildAuditScopeKey('actor', { actorUserId });
    store.dispatch(auditActions.clearTimeline(actorScope));
    store.dispatch(auditActions.loadActorTimeline(actorUserId, params));
  }
}

export function resolveTimesheetAuditRefreshTargets(state, selectedEmployee) {
  const timeSheetRequest = state && state.timeSheetRequest;
  const employee = selectedEmployee || (state && state.selectedEmployee);
  return {
    weekId: timeSheetRequest && timeSheetRequest.weekId,
    actorUserId: employee && employee.id,
  };
}
