async function detachDocument(dossierRef, linkRef, body = {}) {
  try {
    const actor = withActor(body);
    const qs = `?userTeamId=${encodeURIComponent(actor.userTeamId)}&actorId=${encodeURIComponent(
      actor.actorId
    )}&pmOrComplianceOrHr=true`;
    const response = await axiosUtils.remove(
      `${urlConfig.DOSSIER_API_PATH}/${encodeURIComponent(dossierRef)}/links/${encodeURIComponent(
        linkRef
      )}${qs}`
    );
    const payload = response && response.payload != null ? response.payload : response;
    return payload ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

