import React, { Component } from "react";
import { getQuestionLayoutSpan } from "../../feedbackForm.utils";
import LuxFeedbackQuestionLabel from "./LuxFeedbackQuestionLabel";
import LuxFeedbackStarRating from "./LuxFeedbackStarRating";

class OverAllRating extends Component {
  onChange = (stars) => {
    this.props.onChange({ ...this.props.questionConfig, answer: stars });
  };

  render() {
    const { questionConfig, readonly } = this.props;
    if (!questionConfig) return null;
    const span = getQuestionLayoutSpan(questionConfig.type);

    return (
      <div className={`lux-fb-q lux-fb-q--${span}`}>
        <div className="lux-fb-q__card lux-fb-q__card--hero-rating">
          <LuxFeedbackQuestionLabel
            questionConfig={questionConfig}
            className="lux-fb-q__label--hero"
            as="h2"
          />
          <LuxFeedbackStarRating
            variant="hero"
            value={questionConfig.answer}
            readonly={readonly}
            onChange={this.onChange}
            ariaLabel={questionConfig.question}
          />
        </div>
      </div>
    );
  }
}
export default OverAllRating;
