const CHART_FONT = "Inter, system-ui, sans-serif";

export function buildUtilizationBarChart(utilizationRows, limit = 12) {
  const rows = (utilizationRows || []).slice(0, limit);
  return {
    type: "bar",
    height: 280,
    series: [{ name: "Utilization %", data: rows.map((r) => r.utilization) }],
    options: {
      chart: { toolbar: { show: false }, fontFamily: CHART_FONT },
      plotOptions: { bar: { borderRadius: 6, columnWidth: "55%" } },
      colors: ["#5b5ff4"],
      dataLabels: { enabled: false },
      xaxis: { categories: rows.map((r) => r.name), labels: { rotate: -35, trim: true, maxHeight: 72 } },
      yaxis: { max: 120, title: { text: "%" } },
      grid: { borderColor: "rgba(148,163,184,0.2)" },
      tooltip: { y: { formatter: (v) => `${v}%` } },
    },
  };
}

export function buildStatusDonutChart(statusCounts) {
  const labels = Object.keys(statusCounts || {});
  const series = labels.map((k) => statusCounts[k]);
  return {
    type: "donut",
    height: 260,
    series,
    options: {
      chart: { fontFamily: CHART_FONT },
      labels,
      legend: { position: "bottom" },
      colors: ["#3b82f6", "#f59e0b", "#10b981", "#64748b", "#8b5cf6", "#ea580c"],
      dataLabels: { enabled: true },
    },
  };
}

export function buildDailyLoadAreaChart(dailyAllocated) {
  const days = dailyAllocated || [];
  return {
    type: "area",
    height: 260,
    series: [
      { name: "Allocated (h)", data: days.map((d) => Math.round((d.allocated || 0) / 60)) },
      {
        name: "Capacity (h)",
        data: days.map((d) => Math.round((d.capacity || 0) / 60)),
      },
    ],
    options: {
      chart: { toolbar: { show: false }, fontFamily: CHART_FONT },
      stroke: { curve: "smooth", width: 2 },
      fill: { type: "gradient", gradient: { opacityFrom: 0.35, opacityTo: 0.05 } },
      colors: ["#14b8a6", "#94a3b8"],
      xaxis: { categories: days.map((d) => d.label) },
      yaxis: { title: { text: "Hours" } },
      grid: { borderColor: "rgba(148,163,184,0.2)" },
    },
  };
}

export function buildProjectEffortChart(projects, limit = 6) {
  const rows = (projects || []).slice(0, limit);
  const hours = rows.map((p) => Math.round((p.minutes || 0) / 60 * 10) / 10);
  return {
    type: "bar",
    height: 220,
    series: [{ name: "Planned hours", data: hours }],
    options: {
      chart: { toolbar: { show: false }, fontFamily: CHART_FONT },
      plotOptions: {
        bar: {
          horizontal: true,
          borderRadius: 8,
          barHeight: "62%",
          distributed: true,
        },
      },
      colors: ["#5b5ff4", "#6366f1", "#14b8a6", "#3b82f6", "#8b5cf6", "#64748b"],
      dataLabels: {
        enabled: true,
        formatter: (val) => `${val}h`,
        style: { fontSize: "11px", fontWeight: 600 },
      },
      xaxis: {
        categories: rows.map((p) => {
          const name = p.name || "Untitled";
          return name.length > 22 ? `${name.slice(0, 20)}…` : name;
        }),
      },
      yaxis: { labels: { maxWidth: 140 } },
      grid: { borderColor: "rgba(148,163,184,0.12)", padding: { left: 4, right: 12 } },
      legend: { show: false },
      tooltip: {
        y: {
          formatter: (val, opts) => {
            const row = rows[opts.dataPointIndex];
            if (!row) return `${val}h`;
            return `${val}h · ${row.sharePct != null ? row.sharePct : ""}% of horizon`;
          },
        },
      },
    },
  };
}

/** Compact charts for assign-work panel (narrow columns). */
export function buildAssignPanelDailyLoadChart(dailyAllocated) {
  const base = buildDailyLoadAreaChart(dailyAllocated);
  return {
    ...base,
    options: {
      ...base.options,
      legend: { show: true, position: "top", fontSize: "9px", markers: { width: 6, height: 6 } },
      xaxis: {
        ...base.options.xaxis,
        labels: { style: { fontSize: "9px" }, rotate: -45, hideOverlappingLabels: true },
      },
      yaxis: {
        ...base.options.yaxis,
        labels: { style: { fontSize: "9px" } },
        title: { text: "h", style: { fontSize: "9px" } },
      },
      grid: { ...base.options.grid, padding: { left: 4, right: 8, top: 0, bottom: 0 } },
    },
  };
}

export function buildAssignPanelStatusDonutChart(statusCounts) {
  const labels = Object.keys(statusCounts || {});
  const series = labels.map((k) => statusCounts[k]);
  return {
    type: "donut",
    series,
    options: {
      chart: { fontFamily: CHART_FONT, sparkline: { enabled: false } },
      labels,
      legend: { show: false },
      colors: ["#3b82f6", "#f59e0b", "#10b981", "#64748b", "#8b5cf6", "#ea580c"],
      dataLabels: { enabled: false },
      plotOptions: {
        pie: {
          donut: {
            size: "70%",
            labels: {
              show: true,
              name: { show: false },
              value: { show: true, fontSize: "11px", fontWeight: 700 },
              total: {
                show: true,
                label: "Items",
                fontSize: "9px",
                fontWeight: 600,
                color: "#64748b",
              },
            },
          },
        },
      },
      stroke: { width: 0 },
    },
  };
}

export function buildAssignPanelTaskTypeChart(taskTypeMinutes) {
  const toHours = (mins) => Math.round(((mins || 0) / 60) * 10) / 10;
  const billableH = toHours(taskTypeMinutes && taskTypeMinutes.billable);
  const nonBillableH = toHours(taskTypeMinutes && taskTypeMinutes.nonBillable);
  const leaveHolidayH = toHours(taskTypeMinutes && taskTypeMinutes.leaveHoliday);
  const series = [billableH, nonBillableH, leaveHolidayH];
  if (series.every((v) => v <= 0)) {
    return null;
  }
  return {
    type: "donut",
    series,
    options: {
      chart: { fontFamily: CHART_FONT, sparkline: { enabled: false } },
      labels: ["Billable", "Non billable", "Leave / holiday"],
      legend: { show: false },
      colors: ["#5b5ff4", "#64748b", "#a855f7"],
      dataLabels: { enabled: false },
      plotOptions: {
        pie: {
          donut: {
            size: "70%",
            labels: {
              show: true,
              name: { show: false },
              value: { show: true, fontSize: "10px", fontWeight: 700 },
              total: {
                show: true,
                label: "Hours",
                fontSize: "9px",
                fontWeight: 600,
                color: "#64748b",
              },
            },
          },
        },
      },
      stroke: { width: 0 },
      tooltip: {
        y: { formatter: (val) => `${val}h` },
      },
    },
  };
}

export function buildAssignPanelProjectChart(projects, limit = 4) {
  const base = buildProjectEffortChart(projects, limit);
  return {
    ...base,
    options: {
      ...base.options,
      dataLabels: {
        ...base.options.dataLabels,
        enabled: false,
      },
      xaxis: {
        ...base.options.xaxis,
        labels: { style: { fontSize: "9px" }, maxHeight: 48 },
      },
      yaxis: {
        ...base.options.yaxis,
        labels: { style: { fontSize: "9px" }, maxWidth: 72 },
      },
      grid: { ...base.options.grid, padding: { left: 0, right: 4, top: -8, bottom: -4 } },
    },
  };
}

export function buildHourlyLoadChart(categories, hoursData) {
  return {
    type: "bar",
    height: 200,
    series: [{ name: "Hours", data: hoursData || [] }],
    options: {
      chart: { toolbar: { show: false }, fontFamily: CHART_FONT, sparkline: { enabled: false } },
      plotOptions: { bar: { borderRadius: 6, columnWidth: "70%" } },
      colors: ["#5b5ff4"],
      dataLabels: { enabled: false },
      xaxis: { categories: categories || [] },
      yaxis: { max: 1.2, title: { text: "h" }, decimalsInFloat: 1 },
      grid: { borderColor: "rgba(148,163,184,0.15)" },
      tooltip: { y: { formatter: (v) => `${v}h` } },
    },
  };
}

export function buildFreeCapacityChart(utilizationRows) {
  const rows = (utilizationRows || [])
    .filter((r) => r.freeMinutes > 0)
    .sort((a, b) => b.freeMinutes - a.freeMinutes)
    .slice(0, 8);
  return {
    type: "bar",
    height: 240,
    series: [{ name: "Free time", data: rows.map((r) => Math.round(r.freeMinutes / 60)) }],
    options: {
      chart: { toolbar: { show: false }, fontFamily: CHART_FONT },
      plotOptions: { bar: { horizontal: true, borderRadius: 6 } },
      colors: ["#10b981"],
      xaxis: { categories: rows.map((r) => r.name) },
      dataLabels: { enabled: false },
      grid: { borderColor: "rgba(148,163,184,0.2)" },
    },
  };
}
