import React, { Component } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import {
  COMPETENCY_OPTIONS,
  FEEDBACK_TYPE_OPTIONS,
  GOAL_TYPE_OPTIONS,
} from "config/performance-management.config";
import { validateFeedbackPayload, validateGoalPayload } from "config/performance-management.utils";
import { PerformanceActionButton } from "views/performance/components/PerformanceLuxShared";

function DrawerShell({ open, title, subtitle, accent, icon, onClose, children, footer }) {
  if (!open) {
    return null;
  }
  return createPortal(
    <div className="lux-perf-drawer-backdrop" role="presentation" onClick={onClose}>
      <aside
        className={classNames("lux-perf-drawer", accent && `lux-perf-drawer--${accent}`)}
        role="dialog"
        aria-modal="true"
        aria-labelledby="lux-perf-drawer-title"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="lux-perf-drawer__ambient" aria-hidden="true">
          <span className="lux-perf-drawer__orb lux-perf-drawer__orb--a" />
          <span className="lux-perf-drawer__orb lux-perf-drawer__orb--b" />
        </div>
        <span className="lux-perf-drawer__accent" aria-hidden="true" />
        <header className="lux-perf-drawer__head">
          <div className="lux-perf-drawer__head-main">
            <span className="lux-perf-drawer__category-icon" aria-hidden="true">
              <i className={icon || "fe fe-award"} />
            </span>
            <div className="lux-perf-drawer__head-copy">
              <span className="lux-perf-drawer__eyebrow">{subtitle}</span>
              <h2 id="lux-perf-drawer-title">{title}</h2>
            </div>
          </div>
          <button type="button" className="lux-perf-drawer__close" onClick={onClose} aria-label="Close">
            <i className="fe fe-x" aria-hidden="true" />
          </button>
        </header>
        <div className="lux-perf-drawer__body">{children}</div>
        {footer ? <footer className="lux-perf-drawer__footer">{footer}</footer> : null}
      </aside>
    </div>,
    document.body
  );
}

function Field({ label, children }) {
  return (
    <label className="lux-perf-drawer__field">
      <span>{label}</span>
      {children}
    </label>
  );
}

export class GoalCreateDrawer extends Component {
  state = { title: "", ownerName: "", type: "individual", dueDate: "", errors: [] };

  handleSubmit = () => {
    const { cycles } = this.props;
    const activeCycle = cycles && cycles.find((row) => row.status === "active");
    const payload = {
      ...this.state,
      cycleId: activeCycle ? activeCycle.id : "",
    };
    const errors = validateGoalPayload(payload);
    if (errors.length) {
      this.setState({ errors });
      return;
    }
    this.props.onCreate(payload);
  };

  render() {
    const { open, onClose, busy, cycles } = this.props;
    const { title, ownerName, type, dueDate, errors } = this.state;
    const activeCycle = cycles && cycles.find((row) => row.status === "active");
    return (
      <DrawerShell
        open={open}
        title="Create goal"
        subtitle="Goals"
        accent="amber"
        icon="fe fe-target"
        onClose={onClose}
        footer={
          <>
            <PerformanceActionButton onClick={onClose}>Cancel</PerformanceActionButton>
            <PerformanceActionButton variant="primary" icon="fe fe-check" onClick={this.handleSubmit} disabled={busy}>
              Create goal
            </PerformanceActionButton>
          </>
        }
      >
        {errors.length ? <div className="lux-perf-drawer__alert">{errors.join(" ")}</div> : null}
        <section className="lux-perf-drawer__section">
          <Field label="Title">
            <input value={title} onChange={(e) => this.setState({ title: e.target.value })} />
          </Field>
          <Field label="Owner">
            <input value={ownerName} onChange={(e) => this.setState({ ownerName: e.target.value })} />
          </Field>
          <Field label="Type">
            <select value={type} onChange={(e) => this.setState({ type: e.target.value })}>
              {GOAL_TYPE_OPTIONS.map((opt) => (
                <option key={opt.id} value={opt.id}>{opt.label}</option>
              ))}
            </select>
          </Field>
          <Field label="Due date">
            <input type="date" value={dueDate} onChange={(e) => this.setState({ dueDate: e.target.value })} />
          </Field>
          {activeCycle ? (
            <p className="lux-perf-drawer__hint">Linked to {activeCycle.name}</p>
          ) : null}
        </section>
      </DrawerShell>
    );
  }
}

