export class GrowthPlanCreateDrawer extends Component {
  state = { employeeName: "", title: "", mentorName: "", dueDate: "", competencies: [] };

  toggleCompetency = (id) => {
    const { competencies } = this.state;
    const next = competencies.indexOf(id) === -1 ? competencies.concat([id]) : competencies.filter((row) => row !== id);
    this.setState({ competencies: next });
  };

  handleSubmit = () => {
    this.props.onCreate({ ...this.state });
  };

  render() {
    const { open, onClose, busy } = this.props;
    const { employeeName, title, mentorName, dueDate, competencies } = this.state;
    return (
      <DrawerShell
        open={open}
        title="Create growth plan"
        subtitle="Development"
        accent="rose"
        icon="fe fe-trending-up"
        onClose={onClose}
        footer={
          <>
            <PerformanceActionButton onClick={onClose}>Cancel</PerformanceActionButton>
            <PerformanceActionButton variant="primary" icon="fe fe-check" onClick={this.handleSubmit} disabled={busy}>
              Create plan
            </PerformanceActionButton>
          </>
        }
      >
        <section className="lux-perf-drawer__section">
          <Field label="Employee">
            <input value={employeeName} onChange={(e) => this.setState({ employeeName: e.target.value })} />
          </Field>
          <Field label="Plan title">
            <input value={title} onChange={(e) => this.setState({ title: e.target.value })} />
          </Field>
          <Field label="Mentor">
            <input value={mentorName} onChange={(e) => this.setState({ mentorName: e.target.value })} />
          </Field>
          <Field label="Target date">
            <input type="date" value={dueDate} onChange={(e) => this.setState({ dueDate: e.target.value })} />
          </Field>
          <div className="lux-perf-drawer__chips">
            {COMPETENCY_OPTIONS.map((opt) => (
              <button
                key={opt.id}
                type="button"
                className={classNames("lux-perf-drawer__chip", competencies.indexOf(opt.id) !== -1 && "is-selected")}
                onClick={() => this.toggleCompetency(opt.id)}
              >
                {opt.label}
              </button>
            ))}
          </div>
        </section>
      </DrawerShell>
    );
  }
}

export class OneOnOneCreateDrawer extends Component {
  state = { employeeName: "", managerName: "", meetingDate: "", summary: "", actionText: "" };

  handleSubmit = () => {
    const actionItems = this.state.actionText
      ? this.state.actionText.split("\n").map((row) => row.trim()).filter(Boolean)
      : [];
    this.props.onCreate({
      employeeName: this.state.employeeName,
      managerName: this.state.managerName,
      meetingDate: this.state.meetingDate,
      summary: this.state.summary,
      actionItems,
    });
  };

  render() {
    const { open, onClose, busy } = this.props;
    const { employeeName, managerName, meetingDate, summary, actionText } = this.state;
    return (
      <DrawerShell
        open={open}
        title="Record 1:1"
        subtitle="Manager notes"
        accent="cyan"
        icon="fe fe-users"
        onClose={onClose}
        footer={
          <>
            <PerformanceActionButton onClick={onClose}>Cancel</PerformanceActionButton>
            <PerformanceActionButton variant="primary" icon="fe fe-save" onClick={this.handleSubmit} disabled={busy}>
              Save note
            </PerformanceActionButton>
          </>
        }
      >
        <section className="lux-perf-drawer__section">
          <Field label="Employee">
            <input value={employeeName} onChange={(e) => this.setState({ employeeName: e.target.value })} />
          </Field>
          <Field label="Manager">
            <input value={managerName} onChange={(e) => this.setState({ managerName: e.target.value })} />
          </Field>
          <Field label="Meeting date">
            <input type="date" value={meetingDate} onChange={(e) => this.setState({ meetingDate: e.target.value })} />
          </Field>
          <Field label="Summary">
            <textarea rows={3} value={summary} onChange={(e) => this.setState({ summary: e.target.value })} />
          </Field>
          <Field label="Action items (one per line)">
            <textarea rows={3} value={actionText} onChange={(e) => this.setState({ actionText: e.target.value })} />
          </Field>
        </section>
      </DrawerShell>
    );
  }
}
