import originalMoment from "moment";
import { extendMoment } from "moment-range";
import dateUtils from "_helpers/date.utils";
import {
  buildTenureBuckets,
} from "../dashboard/employeeDashboard.utils";

const moment = extendMoment(originalMoment);

const EMP_TYPES = ["Permanent", "Contract", "Intern", "Consultant"];

function parseJoinMoment(val) {
  if (!val) return null;
  let m = moment(val, moment.ISO_8601, true);
  if (m.isValid()) return m;
  m = moment(val, dateUtils.CLIENT_DATE_FORMAT, true);
  if (m.isValid()) return m;
  m = moment(val);
  return m.isValid() ? m : null;
}

function toMix(label, count, total, tone, key) {
  return {
    key: key || label.toLowerCase().replace(/\s+/g, "-"),
    label,
    count,
    pct: total ? Math.round((count / total) * 100) : 0,
    tone,
  };
}

function buildInsights(employmentMix, genderMix) {
  return [
    {
      key: "employment",
      icon: "fe fe-briefcase",
      title: "Employment mix",
      subtitle: "How active employees are engaged",
      mix: employmentMix,
      emptyLabel: "No employment type data",
    },
    {
      key: "gender",
      icon: "fe fe-users",
      title: "Gender balance",
      subtitle: "Distribution among active employees",
      mix: genderMix,
      emptyLabel: "No gender data recorded",
    },
  ];
}

function buildKpis(stat) {
  return [
    {
      key: "active",
      label: "Active",
      value: stat.active,
      hint: `${stat.activeRate}% of roster`,
      icon: "fe fe-check-circle",
      tone: "green",
    },
    {
      key: "inactive",
      label: "Inactive",
      value: stat.inactive,
      hint: stat.inactive ? "Not currently active" : "Everyone active",
      icon: "fe fe-pause-circle",
      tone: "amber",
    },
    {
      key: "permanent",
      label: "Permanent",
      value: stat.fulltime,
      hint: "Full-time core team",
      icon: "fe fe-briefcase",
      tone: "blue",
    },
    {
      key: "contract",
      label: "Contract",
      value: stat.contract,
      hint: "Contract & flexible",
      icon: "fe fe-file-text",
      tone: "indigo",
    },
    {
      key: "intern",
      label: "Interns",
      value: stat.intern,
      hint: "Early-career pipeline",
      icon: "fe fe-award",
      tone: "teal",
    },
    {
      key: "new",
      label: "New (30d)",
      value: stat.newJoiners30,
      hint: "Recent joiners",
      icon: "fe fe-trending-up",
      tone: "rose",
    },
  ];
}

function buildHighlights(stat) {
  return [
    {
      key: "skills",
      label: "Skill coverage",
      value: stat.uniqueSkills,
      hint: "Distinct primary skills",
      icon: "fe fe-layers",
      tone: "sky",
    },
    {
      key: "teams",
      label: "Team spread",
      value: stat.uniqueTeams,
      hint: "Teams represented",
      icon: "fe fe-users",
      tone: "indigo",
    },
    {
      key: "joins",
      label: "Recent joins",
      value: stat.newJoiners30,
      hint: "Last 30 days",
      icon: "fe fe-user-plus",
      tone: "teal",
    },
    {
      key: "tenure",
      label: "Avg tenure",
      display: formatTenureShort(stat.avgTenureMonths),
      hint: "Among active employees",
      icon: "fe fe-clock",
      tone: "amber",
    },
  ];
}

function formatAvgTenure(months) {
  if (months == null || months < 0) return "—";
  const years = Math.floor(months / 12);
  const rem = months % 12;
  if (years === 0) return `${months} mo avg`;
  if (rem === 0) return `${years} yr${years > 1 ? "s" : ""} avg`;
  return `${years}y ${rem}m avg`;
}

function formatTenureShort(months) {
  if (months == null || months <= 0) return "—";
  const years = Math.floor(months / 12);
  const rem = months % 12;
  if (years === 0) return `${months} mo`;
  if (rem === 0) return `${years} yr${years > 1 ? "s" : ""}`;
  return `${years}y ${rem}m`;
}

export function buildEmployeeSummaryStats(items, userTeams) {
  const empty = {
    total: 0,
    active: 0,
    inactive: 0,
    deleted: 0,
    fulltime: 0,
    contract: 0,
    intern: 0,
    consultant: 0,
    otherType: 0,
    male: 0,
    female: 0,
    unspecifiedGender: 0,
    activeRate: 0,
    newJoiners30: 0,
    exits30: 0,
    uniqueSkills: 0,
    uniqueTeams: 0,
    selectedTeams: 0,
    avgTenureMonths: 0,
    avgTenureLabel: "—",
    employmentMix: [],
    genderMix: [],
    tenureBuckets: [],
    kpis: [],
    insights: [],
    highlights: [],
  };

  if (!items || !items.length) {
    if (userTeams && userTeams.length) {
      empty.selectedTeams = userTeams.filter((team) => team.isChecked).length;
    }
    empty.kpis = buildKpis(empty);
    empty.insights = buildInsights([], []);
    empty.highlights = buildHighlights(empty);
    return empty;
  }

  const all = items;
  const activeList = all.filter((employee) => employee.active && !employee.deleted);
  const inactive = all.filter((employee) => !employee.active && !employee.deleted).length;
  const deleted = all.filter((employee) => employee.deleted).length;
  const total = all.length;
  const active = activeList.length;

  const countByType = (type) =>
    activeList.filter((employee) => employee.empType === type).length;

  const fulltime = countByType("Permanent");
  const contract = countByType("Contract");
  const intern = countByType("Intern");
  const consultant = countByType("Consultant");
  const otherType = activeList.filter(
    (employee) => !EMP_TYPES.includes(employee.empType)
  ).length;

  const male = activeList.filter((employee) => employee.gender === "male").length;
  const female = activeList.filter((employee) => employee.gender === "female").length;
  const unspecifiedGender = Math.max(0, active - male - female);

  const cutoff = moment().subtract(30, "days").startOf("day");
  const newJoiners30 = activeList.filter((employee) => {
    const joinDate = parseJoinMoment(employee.dateOfJoin);
    return joinDate && joinDate.isSameOrAfter(cutoff);
  }).length;

  const exits30 = all.filter((employee) => {
    const exitDate = parseJoinMoment(employee.exitDate);
    return exitDate && exitDate.isSameOrAfter(cutoff);
  }).length;

  const skillSet = new Set(
    activeList.map((employee) => employee.primarySkill).filter(Boolean)
  );
  const teamSet = new Set(
    activeList.map((employee) => employee.userTeamId).filter((id) => id != null)
  );

  const selectedTeams =
    userTeams && userTeams.length
      ? userTeams.filter((team) => team.isChecked).length
      : 0;

  const now = moment();
  const tenureMonthsList = activeList
    .map((employee) => {
      const join = parseJoinMoment(employee.dateOfJoin);
      return join ? now.diff(join, "months") : null;
    })
    .filter((months) => months != null && months >= 0);
  const avgTenureMonths = tenureMonthsList.length
    ? Math.round(
        tenureMonthsList.reduce((sum, months) => sum + months, 0) / tenureMonthsList.length
      )
    : 0;

  const employmentMix = [
    toMix("Permanent", fulltime, active, "blue"),
    toMix("Contract", contract, active, "amber"),
    toMix("Intern", intern, active, "teal"),
    toMix("Consultant", consultant, active, "violet"),
  ];
  if (otherType > 0) {
    employmentMix.push(toMix("Other", otherType, active, "slate"));
  }

  const genderMix = [
    toMix("Male", male, active, "blue"),
    toMix("Female", female, active, "rose"),
  ];
  if (unspecifiedGender > 0) {
    genderMix.push(toMix("Unspecified", unspecifiedGender, active, "slate"));
  }

  const tenureBuckets = buildTenureBuckets(activeList).map((bucket, index) => ({
    ...bucket,
    key: ["lt1", "1-3", "3-5", "5plus"][index] || bucket.label,
    tone: ["sky", "indigo", "teal", "amber"][index] || "slate",
  }));

  const stat = {
    total,
    active,
    inactive,
    deleted,
    fulltime,
    contract,
    intern,
    consultant,
    otherType,
    male,
    female,
    unspecifiedGender,
    activeRate: total ? Math.round((active / total) * 100) : 0,
    newJoiners30,
    exits30,
    uniqueSkills: skillSet.size,
    uniqueTeams: teamSet.size,
    selectedTeams,
    avgTenureMonths,
    avgTenureLabel: formatAvgTenure(avgTenureMonths),
    employmentMix: employmentMix.filter((entry) => entry.count > 0),
    genderMix: genderMix.filter((entry) => entry.count > 0),
    tenureBuckets,
  };

  stat.kpis = buildKpis(stat);
  stat.insights = buildInsights(stat.employmentMix, stat.genderMix);
  stat.highlights = buildHighlights(stat);

  return stat;
}
