/** F28 — Knowledge, RCA and lessons learned (live API only; no mock/demo). */

export function isKnowledgeRcaEnabled() {
  return shouldUseKnowledgeRca() || envconfig.USE_KNOWLEDGE_RCA_API === true;
}

export function shouldUseKnowledgeRcaApi() {
  return envconfig.USE_KNOWLEDGE_RCA_API !== false;
}

