import { axiosUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUsePerformanceManagementApi } from "config/performance-management.config";

import { apiErrorResult } from "config/mock-fallback.utils";

export const performanceManagementService = {
  getOverview,
  listGoals,
  createGoal,
  updateGoal,
  listReviewCycles,
  createReviewCycle,
  listReviews,
  submitSelfReview,
  submitManagerReview,
  getEmployeePerformanceSnapshot,
  listFeedback,
  createFeedback,
  listOneOnOnes,
  createOneOnOne,
  listGrowthPlans,
  createGrowthPlan,
  getCalibrationBoard,
  getPerformanceAnalytics,
  getAiEvidenceSummary,
};

async function getOverview(filters) {
  if (!shouldUsePerformanceManagementApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(`${urlConfig.PERFORMANCE_MANAGEMENT_API_PATH}/overview`, filters);
  return { payload: (response && response.payload) || response, source: "api" };
}

async function listGoals(filters) {
  if (!shouldUsePerformanceManagementApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(`${urlConfig.PERFORMANCE_MANAGEMENT_API_PATH}/goals`, filters);
  return { payload: (response && response.payload) || response || [], source: "api" };
}

async function createGoal(payload) {
  if (!shouldUsePerformanceManagementApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.post(`${urlConfig.PERFORMANCE_MANAGEMENT_API_PATH}/goals`, payload);
  return { payload: (response && response.payload) || response, source: "api" };
}

async function updateGoal(goalId, payload) {
  if (!shouldUsePerformanceManagementApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.put(
    `${urlConfig.PERFORMANCE_MANAGEMENT_API_PATH}/goals/${goalId}`,
    payload
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

