import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isFinanceIntelligenceEnabled } from "config/finance-intelligence.config";
import { FINANCE_HUB_META } from "config/finance-intelligence-nav.config";
import { financeIntelligenceService } from "_services/financeIntelligence.service";
import FinanceLuxPage, {
  FinanceActionButton,
  FinanceInsightPanel,
  FinanceLuxPanel,
} from "views/finance/components/FinanceLuxShared";
import FinanceLoadAlert from "views/finance/components/FinanceLoadAlert";
import FinanceChartStrip from "views/finance/components/FinanceChartStrip";
import InvoiceRecommendationsPanel from "views/finance/components/InvoiceRecommendationsPanel";
import { shouldHideRegisterOnLoadError } from "_helpers/registerListError.utils";

class FinanceDashboardPage extends Component {
  state = {
    loading: true,
    loadError: null,
    exporting: false,
    busyRecId: null,
    dataSource: null,
    kpiCards: [],
    insights: [],
    chartSeries: [],
    pendingRecommendations: [],
    openLeakage: [],
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Finance dashboard");
    }
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const [dashboardResult, recsResult] = await Promise.all([
        financeIntelligenceService.getFinanceDashboardOverview(),
        financeIntelligenceService.listInvoiceRecommendations({ status: "PENDING" }),
      ]);
      const overview = dashboardResult.payload || {};
      this.setState({
        loading: false,
        kpiCards: overview.kpiCards || [],
        insights: overview.insights || [],
        chartSeries: overview.chartSeries || [],
        pendingRecommendations: recsResult.payload || overview.pendingRecommendations || [],
        openLeakage: overview.openLeakage || [],
        dataSource: dashboardResult.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: error,
      });
    }
  };

  handleExportPack = async () => {
    this.setState({ exporting: true });
    try {
      const result = await financeIntelligenceService.exportFinancePack();
      const blob = new Blob([result.payload || ""], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = result.filename || "finance-pack.csv";
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      this.setState({ loadError: error });
    } finally {
      this.setState({ exporting: false });
    }
  };

  handleApproveRec = async (recommendationId) => {
    this.setState({ busyRecId: recommendationId });
    try {
      await financeIntelligenceService.approveInvoiceRecommendation(recommendationId);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: error });
    } finally {
      this.setState({ busyRecId: null });
    }
  };

  handleDismissRec = async (recommendationId) => {
    this.setState({ busyRecId: recommendationId });
    try {
      await financeIntelligenceService.dismissInvoiceRecommendation(recommendationId);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: error });
    } finally {
      this.setState({ busyRecId: null });
    }
  };

  render() {
    if (!isFinanceIntelligenceEnabled()) {
      return <PersonaAccessDenied featureLabel="Finance dashboard" />;
    }

    const {
      loading,
      loadError,
      exporting,
      busyRecId,
      dataSource,
      kpiCards,
      insights,
      chartSeries,
      pendingRecommendations,
      openLeakage,
    } = this.state;
    const hideBody = shouldHideRegisterOnLoadError(loadError, kpiCards);

    return (
      <FinanceLuxPage
        pageMeta={FINANCE_HUB_META}
        dataSource={dataSource}
        demoLabel="Demo finance hub"
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <FinanceActionButton
              icon="fe fe-download"
              variant="ghost"
              onClick={this.handleExportPack}
              disabled={exporting}
            >
              {exporting ? "Exporting…" : "Export pack"}
            </FinanceActionButton>
            <FinanceActionButton to="/analytics/finance" icon="fe fe-trending-up" variant="ghost">
              Financial analytics
            </FinanceActionButton>
            <FinanceActionButton to="/finance/invoice" icon="fe fe-credit-card" variant="primary">
              Invoices
            </FinanceActionButton>
          </>
        }
      >
        <FinanceLoadAlert
          error={loadError}
          fallback="Unable to load finance dashboard."
          onDismiss={() => this.setState({ loadError: null })}
        />

        {hideBody ? null : (
        <>
        <FinanceInsightPanel insights={insights} />

        <FinanceLuxPanel
          title="Revenue forecast trend"
          meta="/T5 — cost vs revenue margin by month"
          icon="fe fe-bar-chart-2"
          accent="green"
        >
          <FinanceChartStrip series={chartSeries} loading={loading} />
        </FinanceLuxPanel>

        <FinanceLuxPanel
          title="Invoice recommendations"
          meta="Billing Advice Agent workflow"
          icon="fe fe-zap"
          accent="violet"
        >
          <InvoiceRecommendationsPanel
            recommendations={pendingRecommendations}
            loading={loading}
            onApprove={this.handleApproveRec}
            onDismiss={this.handleDismissRec}
            busyId={busyRecId}
          />
        </FinanceLuxPanel>

        <FinanceLuxPanel
          title="Open revenue leakage"
          meta={`${openLeakage.length} open flag${openLeakage.length !== 1 ? "s" : ""}`}
          icon="fe fe-shield"
          accent="rose"
          actions={
            <FinanceActionButton to="/finance/revenue-leakage" icon="fe fe-arrow-right" variant="ghost">
              Leakage dashboard
            </FinanceActionButton>
          }
        >
          {openLeakage.length ? (
            <ul className="lux-finance-dash-list">
              {openLeakage.map((row) => (
                <li key={row.id}>
                  <strong>{row.projectName}</strong>
                  <span>
                    {row.severity} · {row.leakageType.replace(/_/g, " ").toLowerCase()}
                  </span>
                  <p>{row.recommendation}</p>
                </li>
              ))}
            </ul>
          ) : (
            <p className="lux-finance-lux__lede">No open leakage flags in the current finance scope.</p>
          )}
        </FinanceLuxPanel>
        </>
        )}
      </FinanceLuxPage>
    );
  }
}

export default FinanceDashboardPage;
