import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { FINANCE_BILLING_STATUSES, FINANCE_MARGIN_BANDS } from "config/finance-intelligence.config";
import { formatFinancePct, formatFinanceUsd } from "config/finance-intelligence.utils";

const MARGIN_TONE = {
  [FINANCE_MARGIN_BANDS.HEALTHY]: "green",
  [FINANCE_MARGIN_BANDS.WATCH]: "amber",
  [FINANCE_MARGIN_BANDS.CRITICAL]: "rose",
};

const BILLING_TONE = {
  [FINANCE_BILLING_STATUSES.CURRENT]: "green",
  [FINANCE_BILLING_STATUSES.PARTIAL]: "amber",
  [FINANCE_BILLING_STATUSES.OVERDUE]: "rose",
  [FINANCE_BILLING_STATUSES.READY]: "blue",
};

export default function ProjectFinancialsRegister({ rows = [], loading }) {
  if (loading) {
    return <div className="lux-finance-register__skeleton" aria-busy="true" />;
  }

  if (!rows.length) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact"
        title="No project financial snapshots"
        description="Adjust filters or expand the finance scope to see margin and billing roll-ups."
      />
    );
  }

  return (
    <div className="lux-finance-register-wrap">
      <table className="lux-portfolio-register lux-finance-register">
        <thead>
          <tr>
            <th>Project</th>
            <th>Program</th>
            <th>Margin</th>
            <th>Revenue</th>
            <th>Cost</th>
            <th>Unbilled</th>
            <th>PO burn</th>
            <th>Billing</th>
            <th>Readiness</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const masked = row.masked === true;
            return (
              <tr key={row.id || row.projectId} className="lux-portfolio-register__row">
                <td>
                  <div className="lux-portfolio-register__primary">
                    <strong>{row.projectName}</strong>
                    <small>{row.projectCode}</small>
                    {row.ownerName ? <span>{row.ownerName}</span> : null}
                  </div>
                </td>
                <td>{row.programName || "—"}</td>
                <td>
                  <strong>{formatFinancePct(row.marginPct, masked)}</strong>
                  {row.marginBand ? (
                    <span className={classNames("lux-portfolio-badge", `is-${MARGIN_TONE[row.marginBand] || "slate"}`)}>
                      {row.marginBand}
                    </span>
                  ) : null}
                </td>
                <td>{formatFinanceUsd(row.revenueUsd, masked)}</td>
                <td>{formatFinanceUsd(row.costUsd, masked)}</td>
                <td>{formatFinanceUsd(row.unbilledUsd, masked)}</td>
                <td>{row.poBurnPct != null ? `${row.poBurnPct}%` : "—"}</td>
                <td>
                  <span className={classNames("lux-portfolio-badge", `is-${BILLING_TONE[row.billingStatus] || "slate"}`)}>
                    {row.billingStatus || "—"}
                  </span>
                  {row.collectionPct != null ? <small>{row.collectionPct}% collected</small> : null}
                </td>
                <td>{row.billingReadinessPct != null ? `${row.billingReadinessPct}%` : "—"}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <p className="lux-finance-register__foot">
        Drill into{" "}
        <Link to="/finance/purchaseorders">purchase orders</Link>,{" "}
        <Link to="/finance/invoice">invoices</Link>, or{" "}
        <Link to="/analytics/finance">financial analytics</Link>.
      </p>
    </div>
  );
}
