import React, { Component } from "react";
import { createPortal } from "react-dom";
import { connect } from "react-redux";
import classNames from "classnames/bind";
import { store } from "_helpers";
import { checklistConstants } from "_constants";
import { commonUtils } from "_helpers";
import { accessUtils } from "_helpers";
import { checklistActions } from "_actions";
import QuestionaireTable from "./QuestionaireTable";
import ItemNotFoundSection from "../ItemsNotFoundSection";
import ChecklistChangeModal from "../modal/ChecklistChangeModal";
import {
    getDefaultChecklistData,
    getChecklistProgress,
    getChecklistStatusLabel,
    formatChecklistAnswer,
    validateMandatoryAnswers,
    isQuestionAnswered,
} from "./checklist.utils";

class ItemChecklistInput extends Component {
    constructor() {
        super();
        this.state = {
            hasFormError: false,
            showEditor: false,
            showChangeModal: false,
            draftChecklistData: null,
            selectedChecklist: null,
            changeButtonEnabled: false,
            showAllPreview: false,
            permission: accessUtils.getChecklistAccessControl(),
        };
    }

    componentDidMount() {
        if (this.props.isSidebar) {
            this.initDraftFromProps();
        }
    }

    componentDidUpdate(prevProps) {
        if (this.props.isSidebar && prevProps.checklistData !== this.props.checklistData) {
            this.initDraftFromProps();
        }
        if (!this.state.showEditor && prevProps.checklistData !== this.props.checklistData) {
            this.setState({ hasFormError: false });
        }
    }

    initDraftFromProps = () => {
        const data = this.props.checklistData;
        this.setState({
            draftChecklistData: data ? JSON.parse(JSON.stringify(data)) : getDefaultChecklistData(),
        });
    };

    cloneChecklistData = (data) => (data ? JSON.parse(JSON.stringify(data)) : getDefaultChecklistData());

    getDisplayData = () => this.props.checklistData || getDefaultChecklistData();

    getDraftData = () => this.state.draftChecklistData || this.getDisplayData();

    onShowChecklistConfig = () => {
        store.dispatch({ type: checklistConstants.SHOW_CHECKLIST_CONFIGURE_WINDOW });
    };

    openEditor = () => {
        this.setState({
            showEditor: true,
            draftChecklistData: this.cloneChecklistData(this.props.checklistData),
            hasFormError: false,
        });
    };

    closeEditor = () => {
        this.setState({
            showEditor: false,
            draftChecklistData: null,
            showChangeModal: false,
            selectedChecklist: null,
            changeButtonEnabled: false,
            hasFormError: false,
        });
    };

    openChangeModal = () => {
        store.dispatch(this.props.getAllChecklists({
            itemType: this.props.type,
            userTeamId: this.props.itemUserTeamId,
        }));
        this.setState({ showChangeModal: true });
    };

    onChangeChecklistSelection = (selectedChecklist) => {
        this.setState({
            selectedChecklist,
            changeButtonEnabled: !!selectedChecklist,
        });
    };

    applyChecklistTemplate = () => {
        const { selectedChecklist } = this.state;
        if (!selectedChecklist) return;

        this.setState({
            draftChecklistData: {
                metaData: {
                    complete: false,
                    active: true,
                    lastModifiedBy: commonUtils.getCurrentUserId(),
                },
                questionDataList: selectedChecklist.questionDataList,
            },
            showChangeModal: false,
            selectedChecklist: null,
            changeButtonEnabled: false,
        });
    };

    onQuestionsDataChange = (name, questionDataList) => {
        this.setState((prev) => ({
            hasFormError: false,
            draftChecklistData: {
                ...prev.draftChecklistData,
                [name]: questionDataList,
            },
        }));
    };

    onClearFormError = () => {
        this.setState({ hasFormError: false });
    };

    canUpdate = (data) => {
        const { permission, readOnly } = this.props;
        if (readOnly || !data || !data.questionDataList) return false;
        return (permission.checklistSaveEnabled && data.metaData.complete === false)
            || (permission.checklistUpdateCompletedEnabled && data.metaData.complete === true);
    };

    handleUpdateChecklist = () => {
        this.props.handleUpdateChecklist(this.getDraftData());
        if (this.props.isSidebar) {
            this.initDraftFromProps();
        } else {
            this.closeEditor();
        }
    };

    handleCompleteChecklist = () => {
        const draft = this.getDraftData();
        if (!validateMandatoryAnswers(draft)) {
            this.setState({ hasFormError: true });
            return;
        }

        const completed = {
            ...draft,
            metaData: {
                ...draft.metaData,
                complete: true,
                active: true,
                lastModifiedBy: commonUtils.getCurrentUserId(),
            },
        };

        this.setState({ draftChecklistData: completed }, () => {
            this.props.handleUpdateChecklist(completed);
            if (!this.props.isSidebar) {
                this.closeEditor();
            }
        });
    };

    renderProgressRing = (percent, complete) => (
        <div className={`pd-checklist__ring${complete ? " is-complete" : ""}`}>
            <svg viewBox="0 0 36 36" aria-hidden="true">
                <path
                    className="pd-checklist__ring-bg"
                    d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831"
                />
                <path
                    className="pd-checklist__ring-fill"
                    strokeDasharray={`${percent}, 100`}
                    d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831"
                />
            </svg>
            <span className="pd-checklist__ring-label">{percent}%</span>
        </div>
    );

    renderChangeModal = () => (
        <ChecklistChangeModal
            show={this.state.showChangeModal}
            selectedChecklist={this.state.selectedChecklist}
            changeButtonEnabled={this.state.changeButtonEnabled}
            onSelect={this.onChangeChecklistSelection}
            onApply={this.applyChecklistTemplate}
            onClose={() => this.setState({ showChangeModal: false, selectedChecklist: null, changeButtonEnabled: false })}
            onResetSelection={() => this.setState({ selectedChecklist: null, changeButtonEnabled: false })}
        />
    );

    renderSummary = () => {
        const data = this.getDisplayData();
        const progress = getChecklistProgress(data);
        const statusLabel = getChecklistStatusLabel(progress);
        const { readOnly, permission } = this.props;
        const questions = data.questionDataList || [];
        const previewLimit = this.state.showAllPreview ? questions.length : 5;
        const previewQuestions = questions.slice(0, previewLimit);
        const canEdit = !readOnly && this.canUpdate(data);
        const primaryActionLabel = progress.complete
            ? "View"
            : canEdit
                ? "Continue"
                : progress.hasChecklist
                    ? "View"
                    : "Start";

        return (
            <article
                className={classNames("pd-checklist", "lux-checklist-panel", {
                    [`is-${progress.status}`]: true,
                })}
            >
                <header className="pd-checklist__head">
                    <span className="pd-checklist__icon" aria-hidden="true">
                        <i className="fe fe-check-square" />
                    </span>
                    <div className="pd-checklist__titles">
                        <h2 className="pd-checklist__title">Checklist</h2>
                        <p className="pd-checklist__subtitle">
                            Quality questions for this project
                        </p>
                    </div>
                    {!readOnly && (
                        <button
                            type="button"
                            className="lux-estimate-btn lux-estimate-btn--primary lux-estimate-btn--sm"
                            onClick={this.openEditor}
                        >
                            <i className={`fe ${progress.hasChecklist ? "fe-edit-2" : "fe-plus"}`} />
                            {primaryActionLabel}
                        </button>
                    )}
                    {readOnly && progress.hasChecklist && (
                        <button
                            type="button"
                            className="lux-estimate-btn lux-estimate-btn--ghost lux-estimate-btn--sm"
                            onClick={this.openEditor}
                        >
                            View
                        </button>
                    )}
                </header>

                {progress.hasChecklist ? (
                    <>
                        <div className="pd-checklist__hero">
                            <div className="pd-checklist__hero-top">
                                {this.renderProgressRing(progress.percent, progress.complete)}
                                <div className="pd-checklist__hero-copy">
                                    <span
                                        className={classNames(
                                            "pd-checklist__status-badge",
                                            progress.complete && "is-complete",
                                            progress.status === "ready" && "is-ready",
                                            progress.status === "progress" && "is-progress"
                                        )}
                                    >
                                        {statusLabel}
                                    </span>
                                    <strong>
                                        {progress.answered} of {progress.total} answered
                                    </strong>
                                    <span>
                                        {progress.remaining === 0
                                            ? "All items have answers"
                                            : `${progress.remaining} remaining`}
                                        {progress.mandatoryTotal > 0
                                            ? ` · ${progress.mandatoryAnswered}/${progress.mandatoryTotal} required`
                                            : ""}
                                    </span>
                                </div>
                            </div>
                            <div
                                className="pd-checklist__bar"
                                role="progressbar"
                                aria-valuenow={progress.percent}
                                aria-valuemin={0}
                                aria-valuemax={100}
                                aria-label="Checklist completion"
                            >
                                <span style={{ width: `${progress.percent}%` }} />
                            </div>
                            <div className="pd-checklist__kpi-row">
                                <div className="pd-checklist__kpi">
                                    <span>Done</span>
                                    <strong>{progress.answered}</strong>
                                </div>
                                <div className="pd-checklist__kpi is-muted">
                                    <span>Left</span>
                                    <strong>{progress.remaining}</strong>
                                </div>
                                <div className="pd-checklist__kpi is-req">
                                    <span>Required</span>
                                    <strong>
                                        {progress.mandatoryAnswered}/{progress.mandatoryTotal || 0}
                                    </strong>
                                </div>
                            </div>
                        </div>

                        <section className="pd-checklist__list-wrap" aria-label="Checklist items">
                            <header className="pd-checklist__list-head">
                                <strong>Items</strong>
                                <span>
                                    Showing {previewQuestions.length} of {progress.total}
                                </span>
                            </header>
                            <ul className="pd-checklist__preview">
                                {previewQuestions.map((q, index) => {
                                    const done = isQuestionAnswered(q);
                                    return (
                                        <li
                                            key={q.id || `${q.question}-${index}`}
                                            className={classNames("pd-checklist__preview-item", {
                                                "is-done": done,
                                                "is-required": q.mandatory,
                                            })}
                                        >
                                            <span className="pd-checklist__preview-mark" aria-hidden="true">
                                                <i className={`fe ${done ? "fe-check" : "fe-circle"}`} />
                                            </span>
                                            <div className="pd-checklist__preview-body">
                                                <div className="pd-checklist__preview-top">
                                                    <span className="pd-checklist__preview-q">
                                                        {q.question || "Untitled question"}
                                                    </span>
                                                    {q.mandatory && (
                                                        <em className="pd-checklist__req-tag">Required</em>
                                                    )}
                                                </div>
                                                <span
                                                    className={classNames("pd-checklist__preview-a", {
                                                        "is-empty": !done,
                                                    })}
                                                >
                                                    {done ? formatChecklistAnswer(q) : "Not answered yet"}
                                                </span>
                                            </div>
                                        </li>
                                    );
                                })}
                            </ul>
                            {progress.total > 5 && (
                                <button
                                    type="button"
                                    className="pd-checklist__more"
                                    onClick={() =>
                                        this.setState((prev) => ({
                                            showAllPreview: !prev.showAllPreview,
                                        }))
                                    }
                                >
                                    {this.state.showAllPreview
                                        ? "Show fewer items"
                                        : `Show all ${progress.total} items`}
                                </button>
                            )}
                        </section>
                    </>
                ) : (
                    <div className="pd-checklist__empty">
                        <span className="pd-checklist__empty-icon" aria-hidden="true">
                            <i className="fe fe-clipboard" />
                        </span>
                        <strong>No checklist yet</strong>
                        <p>Attach a template to track delivery quality questions on this project.</p>
                        {!readOnly && (
                            <button
                                type="button"
                                className="lux-estimate-btn lux-estimate-btn--ghost"
                                onClick={this.openEditor}
                            >
                                Attach checklist
                            </button>
                        )}
                    </div>
                )}

                {permission.viewEnabled && !readOnly && (
                    <button
                        type="button"
                        className="pd-checklist__configure"
                        onClick={this.onShowChecklistConfig}
                    >
                        <i className="fe fe-settings" /> Configure templates
                    </button>
                )}
            </article>
        );
    };

    renderEditorBody = () => {
        const draft = this.getDraftData();
        const updateEnabled = this.canUpdate(draft);
        const progress = getChecklistProgress(draft);
        const statusLabel = getChecklistStatusLabel(progress);

        return (
            <>
                <div className="lux-checklist-editor__status">
                    {this.renderProgressRing(progress.percent, progress.complete)}
                    <div>
                        <span
                            className={classNames(
                                "pd-checklist__status-badge",
                                progress.complete && "is-complete",
                                progress.status === "ready" && "is-ready",
                                progress.status === "progress" && "is-progress"
                            )}
                        >
                            {statusLabel}
                        </span>
                        <p className="lux-checklist-editor__status-copy">
                            {progress.answered} of {progress.total} answered
                            {progress.mandatoryTotal > 0 &&
                                ` · ${progress.mandatoryAnswered}/${progress.mandatoryTotal} required`}
                        </p>
                        <div
                            className="pd-checklist__bar pd-checklist__bar--editor"
                            role="progressbar"
                            aria-valuenow={progress.percent}
                            aria-valuemin={0}
                            aria-valuemax={100}
                        >
                            <span style={{ width: `${progress.percent}%` }} />
                        </div>
                    </div>
                </div>

                {!this.props.readOnly && this.props.permission.checklistChangeEnabled && (
                    <button
                        type="button"
                        className="lux-checklist-change-btn"
                        onClick={this.openChangeModal}
                    >
                        <i className="fe fe-repeat" /> Change checklist template
                    </button>
                )}

                <div className="lux-checklist-questions">
                    <QuestionaireTable
                        dragMode={false}
                        editMode={false}
                        configureMode={false}
                        readOnly={!updateEnabled}
                        onChange={this.onQuestionsDataChange}
                        questionDataList={draft.questionDataList}
                    />
                    {this.props.isSidebar && (
                        <ItemNotFoundSection
                            items={draft.questionDataList}
                            imgurl="no_checklist.png"
                            text="Checklist not added?"
                            description="Try attaching a checklist..."
                        />
                    )}
                </div>

                {this.state.hasFormError && (
                    <div className="lux-checklist-editor__error">
                        <i className="fe fe-alert-triangle" />
                        Please complete all required fields before marking as complete.
                        <button type="button" className="link ml-2" onClick={this.onClearFormError}>
                            Dismiss
                        </button>
                    </div>
                )}
            </>
        );
    };

    renderEditorSidebar = () => {
        if (!this.state.showEditor) return null;

        const draft = this.getDraftData();
        const updateEnabled = this.canUpdate(draft);
        const progress = getChecklistProgress(draft);

        const panel = (
            <>
                <button
                    type="button"
                    className="lux-checklist-sidebar__backdrop"
                    aria-label="Close checklist"
                    onClick={this.closeEditor}
                />
                <aside
                    className="right_sidebar lux-checklist-sidebar open"
                    role="dialog"
                    aria-modal="true"
                    aria-label="Project checklist"
                >
                    <div className="lux-checklist-sidebar__shell">
                        <header className="lux-checklist-sidebar__head">
                            <div className="lux-checklist-sidebar__head-copy">
                                <span className="lux-checklist-sidebar__kicker">
                                    Quality &amp; compliance
                                </span>
                                <h2 className="lux-checklist-sidebar__title">Project checklist</h2>
                                <p className="lux-checklist-sidebar__subtitle">
                                    Answer delivery questions, save progress, and mark the checklist
                                    complete when ready.
                                </p>
                            </div>
                            <button
                                type="button"
                                className="lux-checklist-sidebar__close"
                                onClick={this.closeEditor}
                                aria-label="Close"
                            >
                                <i className="fe fe-x" />
                            </button>
                        </header>

                        <div className="lux-checklist-sidebar__summary">
                            <div className="lux-checklist-sidebar__summary-kpi">
                                <span>Answered</span>
                                <strong>
                                    {progress.answered}/{progress.total || 0}
                                </strong>
                            </div>
                            <div className="lux-checklist-sidebar__summary-kpi">
                                <span>Remaining</span>
                                <strong>{progress.remaining}</strong>
                            </div>
                            <div
                                className={classNames("lux-checklist-sidebar__summary-kpi", {
                                    "is-primary": !progress.complete,
                                    "is-complete": progress.complete,
                                })}
                            >
                                <span>Progress</span>
                                <strong>{progress.percent}%</strong>
                            </div>
                        </div>

                        <div className="lux-checklist-sidebar__body">
                            {this.renderEditorBody()}
                        </div>

                        <footer className="lux-checklist-sidebar__foot">
                            <button
                                type="button"
                                className="lux-estimate-btn lux-estimate-btn--ghost"
                                onClick={this.closeEditor}
                            >
                                Close
                            </button>
                            {updateEnabled && (
                                <button
                                    type="button"
                                    className="lux-estimate-btn lux-estimate-btn--primary"
                                    onClick={this.handleUpdateChecklist}
                                >
                                    <i className="fe fe-save" /> Save progress
                                </button>
                            )}
                            {this.props.permission.checklistCompleteEnabled
                                && draft.questionDataList
                                && draft.metaData.complete === false
                                && !this.props.readOnly && (
                                <button
                                    type="button"
                                    className="lux-estimate-btn lux-estimate-btn--primary"
                                    onClick={this.handleCompleteChecklist}
                                >
                                    <i className="fe fe-check" /> Mark complete
                                </button>
                            )}
                        </footer>
                    </div>
                </aside>
                {this.renderChangeModal()}
            </>
        );

        if (typeof document !== "undefined") {
            return createPortal(panel, document.body);
        }
        return panel;
    };

    renderInlineSidebarMode = () => {
        const draft = this.getDraftData();
        const updateEnabled = this.canUpdate(draft);

        return (
            <div className="lux-checklist-inline">
                <header className="lux-checklist-inline__head">
                    <span className="pd-checklist__icon"><i className="fe fe-check-square" /></span>
                    <h3 className="lux-checklist-inline__title">Checklist</h3>
                    <span className="lux-checklist-inline__actions">
                        {!this.props.readOnly && this.props.permission.checklistChangeEnabled && (
                            <button type="button" className="link lux-checklist-inline__action" onClick={this.openChangeModal}>
                                {draft.questionDataList ? "Change" : "Add checklist"}
                            </button>
                        )}
                        {this.state.permission.viewEnabled && (
                            <button type="button" className="link lux-checklist-inline__action" onClick={this.onShowChecklistConfig}>
                                <i className="fe fe-settings" /> Configure
                            </button>
                        )}
                    </span>
                </header>

                <div className="lux-checklist-inline__body">
                    {this.renderEditorBody()}
                </div>

                <footer className="lux-checklist-inline__foot">
                    {updateEnabled && (
                        <button type="button" className="lux-estimate-btn lux-estimate-btn--primary lux-estimate-btn--sm" onClick={this.handleUpdateChecklist}>
                            Save
                        </button>
                    )}
                    {this.props.permission.checklistCompleteEnabled
                        && draft.questionDataList
                        && draft.metaData.complete === false
                        && !this.props.readOnly && (
                        <button type="button" className="lux-estimate-btn lux-estimate-btn--primary lux-estimate-btn--sm" onClick={this.handleCompleteChecklist}>
                            Complete
                        </button>
                    )}
                </footer>

                {this.renderChangeModal()}
            </div>
        );
    };

    render() {
        if (this.props.isSidebar) {
            return this.renderInlineSidebarMode();
        }

        return (
            <>
                {this.renderSummary()}
                {this.renderEditorSidebar()}
            </>
        );
    }
}

const mapDispatchToProps = () => ({
    getAllChecklists: checklistActions.getAllChecklists,
});

export default connect(null, mapDispatchToProps)(ItemChecklistInput);
