import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { industryTemplateService } from "_services/industryTemplates/industryTemplates.service";
import {
  ITPL_APPLY_PIPELINE,
  ITPL_RELATED_LINKS,
  buildIndustryTemplateMetrics,
  enrichIndustryTemplateRows,
  normalizeIndustryTemplateStatus,
} from "config/industry-templates-catalog.config";
import {
  AdminActionButton,
  AdminLuxPage,
  AdminPanelLink,
} from "views/admin/components/AdminLuxShared";
import AdminInsightsSummary from "views/admin/components/AdminInsightsSummary";
import AdminLoadAlert from "views/admin/components/AdminLoadAlert";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

/**
 * W26 ITPL — luxury compact industry template catalog.
 */
class IndustryTemplatesPage extends Component {
  state = {
    loading: true,
    loadError: null,
    rows: [],
    query: "",
    statusFilter: "ALL",
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Industry templates");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await industryTemplateService.listCatalog();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load industry templates"),
      });
    }
  };

  getFilteredRows = () => {
    const { rows, query, statusFilter } = this.state;
    const q = String(query || "")
      .trim()
      .toLowerCase();
    return enrichIndustryTemplateRows(rows).filter((row) => {
      if (statusFilter !== "ALL" && row.statusLabel !== statusFilter) {
        return false;
      }
      if (!q) return true;
      const hay = [
        row.industryPack,
        row.name,
        row.templateRef,
        row.version,
        row.status,
        row.description,
        ...(row.enrichment.seeds || []),
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return hay.includes(q);
    });
  };

  render() {
    const { loading, loadError, query, statusFilter, rows } = this.state;
    const metrics = buildIndustryTemplateMetrics(rows);
    const filtered = this.getFilteredRows();
    const statuses = [
      "ALL",
      ...Array.from(
        new Set((rows || []).map((r) => normalizeIndustryTemplateStatus(r.status)).filter(Boolean))
      ).sort(),
    ];
    const nextPublished = enrichIndustryTemplateRows(rows).find(
      (r) => r.statusLabel === "PUBLISHED"
    );

    return (
      <AdminLuxPage
        testId="industry-templates-page"
        className="lux-admin-page lux-itpl-page"
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-package",
          eyebrow: "Admin · Configuration",
          titleLead: "Industry",
          titleAccent: "templates",
          lede: "Vertical packs seed allowlisted App Config defaults — preview, draft, then commit with an overwrite guard.",
        }}
        dataSource="api"
        loading={loading}
        onRefresh={this.load}
        refreshLoading={loading}
        heroActions={<><AdminActionButton to="/admin/setup-checklist" variant="secondary" icon="fe fe-check-square">
              Setup checklist
            </AdminActionButton>
            <AdminActionButton to="/admin/industry-templates/apply" variant="primary" icon="fe fe-play">
              Apply wizard
            </AdminActionButton>
          </>}
      >
        <AdminInsightsSummary
          storageKey="famstack-industry-templates-summary-expanded"
          domainClass="lux-admin-summary--itpl"
          loading={loading}
          eyebrow="Catalog intelligence"
          eyebrowIcon="fe-package"
          title="Industry template insights"
          compactTitle={`${metrics.published}/${metrics.total || "—"} published · ${metrics.packs} verticals`}
          collapsedLine={`${metrics.draft} draft · overwrite guarded · App Config only`}
          subtitle="Packs seed roles, workflows, checklists, and allowlisted module flags — never a second source of truth."
          kpis={[
            {
              key: "packs",
              label: "Templates",
              value: metrics.total,
              hint: `${metrics.packs} verticals`,
              tone: "indigo",
              icon: "fe fe-package",
            },
            {
              key: "published",
              label: "Published",
              value: metrics.published,
              hint: "Apply-ready",
              tone: metrics.published ? "green" : "slate",
              icon: "fe fe-check-circle",
            },
            {
              key: "draft",
              label: "Draft",
              value: metrics.draft,
              hint: "Not published",
              tone: metrics.draft ? "amber" : "slate",
              icon: "fe fe-edit-3",
            },
            {
              key: "guard",
              label: "Overwrite",
              value: "Guarded",
              hint: "ITPL-009",
              tone: "violet",
              icon: "fe fe-lock",
            },
          ]}
          highlights={[
            {
              key: "pipeline",
              label: "Apply path",
              value: "4 steps",
              hint: "Preview → draft → guard → commit",
              tone: "blue",
              icon: "fe fe-git-commit",
            },
            {
              key: "scope",
              label: "Write scope",
              value: "App Config",
              hint: "Allowlisted keys only",
              tone: "slate",
              icon: "fe fe-settings",
            },
          ]}
          attention={
            loading
              ? []
              : nextPublished
                ? [
                    {
                      id: "ready",
                      eyebrow: "Ready",
                      stat: nextPublished.industryPack || "Pack",
                      title: nextPublished.name || nextPublished.templateRef,
                      copy:
                        nextPublished.description ||
                        nextPublished.enrichment.blurb ||
                        "Open the apply wizard to seed the active team.",
                      hint: "Preview first — no silent App Config write.",
                      icon: "fe fe-play",
                      tone: "green",
                    },
                  ]
                : [
                    {
                      id: "empty",
                      eyebrow: "Catalog",
                      stat: "—",
                      title: "No published packs yet",
                      copy: "Publish a vertical pack before running the apply wizard.",
                      hint: "Refresh the catalog or check Application Config access.",
                      icon: "fe fe-alert-circle",
                      tone: "amber",
                    },
                  ]
          }
          mixInsights={[
            {
              key: "publish-mix",
              icon: "fe fe-pie-chart",
              title: "Publish mix",
              subtitle: "Catalog readiness",
              mix: [
                {
                  key: "published",
                  label: "Published",
                  count: metrics.published,
                  pct: Math.round((metrics.published / Math.max(metrics.total, 1)) * 100),
                  tone: "green",
                },
                {
                  key: "draft",
                  label: "Draft",
                  count: metrics.draft,
                  pct: Math.round((metrics.draft / Math.max(metrics.total, 1)) * 100),
                  tone: "amber",
                },
                {
                  key: "other",
                  label: "Other",
                  count: Math.max(metrics.total - metrics.published - metrics.draft, 0),
                  pct: Math.round(
                    (Math.max(metrics.total - metrics.published - metrics.draft, 0) /
                      Math.max(metrics.total, 1)) *
                      100
                  ),
                  tone: "slate",
                },
              ],
            },
          ]}
          series={[
            {
              id: "packs",
              title: "Vertical packs",
              subtitle: "Catalog slice",
              rows: enrichIndustryTemplateRows(rows)
                .slice(0, 6)
                .map((row) => ({
                  key: row.templateRef || row.code,
                  label: row.industryPack || row.name || row.templateRef,
                  icon: row.enrichment.icon,
                  tone: row.statusTone,
                  value: row.statusLabel === "PUBLISHED" ? 1 : 0,
                  pct: row.statusLabel === "PUBLISHED" ? 100 : 28,
                  meta: row.statusLabel,
                })),
            },
          ]}
          testId="industry-templates-insights"
        />

        <section
          className="lux-admin-atelier lux-admin-atelier--itpl lux-admin-atelier--compact"
          data-testid="industry-templates-atelier"
        >
          <header className="lux-admin-atelier__masthead">
            <div className="lux-admin-atelier__masthead-main">
              <span className="lux-admin-atelier__mark" aria-hidden="true">
                <i className="fe fe-package" />
              </span>
              <div className="lux-admin-atelier__masthead-copy">
                <div className="lux-admin-atelier__title-row">
                  <p className="lux-admin-atelier__eyebrow">Template studio</p>
                  <h2 className="lux-admin-atelier__title">Industry packs</h2>
                </div>
                <p className="lux-admin-atelier__lede">
                  Compact catalog · apply pipeline · related admin consoles
                </p>
              </div>
            </div>
            <div className="lux-admin-atelier__masthead-aside">
              <AdminPanelLink to="/admin/appconfig">Application config</AdminPanelLink>
              <span className="lux-admin-atelier__count">
                <strong>{metrics.published}</strong>
                <em>ready</em>
              </span>
            </div>
          </header>

          <div className="lux-admin-atelier__body">
            <AdminLoadAlert
              error={loadError}
              fallback="Unable to load industry templates."
              onDismiss={() => this.setState({ loadError: null })}
            />

            <div className="lux-itpl-pipeline" data-testid="industry-templates-pipeline">
              <header className="lux-itpl-pipeline__head">
                <div>
                  <p className="lux-itpl-eyebrow">Safe apply</p>
                  <h3>How template apply works</h3>
                  <p>
                    Never writes App Config until commit. Conflicts require an explicit overwrite
                    approval.
                  </p>
                </div>
                <Link className="lux-admin-panel-link" to="/admin/industry-templates/apply">
                  Open wizard
                  <i className="fe fe-arrow-right" aria-hidden="true" />
                </Link>
              </header>
              <ol className="lux-itpl-pipeline__steps">
                {ITPL_APPLY_PIPELINE.map((step, index) => (
                  <li key={step.id} className="lux-itpl-pipeline__step">
                    <span className="lux-itpl-pipeline__index" aria-hidden="true">
                      {index + 1}
                    </span>
                    <span className="lux-itpl-pipeline__icon" aria-hidden="true">
                      <i className={step.icon} />
                    </span>
                    <div>
                      <strong>{step.label}</strong>
                      <em>{step.copy}</em>
                    </div>
                  </li>
                ))}
              </ol>
            </div>

            <div
              className="lux-itpl-related"
              role="list"
              aria-label="Related admin consoles"
            >
              {ITPL_RELATED_LINKS.map((item) => (
                <Link
                  key={item.to}
                  to={item.to}
                  className={classNames("lux-itpl-related__card", `is-${item.tone}`)}
                  role="listitem"
                >
                  <span className="lux-itpl-related__icon" aria-hidden="true">
                    <i className={item.icon} />
                  </span>
                  <span className="lux-itpl-related__copy">
                    <strong>{item.title}</strong>
                    <em>{item.copy}</em>
                  </span>
                  <i className="fe fe-arrow-right lux-itpl-related__chevron" aria-hidden="true" />
                </Link>
              ))}
            </div>

            <div className="lux-admin-atelier__stage-card lux-itpl-stage">
              <div className="lux-itpl-toolbar">
                <div className="lux-itpl-toolbar__copy">
                  <p className="lux-itpl-eyebrow">Catalog</p>
                  <h3>Vertical packs</h3>
                  <p>
                    Open a pack for payload detail, or start apply to seed the active team&apos;s
                    Application Config.
                  </p>
                </div>
                <div className="lux-itpl-toolbar__controls">
                  <label className="lux-itpl-search">
                    <i className="fe fe-search" aria-hidden="true" />
                    <input
                      type="search"
                      value={query}
                      placeholder="Search pack, name, or ref"
                      onChange={(e) => this.setState({ query: e.target.value })}
                      aria-label="Search industry templates"
                    />
                  </label>
                  <div className="lux-itpl-chips" role="tablist" aria-label="Filter by status">
                    {statuses.map((status) => (
                      <button
                        key={status}
                        type="button"
                        role="tab"
                        aria-selected={statusFilter === status}
                        className={classNames("lux-itpl-filter", {
                          "is-active": statusFilter === status,
                        })}
                        onClick={() => this.setState({ statusFilter: status })}
                      >
                        {status === "ALL" ? "All" : status}
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              {loading ? (
                <LuxRegisterEmptyState
                  className="lux-register-empty--compact"
                  eyebrow="Templates"
                  title="Loading catalog"
                  description="Fetching industry template packs."
                />
              ) : !loadError && filtered.length === 0 ? (
                <LuxRegisterEmptyState
                  className="lux-register-empty--compact"
                  eyebrow="Templates"
                  title={rows.length ? "No matching packs" : "No templates found"}
                  description={
                    rows.length
                      ? "Try another status filter or clear the search."
                      : "No industry packs are available in the catalog."
                  }
                />
              ) : !loadError ? (
                <div className="lux-itpl-grid">
                  {filtered.map((row) => {
                    const { enrichment, statusTone, statusLabel } = row;
                    const href = `/admin/industry-templates/${encodeURIComponent(row.templateRef)}`;
                    const applyHref = `/admin/industry-templates/apply?templateRef=${encodeURIComponent(
                      row.templateRef || ""
                    )}`;
                    return (
                      <article
                        key={row.templateRef || row.code}
                        className={classNames(
                          "lux-itpl-card",
                          `is-${statusTone}`,
                          `is-pack-${enrichment.tone}`
                        )}
                        data-testid={`industry-template-card-${row.templateRef}`}
                      >
                        <header className="lux-itpl-card__head">
                          <span
                            className={classNames(
                              "lux-itpl-card__icon",
                              `is-${enrichment.tone}`
                            )}
                            aria-hidden="true"
                          >
                            <i className={enrichment.icon} />
                          </span>
                          <div className="lux-itpl-card__titles">
                            <p className="lux-itpl-card__pack">
                              {row.industryPack || "Industry pack"}
                            </p>
                            <h3 className="lux-itpl-card__title">
                              {row.name || row.templateRef}
                            </h3>
                          </div>
                          <span className={classNames("lux-itpl-pill", `is-${statusTone}`)}>
                            {statusLabel}
                          </span>
                        </header>

                        <p className="lux-itpl-card__meta">
                          <code>{row.templateRef}</code>
                          <span>v{row.version || "—"}</span>
                        </p>

                        <p className="lux-itpl-card__desc">
                          {row.description || enrichment.blurb}
                        </p>

                        <ul className="lux-itpl-card__seeds" aria-label="What this pack seeds">
                          {(enrichment.seeds || []).map((seed) => (
                            <li key={seed}>{seed}</li>
                          ))}
                        </ul>

                        {(enrichment.docs || []).length ? (
                          <div className="lux-itpl-card__docs">
                            {enrichment.docs.map((doc) => (
                              <a
                                key={`${row.templateRef}-${doc.href}`}
                                href={doc.href}
                                target="_blank"
                                rel="noopener noreferrer"
                              >
                                <i className="fe fe-book-open" aria-hidden="true" />
                                {doc.label}
                              </a>
                            ))}
                          </div>
                        ) : null}

                        <footer className="lux-itpl-card__foot">
                          <Link className="lux-admin-panel-link" to={href}>
                            Open detail
                            <i className="fe fe-arrow-right" aria-hidden="true" />
                          </Link>
                          <AdminActionButton to={applyHref} variant="secondary" icon="fe fe-play">
                            Apply
                          </AdminActionButton>
                        </footer>
                      </article>
                    );
                  })}
                </div>
              ) : null}
            </div>
          </div>
        </section>
      </AdminLuxPage>
    );
  }
}

export default IndustryTemplatesPage;
