/** Shipped: hide when flag is explicitly false. Planned: visible only when REACT_APP_SHOW_PLANNED_MENU_ITEMS=true. */
export function isSidebarItemVisible(item, menuAccessControl, activePersona, sidebarGroupId) {
  return evaluateSidebarItemAccess(item, menuAccessControl, activePersona, {
    honorHideWhenFlag: true,
    sidebarGroupId,
  });
}

/**
 * Route/persona access for a sidebar item. Ignores {@code hideWhenFlag} so a
 * page can stay deep-linkable (e.g. classic Types &amp; fallback) while the
 * duplicate sidebar entry is suppressed when Global Leave is enabled.
 */
export function isSidebarItemRouteAccessible(item, menuAccessControl, activePersona, sidebarGroupId) {
  return evaluateSidebarItemAccess(item, menuAccessControl, activePersona, {
    honorHideWhenFlag: false,
    sidebarGroupId,
  });
}

function evaluateSidebarItemAccess(item, menuAccessControl, activePersona, options = {}) {
  const honorHideWhenFlag = options.honorHideWhenFlag !== false;
  if (!item) {
    return false;
  }
  if (options.sidebarGroupId && isOrgSidebarGroupDisabled(options.sidebarGroupId)) {
    return false;
  }
  if (isOrgPathDisabled(item.path) || (item.aliasPath && isOrgPathDisabled(item.aliasPath))) {
    return false;
  }
  if (item.flagModule && isOrgModuleDisabled(item.flagModule)) {
    return false;
  }
  const persona = activePersona || resolveActivePersona(menuAccessControl);
  if (!isItemVisibleForPersona(item, persona)) {
    return false;
  }
  if (item.hidden === true) {
    return false;
  }
  // Org pilots are AND-ed inside getMenuAccessControl — never short-circuit role.json flags.
  if (!item.flagModule || !item.flag) {
    if (item.planned === true) {
      return isPlannedMenuItemsEnabled();
    }
    return true;
  }
  const mod = menuAccessControl && menuAccessControl[item.flagModule];
  if (!mod) {
    return false;
  }
  if (honorHideWhenFlag && item.hideWhenFlag && mod[item.hideWhenFlag] === true) {
    return false;
  }
  if (mod[item.flag] === true) {
    return true;
  }
  if (item.planned === true) {
    return isPlannedMenuItemsEnabled();
  }
  return false;
}

export function getVisibleSidebarItems(group, menuAccessControl, activePersona) {
  const persona = activePersona || resolveActivePersona(menuAccessControl);
  if (group && isOrgSidebarGroupDisabled(group.id)) {
    return [];
  }
  return (group.items || []).filter((item) =>
    isSidebarItemVisible(item, menuAccessControl, persona, group && group.id)
  );
}

export function isSidebarGroupVisible(group, menuAccessControl, activePersona) {
  const persona = activePersona || resolveActivePersona(menuAccessControl);
  if (!group) {
    return false;
  }
  if (isOrgSidebarGroupDisabled(group.id)) {
    return false;
  }
  if (!isGroupVisibleForPersona(group, persona)) {
    return false;
  }
  return getVisibleSidebarItems(group, menuAccessControl, persona).length > 0;
}

export function pathMatchesSidebarGroup(pathname, group) {
  const path = (pathname || "").split("?")[0];
  const excludes = group.pathExclude || [];
  if (excludes.some((ex) => path === ex || path.startsWith(`${ex}/`))) {
    return false;
  }
  const prefixes = group.pathPrefixes || [];
  return prefixes.some((prefix) => path === prefix || path.startsWith(`${prefix}/`));
}

/** Resolve enterprise module label for header kicker / breadcrumbs (matches sidebar groups). */
export function resolveSidebarModuleLabel(pathname) {
  const path = (pathname || "").split("?")[0];
  for (let i = SIDEBAR_GROUPS.length - 1; i >= 0; i -= 1) {
    const group = SIDEBAR_GROUPS[i];
    if (pathMatchesSidebarGroup(path, group)) {
      return group.menuName;
    }
  }
  if (path.startsWith("/project")) {
    return "Projects";
  }
  return null;
}
