/**
 * W20 — LMS FE service. Real API only (no mock fallback).
 */
import { axiosUtils, commonUtils } from "../../_helpers";
import urlConfig from "url.config";

export const learningService = {
  listCourses,
  createCourse,
  updateCourse,
  listModules,
  createModule,
  listAssignments,
  createAssignment,
  myLearning,
  markProgress,
  completeAssignment,
  complianceDue,
  completionReport,
  employeeLearning,
};

const API_ERROR = { payload: null, source: "api-error" };

function resolveUserTeamId() {
  return commonUtils.getCurrentUserTeamId();
}

function resolveActorId() {
  return commonUtils.getCurrentUserId();
}

function resolveEmployeeId() {
  return commonUtils.getCurrentUserId();
}

function withHr(params = {}) {
  return { ...params, userTeamId: resolveUserTeamId(), hrAdmin: true };
}

function withManager(params = {}) {
  return { ...params, userTeamId: resolveUserTeamId(), managerOrHr: true };
}

async function listCourses() {
  try {
    const response = await axiosUtils.getWithParam(`${urlConfig.LEARNING_API_PATH}/courses`, withHr());
    const payload = response && response.payload != null ? response.payload : response;
    return Array.isArray(payload) ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function createCourse(body = {}) {
  try {
    const response = await axiosUtils.post(`${urlConfig.LEARNING_API_PATH}/courses`, {
      ...body,
      userTeamId: body.userTeamId || resolveUserTeamId(),
      actorId: body.actorId || resolveActorId(),
      hrAdmin: true,
      active: body.active !== false,
    });
    const payload = response && response.payload != null ? response.payload : response;
    return payload ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function updateCourse(courseRef, body = {}) {
  try {
    const response = await axiosUtils.put(
      `${urlConfig.LEARNING_API_PATH}/courses/${encodeURIComponent(courseRef)}`,
      {
        ...body,
        userTeamId: body.userTeamId || resolveUserTeamId(),
        actorId: body.actorId || resolveActorId(),
        hrAdmin: true,
      }
    );
    const payload = response && response.payload != null ? response.payload : response;
    return payload ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

