async function myLearning(employeeId) {
  try {
    const empId = employeeId || resolveEmployeeId();
    const response = await axiosUtils.getWithParam(`${urlConfig.LEARNING_API_PATH}/my-learning`, {
      userTeamId: resolveUserTeamId(),
      employeeId: empId,
      actorEmployeeId: empId,
      hrAdmin: false,
    });
    const payload = response && response.payload != null ? response.payload : response;
    return Array.isArray(payload) ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function markProgress(body = {}) {
  try {
    const empId = body.employeeId || resolveEmployeeId();
    const response = await axiosUtils.post(`${urlConfig.LEARNING_API_PATH}/progress/mark`, {
      ...body,
      userTeamId: body.userTeamId || resolveUserTeamId(),
      actorId: body.actorId || resolveActorId(),
      actorEmployeeId: body.actorEmployeeId || empId,
      employeeId: empId,
      hrAdmin: body.hrAdmin === true,
    });
    const payload = response && response.payload != null ? response.payload : response;
    return payload ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function completeAssignment(assignmentRef, body = {}) {
  try {
    const empId = body.employeeId || resolveEmployeeId();
    const response = await axiosUtils.post(
      `${urlConfig.LEARNING_API_PATH}/assignments/${encodeURIComponent(assignmentRef)}/complete`,
      {
        ...body,
        userTeamId: body.userTeamId || resolveUserTeamId(),
        actorId: body.actorId || resolveActorId(),
        actorEmployeeId: body.actorEmployeeId || empId,
        employeeId: empId,
        hrAdmin: body.hrAdmin === true,
      }
    );
    const payload = response && response.payload != null ? response.payload : response;
    return payload ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

