import React from "react";
import AdminInsightsSummary from "views/admin/components/AdminInsightsSummary";
import {
  buildModuleGrantSeries,
  buildPersonaDistribution,
  buildRolePermissionInsights,
  buildRolePermissionMetrics,
} from "config/role-permission.utils";

const STORAGE_KEY = "famstack-rbac-insights-expanded";

export default function RolePermissionOverview({ roles, selectedRole, loading }) {
  const metrics = loading ? null : buildRolePermissionMetrics(roles);
  const personas = loading ? [] : buildPersonaDistribution(roles);
  const modules = loading ? [] : buildModuleGrantSeries(roles);
  const attention = loading ? [] : buildRolePermissionInsights(roles);
  const peakPersona = personas[0];
  const attentionCount = attention.filter((row) => row.tone !== "green").length;

  const activeCount = metrics ? metrics.activeRoles : 0;
  const inactiveCount = metrics ? Math.max(metrics.totalRoles - metrics.activeRoles, 0) : 0;
  const statusTotal = Math.max(activeCount + inactiveCount, 1);

  return (
    <AdminInsightsSummary
      storageKey={STORAGE_KEY}
      domainClass="lux-admin-summary--roles"
      loading={loading}
      eyebrow="Access intelligence"
      eyebrowIcon="fe-shield"
      title="Roles & permissions insights"
      compactTitle={
        metrics
          ? `${metrics.totalRoles} roles · ${metrics.coverage}% coverage${
              attentionCount > 0 ? ` · ${attentionCount} to review` : ""
            }`
          : "Roles insights"
      }
      collapsedLine={
        metrics
          ? `${metrics.activeRoles} active · ${metrics.assignedUsers} users · ${metrics.adminGrants} admin grants${
              peakPersona ? ` · ${peakPersona.meta.label} leads` : ""
            }${selectedRole ? ` · reviewing ${selectedRole.name}` : ""}`
          : null
      }
      subtitle="Governance health, persona mix, and module grant density across the role matrix."
      testId="rbac-insights-panel"
      ariaLabel="Roles & permissions insights"
      kpis={
        metrics
          ? [
              {
                key: "roles",
                label: "Roles",
                value: metrics.totalRoles,
                hint: `${metrics.activeRoles} active`,
                tone: "primary",
                icon: "fe fe-shield",
              },
              {
                key: "users",
                label: "Users mapped",
                value: metrics.assignedUsers,
                hint: "Assigned to profiles",
                tone: "blue",
                icon: "fe fe-users",
              },
              {
                key: "coverage",
                label: "Coverage",
                value: metrics.coverage,
                suffix: "%",
                hint: `${metrics.enabledFlags}/${metrics.totalFlags} flags on`,
                tone: "green",
                icon: "fe fe-check-circle",
              },
              {
                key: "admin",
                label: "Admin grants",
                value: metrics.adminGrants,
                hint: "Elevated module access",
                tone: "amber",
                icon: "fe fe-lock",
              },
            ]
          : []
      }
      highlights={
        metrics
          ? [
              {
                key: "flags",
                label: "Flags enabled",
                value: metrics.enabledFlags,
                hint: `of ${metrics.totalFlags} total`,
                tone: "indigo",
                icon: "fe fe-toggle-right",
              },
              {
                key: "personas",
                label: "Persona types",
                value: personas.length,
                hint: peakPersona ? `${peakPersona.meta.label} leads` : "No personas yet",
                tone: "violet",
                icon: "fe fe-layers",
              },
              {
                key: "modules",
                label: "Module surfaces",
                value: modules.length,
                hint: "Grant density tracked",
                tone: "mint",
                icon: "fe fe-grid",
              },
            ]
          : []
      }
      attention={attention}
      mixInsights={
        metrics
          ? [
              {
                key: "status-mix",
                icon: "fe fe-activity",
                title: "Role status mix",
                subtitle: "Active vs inactive permission profiles",
                mix: [
                  {
                    key: "active",
                    label: "Active",
                    count: activeCount,
                    pct: Math.round((activeCount / statusTotal) * 100),
                    tone: "green",
                  },
                  {
                    key: "inactive",
                    label: "Inactive",
                    count: inactiveCount,
                    pct: Math.round((inactiveCount / statusTotal) * 100),
                    tone: "slate",
                  },
                ],
              },
              {
                key: "persona-mix",
                icon: "fe fe-users",
                title: "Persona distribution",
                subtitle: peakPersona
                  ? `${peakPersona.meta.label} leads at ${peakPersona.pct}%`
                  : "No persona mix yet",
                mix: personas.map((row) => ({
                  key: row.persona,
                  label: row.meta.label,
                  count: row.count,
                  pct: row.pct,
                  tone: row.meta.tone || "slate",
                })),
                emptyLabel: "No roles loaded",
              },
            ]
          : []
      }
      series={[
        {
          id: "persona-series",
          title: "Role distribution",
          subtitle: "Profiles by persona",
          rows: personas.map((row) => ({
            key: row.persona,
            label: row.meta.label,
            icon: row.meta.icon,
            tone: row.meta.tone,
            value: row.count,
            pct: row.pct,
            meta: String(row.count),
          })),
          emptyLabel: "No persona data yet",
        },
        {
          id: "module-series",
          title: "Grant density",
          subtitle: metrics ? `${metrics.enabledFlags} flags enabled org-wide` : "Module grants",
          rows: modules.map((row) => ({
            key: row.moduleKey,
            label: row.meta.label,
            icon: row.meta.icon,
            tone: row.meta.tone,
            value: row.enabled,
            total: row.total,
            pct: row.pct,
          })),
          emptyLabel: "No module grants yet",
        },
      ]}
    />
  );
}
