function formatCurrencyAmount(value) {
  if (value == null || Number.isNaN(Number(value))) {
    return "—";
  }
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: value % 1 === 0 ? 0 : 2,
  }).format(Number(value));
}

export function resolvePayrollSummary(summary) {
  return (summary && summary.payroll) || null;
}

function formatFinanceCurrency(value, masked) {
  if (masked) {
    return "Restricted";
  }
  return formatCurrencyAmount(value);
}

export function buildPerformanceTabStats(snapshot, maskingPolicy) {
  const data = snapshot || {};
  const activeReview = data.activeReview;
  const ratingsVisible = isFieldVisible("performanceReview", maskingPolicy);
  const selfRating =
    activeReview && activeReview.selfRating != null
      ? resolveMaskedFieldValue("performanceReview", String(activeReview.selfRating), maskingPolicy)
      : "—";
  const managerRating =
    activeReview && activeReview.managerRating != null
      ? resolveMaskedFieldValue("performanceReview", String(activeReview.managerRating), maskingPolicy)
      : "—";

  return [
    {
      key: "goals",
      label: "Open goals",
      value: String(data.openGoals != null ? data.openGoals : 0),
      hint: "Linked OKRs",
      tone: "amber",
    },
    {
      key: "progress",
      label: "Goal progress",
      value: data.avgGoalProgress != null ? `${data.avgGoalProgress}%` : "—",
      hint: "Average completion",
      tone: "rose",
    },
    {
      key: "praise",
      label: "Praise notes",
      value: String(data.praiseCount != null ? data.praiseCount : 0),
      hint: "Continuous feedback",
      tone: "emerald",
    },
    {
      key: "review",
      label: "Review status",
      value: (activeReview && activeReview.status) || "—",
      hint: ratingsVisible ? `Self ${selfRating} · Mgr ${managerRating}` : "Ratings restricted",
      tone: activeReview && activeReview.status === "completed" ? "green" : "indigo",
    },
  ];
}

export function buildFinanceTabStats(bundle, masked = false) {
  const profile = bundle && bundle.profile;
  const advances = (bundle && bundle.advances) || [];
  const loans = (bundle && bundle.loans) || [];
  const openAdvance = profile && profile.openAdvanceUsd != null ? profile.openAdvanceUsd : 0;
  const openLoan = profile && profile.openLoanUsd != null ? profile.openLoanUsd : 0;
  const margin = profile && profile.marginPct != null ? `${profile.marginPct}%` : "—";

  return [
    {
      key: "ctc",
      label: "CTC",
      value: formatFinanceCurrency(profile && profile.ctcUsd, masked),
      hint: "Cost to company",
      tone: masked ? "slate" : "indigo",
    },
    {
      key: "margin",
      label: "Margin",
      value: masked ? "Restricted" : margin,
      hint: "Bill vs cost rate",
      tone: !masked && profile && profile.marginPct < 25 ? "rose" : "green",
    },
    {
      key: "advances",
      label: "Open advances",
      value: formatFinanceCurrency(openAdvance, masked),
      hint: `${advances.length} record(s)`,
      tone: openAdvance > 0 ? "amber" : "slate",
    },
    {
      key: "loans",
      label: "Open loans",
      value: formatFinanceCurrency(openLoan, masked),
      hint: `${loans.length} active schedule(s)`,
      tone: openLoan > 0 ? "amber" : "slate",
    },
  ];
}

export function buildPayrollTabStats(summary, maskingPolicy) {
  const payroll = resolvePayrollSummary(summary);
  const baseSalary = payroll && payroll.baseSalary;
  const salaryDisplay =
    baseSalary != null
      ? resolveMaskedFieldValue("salary", formatCurrencyAmount(baseSalary), maskingPolicy)
      : "—";
  const lastPaycheck =
    payroll && payroll.lastPaycheckAmount != null
      ? resolveMaskedFieldValue(
          "paycheckAmount",
          formatCurrencyAmount(payroll.lastPaycheckAmount),
          maskingPolicy
        )
      : "—";
  const ytdNet =
    payroll && payroll.ytdNet != null
      ? resolveMaskedFieldValue("payrollLines", formatCurrencyAmount(payroll.ytdNet), maskingPolicy)
      : "—";

  return [
    {
      key: "salary",
      label: "Base salary",
      value: salaryDisplay,
      hint: payroll && payroll.payFrequency ? payroll.payFrequency : "Per pay cycle",
      tone: salaryDisplay === "Restricted" ? "slate" : "green",
    },
    {
      key: "last-pay",
      label: "Last paycheck",
      value: lastPaycheck,
      hint: payroll && payroll.lastPaycheckDate ? payroll.lastPaycheckDate : "Most recent run",
      tone: "slate",
    },
    {
      key: "ytd",
      label: "YTD net",
      value: ytdNet,
      hint: "Year to date",
      tone: "slate",
    },
    {
      key: "status",
      label: "Payroll status",
      value: (payroll && payroll.payStatus) || (summary && summary.payrollGroup) || "—",
      hint: "Next run readiness",
      tone: payroll && String(payroll.payStatus || "").toLowerCase().includes("ready") ? "green" : "amber",
    },
  ];
}

export function buildProjectAllocations(summary, employee) {
  if (summary && Array.isArray(summary.projectAllocations) && summary.projectAllocations.length > 0) {
    return summary.projectAllocations;
  }
  const names =
    (summary && summary.allocatedProjects) ||
    (employee && employee.allocatedProjects) ||
    [];
  return names.map((name, index) => ({
    id: `alloc-${index + 1}`,
    name,
    code: "—",
    role: (employee && employee.designation) || "—",
    allocationPct: null,
    health: "—",
    schedule: "—",
  }));
}

