export function buildProjectsTabStats(allocations) {
  const rows = allocations || [];
  const totalPct = rows.reduce(
    (sum, row) => sum + (row.allocationPct != null ? Number(row.allocationPct) : 0),
    0
  );
  const atRisk = rows.filter((row) => String(row.health || "").toLowerCase().includes("risk")).length;

  return [
    {
      key: "count",
      label: "Active projects",
      value: rows.length ? String(rows.length) : "0",
      hint: "Current allocations",
      tone: rows.length ? "green" : "slate",
    },
    {
      key: "allocation",
      label: "Allocated",
      value: totalPct ? `${totalPct}%` : "—",
      hint: "Combined allocation",
      tone: totalPct > 100 ? "amber" : "slate",
    },
    {
      key: "risk",
      label: "At risk",
      value: String(atRisk),
      hint: "Projects flagged",
      tone: atRisk > 0 ? "amber" : "green",
    },
  ];
}

export function buildDocumentsTabStats(documents, assets) {
  const docRows = documents || [];
  const assetRows = assets || [];
  const pendingDocs = docRows.filter((row) =>
    String(row.status || "").toLowerCase().includes("pending")
  ).length;

  return [
    {
      key: "documents",
      label: "Documents",
      value: String(docRows.length),
      hint: "Vault records",
      tone: docRows.length ? "green" : "slate",
    },
    {
      key: "assets",
      label: "Assets",
      value: String(assetRows.length),
      hint: "Assigned equipment",
      tone: assetRows.length ? "green" : "slate",
    },
    {
      key: "pending",
      label: "Pending review",
      value: String(pendingDocs),
      hint: "Needs HR action",
      tone: pendingDocs > 0 ? "amber" : "green",
    },
  ];
}

export function resolveEmployeeDocuments(summary) {
  return (summary && summary.documents) || [];
}

