import React from "react";
import { DOCUMENT_TYPES, DOCUMENT_VISIBILITY } from "config/document-vault.config";
import PayrollLuxDrawerShell from "views/payroll/components/PayrollLuxDrawerShell";
import {
  PayrollDrawerBanner,
  PayrollDrawerCard,
  PayrollDrawerField,
  PayrollDrawerMeta,
} from "views/payroll/components/PayrollLuxDrawerShared";
import { PayrollActionButton } from "views/payroll/components/PayrollLuxShared";

const DEFAULT_FORM = {
  title: "",
  type: "OTHER",
  employeeId: "",
  employeeName: "",
  visibility: "HR_ONLY",
  expiresAt: "",
  fileName: "",
  contentType: "",
  fileSizeKb: null,
  fileContentBase64: "",
};

const DRAWER_LINKS = [
  { to: "/people/policies", label: "Policy hub", hint: "Acknowledgment campaigns", icon: "fe fe-book" },
  { to: "/people/documents", label: "Document vault", hint: "Employee records", icon: "fe fe-file-text" },
];

function readFileAsBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = String(reader.result || "");
      const comma = result.indexOf(",");
      resolve(comma >= 0 ? result.slice(comma + 1) : result);
    };
    reader.onerror = () => reject(reader.error || new Error("Unable to read file"));
    reader.readAsDataURL(file);
  });
}

export default class DocumentUploadDrawer extends React.Component {
  state = {
    form: { ...DEFAULT_FORM },
    saving: false,
    error: null,
  };

  fileInputRef = React.createRef();

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open) {
      this.setState({
        form: {
          ...DEFAULT_FORM,
          employeeId: this.props.defaultEmployeeId || "",
          employeeName: this.props.defaultEmployeeName || "",
        },
        saving: false,
        error: null,
      });
      if (this.fileInputRef.current) {
        this.fileInputRef.current.value = "";
      }
    }
  }

  handleChange = (field) => (event) => {
    this.setState((prev) => ({
      form: { ...prev.form, [field]: event.target.value },
      error: null,
    }));
  };

  handleFileChange = async (event) => {
    const file = event.target.files && event.target.files[0];
    if (!file) {
      return;
    }
    try {
      const fileContentBase64 = await readFileAsBase64(file);
      this.setState((prev) => ({
        form: {
          ...prev.form,
          fileName: file.name,
          contentType: file.type || "application/octet-stream",
          fileSizeKb: Math.max(1, Math.round(file.size / 1024)),
          fileContentBase64,
        },
        error: null,
      }));
    } catch (e) {
      this.setState({ error: "Unable to read the selected file." });
    }
  };

  handleClearFile = () => {
    if (this.fileInputRef.current) {
      this.fileInputRef.current.value = "";
    }
    this.setState((prev) => ({
      form: {
        ...prev.form,
        fileName: "",
        contentType: "",
        fileSizeKb: null,
        fileContentBase64: "",
      },
      error: null,
    }));
  };

  handleSubmit = async (event) => {
    event.preventDefault();
    const { form } = this.state;
    const { onSubmit } = this.props;
    if (!form.title.trim()) {
      this.setState({ error: "Document title is required." });
      return;
    }
    if (!form.employeeId || !String(form.employeeId).trim()) {
      this.setState({ error: "Employee id is required for vault ownership." });
      return;
    }
    this.setState({ saving: true, error: null });
    try {
      const fileName =
        form.fileName || `${form.title.replace(/\s+/g, "-").toLowerCase()}.pdf`;
      await onSubmit({
        title: form.title.trim(),
        type: form.type,
        employeeId: form.employeeId,
        employeeName: form.employeeName,
        visibility: form.visibility,
        expiresAt: form.expiresAt || undefined,
        fileName,
        contentType: form.contentType || undefined,
        fileSizeKb: form.fileSizeKb || undefined,
        fileContentBase64: form.fileContentBase64 || undefined,
        uploadedBy: "HR Admin",
      });
      this.props.onClose();
    } catch (e) {
      this.setState({ saving: false, error: "Unable to upload document." });
    }
  };

  render() {
    const { open, onClose } = this.props;
    const { form, saving, error } = this.state;
    if (!open) {
      return null;
    }

    const typeMatch = Object.values(DOCUMENT_TYPES).find((type) => type.id === form.type);
    const typeLabel = (typeMatch && typeMatch.label) || form.type;
    const hasAttachedFile = Boolean(form.fileContentBase64);

    const footer = (
      <>
        <PayrollActionButton variant="ghost" onClick={onClose} disabled={saving}>
          Cancel
        </PayrollActionButton>
        <PayrollActionButton type="submit" form="document-upload-form" variant="primary" disabled={saving}>
          {saving ? "Uploading…" : "Upload document"}
        </PayrollActionButton>
      </>
    );

    return (
      <PayrollLuxDrawerShell
        open={open}
        onClose={onClose}
        accent="violet"
        icon="fe-upload-cloud"
        eyebrow="Document vault"
        title="Upload document"
        subtitle="Add employment, compliance, or payroll documents with visibility and expiry controls."
        quickLinks={DRAWER_LINKS}
        footer={footer}
      >
        <form id="document-upload-form" onSubmit={this.handleSubmit}>
          {error && (
            <div className="lux-employee-360__error" role="alert">
              {error}
            </div>
          )}

          <PayrollDrawerBanner icon="fe-shield" tone="info">
            Documents are stored in the employee vault — not an isolated file repository. Verification and expiry queues
            update after upload.
          </PayrollDrawerBanner>

          <PayrollDrawerCard title="Document details" subtitle="Title, employee context, and classification">
            <PayrollDrawerField label="Title" hint="Displayed in vault register and employee 360">
              <input type="text" value={form.title} onChange={this.handleChange("title")} placeholder="Employment contract" required />
            </PayrollDrawerField>

            <PayrollDrawerField label="Employee id" hint="Required vault owner — Employee source id">
              <input
                type="text"
                value={form.employeeId}
                onChange={this.handleChange("employeeId")}
                placeholder="emp-001"
                required
              />
            </PayrollDrawerField>

            <PayrollDrawerField label="Employee name" hint="Display label in vault register">
              <input
                type="text"
                value={form.employeeName}
                onChange={this.handleChange("employeeName")}
                placeholder="Employee name"
              />
            </PayrollDrawerField>

            <PayrollDrawerField label="Document type">
              <select value={form.type} onChange={this.handleChange("type")}>
                {Object.values(DOCUMENT_TYPES).map((type) => (
                  <option key={type.id} value={type.id}>
                    {type.label}
                  </option>
                ))}
              </select>
            </PayrollDrawerField>

            <PayrollDrawerField label="Visibility" hint="Controls persona access and download authorization">
              <select value={form.visibility} onChange={this.handleChange("visibility")}>
                {Object.entries(DOCUMENT_VISIBILITY).map(([key, value]) => (
                  <option key={key} value={value}>
                    {String(value).replace(/_/g, " ")}
                  </option>
                ))}
              </select>
            </PayrollDrawerField>
          </PayrollDrawerCard>

          <PayrollDrawerCard title="File & retention" subtitle="Attach a file for blob storage, or provide a filename hint">
            <div className="lux-payroll-drawer__upload-zone">
              <PayrollDrawerField
                label="File name"
                hint={hasAttachedFile ? "Taken from the attached file" : "Used when no binary is attached"}
              >
                <input
                  type="text"
                  value={form.fileName}
                  onChange={this.handleChange("fileName")}
                  placeholder="contract-elena-rossi.pdf"
                  readOnly={hasAttachedFile}
                />
              </PayrollDrawerField>
              <div className="d-flex align-items-center flex-wrap" style={{ gap: "0.5rem" }}>
                <label className="lux-onb-action lux-onb-action--secondary lux-payroll-action mb-0">
                  <i className="fe fe-paperclip" aria-hidden="true" />
                  <span>{hasAttachedFile ? "Replace file" : "Attach file"}</span>
                  <input
                    ref={this.fileInputRef}
                    type="file"
                    className="d-none"
                    onChange={this.handleFileChange}
                    disabled={saving}
                  />
                </label>
                {hasAttachedFile && (
                  <button
                    type="button"
                    className="lux-onb-action lux-onb-action--ghost lux-payroll-action mb-0"
                    onClick={this.handleClearFile}
                    disabled={saving}
                  >
                    Clear
                  </button>
                )}
              </div>
              {hasAttachedFile && (
                <p className="lux-payroll-drawer__hint mb-0 mt-2" role="status">
                  Attached {form.fileName}
                  {form.fileSizeKb != null ? ` · ${form.fileSizeKb} KB` : ""}
                  {form.contentType ? ` · ${form.contentType}` : ""}
                </p>
              )}
            </div>

            <PayrollDrawerField label="Expires on" hint="Triggers expiry reminders in compliance panels">
              <input type="date" value={form.expiresAt} onChange={this.handleChange("expiresAt")} />
            </PayrollDrawerField>
          </PayrollDrawerCard>

          <PayrollDrawerCard title="Review" subtitle="Confirm before upload" className="is-review">
            <PayrollDrawerMeta
              items={[
                { label: "Title", value: form.title.trim() || "—" },
                { label: "Employee", value: form.employeeName.trim() || "—" },
                { label: "Type", value: typeLabel },
                { label: "Visibility", value: String(form.visibility).replace(/_/g, " ") },
                { label: "File", value: hasAttachedFile ? form.fileName : form.fileName.trim() || "Metadata only" },
              ]}
            />
          </PayrollDrawerCard>
        </form>
      </PayrollLuxDrawerShell>
    );
  }
}
