import React, { Component } from "react";
import classNames from "classnames/bind";
import { isStaffingAiEnabled } from "config/staffing-ai.config";
import { getEmployeeInitials, getStaffingPriorityTone } from "config/resource-planning.utils";
import { resourcePlanningService } from "_services/resourcePlanning.service";
import { ResourcesRegisterAtelier } from "views/resources/components/ResourcesLuxShared";

export default class StaffingAiQueuePanel extends Component {
  state = {
    queue: [],
    loading: false,
  };

  componentDidMount() {
    this.loadQueue();
  }

  componentDidUpdate(prevProps) {
    if (prevProps.refreshKey !== this.props.refreshKey) {
      this.loadQueue();
    }
  }

  loadQueue = async () => {
    if (!isStaffingAiEnabled()) {
      return;
    }
    this.setState({ loading: true });
    try {
      const result = await resourcePlanningService.listStaffingAiQueue();
      this.setState({ queue: result.payload || [], loading: false });
    } catch (e) {
      this.setState({ queue: [], loading: false });
    }
  };

  render() {
    if (!isStaffingAiEnabled()) {
      return null;
    }

    const { onSelectRequest, loading: parentLoading } = this.props;
    const { queue, loading } = this.state;

    if (loading || parentLoading) {
      return (
        <ResourcesRegisterAtelier
          tone="amber"
          className="lux-res-atelier--compact lux-staffing-panel--ai"
          kickerIcon="fe fe-zap"
          kicker="AI matching"
          title="Staffing intelligence queue"
          subtitle="Top-ranked bench matches — human approval required"
          pulseCards={[{ id: "loading", label: "Queue", value: "…", tone: "amber" }]}
        >
          <p className="lux-staffing-ai-queue__loading">Loading staffing intelligence queue…</p>
        </ResourcesRegisterAtelier>
      );
    }

    if (!queue.length) {
      return null;
    }

    const topScore = queue.reduce(
      (best, row) => Math.max(best, row.topMatch ? row.topMatch.matchScore : 0),
      0
    );

    return (
      <ResourcesRegisterAtelier
        tone="amber"
        className="lux-res-atelier--compact lux-staffing-panel--ai"
        kickerIcon="fe fe-zap"
        kicker="AI matching"
        title="Staffing intelligence queue"
        subtitle="Top-ranked bench matches — human approval required"
        pulseCards={[
          { id: "open", label: "Open", value: queue.length, tone: "amber" },
          { id: "top", label: "Top fit", value: topScore ? `${topScore}%` : "—", tone: "green" },
        ]}
      >
        <div className="lux-staffing-ai-queue__list" role="list">
          {queue.map((row) => {
            const priorityTone = getStaffingPriorityTone(row.priority);
            const top = row.topMatch;
            return (
              <button
                key={row.requestId}
                type="button"
                className="lux-staffing-ai-queue__item"
                role="listitem"
                onClick={() => onSelectRequest && onSelectRequest(row.requestId)}
              >
                <div className="lux-staffing-ai-queue__request">
                  <strong>{row.title}</strong>
                  <span>{row.projectName} · {row.roleNeeded}</span>
                  <span className={classNames("lux-staffing-ai-queue__priority", `is-${priorityTone}`)}>
                    {row.priority || "NORMAL"}
                  </span>
                </div>
                {top ? (
                  <div className="lux-staffing-ai-queue__match">
                    <span className="lux-staffing-ai-queue__avatar" aria-hidden="true">
                      {getEmployeeInitials(top.employeeName)}
                    </span>
                    <span className="lux-staffing-ai-queue__match-copy">
                      <strong>{top.employeeName}</strong>
                      <small>{top.matchScore}% fit · {top.availabilityPct}% free</small>
                    </span>
                  </div>
                ) : (
                  <span className="lux-staffing-ai-queue__empty-match">No bench match</span>
                )}
                <i className="fe fe-chevron-right lux-staffing-ai-queue__chevron" aria-hidden="true" />
              </button>
            );
          })}
        </div>
      </ResourcesRegisterAtelier>
    );
  }
}
