import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import { isNotePending, noteCardTone } from "./notes.utils";

export default class LuxNoteCard extends PureComponent {
  state = {
    confirmDelete: false,
  };

  componentDidUpdate(prevProps) {
    if (prevProps.note && this.props.note && prevProps.note.id !== this.props.note.id) {
      this.setState({ confirmDelete: false });
    }
  }

  handleDeleteClick = () => {
    const { onDelete, note } = this.props;
    if (!onDelete) return;
    if (this.state.confirmDelete) {
      onDelete(note);
      this.setState({ confirmDelete: false });
    } else {
      this.setState({ confirmDelete: true });
    }
  };

  render() {
    const {
      note,
      formatWhen,
      compact = false,
      stickyVisual = false,
      permission,
      onMarkDone,
      onEdit,
      onDelete,
      onToggleComplete,
    } = this.props;
    const { confirmDelete } = this.state;
    const pending = isNotePending(note);
    const tone = noteCardTone(note);
    const handleDone =
      onMarkDone || (onToggleComplete ? () => onToggleComplete(note) : null);

    return (
      <article
        className={classNames("lux-note-card", `is-${tone}`, {
          "is-done": !pending,
          "is-compact": compact,
          "is-sticky": stickyVisual,
        })}
      >
        {stickyVisual && <span className="lux-note-card__pin" aria-hidden="true" />}
        <span className="lux-note-card__accent" aria-hidden="true" />
        <header className="lux-note-card__head">
          <h3 className="lux-note-card__title">{note.name || "Untitled note"}</h3>
          <div className="lux-note-card__badges">
            {note.remindMe && (
              <span className="lux-note-card__remind" title="Reminder enabled">
                <i className="fe fe-bell" aria-hidden="true" />
              </span>
            )}
            <span className={classNames("lux-note-card__status", pending ? "is-open" : "is-done")}>
              {pending ? "Open" : "Done"}
            </span>
          </div>
        </header>
        {note.description ? (
          <p className="lux-note-card__body">{note.description}</p>
        ) : (
          <p className="lux-note-card__body is-empty">No extra detail</p>
        )}
        <footer className="lux-note-card__foot">
          <span className="lux-note-card__when">
            <i className="fe fe-calendar" aria-hidden="true" />
            {formatWhen(note.noteDateTime)}
          </span>
          <div className="lux-note-card__actions" role="group" aria-label="Note actions">
            {pending && handleDone && (!permission || permission.editEnabled !== false) && (
              <button
                type="button"
                className="lux-note-card__icon-btn is-done"
                title="Mark as done"
                aria-label="Mark as done"
                onClick={() => handleDone(note)}
              >
                <i className="fe fe-check" aria-hidden="true" />
              </button>
            )}
            {!pending && onToggleComplete && (!permission || permission.editEnabled !== false) && (
              <button
                type="button"
                className="lux-note-card__icon-btn"
                title="Reopen note"
                aria-label="Reopen note"
                onClick={() => onToggleComplete(note)}
              >
                <i className="fe fe-rotate-ccw" aria-hidden="true" />
              </button>
            )}
            {(!permission || permission.editEnabled !== false) && onEdit && (
              <button
                type="button"
                className="lux-note-card__icon-btn"
                title="Edit note"
                aria-label="Edit note"
                onClick={() => onEdit(note)}
              >
                <i className="fe fe-edit-2" aria-hidden="true" />
              </button>
            )}
            {(!permission || permission.removeEnabled !== false) && onDelete && (
              <button
                type="button"
                className={classNames("lux-note-card__icon-btn", "is-delete", {
                  blink_text: confirmDelete,
                })}
                title={confirmDelete ? "Confirm delete" : "Delete note"}
                aria-label={confirmDelete ? "Confirm delete" : "Delete note"}
                onClick={this.handleDeleteClick}
              >
                <i className={classNames("fe", confirmDelete ? "fe-check" : "fe-trash-2")} aria-hidden="true" />
              </button>
            )}
          </div>
        </footer>
      </article>
    );
  }
}
