import React, { Component } from "react";
import classNames from "classnames/bind";
import { workItemActions } from "_actions";
import { connect } from "react-redux";
import { store } from "_helpers";
import { workItemConstants } from "_constants";
import { commonUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import { accessUtils } from "_helpers";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";
import UserCalendarSummary from "./components/calendar/UserCalendarSummary";
import LuxUserCalendarSidebar from "./components/calendar/LuxUserCalendarSidebar";
import LuxUserCalendarEventPanel from "./components/calendar/LuxUserCalendarEventPanel";
import LuxUserCalendarToolbar from "./components/calendar/LuxUserCalendarToolbar";
import LuxUserCalendarView from "./components/calendar/LuxUserCalendarView";
import WorkItemActivityDetailPopover from "./components/WorkItemActivityDetailPopover";
import { getPeriodLabel } from "./components/calendar/customCalendar.utils";
import {
  buildUserCalendarSummary,
  buildUpcomingEvents,
  filterCalendarEvents,
  getCalendarRangeForView,
  mapCalendarEvents,
  VIEW_MODE_LABELS,
} from "./components/calendar/userCalendar.utils";

class UserCalendarPage extends Component {
  constructor() {
    super();
    this.state = {
      permission: accessUtils.getUserCalendarAccessControl(),
      activityPermission: accessUtils.getWorkItemsCalendarAccessControl(),
      calendarDate: new Date(),
      calendarView: "week",
      statusFilter: "ALL",
      searchQuery: "",
      selectedEvent: null,
    };
    this.lastFetchKey = null;
  }

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    const userTeams = commonUtils.getUserTeams(this.props.userTeams);
    const viewMode = this.props.viewMode || "WORKITEMS";
    store.dispatch({
      type: workItemConstants.INITIALIZE_WORK_ITEMS_FULLCALENDAR,
      userTeams,
      viewMode,
    });
    this.loadCalendarRange(this.state.calendarDate, this.state.calendarView, userTeams);
  }

  getFilteredEvents = () => {
    const { statusFilter, searchQuery } = this.state;
    return filterCalendarEvents(this.props.events, statusFilter, searchQuery);
  };

  loadCalendarRange = (date, view, userTeams) => {
    const { start, end } = getCalendarRangeForView(date, view);
    const teams = userTeams || commonUtils.getUserTeams(this.props.userTeams);
    const selected = commonUtils.getSelectedUserTeamIds(teams);
    const selectedUserTeams = commonUtils.resolveUserTeamIds(
      selected.length ? selected : null
    );
    const fetchKey = `${view}|${selectedUserTeams.join(",")}|${start.format(dateUtils.SERVER_DATE_FORMAT)}|${end.format(dateUtils.SERVER_DATE_FORMAT)}`;
    if (fetchKey === this.lastFetchKey) return;
    this.lastFetchKey = fetchKey;

    store.dispatch(
      this.props.getWorkItemActivitiesForCalendar({
        userTeamIds: selectedUserTeams,
        startDate: start.format(dateUtils.SERVER_DATE_FORMAT),
        endDate: end.format(dateUtils.SERVER_DATE_FORMAT),
      })
    );
  };

  handleNavigate = (action) => {
    const { calendarDate, calendarView } = this.state;
    const m = dateUtils.convertDateToMoment(calendarDate).clone();

    if (action === "PREV") {
      if (calendarView === "month") m.subtract(1, "month");
      else if (calendarView === "week") m.subtract(1, "week");
      else if (calendarView === "day") m.subtract(1, "day");
      else m.subtract(30, "days");
    } else if (action === "NEXT") {
      if (calendarView === "month") m.add(1, "month");
      else if (calendarView === "week") m.add(1, "week");
      else if (calendarView === "day") m.add(1, "day");
      else m.add(30, "days");
    } else {
      const nextDate = dateUtils.getCurrentTime().toDate();
      this.setState({ calendarDate: nextDate });
      this.loadCalendarRange(nextDate, calendarView);
      return;
    }

    const nextDate = m.toDate();
    this.setState({ calendarDate: nextDate });
    this.loadCalendarRange(nextDate, calendarView);
  };

  handleViewChange = (view) => {
    if (!view || view === this.state.calendarView) return;
    this.lastFetchKey = null;
    this.setState({ calendarView: view, selectedEvent: null }, () => {
      this.loadCalendarRange(this.state.calendarDate, view);
    });
  };

  handleOpenDay = (calendarDate) => {
    this.lastFetchKey = null;
    this.setState({ calendarDate, calendarView: "day", selectedEvent: null }, () => {
      this.loadCalendarRange(calendarDate, "day");
    });
  };

  handleSelectEvent = (event) => {
    this.setState({ selectedEvent: event });
  };

  handleCloseDetail = () => {
    this.setState({ selectedEvent: null });
  };

  handleStatusFilter = (statusFilter) => {
    this.setState({ statusFilter, selectedEvent: null });
  };

  handleSearchChange = (searchQuery) => {
    this.setState({ searchQuery });
  };

  render() {
    const filteredEvents = this.getFilteredEvents();
    const summary = buildUserCalendarSummary(filteredEvents);
    const viewModeLabel = VIEW_MODE_LABELS[this.props.viewMode] || "work items";
    const upcoming = buildUpcomingEvents(filteredEvents, 12);
    const { selectedEvent, calendarDate, calendarView } = this.state;
    const showWorkItemPopover =
      selectedEvent &&
      selectedEvent.viewMode === "WORKITEMS" &&
      selectedEvent.resource;

    return (
      <div className="lux-user-calendar-page lux-bid-requests lux-register-page">
        <PageDataSourceReporter dataSource="api" />
        <LuxModuleIntro meta={DENSE_PAGE_META.userCalendar} />
        <UserCalendarSummary stat={summary} viewModeLabel={viewModeLabel} />

        <div className="lux-user-calendar-workspace">
          <LuxUserCalendarSidebar
            upcoming={upcoming}
            selectedEvent={selectedEvent}
            onSelectEvent={this.handleSelectEvent}
            viewModeLabel={viewModeLabel}
            isLoading={this.props.isCalendarLoading}
          />

          <div className="lux-user-calendar-main">
            <div
              className={classNames("lux-user-calendar-shell", "lux-custom-cal-root", {
                "is-loading": this.props.isCalendarLoading,
              })}
            >
              <LuxUserCalendarToolbar
                date={calendarDate}
                view={calendarView}
                periodLabel={getPeriodLabel(calendarDate, calendarView)}
                onNavigate={this.handleNavigate}
                onView={this.handleViewChange}
                viewMode={this.props.viewMode}
                isLoading={this.props.isCalendarLoading}
                statusFilter={this.state.statusFilter}
                onStatusFilterChange={this.handleStatusFilter}
                searchQuery={this.state.searchQuery}
                onSearchChange={this.handleSearchChange}
                userTeams={this.props.userTeams}
                onLoadRange={this.loadCalendarRange}
              />
              <LuxUserCalendarView
                events={filteredEvents}
                date={calendarDate}
                view={calendarView}
                onOpenDay={this.handleOpenDay}
                onSelectEvent={this.handleSelectEvent}
                onSelectSlot={this.handleCloseDetail}
                selectedEvent={selectedEvent}
                isLoading={this.props.isCalendarLoading}
              />
            </div>

            {selectedEvent && !showWorkItemPopover && (
              <LuxUserCalendarEventPanel
                event={selectedEvent}
                viewModeLabel={viewModeLabel}
                onClose={this.handleCloseDetail}
              />
            )}
          </div>
        </div>

        {showWorkItemPopover && (
          <WorkItemActivityDetailPopover
            show
            item={selectedEvent.resource}
            permission={this.state.activityPermission}
            onClose={this.handleCloseDetail}
          />
        )}
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  events: mapCalendarEvents(state.workItem.workItemsCalendar, state.workItem.viewMode),
  userTeams: state.workItem.userTeamsFC,
  viewMode: state.workItem.viewMode,
  isCalendarLoading: state.workItem.isCalendarLoading === true,
});

const mapDispatchToProps = () => ({
  getWorkItemActivitiesForCalendar: workItemActions.getWorkItemActivitiesForCalendar,
});

export default connect(mapStateToProps, mapDispatchToProps)(UserCalendarPage);
