import React from "react";
import classNames from "classnames/bind";
import { buildDocumentComplianceChartRows } from "config/document-vault.utils";

export default function DocumentCompliancePanel({ metrics, documents }) {
  const chartRows = buildDocumentComplianceChartRows(documents);
  const cards = [
    { id: "verified", label: "Verified", value: `${metrics.verifiedPct || 0}%`, hint: "Document completion", tone: "green" },
    { id: "pending", label: "Pending verification", value: metrics.pendingVerification || 0, hint: "HR queue", tone: "amber" },
    { id: "expiring", label: "Expiring (30d)", value: metrics.expiringCount || 0, hint: "Renewal needed", tone: "rose" },
    { id: "policy", label: "Policy compliance", value: `${metrics.policyCompliancePct || 0}%`, hint: "Acknowledgments", tone: "primary" },
  ];

  return (
    <div className="lux-doc-compliance">
      <div className="lux-hrms-dash__kpi-strip lux-doc-kpi-strip" role="list">
        {cards.map((card) => (
          <article
            key={card.id}
            className={classNames("lux-hrms-dash__kpi lux-doc-kpi", card.tone && `is-${card.tone}`)}
            role="listitem"
          >
            <span className="lux-hrms-dash__kpi-label">{card.label}</span>
            <strong className="lux-hrms-dash__kpi-value">{card.value}</strong>
            <span className="lux-hrms-dash__kpi-hint">{card.hint}</span>
          </article>
        ))}
      </div>

      <div className="lux-doc-compliance__chart">
        <h3 className="lux-doc-compliance__title">Documents by type</h3>
        {chartRows.length === 0 ? (
          <p className="lux-doc-compliance__empty">No document data to chart yet.</p>
        ) : (
          <ul className="lux-doc-compliance__bars">
            {chartRows.map((row) => {
              const verifiedPct = row.total ? Math.round((row.verified / row.total) * 100) : 0;
              return (
                <li key={row.label} className="lux-doc-compliance__bar-row">
                  <div className="lux-doc-compliance__bar-label">
                    <span>{row.label}</span>
                    <strong>{row.total}</strong>
                  </div>
                  <div className="lux-doc-compliance__bar-track" aria-hidden="true">
                    <span className="is-verified" style={{ width: `${verifiedPct}%` }} />
                    <span className="is-pending" style={{ width: `${100 - verifiedPct}%` }} />
                  </div>
                  <span className="lux-doc-compliance__bar-meta">{verifiedPct}% verified</span>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  );
}
