import React from "react";
import classNames from "classnames/bind";
import {
  getBenchStatusLabel,
  getBenchStatusTone,
  getEmployeeInitials,
  isRolloffWithinDays,
} from "config/resource-planning.utils";

export default function BenchRegister({ rows, loading, onSelect }) {
  if (loading) {
    return null;
  }

  return (
    <div className="lux-res-queue" aria-label="Bench availability register">
      <ul className="lux-res-queue__list">
        {rows.map((row) => {
          const statusTone = getBenchStatusTone(row.status);
          const isSoon = row.status === "ROLLING_OFF" && isRolloffWithinDays(row, 14);
          const isLongBench = row.status === "ON_BENCH" && row.daysOnBench >= 14;
          const initials = getEmployeeInitials(row.employeeName);
          const skills = String(row.primarySkills || "")
            .split(",")
            .map((s) => s.trim())
            .filter(Boolean)
            .slice(0, 3);

          return (
            <li key={row.id}>
              <button
                type="button"
                className={classNames("lux-res-card", `is-tone-${statusTone}`, {
                  "is-urgent": isSoon || isLongBench,
                  "is-open": row.status === "ON_BENCH" || row.status === "ROLLING_OFF" || row.status === "PARTIAL",
                })}
                onClick={() => onSelect && onSelect(row)}
              >
                <span className="lux-res-card__accent" aria-hidden="true" />

                <span className={classNames("lux-res-card__avatar", `is-${statusTone}`)} aria-hidden="true">
                  {initials}
                </span>

                <div className="lux-res-card__main">
                  <div className="lux-res-card__title-row">
                    <strong className="lux-res-card__title">{row.employeeName}</strong>
                    {isSoon ? (
                      <span className="lux-res-card__flag is-amber">
                        <i className="fe fe-zap" aria-hidden="true" />
                        Soon
                      </span>
                    ) : null}
                    {isLongBench ? (
                      <span className="lux-res-card__flag is-rose">
                        <i className="fe fe-alert-circle" aria-hidden="true" />
                        Long bench
                      </span>
                    ) : null}
                  </div>

                  <div className="lux-res-card__project">
                    <i className="fe fe-briefcase" aria-hidden="true" />
                    <span>
                      {row.role || "Role TBD"}
                      {row.department ? ` · ${row.department}` : ""}
                    </span>
                  </div>

                  <div className="lux-res-card__meta">
                    <span className="lux-res-card__chip is-count">
                      <i className="fe fe-percent" aria-hidden="true" />
                      {row.availabilityPct != null ? `${row.availabilityPct}% free` : "—"}
                    </span>
                    <span className="lux-res-card__chip">
                      <i className="fe fe-folder" aria-hidden="true" />
                      {row.lastProjectName || "No last project"}
                    </span>
                    <span className="lux-res-card__chip is-muted">
                      <i className="fe fe-calendar" aria-hidden="true" />
                      {row.lastProjectEndDate || row.availableFrom || "No date"}
                    </span>
                    {skills.map((skill) => (
                      <span key={skill} className="lux-res-card__chip">
                        {skill}
                      </span>
                    ))}
                  </div>
                </div>

                <div className="lux-res-card__aside">
                  <span className={classNames("lux-res-card__priority", `is-${statusTone}`)}>
                    {getBenchStatusLabel(row.status)}
                  </span>
                  <span
                    className={classNames("lux-res-card__status", {
                      "is-rose": isLongBench,
                      "is-amber": isSoon && !isLongBench,
                      "is-sky": !isSoon && !isLongBench,
                    })}
                  >
                    {row.daysOnBench > 0 ? `${row.daysOnBench}d bench` : "Ready"}
                  </span>
                  <span className="lux-res-card__open">
                    Open
                    <i className="fe fe-chevron-right" aria-hidden="true" />
                  </span>
                </div>
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}
