function workspaceTeamQuery(extra) {
  const query = {
    userTeamId: commonUtils.getCurrentUserTeamId(),
    employeeId: commonUtils.getCurrentUserId(),
  };
  const teamIds = commonUtils.getCurrentUserTeamIds();
  if (Array.isArray(teamIds) && teamIds.length > 0) {
    query.userTeamIds = teamIds;
  }
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

function workspaceTeamQueryString(extra) {
  const query = workspaceTeamQuery(extra);
  return Object.keys(query)
    .map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(query[key])}`)
    .join("&");
}

async function getMyWorkQueueFromApi() {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.WORKSPACE_API_PATH}/my-work`,
    workspaceTeamQuery()
  );
  const payload = (response && response.payload) || response || [];
  return { payload: Array.isArray(payload) ? payload : [], source: "api" };
}

async function getMyWorkQueue() {

  if (shouldUseWorkspaceHomeApi()) {
    try {
      return await getMyWorkQueueFromApi();
    } catch (e) {
      // fall through
    }
  }

  return apiErrorResult(null);
}

