async function markNotificationRead(notificationId) {
  if (shouldUseWorkspaceHomeApi()) {
    try {
      const response = await axiosUtils.post(
        `${urlConfig.WORKSPACE_API_PATH}/notifications/${notificationId}/read?${workspaceTeamQueryString()}`
      );
      recordWorkspaceAudit(AUDIT_ACTION_TYPES.UPDATED, "Notification read", notificationId);
      return { payload: (response && response.payload) || response, source: "api" };
    } catch (e) {
      // fall through
    }
  }
  throw new Error("Unable to mark notification via API.");

}

