async function getHomeDashboardFromApi(activePersona) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.WORKSPACE_API_PATH}/home`,
    workspaceTeamQuery({ activePersona: activePersona || undefined })
  );
  const raw = (response && response.payload) || response || {};
  if (raw.metrics && raw.insights) {
    return { payload: raw, source: "api" };
  }
  // Incomplete API payload — fail closed rather than inventing client metrics.
  return { payload: null, source: "api-error", reason: "incomplete-home-payload" };
}

async function aggregateHomeDashboard(activePersona, source) {
  const [workResult, notificationResult, approvalResult, favoritesResult, savedViewsResult] =
    await Promise.all([
      getMyWorkQueue(),
      getNotifications(),
      universalApprovalService.listInbox({ status: "ALL" }),
      listFavorites(),
      listSavedViews(),
    ]);

  const payload = buildWorkspaceHomePayload({
    workItems: workResult.payload || [],
    notifications: notificationResult.payload || [],
    approvals: approvalResult.payload || [],
    favorites: favoritesResult.payload || [],
    savedViews: savedViewsResult.payload || [],
    activePersona: activePersona || "EMPLOYEE",
  });

  const mergedSource = [workResult.source, notificationResult.source, approvalResult.source]
    .filter(Boolean)
    .includes("api")
    ? "api"
    : source || "client";

  return { payload, source: mergedSource };
}

async function getHomeDashboard(activePersona) {

  if (envconfig.USE_WORKSPACE_HOME_API === true) {
    try {
      return await getHomeDashboardFromApi(activePersona);
    } catch (e) {
      return { payload: null, source: "api-error", error: e };
    }
  }

  try {
    return await aggregateHomeDashboard(activePersona, "client");
  } catch (e) {
    return {
      payload: buildWorkspaceHomePayload({ activePersona: activePersona || "EMPLOYEE" }),
      source: "client",
    };
  }
}

