import React, { Component } from "react";
import PageInnerHeader from "views/common/PageInnerHeader";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import PageCreateButton from "views/common/fragments/PageCreateButton";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxRegisterPagination from "views/common/fragments/LuxRegisterPagination";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";
import LuxRegisterListSection from "views/common/lux/LuxRegisterListSection";
import {
  buildPulseCardsFromKpis,
  buildShownPulse,
  mergePulseCards,
} from "views/common/lux/registerAtelier.utils";
import {
  paginateRegisterList,
  REGISTER_DEFAULT_PAGE_SIZE,
  REGISTER_PAGE_SIZE_OPTIONS,
} from "_helpers/registerPagination.utils";
import { documentVaultService } from "_services/documentVault.service";
import { commonUtils } from "_helpers";
import { shouldUseDocumentVaultApi } from "config/document-vault.config";
import FileManagerPageSummary from "./components/filemanager/FileManagerPageSummary";
import FileManagerRecentStrip from "./components/filemanager/FileManagerRecentStrip";
import FileManagerToolbar from "./components/filemanager/FileManagerToolbar";
import FileManagerListTable from "./components/filemanager/FileManagerListTable";
import FileManagerGridView from "./components/filemanager/FileManagerGridView";
import {
  FILE_MANAGER_ROOT_ID,
  mapVaultDocumentsToFileItems,
  getRecentFileManagerItems,
  getFolderBreadcrumb,
  filterFileManagerItems,
  buildFileManagerSummary,
} from "./components/filemanager/fileManager.utils";

/**
 * W1-E03 — Project file manager backed by Document Vault (sourceEntityType=PROJECT).
 */
class FileManagerPage extends Component {
  constructor() {
    super();
    this.state = {
      allItems: [],
      loading: true,
      loadError: null,
      dataSource: null,
      currentFolderId: FILE_MANAGER_ROOT_ID,
      viewMode: "list",
      page: 1,
      pageSize: REGISTER_DEFAULT_PAGE_SIZE,
      filterOptions: {
        SHOW: {
          options: [
            { name: "ALL", label: "All" },
            { name: "FOLDERS", label: "Folders" },
            { name: "FILES", label: "Files" },
            { name: "SHARED", label: "Shared" },
            { name: "MINE", label: "Mine" },
          ],
          selected: "ALL",
        },
        SORT: {
          options: [
            { name: "NAME", label: "Name" },
            { name: "DATE", label: "Last updated" },
            { name: "SIZE", label: "Size" },
          ],
          selected: "NAME",
          directionUp: true,
        },
        filterText: null,
      },
    };
  }

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    this.loadDocuments();
  }

  loadDocuments = async () => {
    this.setState({ loading: true, loadError: null });
    if (!shouldUseDocumentVaultApi()) {
      this.setState({
        loading: false,
        allItems: [],
        dataSource: "disabled",
        loadError: "Document Vault API is not enabled for this environment.",
      });
      return;
    }
    const projectId = this.props.projectId || undefined;
    const result = await documentVaultService.listDocuments({
      sourceEntityType: "PROJECT",
      projectId,
    });
    if (!result || result.source === "api-error") {
      this.setState({
        loading: false,
        allItems: [],
        dataSource: "api-error",
        loadError: "Unable to load project documents from Document Vault.",
      });
      return;
    }
    this.setState({
      loading: false,
      allItems: mapVaultDocumentsToFileItems(result.payload || []),
      dataSource: result.source,
      loadError: null,
    });
  };

  getVisibleItems = () => {
    return filterFileManagerItems(this.state.allItems, {
      parentId: this.state.currentFolderId,
      filterOptions: this.state.filterOptions,
    });
  };

  getSummaryItems = () => {
    if (this.state.currentFolderId === FILE_MANAGER_ROOT_ID) {
      return this.state.allItems;
    }
    const descendants = new Set([this.state.currentFolderId]);
    let changed = true;
    while (changed) {
      changed = false;
      this.state.allItems.forEach((item) => {
        if (descendants.has(item.parentId) && !descendants.has(item.id)) {
          descendants.add(item.id);
          changed = true;
        }
      });
    }
    return this.state.allItems.filter((i) => descendants.has(i.id));
  };

  handleFilterChange = (filterOptions) => {
    this.setState({ filterOptions, page: 1 });
  };

  onFilterTextChange = (value) => {
    this.handleFilterChange({
      ...this.state.filterOptions,
      filterText: value,
    });
  };

  handleSummaryQuickFilter = (showValue) => {
    this.handleFilterChange({
      ...this.state.filterOptions,
      SHOW: { ...this.state.filterOptions.SHOW, selected: showValue },
    });
  };

  handlePageChange = (page) => this.setState({ page });
  handlePageSizeChange = (pageSize) => this.setState({ pageSize, page: 1 });
  handleNavigateFolder = (folderId) => this.setState({ currentFolderId: folderId, page: 1 });
  handleOpenItem = (item) => {
    if (item.type === "folder") {
      this.handleNavigateFolder(item.id);
    }
  };
  handleViewModeChange = (viewMode) => this.setState({ viewMode });

  handleUpload = async () => {
    const title = window.prompt("Document title");
    if (!title) return;
    const fileName = window.prompt("File name (e.g. report.pdf)", `${title}.pdf`);
    if (!fileName) return;
    const result = await documentVaultService.uploadDocument({
      title,
      fileName,
      type: "OTHER",
      category: "PROJECT",
      sourceEntityType: "PROJECT",
      projectId: this.props.projectId || undefined,
      employeeId: String(commonUtils.getCurrentUserId() || ""),
          uploadedBy: commonUtils.getCurrentUserName() || "User",
    });
    if (!result || result.source === "api-error") {
      window.alert("Upload failed. Document Vault did not accept the file.");
      return;
    }
    await this.loadDocuments();
  };

  handleNewFolder = () => {
    window.alert("Folders are not persisted in Document Vault yet. Upload project files instead.");
  };

  handleDownload = async (item) => {
    if (!item || !item.documentRef) return;
    const result = await documentVaultService.getDownloadUrl(item.documentRef);
    if (result && result.payload && result.payload.url) {
      window.open(result.payload.url, "_blank", "noopener,noreferrer");
      return;
    }
    window.alert("Download URL unavailable for this document.");
  };

  handleShare = () => {
    window.alert("Sharing is managed through Document Vault visibility controls.");
  };

  handleRename = () => {
    window.alert("Rename is not available in this release.");
  };

  handleDelete = () => {
    window.alert("Delete is not available from the file manager in this release.");
  };

  getCurrentFolderName = (breadcrumb) => {
    if (!breadcrumb || breadcrumb.length === 0) return "All files";
    return breadcrumb[breadcrumb.length - 1].name;
  };

  render() {
    const { allItems, loading, loadError, dataSource } = this.state;
    const visibleItems = this.getVisibleItems();
    const summaryItems = this.getSummaryItems();
    const summaryStat = buildFileManagerSummary(summaryItems);
    const pagination = paginateRegisterList(visibleItems, this.state.page, this.state.pageSize);
    const pageItems = pagination.items;
    const breadcrumb = getFolderBreadcrumb(this.state.currentFolderId, allItems);
    const currentFolderName = this.getCurrentFolderName(breadcrumb);
    const recentItems =
      this.state.currentFolderId === FILE_MANAGER_ROOT_ID
        ? getRecentFileManagerItems(allItems)
        : getRecentFileManagerItems(visibleItems);

    const showRecent =
      this.state.currentFolderId === FILE_MANAGER_ROOT_ID &&
      !this.state.filterOptions.filterText &&
      this.state.filterOptions.SHOW.selected === "ALL" &&
      recentItems.length > 0;
    const registerPulse = mergePulseCards(
      buildPulseCardsFromKpis(summaryStat && summaryStat.kpis),
      buildShownPulse(pagination.total, "Items")
    );

    return (
      <div className="lux-file-manager lux-bid-requests lux-register-page" data-testid="page-project-filemanager">
        <PageDataSourceReporter dataSource={dataSource || "api"} />
        <LuxModuleIntro
          meta={DENSE_PAGE_META.fileManager}
          actions={
            <PageCreateButton onClick={this.handleUpload}>Upload file</PageCreateButton>
          }
        />
        <PageInnerHeader
          showFilter
          stickytop={false}
          isLoading={loading}
          showUserTeamMenu={false}
          filterOptions={this.state.filterOptions}
          handleFilterChange={this.handleFilterChange}
          onFilterTextChange={this.onFilterTextChange}
        />

        <FileManagerPageSummary
          stat={summaryStat}
          visibleCount={visibleItems.length}
          filterOptions={this.state.filterOptions}
          isLoading={loading}
          currentFolderName={currentFolderName}
          onQuickFilter={this.handleSummaryQuickFilter}
        />

        {dataSource ? (
          <p className="lux-file-manager__source" data-testid="filemanager-data-source">
            Source: {dataSource === "api" ? "Document Vault" : dataSource}
          </p>
        ) : null}

        {loadError ? (
          <LuxRegisterEmptyState
            variant="files"
            eyebrow="Document Vault"
            title="Project files unavailable"
            description={loadError}
            onCreate={this.loadDocuments}
            createLabel="Retry"
            showCreate
          />
        ) : null}

        {!loadError && showRecent && (
          <FileManagerRecentStrip items={recentItems} onOpenItem={this.handleOpenItem} />
        )}

        {!loadError && (
          <FileManagerToolbar
            breadcrumb={breadcrumb}
            viewMode={this.state.viewMode}
            onViewModeChange={this.handleViewModeChange}
            onNavigate={this.handleNavigateFolder}
            onUpload={this.handleUpload}
            onNewFolder={this.handleNewFolder}
          />
        )}

        {!loadError && visibleItems.length > 0 && (
          <LuxRegisterListSection
            tone="indigo"
            kickerIcon="fe fe-folder"
            kicker="Document register"
            title={DENSE_PAGE_META.fileManager.title || "Files"}
            subtitle={currentFolderName ? `Browsing ${currentFolderName}` : "Project document vault"}
            pulseCards={registerPulse}
          >
            {this.state.viewMode === "list" ? (
              <FileManagerListTable
                items={pageItems}
                totalCount={pagination.total}
                isLoading={loading}
                pagination={pagination}
                onPageChange={this.handlePageChange}
                onPageSizeChange={this.handlePageSizeChange}
                onOpenItem={this.handleOpenItem}
                onDownload={this.handleDownload}
                onShare={this.handleShare}
                onRename={this.handleRename}
                onDelete={this.handleDelete}
              />
            ) : (
              <div className="lux-file-grid-wrap">
                <FileManagerGridView
                  items={pageItems}
                  onOpenItem={this.handleOpenItem}
                  onDownload={this.handleDownload}
                  onShare={this.handleShare}
                />
                {pagination.total > 0 && (
                  <LuxRegisterPagination
                    pagination={pagination}
                    onPageChange={this.handlePageChange}
                    onPageSizeChange={this.handlePageSizeChange}
                    pageSizeOptions={REGISTER_PAGE_SIZE_OPTIONS}
                    summaryLabel="items"
                    className="lux-register-list__pagination"
                  />
                )}
              </div>
            )}
          </LuxRegisterListSection>
        )}

        {!loadError && !loading && visibleItems.length === 0 && (
          <LuxRegisterEmptyState
            variant="files"
            eyebrow="Document Vault"
            title="No project documents yet"
            description="Project files are loaded from Document Vault with sourceEntityType=PROJECT. Upload a file to persist it against the vault."
            hints={[
              "Only live Document Vault rows appear here — no demo files",
              "Filter by project when opened from a project context",
            ]}
            createLabel="Upload file"
            onCreate={this.handleUpload}
            showCreate
          />
        )}
      </div>
    );
  }
}

export default FileManagerPage;
