export function getDefaultChecklistData() {
    return {
        metaData: {
            complete: false,
            active: true,
        },
    };
}

export function isQuestionAnswered(question) {
    if (!question) return false;
    return (
        question.answer !== undefined &&
        question.answer !== "" &&
        question.answer !== null
    );
}

export function getChecklistProgress(checklistData) {
    const questions = (checklistData && checklistData.questionDataList) || [];
    const total = questions.length;
    const answered = questions.filter(isQuestionAnswered).length;
    const mandatoryQuestions = questions.filter((q) => q.mandatory === true);
    const mandatoryAnswered = mandatoryQuestions.filter(isQuestionAnswered).length;
    const complete = !!(checklistData && checklistData.metaData && checklistData.metaData.complete);
    const percent = total > 0 ? Math.round((answered / total) * 100) : 0;
    const mandatoryPercent = mandatoryQuestions.length > 0
        ? Math.round((mandatoryAnswered / mandatoryQuestions.length) * 100)
        : 100;
    const remaining = Math.max(0, total - answered);

    let status = "empty";
    if (complete) status = "complete";
    else if (total > 0 && answered === 0) status = "ready";
    else if (total > 0) status = "progress";

    return {
        total,
        answered,
        remaining,
        mandatoryTotal: mandatoryQuestions.length,
        mandatoryAnswered,
        complete,
        percent,
        mandatoryPercent,
        hasChecklist: total > 0,
        status,
    };
}

export function getChecklistStatusLabel(progress) {
    if (!progress) return "Not started";
    if (progress.complete) return "Completed";
    if (!progress.hasChecklist) return "Not started";
    if (progress.answered === 0) return "Ready to fill";
    return "In progress";
}

export function formatChecklistAnswer(question) {
    if (!question) return "—";
    if (question.type === "boolean") {
        if (question.answer === false || question.answer === "false") return "No";
        if (question.answer === true || question.answer === "true") return "Yes";
    }
    return question.answer || "—";
}

export function validateMandatoryAnswers(checklistData) {
    const questions = (checklistData && checklistData.questionDataList) || [];
    return questions.every((question) => {
        if (!question.mandatory) return true;
        return question.answer !== undefined && question.answer !== "";
    });
}
