/**
 * Shared persona ↔ page matrix helpers for Roles (persona-first) and
 * Persona navigation (page-first). Page edits always target the org pagePersonaMap.
 */

import { PERSONA_TYPES, resolveAllowedPersonasFromModules } from "config/persona-navigation.utils";
import { listCatalogPagesForPersonaAdmin } from "config/persona-page-map.config";
import { isOrgPersonaDisabled } from "config/org-access-policy.config";
import { ROLE_PERSONA_META, ROLE_PERSONA_OPTIONS } from "config/role-permission.config";

export const EDITABLE_PERSONAS = PERSONA_TYPES.filter((p) => p !== "CLIENT");

/** Allowed personas that are not org-disabled — candidates for Default persona. */
export function listSelectableDefaultPersonas(allowedPersonas) {
  return (allowedPersonas || []).filter((code) => code && !isOrgPersonaDisabled(code));
}

/** Prefer current default when selectable; otherwise first enabled (org) persona. */
export function resolveDefaultPersona(allowedPersonas, preferred) {
  const selectable = listSelectableDefaultPersonas(allowedPersonas);
  const preferredCode = preferred != null ? String(preferred).trim().toUpperCase() : "";
  if (preferredCode && selectable.includes(preferredCode)) {
    return preferredCode;
  }
  return selectable[0] || "";
}

export function getPersonaAccessMeta(code) {
  return (
    ROLE_PERSONA_META[code] || {
      label: code,
      icon: "fe fe-user",
      tone: "slate",
    }
  );
}

export function clonePagePersonaDraft(map) {
  const draft = {};
  Object.keys(map || {}).forEach((path) => {
    draft[path] = [...(map[path] || [])];
  });
  return draft;
}

/** Effective persona list for a catalog page given draft overrides. */
export function getEffectivePersonasForPage(pageRow, pageMapDraft) {
  if (!pageRow) {
    return [];
  }
  const override = pageMapDraft && pageMapDraft[pageRow.path];
  if (override != null) {
    return [...override];
  }
  return Array.isArray(pageRow.defaultPersonas) ? [...pageRow.defaultPersonas] : [];
}

export function isPageUsingOverride(pageRow, pageMapDraft) {
  return !!(pageRow && pageMapDraft && Object.prototype.hasOwnProperty.call(pageMapDraft, pageRow.path));
}

/**
 * Whether a persona is allowed on a page by catalog/override rules.
 * Product default with an empty personas[] = open to all.
 * An explicit override with [] = nobody (until personas are added back).
 */
export function isPersonaOnPage(pageRow, personaCode, pageMapDraft) {
  if (isPageUsingOverride(pageRow, pageMapDraft)) {
    const override = (pageMapDraft && pageMapDraft[pageRow.path]) || [];
    return override.includes(personaCode);
  }
  const defaults = Array.isArray(pageRow.defaultPersonas) ? pageRow.defaultPersonas : [];
  if (!defaults.length) {
    return true;
  }
  return defaults.includes(personaCode);
}

export function isModuleFlagEnabledForPage(pageRow, roleModules) {
  if (!pageRow || !pageRow.flagModule || !pageRow.flag) {
    return true;
  }
  const mod = roleModules && roleModules[pageRow.flagModule];
  if (!mod) {
    return false;
  }
  return mod[pageRow.flag] === true;
}

/**
 * Seed personas when promoting a page from product default to an editable override.
 */
export function seedPersonasForPageOverride(pageRow, editablePersonas = EDITABLE_PERSONAS) {
  if (pageRow && Array.isArray(pageRow.defaultPersonas) && pageRow.defaultPersonas.length > 0) {
    return editablePersonas.filter((p) => pageRow.defaultPersonas.includes(p));
  }
  return [...editablePersonas];
}

export function togglePersonaOnPageInDraft(draft, pageRow, personaCode, editablePersonas = EDITABLE_PERSONAS) {
  if (!pageRow || !personaCode) {
    return draft || {};
  }
  const path = pageRow.path;
  const current = draft && draft[path];
  const base =
    current != null ? [...current] : seedPersonasForPageOverride(pageRow, editablePersonas);
  const set = new Set(base);
  if (set.has(personaCode)) {
    set.delete(personaCode);
  } else {
    set.add(personaCode);
  }
  const next = editablePersonas.filter((p) => set.has(p));
  return { ...(draft || {}), [path]: next };
}

export function resetPageToProductDefault(draft, path) {
  const next = { ...(draft || {}) };
  delete next[path];
  return next;
}

export function setPageOverridePersonas(draft, path, personas, editablePersonas = EDITABLE_PERSONAS) {
  const set = new Set(personas || []);
  return {
    ...(draft || {}),
    [path]: editablePersonas.filter((p) => set.has(p)),
  };
}

/**
 * Pages grouped for one persona, with enable + module + source metadata.
 */
export function buildPersonaPageRows(personaCode, pages, pageMapDraft, roleModules) {
  const rows = [];
  (pages || listCatalogPagesForPersonaAdmin()).forEach((page) => {
    const personaAllowed = isPersonaOnPage(page, personaCode, pageMapDraft);
    const moduleEnabled = isModuleFlagEnabledForPage(page, roleModules);
    const usingOverride = isPageUsingOverride(page, pageMapDraft);
    const effective = getEffectivePersonasForPage(page, pageMapDraft);
    const effectiveOpen = !usingOverride && effective.length === 0;
    rows.push({
      ...page,
      personaAllowed,
      moduleEnabled,
      usingOverride,
      effectiveOpen,
      wouldShow: personaAllowed && moduleEnabled,
    });
  });
  return rows;
}

export function groupPersonaPageRows(rows) {
  const groups = [];
  const byId = {};
  (rows || []).forEach((row) => {
    const id = row.groupId || "other";
    if (!byId[id]) {
      byId[id] = {
        groupId: id,
        groupName: row.groupName || id,
        pages: [],
        enabledCount: 0,
      };
      groups.push(byId[id]);
    }
    byId[id].pages.push(row);
    if (row.personaAllowed) {
      byId[id].enabledCount += 1;
    }
  });
  return groups;
}

export function summarizePersonaPages(personaCode, pages, pageMapDraft, roleModules) {
  const rows = buildPersonaPageRows(personaCode, pages, pageMapDraft, roleModules);
  const enabled = rows.filter((r) => r.personaAllowed).length;
  const visible = rows.filter((r) => r.wouldShow).length;
  const blockedByModule = rows.filter((r) => r.personaAllowed && !r.moduleEnabled).length;
  return {
    total: rows.length,
    enabled,
    visible,
    blockedByModule,
    rows,
    groups: groupPersonaPageRows(rows),
  };
}

/** Suggested allowed personas from role module flags (legacy heuristic). */
export function suggestPersonasFromRoleModules(roleModules) {
  return resolveAllowedPersonasFromModules(roleModules || {}).filter((p) =>
    ROLE_PERSONA_OPTIONS.includes(p)
  );
}

export function buildPersonaDraftFromRole(role) {
  const personaModules = (role && role.personaModules) || {};
  const configured = personaModules.configured === true;
  let allowed = Array.isArray(personaModules.allowedPersonas)
    ? [...personaModules.allowedPersonas]
    : [];
  if (!configured || allowed.length === 0) {
    allowed = suggestPersonasFromRoleModules(role && role.modules);
  }
  const preferred =
    personaModules.defaultPersona && allowed.includes(personaModules.defaultPersona)
      ? personaModules.defaultPersona
      : null;
  return {
    allowedPersonas: allowed,
    defaultPersona: resolveDefaultPersona(allowed, preferred) || allowed[0] || "EMPLOYEE",
    personaSwitchEnabled: personaModules.personaSwitchEnabled !== false,
    configured,
  };
}
