import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { WorkspacePanelHead } from "views/workspace/components/WorkspaceLuxShared";

const ATTENTION_TONES = ["rose", "amber", "blue", "green", "primary", "violet"];

function getAttentionTone(index) {
  return ATTENTION_TONES[index % ATTENTION_TONES.length];
}

export default function WorkspaceAttentionPanel({ items = [], loading }) {
  if (loading) {
    return (
      <section
        className="lux-hrms-dash__panel lux-workspace-home-panel lux-workspace-home-panel--attention"
        aria-label="What needs attention"
        aria-busy="true"
      >
        <WorkspacePanelHead title="What needs attention" subtitle="Prioritized actions for today" />
        <div className="lux-hrms-dash__panel-body">
          <p className="lux-hrms-dash__empty">Loading attention items…</p>
        </div>
      </section>
    );
  }

  if (items.length === 0) {
    return (
      <section
        className="lux-hrms-dash__panel lux-workspace-home-panel lux-workspace-home-panel--attention"
        aria-label="What needs attention"
      >
        <WorkspacePanelHead title="What needs attention" subtitle="Prioritized actions for today" />
        <div className="lux-hrms-dash__panel-body">
          <p className="lux-hrms-dash__empty">
            Nothing urgent right now — approvals, expiring documents, payroll exceptions, and bench alerts will surface here.
          </p>
        </div>
      </section>
    );
  }

  return (
    <section className="lux-hrms-dash__panel lux-workspace-home-panel lux-workspace-home-panel--attention" aria-label="What needs attention">
      <WorkspacePanelHead
        title="What needs attention"
        subtitle="Prioritized actions for today"
      />
      <div className="lux-hrms-dash__panel-body">
        <ul className="lux-workspace-attention__grid" role="list">
          {items.map((item, index) => {
            const tone = item.tone || getAttentionTone(index);
            return (
              <li key={item.id} role="listitem">
                <Link
                  to={item.path || "/workspace/home"}
                  className={classNames("lux-workspace-attention__card", `is-${tone}`)}
                >
                  <span className="lux-workspace-attention__icon" aria-hidden="true">
                    <i className={item.icon || "fe fe-alert-circle"} />
                  </span>
                  <span className="lux-workspace-attention__copy">
                    <strong>{item.label}</strong>
                    {item.hint && <small>{item.hint}</small>}
                  </span>
                  <i className="fe fe-arrow-right lux-workspace-attention__chevron" aria-hidden="true" />
                </Link>
              </li>
            );
          })}
        </ul>
      </div>
    </section>
  );
}
