import React, { Component } from "react";
import { recruitingService } from "_services/recruiting/recruiting.service";
import RecruitingLuxPage, {
  RecruitingActionButton,
  RecruitingLuxPanel,
} from "views/recruiting/components/RecruitingLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class CandidatesPage extends Component {
  state = {
    loading: true,
    loadError: null,
    rows: [],
    saving: false,
    form: { name: "", email: "", source: "", resumeDocumentRef: "" },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Candidates");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await recruitingService.listCandidates();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load candidates"),
      });
    }
  };

  handleCreate = async (e) => {
    e.preventDefault();
    const { form } = this.state;
    if (!form.name) return;
    this.setState({ saving: true });
    const result = await recruitingService.createCandidate({
      name: form.name,
      email: form.email || null,
      source: form.source || null,
      resumeDocumentRef: form.resumeDocumentRef || null,
    });
    this.setState({ saving: false });
    if (result.source === "api") {
      this.setState({ form: { name: "", email: "", source: "", resumeDocumentRef: "" } });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Create failed") });
    }
  };

  render() {
    const { loading, loadError, rows, saving, form } = this.state;
    return (
      <RecruitingLuxPage
        testId="recruiting-candidates-page"
        dataSource={rows.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        loading={loading}
        onRefresh={this.load}
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-users",
          eyebrow: "People · ATS",
          titleLead: "Candidate",
          titleAccent: "pipeline",
          lede: "Resume links use Document Vault refs only — no blob stored on the candidate row.",
        }}
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load candidates">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        <RecruitingLuxPanel title="Create candidate" icon="fe fe-plus">
          <form className="lux-module-inline-form" onSubmit={this.handleCreate}>
            <div className="form-row">
              <div className="col-md-3">
                <input
                  className="form-control"
                  placeholder="Name"
                  value={form.name}
                  onChange={(e) => this.setState({ form: { ...form, name: e.target.value } })}
                />
              </div>
              <div className="col-md-3">
                <input
                  className="form-control"
                  placeholder="Email"
                  value={form.email}
                  onChange={(e) => this.setState({ form: { ...form, email: e.target.value } })}
                />
              </div>
              <div className="col-md-2">
                <input
                  className="form-control"
                  placeholder="Source"
                  value={form.source}
                  onChange={(e) => this.setState({ form: { ...form, source: e.target.value } })}
                />
              </div>
              <div className="col-md-2">
                <input
                  className="form-control"
                  placeholder="Vault documentRef"
                  value={form.resumeDocumentRef}
                  onChange={(e) => this.setState({ form: { ...form, resumeDocumentRef: e.target.value } })}
                />
              </div>
              <div className="col-md-2">
                <RecruitingActionButton type="submit" disabled={saving}>
                  Create
                </RecruitingActionButton>
              </div>
            </div>
          </form>
        </RecruitingLuxPanel>
        <RecruitingLuxPanel title="Candidates" meta={`${rows.length} record${rows.length === 1 ? "" : "s"}`} icon="fe fe-list">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
          {!loading && rows.length === 0 ? (
            <LuxRegisterEmptyState
              title="No candidates yet"
              description="Add a candidate to begin stage transitions."
              showCreate={false}
            />
          ) : !loading ? (
            <div className="lux-module-table-wrap">
              <table className="table table-sm mb-0">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Name</th>
                    <th>Stage</th>
                    <th>Source</th>
                    <th>Resume ref</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((c) => (
                    <tr key={c.candidateRef || c.id}>
                      <td>{c.candidateRef}</td>
                      <td>{c.name}</td>
                      <td>
                        <span className={`lux-expansion-status is-${String(c.stage || "applied").toLowerCase()}`}>
                          {c.stage || "Applied"}
                        </span>
                      </td>
                      <td>{c.source}</td>
                      <td className="small">{c.resumeDocumentRef || "—"}</td>
                      <td>
                        {c.stage === "APPLIED" && (
                          <RecruitingActionButton
                            type="button"
                            variant="ghost"
                            className="lux-onb-action--compact"
                            onClick={() =>
                              recruitingService.transitionStage(c.candidateRef, "SCREENING").then(this.load)
                            }
                          >
                            → Screening
                          </RecruitingActionButton>
                        )}
                        {c.stage === "SCREENING" && (
                          <RecruitingActionButton
                            type="button"
                            variant="ghost"
                            className="lux-onb-action--compact"
                            onClick={() =>
                              recruitingService.transitionStage(c.candidateRef, "INTERVIEW").then(this.load)
                            }
                          >
                            → Interview
                          </RecruitingActionButton>
                        )}
                        {c.stage === "INTERVIEW" && (
                          <RecruitingActionButton
                            type="button"
                            variant="ghost"
                            className="lux-onb-action--compact"
                            onClick={() =>
                              recruitingService.transitionStage(c.candidateRef, "OFFER").then(this.load)
                            }
                          >
                            → Offer
                          </RecruitingActionButton>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : null}
        </RecruitingLuxPanel>
      </RecruitingLuxPage>
    );
  }
}

export default CandidatesPage;
