import { PAYCHECK_STATUSES } from "config/payroll.config";
import { formatPayrollCurrency, formatPayrollDate } from "config/payroll.utils";

export function getPaycheckStatusTone(status) {
  const normalized = String(status || "").toLowerCase();
  if (normalized === "published") return "success";
  if (normalized === "draft") return "warning";
  if (normalized === "retracted") return "danger";
  return "slate";
}

export function filterPaychecks(paychecks, filters = {}) {
  const rows = paychecks || [];
  const { status, runId, employeeId, query } = filters;
  return rows.filter((row) => {
    if (status && status !== "ALL" && row.status !== status) {
      return false;
    }
    if (runId && row.runId !== runId) {
      return false;
    }
    if (employeeId && String(row.employeeId) !== String(employeeId)) {
      return false;
    }
    if (query) {
      const q = String(query).toLowerCase();
      const haystack = [row.employeeName, row.runName, row.periodLabel, row.department]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      if (!haystack.includes(q)) {
        return false;
      }
    }
    return true;
  });
}

export function buildPaycheckAdminMetrics(paychecks) {
  const rows = paychecks || [];
  return {
    total: rows.length,
    published: rows.filter((row) => row.status === PAYCHECK_STATUSES.PUBLISHED).length,
    draft: rows.filter((row) => row.status === PAYCHECK_STATUSES.DRAFT).length,
    retracted: rows.filter((row) => row.status === PAYCHECK_STATUSES.RETRACTED).length,
    netTotal: rows.reduce((sum, row) => sum + (Number(row.net) || 0), 0),
    employees: new Set(rows.map((row) => row.employeeId).filter(Boolean)).size,
  };
}

export function buildPaycheckInsights(paychecks) {
  const metrics = buildPaycheckAdminMetrics(paychecks);
  const insights = [];

  if (metrics.draft > 0) {
    insights.push({
      id: "draft",
      tone: "amber",
      icon: "fe fe-file-text",
      title: `${metrics.draft} draft paycheck(s)`,
      copy: "Publish after payroll run is finalized and amounts are verified.",
    });
  }
  if (metrics.published > 0) {
    insights.push({
      id: "published",
      tone: "green",
      icon: "fe fe-check-circle",
      title: `${metrics.published} published to employees`,
      copy: "Employees can view payslips in My paychecks and download PDF copies.",
      path: "/workspace/my-paychecks",
    });
  }
  if (metrics.retracted > 0) {
    insights.push({
      id: "retracted",
      tone: "rose",
      icon: "fe fe-alert-triangle",
      title: `${metrics.retracted} retracted paycheck(s)`,
      copy: "Review and republish corrected payslips after payroll adjustments.",
    });
  }
  if (metrics.total === 0) {
    insights.push({
      id: "empty",
      tone: "blue",
      icon: "fe fe-dollar-sign",
      title: "No paychecks generated yet",
      copy: "Finalize a payroll run to generate employee paycheck records.",
      path: "/payroll/runs",
    });
  }
  return insights.slice(0, 3);
}

export function buildMyPaycheckMetrics(paychecks) {
  const rows = (paychecks || []).filter((row) => row.status === PAYCHECK_STATUSES.PUBLISHED);
  const latest = rows
    .slice()
    .sort((a, b) => String(b.payDate || "").localeCompare(String(a.payDate || "")))[0];
  return {
    total: rows.length,
    latestNet: latest && latest.net != null ? latest.net : null,
    latestPeriod: latest && latest.periodLabel,
    ytdNet: latest && latest.ytdNet != null ? latest.ytdNet : null,
    currency: (latest && latest.currency) || "USD",
  };
}

export function buildMyPaycheckInsights(paychecks) {
  const published = (paychecks || []).filter((row) => row.status === PAYCHECK_STATUSES.PUBLISHED);
  const insights = [];

  if (published.length === 0) {
    insights.push({
      id: "empty",
      tone: "blue",
      icon: "fe fe-dollar-sign",
      title: "No published paychecks yet",
      copy: "Payslips appear here after payroll publishes your pay for a completed period.",
    });
    return insights;
  }

  const latest = published
    .slice()
    .sort((a, b) => String(b.payDate || "").localeCompare(String(a.payDate || "")))[0];
  if (latest) {
    insights.push({
      id: "latest",
      tone: "green",
      icon: "fe fe-check-circle",
      title: `Latest pay · ${latest.periodLabel || "Recent period"}`,
      copy: `Net ${formatPayrollCurrency(latest.net, latest.currency)} deposited on ${formatPayrollDate(latest.payDate)}.`,
      path: `/payroll/paychecks/${latest.id}`,
    });
  }
  if (published.length > 1) {
    insights.push({
      id: "history",
      tone: "primary",
      icon: "fe fe-layers",
      title: `${published.length} payslips on file`,
      copy: "Download PDF copies or review YTD earnings and deductions.",
    });
  }
  return insights.slice(0, 3);
}

export function groupPaycheckLines(lines) {
  const rows = lines || [];
  return {
    earnings: rows.filter((row) => row.type === "EARNING"),
    deductions: rows.filter((row) => row.type === "DEDUCTION"),
  };
}

export function buildPaycheckYtdSummary(paycheck) {
  if (!paycheck) {
    return null;
  }
  return {
    gross: paycheck.ytdGross,
    deductions: paycheck.ytdDeductions,
    net: paycheck.ytdNet,
    currency: paycheck.currency || "USD",
  };
}

export function getPaycheckEmployeeInitials(name) {
  const parts = String(name || "?")
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  if (!parts.length) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase();
}

export function canPublishPaycheck(paycheck) {
  return paycheck && paycheck.status === PAYCHECK_STATUSES.DRAFT;
}

export function canRetractPaycheck(paycheck) {
  return paycheck && paycheck.status === PAYCHECK_STATUSES.PUBLISHED;
}

/**
 * Indian financial year label YYYY-YY from a date (Apr–Mar).
 * Defaults to today when no date is provided.
 */
export function resolveIndianFinancialYear(dateInput) {
  const date = dateInput ? new Date(dateInput) : new Date();
  if (Number.isNaN(date.getTime())) {
    return resolveIndianFinancialYear(new Date());
  }
  const year = date.getFullYear();
  const month = date.getMonth(); // 0-based
  const startYear = month >= 3 ? year : year - 1;
  const endSuffix = String((startYear + 1) % 100).padStart(2, "0");
  return `${startYear}-${endSuffix}`;
}

export function canDownloadPayslipPdf(paycheck) {
  if (!paycheck) {
    return false;
  }
  if (paycheck.status !== PAYCHECK_STATUSES.PUBLISHED) {
    return false;
  }
  return paycheck.hasPdf !== false;
}
