import React, { Component } from "react";
import { learningService } from "_services/learning/learning.service";
import LearningLuxPage, {
  LearningActionButton,
  LearningField,
  LearningLuxPanel,
} from "views/learning/components/LearningLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class AssignmentsPage extends Component {
  state = {
    loading: true,
    loadError: null,
    rows: [],
    saving: false,
    form: { courseId: "", assigneeType: "EMPLOYEE", assigneeId: "", dueDate: "" },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Learning assignments");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await learningService.listAssignments();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load assignments"),
      });
    }
  };

  handleCreate = async (e) => {
    e.preventDefault();
    const { form } = this.state;
    if (!form.courseId || !form.assigneeId) return;
    this.setState({ saving: true });
    const result = await learningService.createAssignment({
      courseId: Number(form.courseId),
      assigneeType: form.assigneeType,
      assigneeId: String(form.assigneeId),
      dueDate: form.dueDate || null,
    });
    this.setState({ saving: false });
    if (result.source === "api") {
      this.setState({
        form: { courseId: "", assigneeType: "EMPLOYEE", assigneeId: "", dueDate: "" },
      });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Assign failed") });
    }
  };

  render() {
    const { loading, loadError, rows, saving, form } = this.state;
    return (
      <LearningLuxPage
        testId="learning-assignments-page"
        dataSource={rows.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        pageMeta={{
          tone: "teal",
          icon: "fe fe-clipboard",
          eyebrow: "People · Learning",
          titleLead: "Learning",
          titleAccent: "assignments",
          lede: "Assign courses to employees, teams, or roles with due dates.",
        }}
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load assignments">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        <LearningLuxPanel title="Create assignment" icon="fe fe-plus">
          <form className="lux-module-inline-form" onSubmit={this.handleCreate}>
            <div className="lux-learning-form-grid lux-learning-form-grid--assignment">
              <LearningField label="Course id" hint="Use the course source id from the catalog.">
                <input
                  className="form-control"
                  placeholder="Course id"
                  value={form.courseId}
                  onChange={(e) => this.setState({ form: { ...form, courseId: e.target.value } })}
                />
              </LearningField>
              <LearningField label="Assign to">
                <select
                  className="form-control"
                  value={form.assigneeType}
                  onChange={(e) => this.setState({ form: { ...form, assigneeType: e.target.value } })}
                >
                  <option value="EMPLOYEE">EMPLOYEE</option>
                  <option value="TEAM">TEAM</option>
                  <option value="ROLE">ROLE</option>
                </select>
              </LearningField>
              <LearningField label="Assignee id" hint="Employee, team, or role reference.">
                <input
                  className="form-control"
                  placeholder="Assignee id"
                  value={form.assigneeId}
                  onChange={(e) => this.setState({ form: { ...form, assigneeId: e.target.value } })}
                />
              </LearningField>
              <LearningField label="Due date">
                <input
                  className="form-control"
                  type="date"
                  value={form.dueDate}
                  onChange={(e) => this.setState({ form: { ...form, dueDate: e.target.value } })}
                />
              </LearningField>
              <div className="lux-learning-form-actions">
                <LearningActionButton type="submit" disabled={saving}>
                  Assign
                </LearningActionButton>
              </div>
            </div>
          </form>
        </LearningLuxPanel>
        <LearningLuxPanel title="Assignments" meta={`${rows.length} record${rows.length === 1 ? "" : "s"}`} icon="fe fe-list">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
          {!loading && rows.length === 0 ? (
            <LuxRegisterEmptyState
              title="No assignments yet"
              description="Assign a course to an employee, team, or role."
              showCreate={false}
            />
          ) : !loading ? (
            <div className="lux-module-table-wrap">
              <table className="table table-sm mb-0">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Course</th>
                    <th>Type</th>
                    <th>Assignee</th>
                    <th>Due</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r) => (
                    <tr key={r.assignmentRef || r.id}>
                      <td>{r.assignmentRef}</td>
                      <td>{r.courseId}</td>
                      <td>{r.assigneeType}</td>
                      <td>{r.assigneeId}</td>
                      <td>{r.dueDate || "—"}</td>
                      <td>
                        <span className={`lux-learning-status is-${String(r.status || "draft").toLowerCase()}`}>
                          {r.status || "Draft"}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : null}
        </LearningLuxPanel>
      </LearningLuxPage>
    );
  }
}

export default AssignmentsPage;
