import React, { Component } from "react";
import { Link } from "react-router-dom";
import { vendorInvoicesService } from "_services/vendorInvoices.service";
import { commonUtils } from "_helpers";
import FinanceLuxPage, {
  FinanceActionButton,
  FinanceLuxPanel,
} from "views/finance/components/FinanceLuxShared";
import FinanceLoadAlert from "views/finance/components/FinanceLoadAlert";

class VendorInvoicesPage extends Component {
  state = {
    loading: true,
    loadError: null,
    saving: false,
    rows: [],
    createForm: {
      vendorId: "",
      invoiceNumber: "",
      amount: "",
      projectId: "",
      purchaseOrderId: "",
      taskId: "",
      costCenter: "",
      reason: "",
      documentRef: "",
      currency: "USD",
    },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Vendor invoices");
    }
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await vendorInvoicesService.listInvoices();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload, loadError: null });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load vendor invoices"),
      });
    }
  };

  handleFormChange = (patch) => {
    this.setState({ createForm: { ...this.state.createForm, ...patch } });
  };

  handleCreate = async (event) => {
    event.preventDefault();
    const { createForm } = this.state;
    if (!createForm.vendorId || !createForm.invoiceNumber || !createForm.amount || !createForm.projectId) {
      return;
    }
    this.setState({ saving: true });
    const result = await vendorInvoicesService.createInvoice({
      vendorId: Number(createForm.vendorId),
      invoiceNumber: createForm.invoiceNumber,
      amount: Number(createForm.amount),
      projectId: Number(createForm.projectId),
      purchaseOrderId: createForm.purchaseOrderId ? Number(createForm.purchaseOrderId) : null,
      taskId: createForm.taskId ? Number(createForm.taskId) : null,
      costCenter: createForm.costCenter || null,
      reason: createForm.reason || null,
      documentRef: createForm.documentRef || null,
      currency: createForm.currency || "USD",
    });
    this.setState({ saving: false });
    if (result.source === "api" && result.payload) {
      this.setState({
        createForm: {
          vendorId: "",
          invoiceNumber: "",
          amount: "",
          projectId: "",
          purchaseOrderId: "",
          taskId: "",
          costCenter: "",
          reason: "",
          documentRef: "",
          currency: "USD",
        },
      });
      this.loadData();
    } else {
      this.setState({ loadError: result.error || new Error("Create failed") });
    }
  };

  handleSubmit = async (ref, userTeamId) => {
    await vendorInvoicesService.submitInvoice(ref, userTeamId);
    this.loadData();
  };

  handleApprove = async (ref, userTeamId) => {
    await vendorInvoicesService.approveInvoice(ref, userTeamId);
    this.loadData();
  };

  handleReject = async (ref, userTeamId) => {
    await vendorInvoicesService.rejectInvoice(ref, "Rejected from UI", userTeamId);
    this.loadData();
  };

  render() {
    const { loading, loadError, saving, rows, createForm } = this.state;
    return (
      <FinanceLuxPage
        testId="vendor-invoices-page"
        pageMeta={{
          tone: "slate",
          icon: "fe fe-file-text",
          eyebrow: "Vendors",
          titleLead: "Vendor",
          titleAccent: "invoices",
          lede: "Create, submit and approve vendor invoices; approval posts project cost ledger.",
        }}
        dataSource="api"
        demoLabel={null}
        loading={loading}
      >
        <FinanceLoadAlert
          error={loadError}
          fallback="Unable to load vendor invoices."
          onDismiss={() => this.setState({ loadError: null })}
        />
        <FinanceLuxPanel title="Create vendor invoice">
          <form onSubmit={this.handleCreate} className="d-flex flex-wrap gap-2 align-items-end">
            <label className="small mb-0">
              Vendor ID
              <input
                className="form-control form-control-sm"
                value={createForm.vendorId}
                onChange={(e) => this.handleFormChange({ vendorId: e.target.value })}
                required
                data-testid="vinv-vendor-id"
              />
            </label>
            <label className="small mb-0">
              Invoice #
              <input
                className="form-control form-control-sm"
                value={createForm.invoiceNumber}
                onChange={(e) => this.handleFormChange({ invoiceNumber: e.target.value })}
                required
                data-testid="vinv-invoice-number"
              />
            </label>
            <label className="small mb-0">
              Amount
              <input
                type="number"
                step="0.01"
                min="0.01"
                className="form-control form-control-sm"
                value={createForm.amount}
                onChange={(e) => this.handleFormChange({ amount: e.target.value })}
                required
                data-testid="vinv-amount"
              />
            </label>
            <label className="small mb-0">
              Project ID
              <input
                className="form-control form-control-sm"
                value={createForm.projectId}
                onChange={(e) => this.handleFormChange({ projectId: e.target.value })}
                required
                data-testid="vinv-project-id"
              />
            </label>
            <label className="small mb-0">
              PO ID
              <input
                className="form-control form-control-sm"
                value={createForm.purchaseOrderId}
                onChange={(e) => this.handleFormChange({ purchaseOrderId: e.target.value })}
              />
            </label>
            <label className="small mb-0">
              Cost center
              <input
                className="form-control form-control-sm"
                value={createForm.costCenter}
                onChange={(e) => this.handleFormChange({ costCenter: e.target.value })}
              />
            </label>
            <label className="small mb-0">
              Vault documentRef
              <input
                className="form-control form-control-sm"
                value={createForm.documentRef}
                onChange={(e) => this.handleFormChange({ documentRef: e.target.value })}
                placeholder="optional"
              />
            </label>
            <FinanceActionButton type="submit" variant="primary" disabled={saving}>
              {saving ? "Saving…" : "Create draft"}
            </FinanceActionButton>
          </form>
        </FinanceLuxPanel>
        <FinanceLuxPanel title="Vendor invoices" className="mt-3">
          {loading ? (
            <p className="text-muted small mb-0">Loading…</p>
          ) : rows.length === 0 ? (
            <p className="text-muted small mb-0">
              No vendor invoices for team {commonUtils.getCurrentUserTeamId()}.
            </p>
          ) : (
            <div className="table-responsive">
              <table className="table table-sm" data-testid="vendor-invoices-table">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Vendor</th>
                    <th>Invoice #</th>
                    <th>Project</th>
                    <th>Amount</th>
                    <th>Status</th>
                    <th />
                  </tr>
                </thead>
                <tbody>
                  {rows.map((row) => (
                    <tr key={row.vendorInvoiceRef || row.id}>
                      <td>
                        <Link to={`/vendors/invoices/${encodeURIComponent(row.vendorInvoiceRef)}`}>
                          {row.vendorInvoiceRef}
                        </Link>
                      </td>
                      <td>{row.vendorId}</td>
                      <td>{row.invoiceNumber}</td>
                      <td>{row.projectId}</td>
                      <td>
                        {row.currency || "USD"} {row.amount}
                      </td>
                      <td>{row.status}</td>
                      <td className="text-nowrap">
                        {(row.status === "DRAFT" || row.status === "REJECTED") && (
                          <button
                            type="button"
                            className="btn btn-link btn-sm p-0 me-2"
                            onClick={() => this.handleSubmit(row.vendorInvoiceRef, row.userTeamId)}
                          >
                            {row.status === "REJECTED" ? "Resubmit" : "Submit"}
                          </button>
                        )}
                        {row.status === "SUBMITTED" && (
                          <>
                            <button
                              type="button"
                              className="btn btn-link btn-sm p-0 me-2"
                              onClick={() => this.handleApprove(row.vendorInvoiceRef, row.userTeamId)}
                            >
                              Approve
                            </button>
                            <button
                              type="button"
                              className="btn btn-link btn-sm p-0"
                              onClick={() => this.handleReject(row.vendorInvoiceRef, row.userTeamId)}
                            >
                              Reject
                            </button>
                          </>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </FinanceLuxPanel>
      </FinanceLuxPage>
    );
  }
}

export default VendorInvoicesPage;
