import dateUtils from "_helpers/date.utils";
import { commonUtils } from "_helpers";
import originalMoment from "moment";
import { extendMoment } from "moment-range";

const moment = extendMoment(originalMoment);

export const INVOICE_LIST_PAGE_SIZE = 12;
export const INVOICE_LIST_LOAD_STEP = 12;

export const INVOICE_DASHBOARD_SCOPE = {
  ALL: "ALL",
  CURRENT_FY: "CURRENT_FY",
  FY: "FY",
};

export const INVOICE_STATUS_META = {
  DRAFT: { label: "Draft", tone: "slate", icon: "fe-edit-3" },
  PENDING: { label: "Pending", tone: "blue", icon: "fe-clock" },
  APPROVED: { label: "Approved", tone: "amber", icon: "fe-check-circle" },
  PAID: { label: "Paid", tone: "green", icon: "fe-dollar-sign" },
  CLOSED: { label: "Closed", tone: "violet", icon: "fe-lock" },
};

export const INVOICE_STATUS_ORDER = ["DRAFT", "PENDING", "APPROVED", "PAID", "CLOSED"];

export function getInvoiceNumber(item) {
  if (!item) return "—";
  if (item.invoiceNumber) return item.invoiceNumber;
  const momentDate = dateUtils.convertDateStringToMoment(item.invoiceDateTime);
  if (momentDate && momentDate.isValid()) {
    return `C5${momentDate.format("YYYYMMDD")}`;
  }
  return "C5—";
}

export function getUserCount(item) {
  return item && item.usersMap ? Object.keys(item.usersMap).length : 0;
}

export function getInvoiceShareAccessToken(header, item) {
  if (item && item.shareToken) {
    return item.shareToken;
  }
  if (item && item.accessToken) {
    return item.accessToken;
  }
  return header && header.accessToken ? header.accessToken : null;
}

export function buildInvoiceShareUrl(item, accessToken) {
  if (!item || !accessToken) return null;

  const invoiceNumber = getInvoiceNumber(item);
  const encryptInvoiceNumber = commonUtils.encryptString(
    invoiceNumber,
    invoiceNumber + "_" + item.id
  );

  const params = new URLSearchParams({
    ac: encryptInvoiceNumber,
    uin: invoiceNumber,
    tk: accessToken,
  });

  return (
    window.location.origin +
    `/document/invoice/details/${item.id}?${params.toString()}`
  );
}

export function parseAmount(value) {
  const num = Number(value);
  return Number.isFinite(num) ? num : 0;
}

export function formatCurrency(value, { compact = false } = {}) {
  const num = parseAmount(value);
  if (compact && num >= 100000) {
    return `₹${(num / 100000).toFixed(1)}L`;
  }
  return `₹${num.toLocaleString("en-IN", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

export function getInvoiceReferenceDate(item) {
  if (!item) return null;
  const raw = item.invoiceMonthYear || item.invoiceDateTime;
  if (!raw) return null;
  const m = dateUtils.convertDateStringToMoment(raw);
  return m && m.isValid() ? m : null;
}

/** Indian financial year starts April 1. Returns the calendar year the FY begins in. */
export function getFinancialYearStartYear(dateInput) {
  const m =
    dateInput && dateInput.isValid
      ? dateInput
      : dateUtils.convertDateStringToMoment(dateInput);
  if (!m || !m.isValid()) return null;
  return m.month() >= 3 ? m.year() : m.year() - 1;
}

export function getCurrentFinancialYearStartYear() {
  return getFinancialYearStartYear(dateUtils.getCurrentTime());
}

export function getFinancialYearLabel(startYear) {
  if (startYear == null) return "Financial year";
  const endSuffix = String(startYear + 1).slice(-2);
  return `FY ${startYear}-${endSuffix}`;
}

export function getFinancialYearRange(startYear) {
  if (startYear == null) return null;
  return {
    start: moment([startYear, 3, 1]).startOf("day"),
    end: moment([startYear + 1, 2, 31]).endOf("day"),
    label: getFinancialYearLabel(startYear),
  };
}

function buildFinancialYearMonthSlots(fyStartYear) {
  return Array.from({ length: 12 }, (_, index) => {
    const monthMoment = moment([fyStartYear, 3, 1]).add(index, "months");
    return {
      label: monthMoment.format("MMM YYYY"),
      shortLabel: monthMoment.format("MMM"),
      sortKey: monthMoment.format("YYYY-MM"),
    };
  });
}

function buildMonthlyInsights(rows) {
  const activeRows = rows.filter((row) => row.count > 0);
  const activeMonths = activeRows.length;
  const fyTotalAmount = rows.reduce((sum, row) => sum + row.amount, 0);
  const peakRow = rows.reduce(
    (best, row) => (row.amount > (best ? best.amount : -1) ? row : best),
    null
  );
  const avgAmountPerMonth = activeMonths ? fyTotalAmount / activeMonths : 0;

  return {
    activeMonths,
    fyTotalAmount,
    peakLabel: peakRow && peakRow.amount > 0 ? peakRow.label : null,
    peakAmount: peakRow ? peakRow.amount : 0,
    avgAmountPerMonth,
  };
}

function annotateMonthlyRows(rows, totalInvoiceCount) {
  if (!rows.length) return rows;

  const peakAmount = Math.max(...rows.map((row) => row.amount), 0);
  const recentSortKey = rows
    .filter((row) => row.count > 0)
    .map((row) => row.sortKey)
    .sort()
    .pop();

  return rows.map((row) => ({
    ...row,
    pct: totalInvoiceCount ? Math.round((row.count / totalInvoiceCount) * 100) : 0,
    amountPct: peakAmount ? Math.round((row.amount / peakAmount) * 100) : 0,
    isPeak: row.amount > 0 && row.amount === peakAmount,
    isRecent: recentSortKey != null && row.sortKey === recentSortKey,
  }));
}

export function isInvoiceInFinancialYear(item, fyStartYear) {
  if (fyStartYear == null) return true;
  const range = getFinancialYearRange(fyStartYear);
  const invoiceDate = getInvoiceReferenceDate(item);
  if (!range || !invoiceDate) return false;
  return invoiceDate.isBetween(range.start, range.end, null, "[]");
}

export function getAvailableFinancialYears(items) {
  if (!items || !items.length) {
    const current = getCurrentFinancialYearStartYear();
    return current != null ? [current] : [];
  }

  const years = new Set();
  items.forEach((item) => {
    const fy = getFinancialYearStartYear(getInvoiceReferenceDate(item));
    if (fy != null) years.add(fy);
  });

  return Array.from(years).sort((a, b) => b - a);
}

export function resolveDashboardFinancialYear(scope, selectedFyStartYear) {
  if (scope === INVOICE_DASHBOARD_SCOPE.ALL) return null;
  if (scope === INVOICE_DASHBOARD_SCOPE.CURRENT_FY) {
    return getCurrentFinancialYearStartYear();
  }
  if (scope === INVOICE_DASHBOARD_SCOPE.FY) {
    return selectedFyStartYear;
  }
  return null;
}

export function filterInvoicesByFinancialYear(items, fyStartYear) {
  if (!items || !items.length || fyStartYear == null) return items || [];
  return items.filter((item) => isInvoiceInFinancialYear(item, fyStartYear));
}

/** Matches CollectionsAgingUtils bucket codes on the backend. */
export const INVOICE_AGING_BUCKETS = [
  { code: "CURRENT", label: "Current", shortLabel: "Current", tone: "green" },
  { code: "DAYS_1_30", label: "1–30 days", shortLabel: "1–30", tone: "blue" },
  { code: "DAYS_31_60", label: "31–60 days", shortLabel: "31–60", tone: "amber" },
  { code: "DAYS_61_90", label: "61–90 days", shortLabel: "61–90", tone: "orange" },
  { code: "DAYS_90_PLUS", label: "90+ days", shortLabel: "90+", tone: "rose" },
];

export function isInvoiceUnpaidForAging(item) {
  if (!item || !item.status) return false;
  return item.status !== "PAID" && item.status !== "CLOSED";
}

export function getInvoiceDueMoment(item) {
  if (!item) return null;
  const raw = item.revisedInvoiceDateTime || item.invoiceDateTime;
  if (!raw) return null;
  const m = dateUtils.convertDateStringToMoment
    ? dateUtils.convertDateStringToMoment(raw)
    : moment(raw);
  return m && m.isValid() ? m : null;
}

export function getInvoiceDaysPastDue(item, asOfMoment = moment()) {
  const due = getInvoiceDueMoment(item);
  if (!due) return 0;
  return asOfMoment.clone().startOf("day").diff(due.clone().startOf("day"), "days");
}

export function getInvoiceAgingBucketCode(item, asOfMoment = moment()) {
  const days = getInvoiceDaysPastDue(item, asOfMoment);
  if (days <= 0) return "CURRENT";
  if (days <= 30) return "DAYS_1_30";
  if (days <= 60) return "DAYS_31_60";
  if (days <= 90) return "DAYS_61_90";
  return "DAYS_90_PLUS";
}

function roundMoney(value) {
  return Math.round((Number(value) || 0) * 100) / 100;
}

/** Effective outstanding for aging (matches CollectionsAgingUtils before CN/WO). */
export function getInvoiceOutstandingForAging(item) {
  if (!item) return 0;
  const total = Number(item.totalAmount) || 0;
  const paid = Number(item.paidAmount) || 0;
  return Math.max(0, total - paid);
}

const AGING_BUCKET_LABELS = {
  CURRENT: "CURRENT",
  DAYS_1_30: "1-30",
  DAYS_31_60: "31-60",
  DAYS_61_90: "61-90",
  DAYS_90_PLUS: "90+",
};

/**
 * Client-side aging payload when GET /accounts/collections/aging is unavailable.
 * Shape matches CollectionsAgingUtils.buildAgingPayload for CollectionsAgingPanel.
 */
export function buildCollectionsAgingFromInvoices(items, options = {}) {
  const asOfMoment = options.asOfMoment || moment();
  const accumulators = INVOICE_AGING_BUCKETS.reduce((acc, meta) => {
    acc[meta.code] = { count: 0, amount: 0 };
    return acc;
  }, {});

  let unpaidCount = 0;
  let unpaidTotal = 0;
  const source = Array.isArray(items) ? items : [];

  source.forEach((item) => {
    if (!isInvoiceUnpaidForAging(item)) {
      return;
    }
    const outstanding = getInvoiceOutstandingForAging(item);
    if (outstanding <= 0) {
      return;
    }
    const code = getInvoiceAgingBucketCode(item, asOfMoment);
    unpaidCount += 1;
    unpaidTotal += outstanding;
    if (accumulators[code]) {
      accumulators[code].count += 1;
      accumulators[code].amount += outstanding;
    }
  });

  const buckets = INVOICE_AGING_BUCKETS.map((meta) => ({
    bucket: AGING_BUCKET_LABELS[meta.code] || meta.code,
    code: meta.code,
    invoiceCount: accumulators[meta.code].count,
    amount: roundMoney(accumulators[meta.code].amount),
  }));

  return {
    asOf: asOfMoment.toISOString(),
    unpaidInvoiceCount: unpaidCount,
    unpaidAmount: roundMoney(unpaidTotal),
    buckets,
    source: "fs_invoice_model",
    readOnly: true,
    approximate: options.approximate === true,
    adjustmentsSource: options.approximate
      ? "register_fallback"
      : "ts_credit_note_model+ts_write_off_model",
  };
}

export function extractCollectionsAgingPayload(response) {
  if (!response || typeof response === "string") {
    return null;
  }
  if (response.payload && typeof response.payload === "object") {
    return response.payload;
  }
  if (response.buckets) {
    return response;
  }
  return null;
}

export function filterInvoices(items, filterOptions) {
  if (!items || !items.length) return [];

  let result = [...items];
  const fyStartYear =
    filterOptions && filterOptions.fyStartYear != null
      ? filterOptions.fyStartYear
      : null;

  if (fyStartYear != null) {
    result = filterInvoicesByFinancialYear(result, fyStartYear);
  }

  const status =
    filterOptions &&
    filterOptions.SHOW &&
    filterOptions.SHOW.selected;

  if (status && status !== "ALL") {
    result = result.filter((item) => item.status === status);
  }

  const agingBucket = filterOptions && filterOptions.agingBucket;
  if (agingBucket) {
    result = result.filter(
      (item) =>
        isInvoiceUnpaidForAging(item) && getInvoiceAgingBucketCode(item) === agingBucket
    );
  }

  const filterText = filterOptions && filterOptions.filterText;
  if (filterText) {
    const needle = filterText.toLowerCase();
    result = result.filter((item) => {
      const number = getInvoiceNumber(item).toLowerCase();
      const name = (item.name || "").toLowerCase();
      const description = (item.description || "").toLowerCase();
      const statusLabel =
        (INVOICE_STATUS_META[item.status] &&
          INVOICE_STATUS_META[item.status].label.toLowerCase()) ||
        (item.status || "").toLowerCase();
      return (
        number.includes(needle) ||
        name.includes(needle) ||
        description.includes(needle) ||
        statusLabel.includes(needle)
      );
    });
  }

  return commonUtils.sortArrayOfObjectsByDateField(result, "invoiceDateTime", false);
}

export const OUTSTANDING_INVOICE_STATUSES = ["DRAFT", "PENDING", "APPROVED"];

export function buildInvoiceDetailRow(item) {
  const refDate = getInvoiceReferenceDate(item);
  const invoiceDate = item.invoiceDateTime
    ? dateUtils.convertDateFormat(item.invoiceDateTime)
    : "—";
  const billingPeriod = refDate ? refDate.format(dateUtils.DATE_MONTH_FORMAT) : null;
  const status = item.status || "DRAFT";
  const statusMeta = INVOICE_STATUS_META[status] || INVOICE_STATUS_META.DRAFT;

  return {
    id: item.id,
    invoiceNumber: getInvoiceNumber(item),
    name: item.name || "Untitled invoice",
    description: item.description || "",
    invoiceDate,
    billingPeriod,
    userCount: getUserCount(item),
    amount: parseAmount(item.subTotal),
    status,
    statusLabel: statusMeta.label,
    statusTone: statusMeta.tone,
    sortDate: item.invoiceDateTime || item.invoiceMonthYear || "",
  };
}

export function buildFyOutstandingInvoices(items, fyStartYear) {
  const empty = {
    fyLabel: fyStartYear != null ? getFinancialYearLabel(fyStartYear) : null,
    pending: [],
    draft: [],
    approved: [],
    openInvoices: [],
    pendingCount: 0,
    pendingAmount: 0,
    draftCount: 0,
    draftAmount: 0,
    approvedCount: 0,
    approvedAmount: 0,
    openCount: 0,
    openAmount: 0,
  };

  if (!items || !items.length || fyStartYear == null) return empty;

  const scoped = filterInvoicesByFinancialYear(items, fyStartYear);
  const pending = [];
  const draft = [];
  const approved = [];

  scoped.forEach((item) => {
    const row = buildInvoiceDetailRow(item);
    if (item.status === "PENDING") pending.push(row);
    else if (item.status === "DRAFT") draft.push(row);
    else if (item.status === "APPROVED") approved.push(row);
  });

  const sortRows = (rows) =>
    commonUtils.sortArrayOfObjectsByDateField(rows, "sortDate", false);

  const sortedPending = sortRows(pending);
  const sortedDraft = sortRows(draft);
  const sortedApproved = sortRows(approved);
  const openInvoices = [...sortedPending, ...sortedDraft, ...sortedApproved];

  const sumAmount = (rows) => rows.reduce((acc, row) => acc + row.amount, 0);

  return {
    fyLabel: getFinancialYearLabel(fyStartYear),
    pending: sortedPending,
    draft: sortedDraft,
    approved: sortedApproved,
    openInvoices,
    pendingCount: sortedPending.length,
    pendingAmount: sumAmount(sortedPending),
    draftCount: sortedDraft.length,
    draftAmount: sumAmount(sortedDraft),
    approvedCount: sortedApproved.length,
    approvedAmount: sumAmount(sortedApproved),
    openCount: openInvoices.length,
    openAmount: sumAmount(openInvoices),
  };
}

export function buildInvoiceSummaryStats(items, options = {}) {
  const fyStartYear = options.fyStartYear;
  const scopedItems =
    fyStartYear != null ? filterInvoicesByFinancialYear(items, fyStartYear) : items;
  const fyRange = fyStartYear != null ? getFinancialYearRange(fyStartYear) : null;

  const empty = {
    total: 0,
    totalAmount: 0,
    pendingCount: 0,
    pendingAmount: 0,
    approvedCount: 0,
    approvedAmount: 0,
    paidCount: 0,
    paidAmount: 0,
    closedCount: 0,
    closedAmount: 0,
    draftCount: 0,
    draftAmount: 0,
    collectedAmount: 0,
    outstandingAmount: 0,
    avgAmount: 0,
    totalUsers: 0,
    statusMix: [],
    recentMonthLabel: null,
    recentMonthCount: 0,
    recentMonthAmount: 0,
    fyLabel: fyRange ? fyRange.label : null,
    fyStartYear: fyStartYear != null ? fyStartYear : null,
    monthlyBreakdown: [],
    monthlyInsights: {
      activeMonths: 0,
      fyTotalAmount: 0,
      peakLabel: null,
      peakAmount: 0,
      avgAmountPerMonth: 0,
    },
  };

  if (!scopedItems || !scopedItems.length) return empty;

  const counts = {};
  const amounts = {};
  INVOICE_STATUS_ORDER.forEach((status) => {
    counts[status] = 0;
    amounts[status] = 0;
  });

  let totalAmount = 0;
  let totalUsers = 0;
  const monthBuckets = {};

  scopedItems.forEach((item) => {
    const amount = parseAmount(item.subTotal);
    const status = item.status || "DRAFT";
    totalAmount += amount;
    totalUsers += getUserCount(item);

    if (counts[status] != null) {
      counts[status] += 1;
      amounts[status] += amount;
    }

    const monthKey = item.invoiceMonthYear || item.invoiceDateTime;
    if (monthKey) {
      const monthMoment = dateUtils.convertDateStringToMoment(monthKey);
      const monthLabel = monthMoment.format("MMM YYYY");
      const sortKey = monthMoment.format("YYYY-MM");
      if (!monthBuckets[monthLabel]) {
        monthBuckets[monthLabel] = { count: 0, amount: 0, sortKey };
      }
      monthBuckets[monthLabel].count += 1;
      monthBuckets[monthLabel].amount += amount;
    }
  });

  const total = scopedItems.length;
  const toMix = (status) => ({
    status,
    label: INVOICE_STATUS_META[status].label,
    tone: INVOICE_STATUS_META[status].tone,
    count: counts[status],
    amount: amounts[status],
    pct: total ? Math.round((counts[status] / total) * 100) : 0,
  });

  const statusMix = INVOICE_STATUS_ORDER.map(toMix).filter(
    (segment) => segment.count > 0
  );

  const collectedAmount = amounts.PAID + amounts.CLOSED;
  const outstandingAmount =
    amounts.DRAFT + amounts.PENDING + amounts.APPROVED;

  let recentMonthLabel = null;
  let recentMonthCount = 0;
  let recentMonthAmount = 0;
  const monthEntries = Object.keys(monthBuckets)
    .map((label) => ({ label, ...monthBuckets[label] }))
    .sort((a, b) => b.sortKey.localeCompare(a.sortKey));

  if (monthEntries.length) {
    recentMonthLabel = monthEntries[0].label;
    recentMonthCount = monthEntries[0].count;
    recentMonthAmount = monthEntries[0].amount;
  }

  let monthlyBreakdown;
  if (fyStartYear != null) {
    monthlyBreakdown = buildFinancialYearMonthSlots(fyStartYear).map((slot) => {
      const bucket = monthBuckets[slot.label];
      return {
        ...slot,
        count: bucket ? bucket.count : 0,
        amount: bucket ? bucket.amount : 0,
      };
    });
  } else {
    monthlyBreakdown = monthEntries.slice(0, 12).map((entry) => ({
      label: entry.label,
      shortLabel: entry.label.split(" ")[0],
      sortKey: entry.sortKey,
      count: entry.count,
      amount: entry.amount,
    }));
  }

  monthlyBreakdown = annotateMonthlyRows(monthlyBreakdown, total);
  const monthlyInsights = buildMonthlyInsights(monthlyBreakdown);

  return {
    total,
    totalAmount,
    pendingCount: counts.PENDING,
    pendingAmount: amounts.PENDING,
    approvedCount: counts.APPROVED,
    approvedAmount: amounts.APPROVED,
    paidCount: counts.PAID,
    paidAmount: amounts.PAID,
    closedCount: counts.CLOSED,
    closedAmount: amounts.CLOSED,
    draftCount: counts.DRAFT,
    draftAmount: amounts.DRAFT,
    collectedAmount,
    outstandingAmount,
    avgAmount: total ? totalAmount / total : 0,
    totalUsers,
    statusMix,
    recentMonthLabel,
    recentMonthCount,
    recentMonthAmount,
    fyLabel: fyRange ? fyRange.label : null,
    fyStartYear: fyStartYear != null ? fyStartYear : null,
    monthlyBreakdown,
    monthlyInsights,
  };
}
