import { notificationActions } from "./notification.actions";
import { timesheetApprovalService } from "_services/timesheetApproval.service";

export const timesheetApprovalActions = {
  loadPendingApprovals,
  approveWeek,
  rejectWeek,
  loadConflicts,
  resolveConflict,
  lockWeeks,
  unlockWeeks,
  reopenWeek,
  loadDefaulters,
};

function loadPendingApprovals(userTeamIds, managerId) {
  return (dispatch) => {
    dispatch(request());
    return timesheetApprovalService
      .listPending(userTeamIds, managerId)
      .then((response) => {
        const weeks = (response && response.payload) || [];
        dispatch(success(weeks));
        return weeks;
      })
      .catch((error) => {
        dispatch(failure(error));
        return Promise.reject(error);
      });
  };

  function request() {
    return { type: "TIMESHEET_PENDING_APPROVALS_REQUEST" };
  }
  function success(weeks) {
    return { type: "TIMESHEET_PENDING_APPROVALS_SUCCESS", weeks };
  }
  function failure(error) {
    return { type: "TIMESHEET_PENDING_APPROVALS_FAILURE", error };
  }
}

function approveWeek(weekIdOrWeek, approverId, approvalComment) {
  const week = weekIdOrWeek && typeof weekIdOrWeek === "object" ? weekIdOrWeek : null;
  const weekId = week ? week.id : weekIdOrWeek;
  const submissionId = week && week.submissionId;
  return (dispatch) => {
    const promise = submissionId
      ? timesheetApprovalService.approveSubmission(submissionId, approverId, approvalComment)
      : timesheetApprovalService.approveWeek(weekId, approverId, approvalComment);
    return promise
      .then((response) => {
        dispatch(notificationActions.success("Timesheet approved."));
        return response && response.payload;
      })
      .catch((error) => {
        const message = (error && error.message) || error || "Unable to approve timesheet.";
        dispatch(notificationActions.error(message));
        return Promise.reject(error);
      });
  };
}

function rejectWeek(weekIdOrWeek, approverId, rejectionComment) {
  const week = weekIdOrWeek && typeof weekIdOrWeek === "object" ? weekIdOrWeek : null;
  const weekId = week ? week.id : weekIdOrWeek;
  const submissionId = week && week.submissionId;
  return (dispatch) => {
    const promise = submissionId
      ? timesheetApprovalService.rejectSubmission(submissionId, approverId, rejectionComment)
      : timesheetApprovalService.rejectWeek(weekId, approverId, rejectionComment);
    return promise
      .then((response) => {
        dispatch(notificationActions.success("Timesheet rejected."));
        return response && response.payload;
      })
      .catch((error) => {
        const message = (error && error.message) || error || "Unable to reject timesheet.";
        dispatch(notificationActions.error(message));
        return Promise.reject(error);
      });
  };
}

