import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import ExpenseStatusBadge from "views/expenses/components/ExpenseStatusBadge";
import { ExpenseActionButton } from "views/expenses/components/ExpensesLuxShared";
import { EXPENSE_CLAIM_STATUSES } from "config/expenses.config";

function formatUsd(value) {
  if (value == null) {
    return "—";
  }
  return `$${Number(value).toLocaleString()}`;
}

function ExpenseRegister({
  rows = [],
  loading,
  mode = "employee",
  busyId,
  onApprove,
  onReject,
  onSubmit,
  onSchedule,
}) {
  if (loading) {
    return <div className="lux-expense-register__skeleton" aria-busy="true" />;
  }

  if (!rows.length) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact lux-expense-empty"
        title="No expense claims"
        description="Submit a new claim or adjust filters to see more results."
      />
    );
  }

  return (
    <div className="lux-expense-register-wrap">
      <table className="lux-expense-register">
        <thead>
          <tr>
            <th>Claim</th>
            <th>Employee</th>
            <th>Category</th>
            <th>Amount</th>
            <th>Project</th>
            <th>Status</th>
            <th>Policy</th>
            <th aria-label="Actions" />
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const hasViolations = row.policyViolations && row.policyViolations.length > 0;
            const canSubmit = mode === "employee" && row.status === EXPENSE_CLAIM_STATUSES.DRAFT;
            const canApprove =
              mode === "finance" &&
              [EXPENSE_CLAIM_STATUSES.SUBMITTED, EXPENSE_CLAIM_STATUSES.MANAGER_APPROVED].includes(row.status);
            return (
              <tr key={row.id} className={classNames(hasViolations && "is-flagged")}>
                <td>
                  <div className="lux-expense-register__title">{row.title}</div>
                  <div className="lux-expense-register__meta">{row.submittedAt || row.updatedAt || "—"}</div>
                </td>
                <td>
                  <div>{row.employeeName}</div>
                  <div className="lux-expense-register__meta">{row.department}</div>
                </td>
                <td>{row.category}</td>
                <td>
                  <strong>{formatUsd(row.totalUsd)}</strong>
                  {row.billable ? <span className="lux-expense-chip is-blue">Billable</span> : null}
                </td>
                <td>{row.projectCode || "—"}</td>
                <td>
                  <ExpenseStatusBadge status={row.status} />
                </td>
                <td>
                  {hasViolations ? (
                    <span className="lux-expense-chip is-rose">{row.policyViolations.length} issue(s)</span>
                  ) : (
                    <span className="lux-expense-chip is-green">Compliant</span>
                  )}
                </td>
                <td>
                  <div className="lux-expense-register__actions">
                    {canSubmit ? (
                      <ExpenseActionButton
                        variant="primary"
                        className="lux-onb-action--sm"
                        disabled={busyId === row.id}
                        onClick={() => onSubmit && onSubmit(row.id)}
                      >
                        Submit
                      </ExpenseActionButton>
                    ) : null}
                    {canApprove ? (
                      <>
                        <ExpenseActionButton
                          icon="fe fe-check"
                          variant="primary"
                          className="lux-onb-action--sm"
                          disabled={busyId === row.id}
                          onClick={() => onApprove && onApprove(row.id)}
                        >
                          Approve
                        </ExpenseActionButton>
                        <ExpenseActionButton
                          icon="fe fe-x"
                          variant="ghost"
                          className="lux-onb-action--sm"
                          disabled={busyId === row.id}
                          onClick={() => onReject && onReject(row.id)}
                        >
                          Reject
                        </ExpenseActionButton>
                      </>
                    ) : null}
                    {row.approvalId ? (
                      <Link to="/workspace/approvals" className="lux-expense-register__link">
                        Inbox
                      </Link>
                    ) : null}
                    {mode === "reimbursements" && onSchedule ? (
                      <ExpenseActionButton
                        variant="ghost"
                        className="lux-onb-action--sm"
                        disabled={busyId === row.id}
                        onClick={() => onSchedule(row.id)}
                      >
                        Schedule
                      </ExpenseActionButton>
                    ) : null}
                  </div>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export default ExpenseRegister;
