import { axiosUtils } from '../_helpers';
import urlConfig from 'url.config';

function payload(res) {
  if (res == null) return null;
  if (res.payload !== undefined) return res.payload;
  return res;
}

const GLOBAL = urlConfig.GLOBAL_LEAVE_POLICY_API_PATH;
const TEST_LAB = urlConfig.LEAVE_TEST_LAB_API_PATH;
const LEGAL_CAL = urlConfig.LEAVE_LEGAL_CALENDARS_API_PATH;
const ABSENCE = urlConfig.LEAVE_ABSENCE_CASES_API_PATH;
const DOCUMENTS = urlConfig.LEAVE_DOCUMENTS_API_PATH;
const INTEGRATIONS = urlConfig.LEAVE_INTEGRATIONS_API_PATH;
const AGREEMENTS = urlConfig.LEAVE_AGREEMENTS_API_PATH;
const LOCALE = urlConfig.LEAVE_LOCALE_API_PATH;
const PLANNING = urlConfig.LEAVE_PLANNING_API_PATH;
const ANOMALY = urlConfig.LEAVE_ANOMALY_API_PATH;

export const leavePhase2Service = {
  // GLP-20 Policy test lab
  listTestScenarios: (userTeamId, policyId) => {
    let url = `${TEST_LAB}/scenarios?userTeamId=${userTeamId}`;
    if (policyId) url += `&policyId=${policyId}`;
    return axiosUtils.get(url).then(payload);
  },
  createTestScenario: (body) => axiosUtils.post(`${TEST_LAB}/scenarios`, body).then(payload),
  updateTestScenario: (id, body) => axiosUtils.put(`${TEST_LAB}/scenarios/${id}`, body).then(payload),
  listTestRuns: (userTeamId, versionId) => {
    let url = `${TEST_LAB}/runs?userTeamId=${userTeamId}`;
    if (versionId) url += `&versionId=${versionId}`;
    return axiosUtils.get(url).then(payload);
  },
  runTestBatch: (body) => axiosUtils.post(`${TEST_LAB}/runs/batch`, body).then(payload),
  listTestResults: (runId) => axiosUtils.get(`${TEST_LAB}/runs/${runId}/results`).then(payload),
  runRegression: (body) => axiosUtils.post(`${TEST_LAB}/regression`, body).then(payload),
  checkPublishGate: (userTeamId, versionId) =>
    axiosUtils.get(`${TEST_LAB}/publish-gate?userTeamId=${userTeamId}&versionId=${versionId}`).then(payload),
  requestPublishException: (body) => axiosUtils.post(`${TEST_LAB}/publish-exceptions`, body).then(payload),
  approvePublishException: (id, body) =>
    axiosUtils.post(`${TEST_LAB}/publish-exceptions/${id}/approve`, body).then(payload),
  exportTestEvidence: (userTeamId, runId) =>
    axiosUtils.get(`${TEST_LAB}/runs/${runId}/export?userTeamId=${userTeamId}`).then(payload),

  // GLP-18 Legal calendars
  listCalendarVersions: (userTeamId) =>
    axiosUtils.get(`${LEGAL_CAL}/versions?userTeamId=${userTeamId}`).then(payload),
  createCalendarVersion: (body) => axiosUtils.post(`${LEGAL_CAL}/versions`, body).then(payload),
  publishCalendarVersion: (id, body) =>
    axiosUtils.post(`${LEGAL_CAL}/versions/${id}/publish`, body || {}).then(payload),
  listHolidayImports: (userTeamId) =>
    axiosUtils.get(`${LEGAL_CAL}/import-batches?userTeamId=${userTeamId}`).then(payload),
  createHolidayImport: (body) => axiosUtils.post(`${LEGAL_CAL}/import-batches`, body).then(payload),
  listHolidayEntries: (calendarVersionId) =>
    axiosUtils.get(`${LEGAL_CAL}/versions/${calendarVersionId}/holidays`).then(payload),
  addHolidayEntry: (body) => axiosUtils.post(`${LEGAL_CAL}/holidays`, body).then(payload),
  listWorkingDayRules: (userTeamId) =>
    axiosUtils.get(`${LEGAL_CAL}/working-day-rules?userTeamId=${userTeamId}`).then(payload),
  saveWorkingDayRule: (body) => axiosUtils.post(`${LEGAL_CAL}/working-day-rules`, body).then(payload),
  resolveWorkingDayPattern: (userTeamId, employeeId) => {
    let url = `${LEGAL_CAL}/working-day-pattern?userTeamId=${userTeamId}`;
    if (employeeId) url += `&employeeId=${employeeId}`;
    return axiosUtils.get(url).then(payload);
  },
  listEmployeeJurisdictions: (userTeamId) =>
    axiosUtils.get(`${LEGAL_CAL}/employee-jurisdictions?userTeamId=${userTeamId}`).then(payload),
  saveEmployeeJurisdiction: (body) =>
    axiosUtils.post(`${LEGAL_CAL}/employee-jurisdictions`, body).then(payload),
  listEmployeeWorkingDays: (userTeamId) =>
    axiosUtils.get(`${LEGAL_CAL}/employee-working-days?userTeamId=${userTeamId}`).then(payload),
  saveEmployeeWorkingDay: (body) =>
    axiosUtils.post(`${LEGAL_CAL}/employee-working-days`, body).then(payload),
  listCalendarChangeTasks: (userTeamId) =>
    axiosUtils.get(`${LEGAL_CAL}/change-tasks?userTeamId=${userTeamId}`).then(payload),
  previewCalendarImpact: (calendarVersionId, userTeamId) =>
    axiosUtils
      .get(`${LEGAL_CAL}/versions/${calendarVersionId}/impact-preview?userTeamId=${userTeamId}`)
      .then(payload),
  /** CFA-LEAVE-W4 — PH budget 11 = mandatory + floating */
  resolvePhBudget: (calendarVersionId, regionCode) => {
    let url = `${LEGAL_CAL}/versions/${calendarVersionId}/ph-budget`;
    if (regionCode) url += `?regionCode=${encodeURIComponent(regionCode)}`;
    return axiosUtils.get(url).then(payload);
  },
  listFloatingCatalogue: (calendarVersionId, verticalCode, clientCode) => {
    let url = `${LEGAL_CAL}/versions/${calendarVersionId}/floating-catalogue`;
    const params = [];
    if (verticalCode) params.push(`verticalCode=${encodeURIComponent(verticalCode)}`);
    if (clientCode) params.push(`clientCode=${encodeURIComponent(clientCode)}`);
    if (params.length) url += `?${params.join("&")}`;
    return axiosUtils.get(url).then(payload);
  },
  validateFloatingPick: (calendarVersionId, body) =>
    axiosUtils
      .post(`${LEGAL_CAL}/versions/${calendarVersionId}/floating-pick/validate`, body || {})
      .then(payload),
  prepareDecemberFloatingPublish: (body) =>
    axiosUtils.post(`${LEGAL_CAL}/floating/december-publish`, body || {}).then(payload),
  renewJanuaryFloatingBalance: (calendarVersionId, body) =>
    axiosUtils
      .post(`${LEGAL_CAL}/versions/${calendarVersionId}/floating/january-renew`, body || {})
      .then(payload),

  // GLP-17 Absence cases
  listAbsenceCases: (userTeamId, employeeId) => {
    let url = `${ABSENCE}?userTeamId=${userTeamId}`;
    if (employeeId) url += `&employeeId=${employeeId}`;
    return axiosUtils.get(url).then(payload);
  },
  getAbsenceCase: (id, managerView = false) =>
    axiosUtils.get(`${ABSENCE}/${id}?managerView=${managerView}`).then(payload),
  createAbsenceCase: (body) => axiosUtils.post(ABSENCE, body).then(payload),
  updateAbsenceCase: (id, body) => axiosUtils.put(`${ABSENCE}/${id}`, body).then(payload),
  listAbsenceBlocks: (caseId) => axiosUtils.get(`${ABSENCE}/${caseId}/blocks`).then(payload),
  listAbsenceEvents: (caseId, managerView = false) =>
    axiosUtils.get(`${ABSENCE}/${caseId}/events?managerView=${managerView}`).then(payload),
  getReturnToWork: (caseId, managerView = false) =>
    axiosUtils.get(`${ABSENCE}/${caseId}/return-to-work?managerView=${managerView}`).then(payload),

  // GLP-22 Document workflow
  listDocumentRules: (userTeamId) =>
    axiosUtils.get(`${DOCUMENTS}/rules?userTeamId=${userTeamId}`).then(payload),
  saveDocumentRule: (body) => axiosUtils.post(`${DOCUMENTS}/rules`, body).then(payload),
  listDocumentRequests: (userTeamId, employeeId) => {
    let url = `${DOCUMENTS}/requests?userTeamId=${userTeamId}`;
    if (employeeId) url += `&employeeId=${employeeId}`;
    return axiosUtils.get(url).then(payload);
  },
  createDocumentRequest: (body) => axiosUtils.post(`${DOCUMENTS}/requests`, body).then(payload),
  updateDocumentRequestStatus: (requestId, body) =>
    axiosUtils.post(`${DOCUMENTS}/requests/${requestId}/status`, body).then(payload),
  listDocumentLinks: (requestId) =>
    axiosUtils.get(`${DOCUMENTS}/requests/${requestId}/links`).then(payload),
  linkDocumentVault: (requestId, body) =>
    axiosUtils.post(`${DOCUMENTS}/requests/${requestId}/links`, body).then(payload),
  listRetentionPolicies: (userTeamId) =>
    axiosUtils.get(`${DOCUMENTS}/retention-policies?userTeamId=${userTeamId}`).then(payload),

  // GLP-21 Integrations
  listIntegrationConnectors: (userTeamId) =>
    axiosUtils.get(`${INTEGRATIONS}/connectors?userTeamId=${userTeamId}`).then(payload),
  saveIntegrationConnector: (body) => axiosUtils.post(`${INTEGRATIONS}/connectors`, body).then(payload),
  listPayrollStaging: (userTeamId) =>
    axiosUtils.get(`${INTEGRATIONS}/payroll-staging?userTeamId=${userTeamId}`).then(payload),
  listIntegrationRuns: (userTeamId, connectorId) => {
    let url = `${INTEGRATIONS}/runs?userTeamId=${userTeamId}`;
    if (connectorId) url += `&connectorId=${connectorId}`;
    return axiosUtils.get(url).then(payload);
  },
  listIntegrationDlq: (userTeamId, status) => {
    let url = `${INTEGRATIONS}/dlq?userTeamId=${userTeamId}`;
    if (status) url += `&status=${encodeURIComponent(status)}`;
    return axiosUtils.get(url).then(payload);
  },
  replayIntegrationDlq: (dlqId, body) =>
    axiosUtils.post(`${INTEGRATIONS}/dlq/${dlqId}/replay`, body || {}).then(payload),

  // GLP-19 Agreements
  listAgreements: (userTeamId) =>
    axiosUtils.get(`${AGREEMENTS}?userTeamId=${userTeamId}`).then(payload),
  createAgreement: (body) => axiosUtils.post(AGREEMENTS, body).then(payload),
  listAgreementVersions: (agreementId) =>
    axiosUtils.get(`${AGREEMENTS}/${agreementId}/versions`).then(payload),
  listContractOverrides: (userTeamId, employeeId) => {
    let url = `${AGREEMENTS}/contract-overrides?userTeamId=${userTeamId}`;
    if (employeeId) url += `&employeeId=${employeeId}`;
    return axiosUtils.get(url).then(payload);
  },
  saveContractOverride: (body) =>
    axiosUtils.post(`${AGREEMENTS}/contract-overrides`, body).then(payload),

  // GLP-25 Localization
  listLocalePacks: (userTeamId) =>
    axiosUtils.get(`${LOCALE}/packs?userTeamId=${userTeamId}`).then(payload),
  saveLocalePack: (body) => axiosUtils.post(`${LOCALE}/packs`, body).then(payload),
  listPolicyTranslations: (versionId, policyId) => {
    const params = new URLSearchParams();
    if (versionId) params.set('versionId', String(versionId));
    if (policyId) params.set('policyId', String(policyId));
    const q = params.toString();
    return axiosUtils.get(`${LOCALE}/translations${q ? `?${q}` : ''}`).then(payload);
  },

  // GLP-24 Workforce planning
  listQuotaWindows: (userTeamId) =>
    axiosUtils.get(`${PLANNING}/quota-windows?userTeamId=${userTeamId}`).then(payload),
  listLeaveBids: (userTeamId, windowId) => {
    let url = `${PLANNING}/bids?userTeamId=${userTeamId}`;
    if (windowId) url += `&windowId=${windowId}`;
    return axiosUtils.get(url).then(payload);
  },
  submitLeaveBid: (body) => axiosUtils.post(`${PLANNING}/bids`, body).then(payload),
  listCoverageRules: (userTeamId) =>
    axiosUtils.get(`${PLANNING}/coverage-rules?userTeamId=${userTeamId}`).then(payload),
  previewCoverage: (userTeamId, windowId) =>
    axiosUtils.get(`${PLANNING}/coverage-preview?userTeamId=${userTeamId}&windowId=${windowId}`).then(payload),

  // GLP-23 Anomaly / fairness
  listAnomalyRules: (userTeamId) =>
    axiosUtils.get(`${ANOMALY}/rules?userTeamId=${userTeamId}`).then(payload),
  saveAnomalyRule: (body) => axiosUtils.post(`${ANOMALY}/rules`, body).then(payload),
  listAnomalyFlags: (userTeamId, employeeId) => {
    let url = `${ANOMALY}/flags?userTeamId=${userTeamId}`;
    if (employeeId) url += `&employeeId=${employeeId}`;
    return axiosUtils.get(url).then(payload);
  },
  listFairnessSnapshots: (userTeamId) =>
    axiosUtils.get(`${ANOMALY}/snapshots?userTeamId=${userTeamId}`).then(payload),

  /** Global policies helper for test lab / agreements context */
  listGlobalPolicies: (userTeamId) =>
    axiosUtils.get(`${GLOBAL}/policies?userTeamId=${userTeamId}`).then(payload),
};

export default leavePhase2Service;
