/**
 * Persist timesheet AI agent Accept / Reject / Defer decisions per week (session scope).
 * No new tables — local decision state + audit write path.
 */
import { commonUtils } from "_helpers";

const STORAGE_PREFIX = "famstack-ts-agent-decision";

function decisionKey(context = {}) {
  const teamId = context.userTeamId || commonUtils.getCurrentUserTeamId() || "team";
  const userId = commonUtils.getCurrentUserId() || "anon";
  const week =
    context.weekStartDate ||
    (context.timeSheetRequest && context.timeSheetRequest.weekStartingDate) ||
    (context.timeSheetRequest && context.timeSheetRequest.weekId) ||
    "week";
  return `${STORAGE_PREFIX}:${teamId}:${userId}:${week}`;
}

export function readTimesheetAgentDecision(context) {
  if (typeof window === "undefined") return null;
  try {
    const raw = sessionStorage.getItem(decisionKey(context));
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return parsed && parsed.action ? parsed : null;
  } catch (e) {
    return null;
  }
}

export function writeTimesheetAgentDecision(context, entry) {
  if (typeof window === "undefined" || !entry) return entry;
  try {
    sessionStorage.setItem(decisionKey(context), JSON.stringify(entry));
  } catch (e) {
    // sessionStorage may be unavailable
  }
  return entry;
}

export function clearTimesheetAgentDecision(context) {
  if (typeof window === "undefined") return;
  try {
    sessionStorage.removeItem(decisionKey(context));
  } catch (e) {
    // ignore
  }
}
