import React, { Component } from 'react';
import Joyride, { STATUS, EVENTS } from 'react-joyride';
import { history } from '_helpers';
import {
  buildTourSteps,
  getTourMeta,
  getTourPageKey,
  shouldAutoStartTour,
} from '_helpers/guidedTour.registry';
import {
  hideTourForPageSession,
  isTourPermanentlyDismissed,
  markPageTourCompleted,
  markShellTourCompleted,
  setTourPermanentlyDismissed,
  clearSessionHiddenForPage,
} from '_helpers/guidedTour.storage';
import {
  GUIDED_NAVIGATION_CONFIG_CHANGED,
  isGuidedNavigationOrgEnabled,
  loadGuidedNavigationConfig,
} from '_helpers/guidedTour.config';
import './LuxuryGuidedTour.css';

const AUTO_START_DELAY_MS = 900;
const JOYRIDE_LOCALE = {
  back: 'Back',
  close: 'Close',
  last: 'Finish',
  next: 'Next',
  skip: 'Skip',
};

const JOYRIDE_STYLES = {
  options: {
    zIndex: 10050,
    arrowColor: '#ffffff',
    backgroundColor: '#ffffff',
    textColor: '#0f172a',
    primaryColor: '#059669',
    overlayColor: 'rgba(15, 23, 42, 0.35)',
  },
  tooltip: {
    borderRadius: 16,
    padding: 0,
    boxShadow: '0 18px 40px rgba(15, 23, 42, 0.12), 0 0 0 1px rgba(5, 150, 105, 0.12)',
  },
  tooltipTitle: {
    fontSize: '0.9375rem',
    fontWeight: 700,
    letterSpacing: '-0.02em',
    color: '#0f172a',
  },
  tooltipContent: {
    color: '#475569',
    padding: '0.35rem 0.15rem 0.15rem',
  },
  tooltipFooter: {
    borderTop: '1px solid #e2e8f0',
    marginTop: '0.5rem',
    paddingTop: '0.5rem',
  },
  buttonNext: {
    borderRadius: 999,
    fontWeight: 700,
    fontSize: '0.75rem',
    color: '#ffffff',
  },
  buttonBack: {
    borderRadius: 999,
    fontWeight: 600,
    fontSize: '0.75rem',
    color: '#475569',
  },
  buttonSkip: {
    fontWeight: 600,
    fontSize: '0.6875rem',
    color: '#64748b',
  },
};

class LuxuryGuidedTour extends Component {
  constructor(props) {
    super(props);
    this.state = {
      run: false,
      steps: [],
      stepIndex: 0,
      popoverOpen: false,
      pathname: history.location.pathname,
      tourMeta: getTourMeta(history.location.pathname),
      orgGuidedNavigationEnabled: isGuidedNavigationOrgEnabled(),
      configReady: false,
    };
    this.autoStartTimer = null;
    this.unlisten = null;
    this.tourMode = 'page';
  }

  componentDidMount() {
    this.unlisten = history.listen(this.handleRouteChange);
    document.addEventListener('mousedown', this.handleDocumentMouseDown);
    window.addEventListener(GUIDED_NAVIGATION_CONFIG_CHANGED, this.handleOrgConfigChange);
    loadGuidedNavigationConfig().then(() => {
      this.setState(
        {
          orgGuidedNavigationEnabled: isGuidedNavigationOrgEnabled(),
          configReady: true,
        },
        () => this.notifyAvailability({ configReady: false, orgGuidedNavigationEnabled: false, pathname: '' }),
      );
      if (isGuidedNavigationOrgEnabled()) {
        this.scheduleAutoStart(history.location.pathname);
      }
    });
  }

  componentWillUnmount() {
    if (this.unlisten) {
      this.unlisten();
    }
    document.removeEventListener('mousedown', this.handleDocumentMouseDown);
    window.removeEventListener(GUIDED_NAVIGATION_CONFIG_CHANGED, this.handleOrgConfigChange);
    this.clearAutoStartTimer();
  }

  componentDidUpdate(prevProps, prevState) {
    this.notifyAvailability(prevState);
    this.notifyPopoverChange(prevState);
  }

  notifyAvailability = (prevState) => {
    const { onAvailabilityChange } = this.props;
    if (!onAvailabilityChange) {
      return;
    }
    const available = this.state.configReady && this.state.orgGuidedNavigationEnabled;
    const pageKey = getTourPageKey(this.state.pathname);
    const hasBadge =
      available &&
      pageKey &&
      buildTourSteps(this.state.pathname, { includeShell: false }).length > 0 &&
      !isTourPermanentlyDismissed();

    const prevAvailable = prevState.configReady && prevState.orgGuidedNavigationEnabled;
    const prevPageKey = getTourPageKey(prevState.pathname);
    const prevHasBadge =
      prevAvailable &&
      prevPageKey &&
      buildTourSteps(prevState.pathname, { includeShell: false }).length > 0 &&
      !isTourPermanentlyDismissed();

    const prevDismissed = prevState.tourMeta
      ? prevState.tourMeta.permanentlyDismissed
      : undefined;
    const dismissed = this.state.tourMeta
      ? this.state.tourMeta.permanentlyDismissed
      : undefined;

    if (
      available !== prevAvailable ||
      hasBadge !== prevHasBadge ||
      prevDismissed !== dismissed
    ) {
      onAvailabilityChange({ available, hasBadge });
    }
  };

  notifyPopoverChange = (prevState) => {
    if (prevState.popoverOpen !== this.state.popoverOpen) {
      const { onPopoverChange } = this.props;
      if (onPopoverChange) {
        onPopoverChange(this.state.popoverOpen);
      }
    }
  };

  getPopoverStyle = () => {
    const getDockAnchor = this.props.getDockAnchor;
    if (!getDockAnchor) {
      return undefined;
    }
    const anchor = getDockAnchor();
    if (!anchor) {
      return undefined;
    }
    return {
      position: 'fixed',
      right: `${anchor.right + 58}px`,
      bottom: `${anchor.bottom}px`,
      top: 'auto',
      transform: 'none',
    };
  };

  handleOrgConfigChange = () => {
    const enabled = isGuidedNavigationOrgEnabled();
    this.setState({ orgGuidedNavigationEnabled: enabled, configReady: true });
    if (!enabled) {
      this.clearAutoStartTimer();
      this.setState({ run: false, popoverOpen: false });
      return;
    }
    this.scheduleAutoStart(this.state.pathname);
  };

  handleDocumentMouseDown = (event) => {
    if (!this.state.popoverOpen) {
      return;
    }
    const root = event.target.closest(
      '.lux-guided-tour, .lux-guided-tour__popover, .lux-assist-dock__icon-btn--tour',
    );
    if (!root) {
      this.closePopover();
    }
  };

  clearAutoStartTimer = () => {
    if (this.autoStartTimer) {
      clearTimeout(this.autoStartTimer);
      this.autoStartTimer = null;
    }
  };

  handleRouteChange = (location) => {
    this.setState({ run: false, popoverOpen: false });
    this.clearAutoStartTimer();
    const pathname = location.pathname;
    this.setState({
      pathname: pathname,
      tourMeta: getTourMeta(pathname),
    });
    if (this.state.orgGuidedNavigationEnabled) {
      this.scheduleAutoStart(pathname);
    }
  };

  scheduleAutoStart = (pathname) => {
    this.clearAutoStartTimer();
    if (!this.state.orgGuidedNavigationEnabled || !shouldAutoStartTour(pathname)) {
      return;
    }
    this.autoStartTimer = setTimeout(() => {
      this.startTourForPath(pathname, { auto: true });
    }, AUTO_START_DELAY_MS);
  };

  startTourForPath = (pathname, options) => {
    const forceShell = options && options.forceShell;
    const isAuto = options && options.auto;
    const meta = getTourMeta(pathname);
    const pageKey = getTourPageKey(pathname);
    const needsShell = !meta.shellCompleted;
    const needsPage = pageKey && !meta.pageCompleted;

    let steps = [];
    if (forceShell) {
      this.tourMode = 'shell';
      steps = buildTourSteps(pathname, { forceShell: true });
    } else if (isAuto) {
      if (needsShell && !needsPage) {
        this.tourMode = 'shell';
        steps = buildTourSteps(pathname, { forceShell: true });
      } else if (needsShell && needsPage) {
        this.tourMode = 'full';
        steps = buildTourSteps(pathname, { includeShell: true });
      } else {
        this.tourMode = 'page';
        steps = buildTourSteps(pathname, { includeShell: false });
      }
    } else if (options && options.includeShell) {
      this.tourMode = 'full';
      steps = buildTourSteps(pathname, { includeShell: true });
    } else {
      this.tourMode = 'page';
      steps = buildTourSteps(pathname, { includeShell: false });
    }

    if (!steps.length) {
      return;
    }

    this.setState({
      run: true,
      steps: steps,
      stepIndex: 0,
      popoverOpen: false,
    });
  };

  handleStartPageTour = () => {
    const pageKey = getTourPageKey(this.state.pathname);
    if (pageKey) {
      clearSessionHiddenForPage(pageKey);
    }
    this.startTourForPath(this.state.pathname, { includeShell: false });
    this.setState({ tourMeta: getTourMeta(this.state.pathname) });
  };

  handleStartShellTour = () => {
    this.startTourForPath(this.state.pathname, { forceShell: true });
  };

  handleHideForPage = () => {
    const pageKey = getTourPageKey(this.state.pathname);
    if (pageKey) {
      hideTourForPageSession(pageKey);
    }
    this.setState({
      run: false,
      popoverOpen: false,
      tourMeta: getTourMeta(this.state.pathname),
    });
  };

  handleDismissAll = () => {
    setTourPermanentlyDismissed(true);
    this.setState({
      run: false,
      popoverOpen: false,
      tourMeta: getTourMeta(this.state.pathname),
    });
  };

  handleReEnable = () => {
    setTourPermanentlyDismissed(false);
    this.setState({
      tourMeta: getTourMeta(this.state.pathname),
      popoverOpen: true,
    });
  };

  togglePopover = () => {
    this.setState((prev) => ({ popoverOpen: !prev.popoverOpen }));
  };

  openPopover = () => {
    this.setState({ popoverOpen: true });
  };

  closePopover = () => {
    this.setState({ popoverOpen: false });
  };

  handleJoyrideCallback = (data) => {
    const { status, type, index } = data;
    const pageKey = getTourPageKey(this.state.pathname);
    const finished = [STATUS.FINISHED, STATUS.SKIPPED].includes(status);

    if (finished) {
      if (status === STATUS.FINISHED) {
        if (this.tourMode === 'shell' || this.tourMode === 'full') {
          markShellTourCompleted();
        }
        if ((this.tourMode === 'page' || this.tourMode === 'full') && pageKey) {
          markPageTourCompleted(pageKey);
        }
      }
      this.setState({ run: false, stepIndex: 0 });
    }

    if (type === EVENTS.STEP_AFTER || type === EVENTS.TARGET_NOT_FOUND) {
      this.setState({ stepIndex: index + (type === EVENTS.STEP_AFTER ? 1 : 0) });
    }
  };

  renderPopover() {
    const { popoverOpen, tourMeta, pathname } = this.state;
    const pageKey = getTourPageKey(pathname);
    const pageTitle = tourMeta.pageTitle || 'this page';
    const dismissed = tourMeta.permanentlyDismissed;

    if (!popoverOpen) {
      return null;
    }

    return (
      <div
        className="lux-guided-tour__popover"
        role="dialog"
        aria-label="Guided tour options"
        style={this.getPopoverStyle()}
      >
        <header className="lux-guided-tour__popover-head">
          <strong>Guided tour</strong>
          <button
            type="button"
            className="lux-guided-tour__popover-close"
            onClick={this.closePopover}
            aria-label="Close menu"
          >
            <i className="fe fe-x" aria-hidden="true" />
          </button>
        </header>
        <p className="lux-guided-tour__popover-lead">
          Luxury walkthroughs explain each screen and the operations you can run here.
        </p>
        {dismissed ? (
          <div className="lux-guided-tour__popover-actions">
            <button type="button" className="lux-guided-tour__action lux-guided-tour__action--primary" onClick={this.handleReEnable}>
              Turn tours back on
            </button>
          </div>
        ) : (
          <div className="lux-guided-tour__popover-actions">
            {pageKey ? (
              <button type="button" className="lux-guided-tour__action lux-guided-tour__action--primary" onClick={this.handleStartPageTour}>
                Tour {pageTitle}
              </button>
            ) : null}
            <button type="button" className="lux-guided-tour__action" onClick={this.handleStartShellTour}>
              Workspace orientation
            </button>
            {pageKey ? (
              <button type="button" className="lux-guided-tour__action" onClick={this.handleHideForPage}>
                Hide for this page (until next login)
              </button>
            ) : null}
            <button type="button" className="lux-guided-tour__action lux-guided-tour__action--muted" onClick={this.handleDismissAll}>
              Dismiss all tours permanently
            </button>
          </div>
        )}
      </div>
    );
  }

  render() {
    const { run, steps, popoverOpen, orgGuidedNavigationEnabled, configReady } = this.state;
    const { embedded } = this.props;

    if (!configReady || !orgGuidedNavigationEnabled) {
      return null;
    }

    if (embedded) {
      return (
        <>
          <Joyride
            callback={this.handleJoyrideCallback}
            continuous
            run={run}
            scrollToFirstStep
            showProgress
            showSkipButton
            disableOverlayClose={false}
            spotlightClicks={false}
            steps={steps}
            locale={JOYRIDE_LOCALE}
            styles={JOYRIDE_STYLES}
            floaterProps={{ disableAnimation: true }}
          />
          {popoverOpen ? (
            <div className={`lux-guided-tour lux-guided-tour--embedded${popoverOpen ? ' is-popover-open' : ''}`}>
              {this.renderPopover()}
            </div>
          ) : null}
        </>
      );
    }

    const pageKey = getTourPageKey(this.state.pathname);
    const hasTour = pageKey && buildTourSteps(this.state.pathname, { includeShell: false }).length > 0;

    return (
      <>
        <Joyride
          callback={this.handleJoyrideCallback}
          continuous
          run={run}
          scrollToFirstStep
          showProgress
          showSkipButton
          disableOverlayClose={false}
          spotlightClicks={false}
          steps={steps}
          locale={JOYRIDE_LOCALE}
          styles={JOYRIDE_STYLES}
          floaterProps={{ disableAnimation: true }}
        />

        <div className={`lux-guided-tour${popoverOpen ? ' is-popover-open' : ''}`} data-tour="lux-tour-launcher">
          {this.renderPopover()}
          <button
            type="button"
            className="lux-guided-tour__launcher"
            onClick={this.togglePopover}
            aria-expanded={popoverOpen}
            aria-haspopup="dialog"
            title="Guided tour"
          >
            <span className="lux-guided-tour__launcher-glow" aria-hidden="true" />
            <i className="fe fe-compass" aria-hidden="true" />
            {hasTour && !isTourPermanentlyDismissed() ? (
              <span className="lux-guided-tour__launcher-badge" aria-hidden="true" />
            ) : null}
          </button>
        </div>
      </>
    );
  }
}

export default LuxuryGuidedTour;
