import React from "react";
import classNames from "classnames/bind";
import { buildApprovalAuthorityHistory } from "_helpers/approvalAuthority.utils";

function ApprovalAuthorityHistory({ record, context, className, compact }) {
  const history = buildApprovalAuthorityHistory(record, context);
  if (!history) {
    return null;
  }

  const isDelegate = history.authorityType === "DELEGATE";

  if (compact) {
    return (
      <span className={classNames("lux-approval-history lux-approval-history--compact", className)}>
        <i className="fe fe-user-check" aria-hidden="true" />
        {history.label}
      </span>
    );
  }

  return (
    <div
      className={classNames(
        "lux-approval-history-card",
        isDelegate ? "is-delegate" : "is-manager",
        className
      )}
      role="note"
    >
      <span className="lux-approval-history-card__icon" aria-hidden="true">
        <i className={isDelegate ? "fe fe-users" : "fe fe-check-circle"} />
      </span>
      <div className="lux-approval-history-card__copy">
        <span className="lux-approval-history-card__eyebrow">
          {isDelegate ? "Delegate approval" : "Manager approval"}
        </span>
        <p>{history.label}</p>
      </div>
    </div>
  );
}

export default ApprovalAuthorityHistory;
