import moment from "moment";
import {
  normalizeDeliverableStatus,
  isDeliverableOverdue,
  getDeliverableActivityPct,
} from "./deliverableList.utils";

const STATUS_TONES = {
  NEW: "sky",
  ASSIGNED: "indigo",
  INPROGRESS: "amber",
  COMPLETED: "green",
  CLOSED: "slate",
};

const STATUS_LABELS = {
  NEW: "New",
  ASSIGNED: "Assigned",
  INPROGRESS: "In progress",
  COMPLETED: "Completed",
  CLOSED: "Closed",
};

const CATEGORY_TONES = ["indigo", "teal", "violet", "amber", "sky"];

const ONGOING_STATUSES = new Set(["NEW", "ASSIGNED", "INPROGRESS"]);
const DONE_STATUSES = new Set(["COMPLETED", "CLOSED"]);

function buildStatusMix(statusCounts, total) {
  return Object.keys(STATUS_LABELS)
    .map((key) => ({
      key,
      label: STATUS_LABELS[key],
      count: statusCounts[key] || 0,
      tone: STATUS_TONES[key] || "slate",
      pct: total ? Math.round(((statusCounts[key] || 0) / total) * 100) : 0,
    }))
    .filter((seg) => seg.count > 0);
}

function topCategories(categoryCounts, limit = 5) {
  return Object.entries(categoryCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([label, count], index) => ({
      label,
      count,
      tone: CATEGORY_TONES[index % CATEGORY_TONES.length],
    }));
}

function buildInsight({ key, title, subtitle, icon, mix, emptyLabel }) {
  return { key, title, subtitle, icon, mix, emptyLabel };
}

function buildCategoryInsight(categoryCounts, total) {
  const top = topCategories(categoryCounts, 5);
  const mix = top.map(({ label, count, tone }) => ({
    key: label,
    label,
    count,
    tone,
    pct: total ? Math.round((count / total) * 100) : 0,
  }));
  return buildInsight({
    key: "categories",
    title: "Category mix",
    subtitle: mix.length ? `${mix.length} categories in use` : "No categories assigned",
    icon: "fe fe-tag",
    mix,
    emptyLabel: "Add categories to group deliverables",
  });
}

function buildActivityInsight(list, total) {
  let noWorkItems = 0;
  let inProgress = 0;
  let complete = 0;

  list.forEach((task) => {
    const taskTotal = Number(task.taskActivityTotalCount) || 0;
    const pct = getDeliverableActivityPct(task);
    if (!taskTotal) noWorkItems += 1;
    else if (pct >= 100) complete += 1;
    else inProgress += 1;
  });

  const mix = [
    { key: "none", label: "No work items", count: noWorkItems, tone: "slate", pct: total ? Math.round((noWorkItems / total) * 100) : 0 },
    { key: "progress", label: "In progress", count: inProgress, tone: "amber", pct: total ? Math.round((inProgress / total) * 100) : 0 },
    { key: "done", label: "Work items done", count: complete, tone: "green", pct: total ? Math.round((complete / total) * 100) : 0 },
  ].filter((seg) => seg.count > 0);

  return buildInsight({
    key: "activity",
    title: "Work item progress",
    subtitle: "Completion across linked work items",
    icon: "fe fe-check-square",
    mix,
    emptyLabel: "No deliverables in view",
  });
}

function buildTimelineInsight(list, total, overdue) {
  let onTrack = 0;
  let noDue = 0;

  list.forEach((task) => {
    const status = normalizeDeliverableStatus(task.status);
    if (DONE_STATUSES.has(status)) return;
    if (!task.estCompletionTime) {
      noDue += 1;
      return;
    }
    if (!isDeliverableOverdue(task)) onTrack += 1;
  });

  const mix = [
    { key: "ontrack", label: "On track", count: onTrack, tone: "green", pct: total ? Math.round((onTrack / total) * 100) : 0 },
    { key: "overdue", label: "Past due", count: overdue, tone: "rose", pct: total ? Math.round((overdue / total) * 100) : 0 },
    { key: "nodue", label: "No due date", count: noDue, tone: "slate", pct: total ? Math.round((noDue / total) * 100) : 0 },
  ].filter((seg) => seg.count > 0);

  return buildInsight({
    key: "timeline",
    title: "Timeline health",
    subtitle: "Open deliverables by due-date risk",
    icon: "fe fe-clock",
    mix,
    emptyLabel: "No open deliverables to assess",
  });
}

export function buildDeliverableSummaryStats(tasks = []) {
  const list = tasks || [];
  const total = list.length;
  let ongoing = 0;
  let completed = 0;
  let inactive = 0;
  let overdue = 0;
  let withWorkItems = 0;
  let activityTotal = 0;
  let activityDone = 0;
  const statusCounts = {};
  const categoryCounts = {};

  list.forEach((task) => {
    const status = normalizeDeliverableStatus(task.status);
    statusCounts[status] = (statusCounts[status] || 0) + 1;
    if (ONGOING_STATUSES.has(status)) ongoing += 1;
    if (DONE_STATUSES.has(status)) completed += 1;
    if (task.active === false) inactive += 1;
    if (isDeliverableOverdue(task)) overdue += 1;
    if (task.category) {
      categoryCounts[task.category] = (categoryCounts[task.category] || 0) + 1;
    }
    const taskActivities = Number(task.taskActivityTotalCount) || 0;
    if (taskActivities > 0) withWorkItems += 1;
    activityTotal += taskActivities;
    activityDone += Number(task.completedTaskActivityCount) || 0;
  });

  const active = total - inactive;
  const activityPct = activityTotal ? Math.round((activityDone / activityTotal) * 100) : 0;
  const statusMix = buildStatusMix(statusCounts, total);
  const categories = topCategories(categoryCounts);

  const statusInsight = buildInsight({
    key: "status",
    title: "Status mix",
    subtitle: `${total} deliverable${total === 1 ? "" : "s"} in project`,
    icon: "fe fe-flag",
    mix: statusMix,
    emptyLabel: "No deliverables in view",
  });

  const insights = [
    statusInsight,
    buildCategoryInsight(categoryCounts, total),
    buildActivityInsight(list, total),
    buildTimelineInsight(list, total, overdue),
  ];

  return {
    total,
    ongoing,
    completed,
    inactive,
    active,
    overdue,
    withWorkItems,
    activityTotal,
    activityDone,
    activityPct,
    statusMix,
    categories,
    stageCounts: {
      newCount: statusCounts.NEW || 0,
      assignedCount: statusCounts.ASSIGNED || 0,
      inProgressCount: statusCounts.INPROGRESS || 0,
      completedCount: (statusCounts.COMPLETED || 0) + (statusCounts.CLOSED || 0),
    },
    kpis: [
      {
        key: "total",
        label: "Deliverables",
        value: total,
        tone: "indigo",
        icon: "fe fe-layers",
        hint: "In this project",
      },
      {
        key: "ongoing",
        label: "In flight",
        value: ongoing,
        tone: "amber",
        icon: "fe fe-activity",
        hint: "New through in progress",
      },
      {
        key: "completed",
        label: "Completed",
        value: completed,
        tone: "green",
        icon: "fe fe-check-circle",
        hint: "Completed or closed",
      },
      {
        key: "activityPct",
        label: "Work item progress",
        value: activityPct,
        tone: "teal",
        icon: "fe fe-pie-chart",
        hint: activityTotal ? `${activityDone} of ${activityTotal} work items` : "No work items yet",
        suffix: "%",
      },
    ],
    highlights: [
      {
        key: "overdue",
        label: "Past due",
        value: overdue,
        tone: overdue > 0 ? "rose" : "slate",
        icon: "fe fe-alert-circle",
        hint: "Due date passed, not closed",
      },
      {
        key: "active",
        label: "Active",
        value: active,
        tone: "green",
        icon: "fe fe-zap",
        hint: `${inactive} inactive in register`,
      },
      {
        key: "workitems",
        label: "With work items",
        value: withWorkItems,
        tone: "indigo",
        icon: "fe fe-check-square",
        hint: "Deliverables tracking work items",
      },
      {
        key: "inactive",
        label: "Inactive",
        value: inactive,
        tone: inactive > 0 ? "amber" : "slate",
        icon: "fe fe-pause-circle",
        hint: "Turned off in register",
      },
      {
        key: "categories",
        label: "Categories",
        value: Object.keys(categoryCounts).length,
        tone: "sky",
        icon: "fe fe-tag",
        hint: categories.length ? categories.map((c) => `${c.label} (${c.count})`).join(" · ") : "No categories yet",
      },
      {
        key: "progress",
        label: "Avg progress",
        value: activityPct,
        tone: "teal",
        icon: "fe fe-trending-up",
        hint: activityTotal ? `${activityDone}/${activityTotal} work items complete` : "Add work items to track",
        suffix: "%",
      },
    ],
    insights,
    statusInsight,
  };
}
