import React, { Component } from "react";
import { Link } from "react-router-dom";
import { npdService } from "_services/npd/npd.service";
import NpdLuxPage, {
  NpdActionButton,
  NpdLuxPanel,
} from "views/npd/components/NpdLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class NpdIdeasPage extends Component {
  state = {
    loading: true,
    loadError: null,
    rows: [],
    saving: false,
    form: { title: "", description: "", linkedProjectId: "", budgetAmount: "" },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("NPD ideas");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await npdService.listIdeas();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load ideas"),
      });
    }
  };

  handleCreate = async (e) => {
    e.preventDefault();
    const { form } = this.state;
    if (!form.title) return;
    this.setState({ saving: true });
    const result = await npdService.createIdea({
      title: form.title,
      description: form.description,
      linkedProjectId: form.linkedProjectId || undefined,
      budgetAmount: form.budgetAmount ? Number(form.budgetAmount) : undefined,
    });
    this.setState({ saving: false });
    if (result.source === "api") {
      this.setState({
        form: { title: "", description: "", linkedProjectId: "", budgetAmount: "" },
      });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Create failed") });
    }
  };

  render() {
    const { loading, loadError, rows, saving, form } = this.state;
    return (
      <NpdLuxPage
        testId="npd-ideas-page"
        dataSource={rows.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        pageMeta={{
          tone: "violet",
          icon: "fe fe-lightbulb",
          eyebrow: "Projects · NPD",
          titleLead: "NPD",
          titleAccent: "ideas",
          lede: "Capture product ideas with optional project links and budget.",
        }}
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load ideas">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        <NpdLuxPanel title="Create idea" icon="fe fe-plus">
          <form className="lux-module-inline-form" onSubmit={this.handleCreate}>
            <div className="form-row">
              <div className="col-md-3">
                <input
                  className="form-control"
                  placeholder="Title"
                  value={form.title}
                  onChange={(e) => this.setState({ form: { ...form, title: e.target.value } })}
                />
              </div>
              <div className="col-md-3">
                <input
                  className="form-control"
                  placeholder="Description"
                  value={form.description}
                  onChange={(e) => this.setState({ form: { ...form, description: e.target.value } })}
                />
              </div>
              <div className="col-md-2">
                <input
                  className="form-control"
                  placeholder="Linked project id"
                  value={form.linkedProjectId}
                  onChange={(e) =>
                    this.setState({ form: { ...form, linkedProjectId: e.target.value } })
                  }
                />
              </div>
              <div className="col-md-2">
                <input
                  className="form-control"
                  placeholder="Budget"
                  value={form.budgetAmount}
                  onChange={(e) => this.setState({ form: { ...form, budgetAmount: e.target.value } })}
                />
              </div>
              <div className="col-md-2">
                <NpdActionButton type="submit" disabled={saving}>
                  {saving ? "Saving…" : "Create idea"}
                </NpdActionButton>
              </div>
            </div>
          </form>
        </NpdLuxPanel>
        <NpdLuxPanel title="Ideas" meta={`${rows.length} record${rows.length === 1 ? "" : "s"}`} icon="fe fe-list">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
          {!loading && rows.length === 0 ? (
            <LuxRegisterEmptyState
              title="No ideas yet"
              description="Create an NPD idea to start the stage-gate lifecycle."
              showCreate={false}
            />
          ) : !loading ? (
            <div className="lux-module-table-wrap">
              <table className="table table-sm mb-0">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Title</th>
                    <th>Status</th>
                    <th>Project</th>
                    <th>Budget</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((row) => (
                    <tr key={row.ideaRef || row.id}>
                      <td>
                        <Link to={`/npd/ideas/${encodeURIComponent(row.ideaRef)}`}>{row.ideaRef}</Link>
                      </td>
                      <td>{row.title}</td>
                      <td>
                        <span className={`lux-expansion-status is-${String(row.status || "draft").toLowerCase()}`}>
                          {row.status || "Draft"}
                        </span>
                      </td>
                      <td>{row.linkedProjectId || "—"}</td>
                      <td>{row.budgetAmount != null ? row.budgetAmount : "—"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : null}
        </NpdLuxPanel>
      </NpdLuxPage>
    );
  }
}

export default NpdIdeasPage;
